window.SYSTEM_DESIGN_BOOK = {"questions":[{"day":1,"title":{"en":"Decoupling Mobile from Backend Services","fr":"Découpler l’application mobile des services backend"},"pages":[4,7],"topic":"architecture","correct":"A","scenario":[{"kind":"figure","page":4,"id":"004-02","width":1730,"height":909,"alt":{"en":"Day 1 featured","fr":"Illustration de la question du jour 1"},"transcript":{"en":["System Design Labs","our mobile app talks to 3 backend services directly.","A 4th one ships next sprint. The mobile team is already drowning.","User DB","Order DB","Be","Payment DB","Mobile App","NotificationService","(notifications.api.com)","Notification DB","Next sprint","Add an API Gateway — single","Build a BFF (Backend for Frontend) —","entry point, all services hide behind one domain.","a dedicated aggregation layer tailored for mobile.","Put a Load Balancer in front of all services —","Switch to GraphQL Federation —","single IP, distributed traffic.","one unified schema the client queries."],"fr":["L’application mobile communique directement avec trois services backend. Un quatrième arrive au prochain sprint.","Application mobile → UserService (users.api.com) → base utilisateurs.","Application mobile → OrderService (orders.api.com) → base commandes.","Application mobile → PaymentService (payments.api.com) → base paiements.","Prochain sprint : Application mobile → NotificationService (notifications.api.com) → base notifications.","A. Passerelle API : un seul point d’entrée, un domaine pour tous les services.","B. BFF (Backend for Frontend) : agrégation dédiée à l’application mobile.","C. Répartiteur de charge : une seule adresse IP, trafic distribué.","D. Fédération GraphQL : le client interroge un schéma unifié."]}},{"kind":"p","page":4,"text":{"en":"our mobile app talks to 3 backend services directly.","fr":"Notre application mobile communique directement avec trois services backend."}},{"kind":"p","page":4,"text":{"en":"A 4th one ships next sprint. The mobile team is already drowning.","fr":"Un quatrième service doit sortir au prochain sprint. L’équipe mobile est déjà débordée."}},{"kind":"p","page":4,"text":{"en":"Every new service means a new domain to whitelist, a new auth scheme to wire, and a new error shape to parse. You're asked to reduce coupling before NotificationService lands.","fr":"Chaque nouveau service ajoute un domaine à autoriser, un mécanisme d’authentification à intégrer et un format d’erreur à interpréter. On vous demande de réduire le couplage avant l’arrivée de NotificationService."}},{"kind":"p","page":4,"text":{"en":"Here's the setup:","fr":"Voici la configuration."}},{"kind":"p","page":4,"text":{"en":"Mobile → UserService (users.api.com)","fr":"Mobile → UserService (users.api.com)"}},{"kind":"p","page":4,"text":{"en":"Mobile → OrderService (orders.api.com)","fr":"Mobile → OrderService (orders.api.com)"}},{"kind":"p","page":4,"text":{"en":"Mobile → PaymentService (payments.api.com)","fr":"Mobile → PaymentService (payments.api.com)"}},{"kind":"p","page":4,"text":{"en":"…and NotificationService next sprint.","fr":"…et NotificationService au prochain sprint."}},{"kind":"p","page":4,"text":{"en":"The client is doing routing the backend should be doing. What do you do?","fr":"Le client assure le routage que devrait prendre en charge le backend. Quelle solution choisissez-vous ?"}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":4,"text":{"en":"Add an API Gateway — single entry point, all services hide behind one domain.","fr":"Ajouter une passerelle API. Tous les services passent derrière un même domaine, qui devient le point d’entrée unique."}}]},{"letter":"B","blocks":[{"kind":"p","page":4,"text":{"en":"Build a BFF (Backend for Frontend) — a dedicated aggregation layer tailored for mobile.","fr":"Construire un BFF (Backend for Frontend), une couche d’agrégation dédiée à l’application mobile."}}]},{"letter":"C","blocks":[{"kind":"p","page":5,"text":{"en":"Put a Load Balancer in front of all services — single IP, distributed traffic.","fr":"Placer un répartiteur de charge devant l’ensemble des services. Le trafic est distribué derrière une même adresse IP."}}]},{"letter":"D","blocks":[{"kind":"p","page":5,"text":{"en":"Switch to GraphQL Federation — one unified schema the client queries.","fr":"Adopter la fédération GraphQL pour que le client interroge un schéma unifié."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"figure","page":6,"id":"006-03","width":1536,"height":1024,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["Why A wins (API Gateway)","One domain. One auth flow. One error contract. The client stops caring that","UserService, OrderService, and PaymentService live on different hosts — the","gateway hides them behind api.yourapp.com/users, /orders, /payments.","Security","When NotificationService ships next sprint, you add one route.","AuthN/AuthZ in one place.","The mobile app ships zero changes.","Performance","Rate limiting &","traffic control.","API Gateway","/users","Observability","(api.yourapp.com)","LF Userservice --S User DB","Consistent logging","AuthN / AuthZ","& monitoring.","HTTPS.","/orders","Bi","JSON","(7)","Rate Limiting","G OrderService = --- ‘=| Order DB","Reliability","TLS termination","/payments","& fail-fast.","Request Logging","re} PaymentService -§ Payment DB","Mobile App","TLS Termination","Consistency","\\\\_ /notifications","Notification","Versioning & error","Versioning","(next sprint)","NotificationService } - - - ‘=|","DB","contract enforcement.","Battle-tested at scale:","That’s what “future-proof” actually means at the transport layer:","NETFLIX","Netflix, Stripe, and every","new services cost nothing on the client side.","mature fintech run some","stripe &>","form of this."],"fr":["L’application mobile contacte la passerelle API sur api.yourapp.com via HTTPS et échange du JSON.","/users → UserService et sa base. /orders → OrderService et sa base. /payments → PaymentService et sa base.","/notifications → NotificationService et sa base, à partir du prochain sprint. Une route à ajouter, sans mise à jour de l’application.","Sécurité : authentification et autorisation au même endroit. Performance : limitation de débit et contrôle du trafic.","Observabilité : journalisation et supervision cohérentes. Fiabilité : terminaison TLS et échec rapide.","Cohérence : versionnement et application d’un contrat d’erreur commun.","Approche employée à grande échelle, notamment chez Netflix, Stripe et les fintechs matures."]}},{"kind":"p","page":6,"text":{"en":"Why A wins (API Gateway):","fr":"Pourquoi retenir A, la passerelle API ?"}},{"kind":"p","page":6,"text":{"en":"One domain. One auth flow. One error contract. The client stops caring that UserService, OrderService, and PaymentService live on different hosts — the gateway hides them behind api.yourapp.com/users, /orders, /payments. When NotificationService ships next sprint, you add one route. The mobile app ships zero changes. That's what \"future-proof\" actually means at the transport layer: new services cost nothing on the client side.","fr":"Un seul domaine, un seul parcours d’authentification et un format d’erreur commun. Le client n’a plus à savoir que UserService, OrderService et PaymentService tournent sur des hôtes différents. La passerelle les expose derrière api.yourapp.com/users, /orders et /payments. À l’arrivée de NotificationService, il suffit d’ajouter une route. Aucun changement à livrer côté mobile. C’est ce qui rend cette couche de transport évolutive : brancher un service supplémentaire ne coûte rien au client."}},{"kind":"p","page":6,"text":{"en":"It also centralizes the things you don't want scattered across 4 codebases: authN/authZ, rate limiting, request logging, TLS termination, versioning. Netflix, Stripe, and every mature fintech run some form of this.","fr":"On centralise aussi les fonctions qu’on veut éviter de disperser dans quatre bases de code : authentification et autorisation (authN/authZ), limitation de débit, journalisation des requêtes, terminaison TLS et versionnement. Netflix, Stripe et les fintechs bien établies utilisent des variantes de cette approche."}}],[{"kind":"p","page":7,"text":{"en":"Why B is the trap answer (BFF):","fr":"Pourquoi B est tentant, avec un BFF"}},{"kind":"p","page":7,"text":{"en":"BFF is a legitimate pattern — and it's close enough to fool a lot of senior engineers. But BFF solves a different problem: data shape per client type. Mobile needs a slim payload, web needs a richer one. BFF gives each client its own backend that aggregates and reshapes data.","fr":"Le BFF est un patron valable et suffisamment proche du besoin pour tromper des ingénieurs expérimentés. Il sert à adapter la forme des données à chaque type de client. Le mobile veut une réponse légère, le Web peut en recevoir une plus riche. Chaque client a son backend pour agréger et remodeler les données."}},{"kind":"p","page":7,"text":{"en":"In this scenario, the pain isn't payload shape — it's domain sprawl and coupling. Putting a BFF here trades 4 URLs for 1 URL + 1 extra service you own end-to-end. That's the wrong tradeoff.","fr":"Le problème ici vient de la multiplication des domaines et du couplage. Avec un BFF, on troque quatre URL contre une URL et un service supplémentaire à exploiter de bout en bout. Le compromis ne vaut pas la peine dans ce cas."}}],[{"kind":"p","page":7,"text":{"en":"Why C is wrong (Load Balancer):","fr":"Pourquoi C ne convient pas, avec un répartiteur de charge"}},{"kind":"p","page":7,"text":{"en":"A load balancer distributes traffic across identical instances of the same service. It doesn't route between different services on different domains. Putting an LB in front of UserService + OrderService doesn't make sense — it has no concept of \"send /orders here and /users there.\" That's application-layer routing, which is exactly what an API Gateway does.","fr":"Un répartiteur de charge distribue le trafic entre les instances identiques d’un service. Il ne choisit pas entre des services distincts exposés sur différents domaines. Devant UserService et OrderService, un simple répartiteur ne sait pas envoyer /orders d’un côté et /users de l’autre. Ce routage de couche applicative est précisément le rôle de la passerelle API."}}],[{"kind":"p","page":7,"text":{"en":"Why D is wrong here (GraphQL Federation):","fr":"Pourquoi D ne convient pas ici, avec la fédération GraphQL"}},{"kind":"p","page":7,"text":{"en":"GraphQL Federation solves schema unification, not transport-layer coupling. You'd still need a gateway in front of the federation, and you'd rewrite every backend service to expose a GraphQL subgraph. That's a multi-quarter migration to solve a problem you can fix in a sprint with a gateway.","fr":"La fédération GraphQL unifie les schémas. Le couplage au niveau du transport reste à résoudre. Il faudrait une passerelle devant la fédération et réécrire chacun des services backend pour exposer un sous-graphe GraphQL. Cela représente plusieurs trimestres de migration pour un problème qu’une passerelle règle en un sprint."}}]]},{"day":2,"title":{"en":"Killing the N+1 Query Problem","fr":"Éliminer le problème des requêtes N+1"},"pages":[8,11],"topic":"data","correct":"A","scenario":[{"kind":"figure","page":8,"id":"008-02","width":1730,"height":909,"alt":{"en":"Day 2 featured","fr":"Illustration de la question du jour 2"},"transcript":{"en":["System Design Labs","Your /","rders endpoint loads 50 orders on a page","P95 is 2.4s. The DB’s fine. The app server's fine. Nothing's on fire.","SELECT orders","(limit 50)","Orders","Forward","DB","coe","N+1 Queries","Web Client",">| Customers","(50x)","DB","Add a DataLoader in front of the customer lookup —","Eager-load the relation — include","{ customer: true } on the Prisma query. One JOIN, done.","batches the 50 IDs into one WHERE id IN (...)","behind the scenes","Denormalize customer_name onto the orders table —","Cache the customer by ID in Redis —","every lookup hits cache first, DB only on miss.","read it straight from the orders row,","no join, no second query."],"fr":["System Design Labs","Votre /","rders endpoint charge 50 commandes sur une page","P95 est 2.4s. La base de données va bien. Le serveur d'applications va bien. Rien n'est en feu.","SÉLECTIONNER les commandes","(limite 50)","Commandes","En avant","DB","coe","N+1 Requêtes","Web Client","> — Clients","(50x)","DB","Ajouter un DataLoader devant la recherche client","Chargez la relation — include","client : true — sur la requête Prisma. Un JOIN, terminé.","Les 50 identifiants sont regroupés en un seul identifiant. (...)","Dans les coulisses","Dénormaliser nom_client dans la table des commandes","Cache le client par ID dans Redis","chaque recherche frappe le cache en premier, DB seulement sur miss.","Lisez-le directement de la rangée des ordres,","pas de jointure, pas de deuxième requête."]}},{"kind":"p","page":8,"text":{"en":"Your /orders endpoint loads 50 orders on a page.","fr":"L’endpoint /orders charge 50 commandes par page."}},{"kind":"p","page":8,"text":{"en":"P95 is 2.4s. The DB's fine. The app server's fine. Nothing's on fire.","fr":"Le p95 est à 2,4 s. La base et le serveur applicatif tournent normalement. Rien ne semble en panne."}},{"kind":"p","page":8,"text":{"en":"Then you open the query log.","fr":"Puis vous ouvrez le journal des requêtes."}},{"kind":"p","page":8,"text":{"en":"51 queries per request. One SELECT for the orders list. Then 50 more — one per order — to fetch the customer. The ORM is doing lazy-load on order.customer inside your map.","fr":"Chaque appel déclenche 51 requêtes. Un SELECT charge la liste des commandes, puis 50 autres récupèrent les clients, commande par commande. L’ORM charge order.customer à la demande, à l’intérieur du map."}},{"kind":"p","page":8,"text":{"en":"Classic N+1. You've seen it before. The fix is \"obvious\" — until the team meeting, where three engineers propose three different things and everyone thinks they're right.","fr":"Le classique problème N+1. Vous l’avez déjà vu et le remède semble évident. En réunion, pourtant, trois ingénieurs défendent trois solutions différentes et chacun pense avoir raison."}},{"kind":"p","page":8,"text":{"en":"Here's what's on the table:","fr":"Voici les options."}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":8,"text":{"en":"Eager-load the relation — include: { customer: true } on the Prisma query. One JOIN, done.","fr":"Charger la relation à l’avance avec include: { customer: true } dans la requête Prisma. Une jointure suffit."}}]},{"letter":"B","blocks":[{"kind":"p","page":8,"text":{"en":"Add a DataLoader in front of the customer lookup — batches the 50 IDs into one WHERE id IN (...) behind the scenes.","fr":"Utiliser un DataLoader pour rechercher les clients. Il regroupe les 50 identifiants dans un seul WHERE id IN (...)."}}]},{"letter":"C","blocks":[{"kind":"p","page":8,"text":{"en":"Cache the customer by ID in Redis — every lookup hits cache first, DB only on miss.","fr":"Mettre chaque client en cache par identifiant dans Redis. Toutes les recherches passent d’abord par le cache et ne consultent la base que si l’entrée est absente."}}]},{"letter":"D","blocks":[{"kind":"p","page":9,"text":{"en":"Denormalize customer_name onto the orders table — read it straight from the orders row, no join, no second query.","fr":"Dénormaliser customer_name dans orders. Le nom se lit directement sur la ligne de commande, sans jointure ni seconde requête."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"figure","page":10,"id":"010-03","width":1536,"height":1024,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["Why A wins:","Eager-load the relation — i","clude","{ custom",": true }","on the Prisma query.","@ What changes","SQL shape (conceptual)","SELECT 0.id, o.created_at, 0o.total,","Forward","c.id AS customer_id, c.name AS customer_name","GET /orders","API","Request","Order","(LEFT JOIN)","c.email AS customer_email","Gateway","Service","FROM orders o","LEFT JOIN customers c","Web Client","ON o.customer_id = c.id","WHERE o.user_id = ?","ORDER BY o.created_at DESC","One LEFT JOIN customers ON orders.customer_id = customers.id","LIMIT 50 OFFSET 0;","returns the whole page in a single round trip.","Performance","Simplicity","Reliability","P95 drops from 2.4s","No new infrastructure.","Fewer moving parts.","(7)","to ~80ms.","No new failure modes.","Fewer things to break.","The real lesson","The N+1 problem in an ORM almost always has the same root cause: a lazy relation the developer","didn’t realize was lazy. Prisma’s include, Sequelize’s include, TypeORM’s relations — every ORM","has this. Reach for fancier patterns only when JOIN genuinely can’t solve it."],"fr":["Pourquoi retenir A :","Chargez la relation — i","clade","custom",": vrai","sur la requête Prisma.","Ce qui change","Forme SQL (conceptuelle)","SÉLECTIONNER 0.id, o.created_at, 0o.total,","En avant","c.id AS customer_id, c.name AS customer_name","GET /orders","API","Demande","Commande","(Joindre à gauche)","c.email AS customer_email","Passerelle","Service","À PROPOS des ordres o","REJOIGNEZ LES CLIENTS","Web Client","ON o.customer_id — c.id","O — o.user_id — ?","COMMANDE PAR o.created_at DESC","Un client à GAUCHE SUR orders.customer_id — customers.id","LIMITE 50 OFFSET 0;","renvoie la page entière en un seul aller-retour.","Exécution du budget","Simplicité","Fiabilité","P95 baisse de 2.4s","Pas de nouvelles infrastructures.","Moins de pièces mobiles.","(7)","à — 80ms.","Pas de nouveaux modes de défaillance.","Moins de choses à casser.","La vraie leçon","Le problème N + 1 dans un ORM a presque toujours la même cause: une relation paresseuse le développeur","Prisma incluait, Sequelize incluait, TypeORM incluait les relations — toutes les relations ORM","Atteindre pour les modèles plus chics seulement quand JOIN vraiment ne peut pas le résoudre."]}},{"kind":"p","page":10,"text":{"en":"Why A wins: One LEFT JOIN customers ON orders.customer_id = customers.id returns the whole page in a single round trip. P95 drops from 2.4s to ~80ms. No new infrastructure. No new failure modes. The N+1 problem in an ORM almost always has the same root cause: a lazy relation the developer didn't realize was lazy. Prisma's include, Sequelize's include, TypeORM's relations — every ORM has this. Reach for fancier patterns only when JOIN genuinely can't solve it.","fr":"Pourquoi retenir A ? Un LEFT JOIN customers ON orders.customer_id = customers.id retourne toute la page en un seul aller-retour. Le p95 passe de 2,4 s à environ 80 ms, sans nouvelle infrastructure ni nouveau mode de panne. Avec un ORM, le N+1 vient presque toujours d’une relation chargée à la demande sans que le développeur s’en rende compte. Prisma et Sequelize proposent include et TypeORM propose relations. Les approches plus élaborées deviennent pertinentes lorsque la jointure ne suffit réellement plus."}}],[{"kind":"p","page":10,"text":{"en":"Why B is the trap (DataLoader): Beautiful pattern — but earns its keep in GraphQL where the resolver graph fans out in ways a single JOIN can't express. Here you have one list endpoint with one relation. A JOIN is strictly simpler and strictly faster. You're solving a problem you don't have and paying the complexity tax forever.","fr":"Pourquoi B est tentant, avec DataLoader ? Le patron a toute sa place dans GraphQL, lorsque le graphe des résolveurs se ramifie d’une manière qu’une seule jointure ne peut pas exprimer. Ici, un endpoint de liste n’a qu’une relation à charger. Une jointure est plus simple et plus rapide. Ajouter un DataLoader reviendrait à payer durablement la complexité d’un problème absent."}}],[{"kind":"p","page":11,"text":{"en":"Why C is wrong (Redis): Cache-first fixes the symptom, not the query pattern. You still issue 50 cache GETs per request, now own a cache invalidation problem every time a customer updates, and cold-hit every ID after a deploy. Cache is a scaling tool, not an N+1 tool.","fr":"Pourquoi C ne convient pas, avec Redis ? Consulter d’abord le cache masque le symptôme, tandis que le schéma de requêtes persiste. Vous exécutez encore 50 GET par appel. Il faut maintenant invalider le cache à chaque changement de client et gérer les défauts de cache pour tous les identifiants après un déploiement. Le cache sert à monter en charge. Le N+1 se traite au niveau des requêtes."}}],[{"kind":"p","page":11,"text":{"en":"Why D is the career-long argument (denormalize): Legitimate at Instagram scale. Also how you end up with a customer's maiden name three years after they got married because nobody wrote the update path. Denormalization is a write-amplification decision masquerading as a read-optimization. Do it when the JOIN genuinely can't hit your latency SLO at your scale — not before.","fr":"Pourquoi D fait débat, avec la dénormalisation ? C’est une approche légitime à l’échelle d’Instagram. C’est aussi comme ça qu’on affiche encore le nom de naissance d’une cliente trois ans après son mariage, faute de mise à jour prévue. Optimiser la lecture par dénormalisation augmente le travail à chaque écriture. Ce compromis se justifie quand une jointure ne permet réellement plus de tenir le SLO de latence à votre échelle."}}]]},{"day":3,"title":{"en":"Rate Limiting Without Boundary Bursts","fr":"Limiter le débit sans rafales aux changements de fenêtre"},"pages":[12,15],"topic":"scale","correct":"C","scenario":[{"kind":"figure","page":12,"id":"012-02","width":1731,"height":909,"alt":{"en":"Day 3 featured","fr":"Illustration de la question du jour 3"},"transcript":{"en":["System Design Labs","You run a SaaS API. POST /v1/messages is the money endpoint.","Customers keep getting 429s at minute boundaries.","Errors / Backpressure","SS was","Counters","Read / Update","POST","Forward","/v1/messages","API","Request","Rate Limiter","Allow","Write","Message","Database","Gateway","(Per API Key)","Service","(Primary)","Clients","Reject","Replicate","Fixed Window — bucket per (api_key, minute).","Sliding Window Log — store every request timestamp","Increment, check, reject. Simple, fast, one Redis","in Redis. Count requests in the last 60s on every call.","key per user.","Exact to the millisecond.","Token Bucket — 100 tokens per key, refill at","Leaky Bucket — queue incoming requests, dispatch","100/60 per second. Each request takes a token.","at a constant 1.66/sec. Excess requests wait or","Bursts up to 100, then shaped.","get dropped."],"fr":["System Design Labs","Vous exécutez une API SaaS. POST /v1/messages est le endpoint de l'argent.","Les clients continuent d'obtenir 429 à des limites de minutes.","Erreurs / Contre-pression","SS était","Compteurs","Lire / Mettre à jour","POST","En avant","/v1/messages","API","Demande","Limiteur de taux","Autoriser","Ecrire","Message","Base de données","Passerelle","(Par clé API)","Service","(primaire)","Clients","Rejeter","Répliquer","Fenêtre fixe — seau par (api_key, minute).","Journal de la fenêtre coulissante — stockez chaque horodatage de demande","Incrémenter, vérifier, rejeter. Simple, rapide, un Redis","Comptez les demandes dans les dernières années 60 à chaque appel.","clé par utilisateur.","Exact à la milliseconde.","Seau à jetons — 100 jetons par clé, recharge à","Leaky Bucket — file d'attente des demandes entrantes, expédition","100/60 par seconde. Chaque demande prend un jeton.","à une constante de 1,66/sec.","Poussée jusqu'à 100, puis mise en forme.","a tombe."]}},{"kind":"p","page":12,"text":{"en":"You run a SaaS API. POST /v1/messages is the money endpoint.","fr":"Vous exploitez une API SaaS. La route POST /v1/messages est celle qui génère le chiffre d’affaires."}},{"kind":"p","page":12,"text":{"en":"Plan limit: 100 requests/minute per API key. Customers keep getting 429s at minute boundaries even though their average RPS is well under the cap.","fr":"Chaque abonnement autorise 100 requêtes par minute et par clé API. Les clients reçoivent des erreurs HTTP 429 aux changements de minute, alors que leur débit moyen est bien inférieur au plafond."}},{"kind":"p","page":12,"text":{"en":"Here's what's happening in prod:","fr":"Voici ce qui se passe en production :"}},{"kind":"p","page":12,"text":{"en":"• 12:59:58 → customer sends 90 requests (batched job kicked off)","fr":"• 12:59:58 → le client envoie 90 requêtes au lancement d’un traitement par lots."}},{"kind":"p","page":12,"text":{"en":"• 13:00:02 → same customer sends 90 more (next tick)","fr":"• 13:00:02 → le même client en envoie 90 de plus au cycle suivant."}},{"kind":"p","page":12,"text":{"en":"• Your counter resets at 13:00:00","fr":"• Votre compteur repart de zéro à 13:00:00."}},{"kind":"p","page":12,"text":{"en":"• Both bursts pass. 180 requests in 4 seconds. Your downstream database starts crying.","fr":"• Les deux rafales passent. Avec 180 requêtes en 4 secondes, la base en aval commence à saturer."}},{"kind":"p","page":12,"text":{"en":"Now Support is on your back about 429s, and SRE is on your back about traffic spikes. You need to replace the limiter this week.","fr":"Le support vous remonte les erreurs 429 et l’équipe SRE vous alerte sur les pics de trafic. Vous devez remplacer le mécanisme de limitation cette semaine."}},{"kind":"p","page":12,"text":{"en":"FOUR OPTIONS ON THE TABLE:","fr":"QUATRE OPTIONS"}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":12,"text":{"en":"Fixed Window — bucket per (api_key, minute). Increment, check, reject. Simple, fast, one Redis key per user.","fr":"Fenêtre fixe. Un compteur par paire (api_key, minute). Incrémenter, contrôler puis rejeter au-delà du plafond. Simple, rapide et une clé Redis par utilisateur."}}]},{"letter":"B","blocks":[{"kind":"p","page":13,"text":{"en":"Sliding Window Log — store every request timestamp in Redis. Count requests in the last 60s on every call. Exact to the millisecond.","fr":"Journal à fenêtre glissante. Enregistrer dans Redis l’horodatage de chaque requête. À chaque appel, compter les requêtes des 60 dernières secondes, à la milliseconde près."}}]},{"letter":"C","blocks":[{"kind":"p","page":13,"text":{"en":"Token Bucket — 100 tokens per key, refill at 100/60 per second. Each request takes a token. Bursts up to 100, then shaped.","fr":"Seau à jetons. Prévoir 100 jetons par clé et en recréditer 100/60 par seconde. Une requête consomme un jeton. Une rafale peut en consommer jusqu’à 100 avant d’être limitée par le rythme de recharge."}}]},{"letter":"D","blocks":[{"kind":"p","page":13,"text":{"en":"Leaky Bucket — queue incoming requests, dispatch at a constant 1.66/sec. Excess requests wait or get dropped.","fr":"Seau percé. Mettre les requêtes entrantes en file et en traiter 1,66 par seconde à débit constant. Le surplus attend ou est rejeté."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"figure","page":14,"id":"014-03","width":1536,"height":1024,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["System Design Labs","Answer:","— Token Bucket","Token Bucket allows bursts up to the limit, then enforces a steady rate.","How Token Bucket works","Why it fixes the boundary-burst","Q Why C wins (Token Bucket):","Refill rate: 100/60 ~ 1.66 tokens/sec","Fixed Window (buggy)","Token Bucket (correct)","[v) Token Bucket is what AWS API Gateway, Stripe,","Burst: 90","90 tokens","GitHub, and basically every mature public API runs.","12:59:58","—> ALLOWED","consumed","requests","Each API key gets a bucket of 100 tokens, refilling","Incoming","request","oH","at ~1.66 tokens/sec. Every request takes a token.","13:00:00","Window","No reset.","Empty bucket = 429.","e-","— @ Allow","resets","Capacity","Bucket almost empty.","100 tokens","This fixes the boundary-burst bug exactly: no","Burst: 90","window resets. The 12:59:58 burst drains the","13:00:02","—> ALLOWED","Mostly denied","requests","(429s)","bucket, and 13:00:02 finds an almost-empty","Deny 429","bucket — not a shiny new 100-request allowance.","[v) O(1) memory per key, O(1) check, trivially distributed.","Each request takes 1 token.","180 requests in 4 seconds","Smooth rate ~1.66 req/sec","No token available? Return 429.","(Overload!)","(Backend stays healthy)","Why the other three trip up good engineers","Token Bucket","CA) Fixed Window","'B) Sliding Window Log","(D) Leaky Bucket","@ Handles bursts up to limit","© Resets at boundaries > bursts","@ Accurate to the millisecond","@ Smooth output rate","@ Smooths traffic over time","© Allows 2x limit in a short time","© Stores every request timestamp","@ O(1) memory, O(1) check","© Adds queuing delay","@ High memory & CPU at scale","© Unfair and spiky traffic","@ Easy to distribute","© Increases tail latency","© Expensive in Redis","© Complex under load","@ Industry standard","Good for simple, non-critical limits.","Overkill cost for little extra benefit.","Right balance of fairness,","Good for shaping internal traffic,","Not for money endpoints.","performance, and simplicity.","not for API rate limits."],"fr":["System Design Labs","Réponse :","Seau à jetons","Token Bucket permet des rafales jusqu'à la limite, puis impose un taux stable.","Comment fonctionne Token Bucket","Pourquoi il fixe la limite-éclat","Q Pourquoi retenir C (Token Bucket) :","Taux de recharge: 100/60 — 1.66 jetons/sec","Fenêtre fixe (buggy)","Seau à jetons (correct)","[v) Token Bucket est ce que AWS API Gateway, Stripe,","Explosion: 90","90 jetons","GitHub, et fondamentalement toutes les API publiques matures s'exécutent.","12:59:58","> AUTORISÉ","consommés","Demandes","Chaque clé API reçoit un seau de 100 jetons, rechargeant","Entrée","demande","oH","à — 1.66 tokens/sec. Chaque requête prend un token.","13:00:00","Fenêtre","Pas de réinitialisation.","Seau vide — 429.","e-","Permettre","reset","Capacité","Seau presque vide.","100 jetons","Ceci corrige le bug boundary-burst exactement : non","Explosion: 90","La fenêtre se réinitialise. La rafale 12:59:58 draine le","13:00:02","> AUTORISÉ","majoritairement démentie","Demandes","(429s)","seau, et 13:00:02 trouve un presque vide","Refuser 429","seau — pas une nouvelle allocation brillante de 100 demandes.","[v) O(1) mémoire par clé, O(1) vérification, trivialement distribué.","Chaque demande prend 1 jeton.","180 requêtes en 4 secondes","Taux lisse — 1.66 req/sec","Aucun jeton disponible? Retour 429.","(Surcharge !)","(Le backend reste en bonne santé)","Pourquoi les trois autres font appel à de bons ingénieurs","Seau à jetons","CA) Fenêtre fixe","'B) Journal de la fenêtre coulissante","(D) Seau qui fuit","Poignées éclate jusqu'à limiter","Réinitialise aux frontières > rafales","Précision à la milliseconde","débit de sortie lisse","Lisse le trafic au fil du temps","Permet 2x limite dans un court laps de temps","Stocke chaque horodatage de demande","O(1) mémoire, O(1) vérification","Ajoute un délai de file d'attente","Haute mémoire et CPU à l'échelle","Trafic inique et épineux","Facile à distribuer","Augmente la latence de queue","Logement entier à Redis","Complexe sous charge","Norme de l'industrie","Bon pour les limites simples et non critiques.","Coût excessif pour peu d'avantages supplémentaires.","Le juste équilibre de l’équité,","Bon pour façonner le trafic interne,","Pas pour les points de terminaison de l'argent.","performance et de simplicité.","Pas pour les limites de taux API."]}},{"kind":"p","page":14,"text":{"en":"Answer: C — Token Bucket ✅","fr":"Réponse C : seau à jetons ✅"}},{"kind":"p","page":14,"text":{"en":"Here's why, and why the other three trip up good engineers:","fr":"Voici pourquoi cette option fonctionne et ce que les trois autres peuvent masquer."}},{"kind":"p","page":14,"text":{"en":"Why C wins (Token Bucket):","fr":"Pourquoi retenir C, le seau à jetons ?"}},{"kind":"p","page":14,"text":{"en":"Token Bucket is what AWS API Gateway, Stripe, GitHub, and basically every mature public API runs. Each API key gets a bucket of 100 tokens, refilling at ~1.66 tokens/sec. Every request takes a token. Empty bucket = 429.","fr":"AWS API Gateway, Stripe, GitHub et la plupart des API publiques matures utilisent ce mécanisme. Chaque clé API dispose d’un seau de 100 jetons, rechargé d’environ 1,66 jeton par seconde. Une requête en dépense un. Seau vide : erreur HTTP 429."}},{"kind":"p","page":14,"text":{"en":"This fixes the boundary-burst bug exactly: no window resets. The 12:59:58 burst drains the bucket, and 13:00:02 finds an almost-empty bucket — not a shiny new 100-request allowance. O(1) memory per key, O(1) check, trivially distributed.","fr":"Cette approche élimine précisément les rafales aux changements de minute, car le compteur ne repart jamais de zéro. La rafale de 12:59:58 vide le seau. À 13:00:02, il est presque vide au lieu d’offrir un nouveau quota de 100 requêtes. Mémoire et vérification en O(1) par clé, avec une distribution simple."}}],[{"kind":"p","page":15,"text":{"en":"Why B is the trap (Sliding Window Log):","fr":"Pourquoi B est tentant, avec un journal à fenêtre glissante"}},{"kind":"p","page":15,"text":{"en":"Mathematically perfect — but stores one Redis entry per request per key. At 100k active keys you're looking at real memory pressure and p99 latency spikes. Smart engineers pick it without thinking about the memory cost. That's the tell.","fr":"Le calcul est exact, mais chaque requête occupe une entrée Redis pour la clé concernée. À 100 000 clés actives, la mémoire devient un problème et le p99 peut grimper. L’exactitude pousse parfois à oublier ce coût."}}],[{"kind":"p","page":15,"text":{"en":"Why A is wrong (Fixed Window):","fr":"Pourquoi A ne convient pas, avec une fenêtre fixe"}},{"kind":"p","page":15,"text":{"en":"Literally the bug in the post. Counter resets at the minute boundary → customers can burst 2x their limit in a 2-second window. Still the most common production mistake.","fr":"C’est le défaut décrit dans le scénario. Le compteur repart de zéro à la minute suivante. Un client peut donc envoyer deux fois son quota en deux secondes. C’est encore l’erreur la plus courante en production."}}],[{"kind":"p","page":15,"text":{"en":"Why D is wrong here (Leaky Bucket):","fr":"Pourquoi D ne convient pas ici, avec le seau percé"}},{"kind":"p","page":15,"text":{"en":"Solves a different problem — shapes output by queuing requests at a constant dispatch rate. Great for protecting a fragile downstream. Wrong for a customer-facing API because it adds latency to legitimate bursts. Token Bucket rejects excess; Leaky Bucket delays it. For a public API, reject > delay.","fr":"Le seau percé lisse le trafic sortant en vidant une file à débit constant. C’est utile pour protéger un service aval fragile, mais les rafales légitimes subissent une latence supplémentaire. Le seau à jetons rejette le surplus et le seau percé le retarde. Pour l’API publique de ce scénario, mieux vaut rejeter rapidement."}}]]},{"day":4,"title":{"en":"Preventing Duplicate Payment Charges","fr":"Éviter les doubles prélèvements"},"pages":[16,20],"topic":"data","correct":"B","scenario":[{"kind":"figure","page":16,"id":"016-02","width":800,"height":421,"alt":{"en":"Day 4 featured","fr":"Illustration de la question du jour 4"},"transcript":{"en":["Aretried payment request hit your API 3 times.","‘System Design Labs","Which approach actually prevents double-charges?","POST /payments","(ist attempt)","POST /payments","forward","charge","Mobile","POST /payments","Payments","Service","App","triggers","‘Add a unique constraint on (orderld, amount)","Require the client to send an idempotency-Key","in the payments table — the second insert","header; store the key + response and return the","fails, problem solved.","‘cached result on retry.","Put a distributed lock (Redis SETNX) around","‘Wrap the charge + DB write in a database","the payment handler keyed by orderld — only","transaction with SERIALIZABLE isolation —","fone request processes at a time.","‘concurrent writes can't both commit."],"fr":["La demande de paiement a été testée sur votre API 3 fois.","«System Design Labs","Quelle approche empêche réellement les doubles charges?","POST /paiements","(tentative)","POST /paiements","vers le haut","charge","Mobile","POST /paiements","Paiements","Service","App","déclencheurs","‘Ajouter une contrainte unique sur (orderld, montant)","Demander au client d'envoyer une clé idempotency","dans le tableau des paiements — le deuxième insérer","header; stocker la clé + réponse et retourner la","Échec, problème résolu.","«résultat en cache sur réessayer.","Placez un verrou distribué (Redis SETNX) autour","‘Envelopper la charge + écrire DB dans une base de données","le gestionnaire de paiement saisi par orderld — uniquement","transaction avec isolation SÉRIALISABLE","fone processus de demande à la fois.","Les écritures concurrentes ne peuvent pas toutes les deux s'engager."]}},{"kind":"p","page":16,"text":{"en":"A user taps \"Pay $499\" on checkout.","fr":"Au moment de payer, un utilisateur touche « Payer 499 $ »."}},{"kind":"p","page":16,"text":{"en":"The spinner hangs. They tap it again. And once more.","fr":"L’indicateur de chargement reste bloqué. L’utilisateur touche de nouveau le bouton, puis encore une fois."}},{"kind":"p","page":16,"text":{"en":"Three requests hit your Payments API. Two of them actually succeed. The customer is charged $1,497 and opens a support ticket before your on-call even sees the alert.","fr":"Trois requêtes atteignent votre API de paiement. Deux réussissent effectivement. Le client est débité de 1 497 $ et ouvre un ticket avant que l’équipe d’astreinte ne lise l’alerte."}},{"kind":"p","page":16,"text":{"en":"Here's the setup:","fr":"Voici la configuration."}},{"kind":"p","page":16,"text":{"en":"Mobile → POST /payments { orderId: \"ord_8821\", amount: 499 }","fr":"Mobile → POST /payments { orderId: \"ord_8821\", amount: 499 }"}},{"kind":"p","page":16,"text":{"en":"Network stalls on the first request → client retries twice","fr":"Le réseau se bloque sur la première requête → le client réessaie deux fois."}},{"kind":"p","page":16,"text":{"en":"Your service receives 3 near-identical POSTs within 4 seconds","fr":"Votre service reçoit trois POST presque identiques en quatre secondes."}},{"kind":"p","page":16,"text":{"en":"Stripe gets charged 3 times. Your DB writes 3 payment rows.","fr":"Trois prélèvements sont effectués via Stripe. La base enregistre trois lignes de paiement."}},{"kind":"p","page":16,"text":{"en":"You have one sprint to make sure a retried request never double-charges again. What do you do?","fr":"Vous avez un sprint pour empêcher qu’une nouvelle tentative débite de nouveau le client. Quelle approche choisissez-vous ?"}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":16,"text":{"en":"Add a unique constraint on (orderId, amount) in the payments table — the second insert fails, problem solved.","fr":"Ajouter une contrainte d’unicité sur (orderId, amount) dans payments. La deuxième insertion échoue, donc le problème paraît réglé."}}]},{"letter":"B","blocks":[{"kind":"p","page":17,"text":{"en":"Require the client to send an Idempotency-Key header; store the key + response and return the cached result on retry.","fr":"Exiger l’en-tête Idempotency-Key. Stocker la clé et la réponse, puis retourner la réponse mise en cache en cas de nouvelle tentative."}}]},{"letter":"C","blocks":[{"kind":"p","page":17,"text":{"en":"Put a distributed lock (Redis SETNX) around the payment handler keyed by orderId — only one request processes at a time.","fr":"Protéger le traitement du paiement par un verrou distribué Redis SETNX indexé par orderId. Une seule requête est traitée à la fois."}}]},{"letter":"D","blocks":[{"kind":"p","page":17,"text":{"en":"Wrap the charge + DB write in a database transaction with SERIALIZABLE isolation — concurrent writes can't both commit.","fr":"Grouper le prélèvement et l’écriture en base dans une transaction au niveau d’isolation SERIALIZABLE. Deux écritures concurrentes ne peuvent pas être validées toutes les deux."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"figure","page":18,"id":"018-03","width":800,"height":334,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["System Design","Answer.","—Idempotency-Key header @","‘The server does the work once, stores {key -> response}, and returns the same response on retries.","OST /payments","Idempotency-Key: 713","~ (ist attempt)","POST /payments","charge","we","Mobile","POST /payments","Payments","‘App","Gateway","Service","(retry)","3. On it: retun the cached","response (same status","2. On miss: proces paymont","+ Wait orth eu or","code + body). Do not","Idempotency","Store","(statu + body with ey","Neer so to eters","(ey response)","wth to same ay."],"fr":["Conception du système","Réponds.","Idempotency-Key header","Le serveur fait le travail une seule fois, stocke la réponse — key -> et retourne la même réponse à chaque nouvelle tentative.","OST /paiements","Clé d'identité: 713","(tentative)","POST /paiements","charge","nous","Mobile","POST /paiements","Paiements","«App","Passerelle","Service","(réessayer)","3. Sur elle : retun the cached","Réponse (même statut)","2. On miss: la vie est belle","+ Wait orth eu ou","code + corps). Ne","Idempotence","Stocker","(statu + corps avec ey","Neer so à eters","(Ey réponse)","Avec le même ay."]}},{"kind":"p","page":18,"text":{"en":"Answer: B — Idempotency-Key header ✅","fr":"Réponse B : en-tête Idempotency-Key ✅"}},{"kind":"p","page":18,"text":{"en":"Here's why, and why the other three are the exact mistakes I've seen in real post-mortems:","fr":"Les trois autres approches reproduisent des erreurs observées dans de vrais retours d’incident."}},{"kind":"p","page":18,"text":{"en":"Why B wins (Idempotency-Key):","fr":"Pourquoi retenir B, avec l’en-tête Idempotency-Key ?"}},{"kind":"p","page":18,"text":{"en":"The client generates a UUID before the first request and attaches it as Idempotency-Key: 7f3e... on every retry of that same logical operation. Your server does the work once, stores {key → response} in a durable store (Postgres, DynamoDB, Redis with persistence — not plain Redis), and on any retry with the same key, it returns the original response without re-executing the charge.","fr":"Le client génère un UUID avant le premier appel et renvoie le même en-tête Idempotency-Key: 7f3e... à chaque tentative de la même opération logique. Le serveur traite l’opération une seule fois et stocke l’association {key → response} dans un stockage durable, par exemple PostgreSQL, DynamoDB ou Redis avec persistance. Si la même clé revient, il restitue la réponse d’origine sans exécuter de nouveau le prélèvement."}},{"kind":"p","page":18,"text":{"en":"Critical detail most people miss: you cache the full response (status code + body), not just \"I saw this key.\" If retry #2 arrives while retry #1 is still processing, you make it wait or return a 409 — never let two executions race with the same key.","fr":"Un détail essentiel : conserver la réponse complète, code de statut et corps, et pas uniquement la trace du passage de la clé. Si la tentative nº 2 arrive pendant la première, la faire attendre ou renvoyer un 409. Deux traitements utilisant la même clé ne doivent jamais s’exécuter en parallèle."}},{"kind":"p","page":18,"text":{"en":"This is exactly what Stripe (Idempotency-Key), PayPal (PayPal-Request-Id), Shopify, and AWS (ClientRequestToken on half their APIs) all ship. It's the only approach that handles the full failure matrix: network retries, client-triggered retries, load balancer retries, and \"the request succeeded but the response got lost\" — which is the nastiest case and the one the other three options silently fail on.","fr":"Stripe (Idempotency-Key), PayPal (PayPal-Request-Id), Shopify et AWS (ClientRequestToken dans nombre de ses API) utilisent cette approche. Elle couvre les nouvelles tentatives déclenchées par le réseau, le client ou le répartiteur de charge, y compris le cas le plus délicat où la requête a réussi mais la réponse s’est perdue. Les trois autres solutions échouent silencieusement sur ce cas."}}],[{"kind":"p","page":19,"text":{"en":"Why A is the trap answer (unique constraint on orderId):","fr":"Pourquoi A est tentant, avec une contrainte d’unicité sur orderId"}},{"kind":"p","page":19,"text":{"en":"This is the answer I've seen in 4 different production codebases, and it's wrong for a subtle reason.","fr":"J’ai vu cette solution dans quatre bases de code en production. L’erreur est subtile."}},{"kind":"p","page":19,"text":{"en":"A unique constraint stops the second insert from committing — good. But what about the first charge to Stripe? In most implementations, you call Stripe's API first, then insert the payment row. So request #1 charges Stripe, DB insert succeeds. Request #2 charges Stripe again, then the DB insert fails with a constraint violation. The customer is now charged twice. Your DB looks clean. Your logs say \"duplicate order prevented.\"","fr":"La contrainte d’unicité empêche de valider la deuxième insertion. Mais que se passe-t-il côté Stripe ? La plupart des implémentations appellent d’abord Stripe, puis insèrent la ligne. La requête nº 1 débite le client et l’insertion aboutit. La nº 2 le débite de nouveau, puis l’insertion échoue sur la contrainte. Le client a payé deux fois. La base paraît saine et les logs disent que le doublon a été évité."}},{"kind":"p","page":19,"text":{"en":"Even if you flip the order (insert first, charge second), you've just moved the race condition — now retry #2 fails at the DB, but if retry #1 crashes between insert and charge, you have a payment row with no actual charge. Worse than double-charging. Silent money loss.","fr":"Inverser l’ordre des opérations déplace la condition de concurrence. La tentative nº 2 échoue bien en base. Pourtant, si la première s’arrête entre l’insertion et le prélèvement, la ligne subsiste sans paiement réel. C’est une perte d’argent silencieuse, pire encore que le double débit."}},{"kind":"p","page":19,"text":{"en":"A unique constraint is a great defense-in-depth layer. It is not the primary mechanism.","fr":"La contrainte d’unicité ajoute une bonne couche de défense. Le mécanisme principal doit couvrir l’opération de bout en bout."}}],[{"kind":"p","page":19,"text":{"en":"Why C is wrong (distributed lock):","fr":"Pourquoi C ne convient pas, avec un verrou distribué"}},{"kind":"p","page":19,"text":{"en":"A Redis lock on orderId serializes the 3 retries so only one runs at a time. Sounds clean. But it only solves the concurrent case. It doesn't help with sequential retries that arrive after the lock has already been released and the response was lost in transit.","fr":"Un verrou Redis sur orderId force les trois tentatives à s’exécuter l’une après l’autre. Il couvre la concurrence. En revanche, rien n’arrête une tentative ultérieure si le verrou a été libéré et que la réponse s’est perdue en route."}},{"kind":"p","page":19,"text":{"en":"Request #1 acquires lock, charges Stripe, releases lock, returns 200 — but the 200 never reaches the client because the connection died. Client retries 30 seconds later. The lock is long gone. You charge again.","fr":"La requête nº 1 prend le verrou, débite via Stripe, libère le verrou et renvoie 200. La connexion tombe et le client ne reçoit jamais le 200. Il réessaie 30 secondes après. Le verrou a disparu depuis longtemps et le client est débité une nouvelle fois."}},{"kind":"p","page":19,"text":{"en":"Distributed locks are for preventing concurrent execution. Idempotency is for preventing repeated execution across time. Different problems.","fr":"Les verrous distribués empêchent des exécutions simultanées. L’idempotence protège des réexécutions successives. Ce sont deux besoins distincts."}},{"kind":"p","page":19,"text":{"en":"Also: distributed locks are famously hard to get right. Martin Kleppmann's \"How to do distributed locking\" post exists for a reason. Don't reach for one unless you actually need the concurrency guarantee.","fr":"Les verrous distribués sont aussi notoirement difficiles à réaliser correctement. L’article « How to do distributed locking » de Martin Kleppmann en explique les pièges. Réservez-les aux cas qui exigent réellement cette garantie de concurrence."}}],[{"kind":"p","page":20,"text":{"en":"Why D is wrong (SERIALIZABLE transaction):","fr":"Pourquoi D ne convient pas, avec une transaction SERIALIZABLE"}},{"kind":"p","page":20,"text":{"en":"SERIALIZABLE isolation is about protecting the database from concurrent-write anomalies. It has nothing to say about the external side effect — the charge to Stripe. Your transaction can roll back and your DB can be pristine, but the HTTP POST to Stripe already went out, and that money is gone.","fr":"L’isolation SERIALIZABLE protège la base des anomalies d’écritures concurrentes. Le prélèvement Stripe reste un effet externe. Même si la transaction est annulée et que la base reste intacte, le POST HTTP est déjà parti et l’argent a été prélevé."}},{"kind":"p","page":20,"text":{"en":"This is the most common conceptual bug in the \"make payments safe\" category: treating the database as the boundary of correctness when the real boundary is the external side effect. The moment you call Stripe, the universe has changed. Your DB transaction can't un-change it.","fr":"L’erreur de raisonnement la plus courante consiste à prendre la base pour périmètre de la garantie, alors que celle-ci doit inclure l’effet externe. Dès l’appel Stripe, l’opération a pu changer le monde extérieur. Une annulation en base ne revient pas sur cet appel."}}]]},{"day":5,"title":{"en":"Choosing a Database Sharding Strategy","fr":"Choisir une stratégie de sharding pour une base de données"},"pages":[21,23],"topic":"data","correct":"C","scenario":[{"kind":"figure","page":21,"id":"021-02","width":800,"height":420,"alt":{"en":"Day 5 featured","fr":"Illustration de la question du jour 5"},"transcript":{"en":["‘system Design Labs","4 database sharding strategies. 4 completely different","scaling outcomes. One wrong choice and you're melting","a primary on Black Friday.","Orders (Primary)","Postgres","Web & Mobile","‘500M Rows+","Analytics","‘Service","‘tae","Hash sharding on order_id —","Range sharding on created_at —","‘even distribution, no hotspots.","keeps time-series queries local.","[4]","(a","Directory-based sharding —","Consistent hashing with virtual nodes —","[c)","lookup table maps customer to shard.","{a","easy rebalancing on scale-up."],"fr":["«système Design Labs","4 stratégies de sharding de base de données. 4 complètement différentes","Un mauvais choix et vous êtes en train de fondre","Une primaire le Black Friday.","Commandes (primaires)","Postgres","Web & Mobile","«500M rangées+","Analyses","«Service","«tae","Hash sharding sur order_id","Plage de découpage sur created_at","« Même distribution, pas de hotspots.","garde les requêtes de séries temporelles locales.","[4]","(a)","sharding basé sur répertoire","Hashing cohérent avec les nœuds virtuels","[c]","Liste des cartes de table client à éclater.","a","rééquilibrage facile sur scale-up."]}},{"kind":"p","page":21,"text":{"en":"4 database sharding strategies. 4 completely different scaling outcomes. One wrong choice and you're melting a primary on Black Friday.","fr":"Quatre stratégies de partitionnement, quatre comportements différents à grande échelle. Un mauvais choix peut saturer le primaire dès le Black Friday."}},{"kind":"p","page":21,"text":{"en":"Your Postgres orders table just crossed 500M rows.","fr":"La table orders de PostgreSQL vient de franchir 500 millions de lignes."}},{"kind":"p","page":21,"text":{"en":"Range scans that used to take 40ms are creeping past 800ms.","fr":"Les parcours par plage grimpaient autrefois à 40 ms. Ils dépassent maintenant les 800 ms."}},{"kind":"p","page":21,"text":{"en":"Vertical scaling is dead. You need to shard.","fr":"La mise à l’échelle verticale a atteint ses limites. Vous devez répartir les données sur plusieurs shards."}},{"kind":"p","page":21,"text":{"en":"Here is the workload:","fr":"Voici le profil de charge."}},{"kind":"p","page":21,"text":{"en":"• orders = 500M rows, growing 3M/week","fr":"• orders : 500 millions de lignes et 3 millions de plus par semaine."}},{"kind":"p","page":21,"text":{"en":"• 80% reads = \"customer X's last 30 days of orders\"","fr":"• 80 % de lectures : « commandes du client X sur les 30 derniers jours »."}},{"kind":"p","page":21,"text":{"en":"• 15% reads = analytics joins on date ranges","fr":"• 15 % de lectures : jointures analytiques sur des plages de dates."}},{"kind":"p","page":21,"text":{"en":"• 5% writes = new orders (steady 400 RPS, 2x on sale days)","fr":"• 5 % d’écritures : nouvelles commandes, 400 RPS en continu et le double les jours de promotion."}},{"kind":"p","page":21,"text":{"en":"Which strategy do you pick?","fr":"Quelle stratégie choisissez-vous ?"}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":21,"text":{"en":"Hash sharding on order_id — even distribution, no hotspots.","fr":"Sharding par hachage sur order_id. Répartition uniforme et aucun point chaud."}}]},{"letter":"B","blocks":[{"kind":"p","page":22,"text":{"en":"Range sharding on created_at — keeps time-series queries local.","fr":"Sharding par plage sur created_at. Les requêtes temporelles restent locales au shard."}}]},{"letter":"C","blocks":[{"kind":"p","page":22,"text":{"en":"Directory-based sharding — lookup table maps customer to shard.","fr":"Sharding par répertoire. Une table de correspondance indique le shard de chaque client."}}]},{"letter":"D","blocks":[{"kind":"p","page":22,"text":{"en":"Consistent hashing with virtual nodes — easy rebalancing on scale-up.","fr":"Hachage cohérent avec nœuds virtuels. Le rééquilibrage est facile quand on ajoute de la capacité."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"p","page":23,"text":{"en":"Answer: C — Directory-based sharding ✅","fr":"Réponse C : sharding par répertoire ✅"}},{"kind":"p","page":23,"text":{"en":"Here is why the other three trick smart engineers:","fr":"Voici ce qui rend les trois autres options trompeuses."}},{"kind":"p","page":23,"text":{"en":"Why C wins (Directory-based):","fr":"Pourquoi retenir C, le sharding par répertoire ?"}},{"kind":"p","page":23,"text":{"en":"80% of reads are \"customer X's orders.\" You want every order for a customer on exactly one shard. A customer-scoped read hits one node, no scatter-gather fan-out.","fr":"Les commandes d’un client représentent 80 % des lectures. Il faut placer toutes les commandes de ce client sur un seul shard. Une lecture ne sollicite alors qu’un nœud, sans requête distribuée dont il faudrait rassembler les résultats."}},{"kind":"p","page":23,"text":{"en":"You keep a customer_shard_map table (cached in Redis). If shard 3 gets hot, you migrate specific heavy customers (whales) without rehashing anything. Targeted rebalancing is the superpower. Figma, Notion, and Slack do this.","fr":"Une table customer_shard_map indique l’emplacement de chaque client et se met en cache dans Redis. Si le shard 3 devient trop sollicité, vous déplacez les clients les plus lourds sans recalculer le hachage des autres. C’est l’avantage du rééquilibrage ciblé. Figma, Notion et Slack y ont recours."}}],[{"kind":"p","page":23,"text":{"en":"Why A is the trap (Hash on order_id):","fr":"Pourquoi A est tentant, avec le hachage de order_id"}},{"kind":"p","page":23,"text":{"en":"The classic tutorial answer: \"Hash the primary key!\" It wrecks you here. A single customer's 200 orders scatter across all shards. Every read becomes a 4-shard fan-out gated by your slowest node. P99 latency goes up.","fr":"Les tutoriels proposent souvent de hacher la clé primaire. Ici, les 200 commandes d’un même client s’éparpillent sur tous les shards. Chaque lecture interroge quatre shards et attend le nœud le plus lent. Le p99 augmente."}}],[{"kind":"p","page":23,"text":{"en":"Why B is wrong (Range on created_at):","fr":"Pourquoi B ne convient pas, avec des plages sur created_at"}},{"kind":"p","page":23,"text":{"en":"Creates a hot shard by design. Every new order writes to the same shard. Your newest shard absorbs 100% of writes and 70% of reads. On Black Friday, this shard melts while others sit idle.","fr":"Le shard le plus récent devient un point chaud par construction : toutes les nouvelles commandes y sont écrites. Il absorbe 100 % des écritures et 70 % des lectures. Le Black Friday, il sature pendant que les autres attendent."}}],[{"kind":"p","page":23,"text":{"en":"Why D is wrong (Consistent hashing):","fr":"Pourquoi D ne convient pas ici, avec le hachage cohérent"}},{"kind":"p","page":23,"text":{"en":"Great for uniform data, but you can't migrate specific heavy tenants. If four whales land on the same shard, you are stuck.","fr":"Le hachage cohérent convient aux données uniformes, mais ne permet pas de déplacer certains clients lourds individuellement. Si quatre gros clients se retrouvent sur le même shard, vous ne pouvez pas les rééquilibrer finement."}}]]},{"day":6,"title":{"en":"Safe Distributed Locks for Cron Jobs","fr":"Sécuriser les verrous distribués des tâches cron"},"pages":[24,27],"topic":"reliability","correct":"A","scenario":[{"kind":"figure","page":24,"id":"024-02","width":800,"height":420,"alt":{"en":"Day 6 featured","fr":"Illustration de la question du jour 6"},"transcript":{"en":["‘System Design Labs","Your job scheduler runs on 3 instances behind an ALB.","Every 5 minutes, a cron fires the same job — and all 3 try to grab it","{Job Scheduler |","forward","acquire","process","= request > |","lock","job","Cron","ALB","(every 5 min)","Storage (D8)","Redis SETNX + short TTL + fencing token —","Redlock — acquire the lock across","monotonically increasing token the","5 independent Redis nodes,","downstream resource checks on every write.","majority wins.","|o","ac","DB-based pessi","ic lock —","Optimistic concurrency —no lock.","‘SELECT ... FOR UPDATE on a jobs table,","Each instance tries to insert the result","transaction holds the lock.","with a unique key; DB rejects duplicates.","|e"],"fr":["«System Design Labs","Votre emploi du temps fonctionne sur 3 instances derrière un ALB.","Toutes les 5 minutes, un cron déclenche le même travail - et tous les 3 essaient de l'attraper.","Job Scheduler","vers le haut","acquérir","processus","demande >","serrure","emploi","Cron","ALB","(toutes les 5 min)","Stockage (D8)","Redis SETNX + court TTL + jeton de fencing","Redlock — acquiert la serrure à travers","monotoniquement croissante, la","5 nœuds Redis indépendants,","contrôle des ressources en aval à chaque écriture.","La majorité gagne.","o","ac","Pessi à base de DB","ic lock","Concurrence optimiste : pas de verrou.","«SÉLECTIONNEZ ... POUR MISE À JOUR sur une table d'emplois,","Chaque instance tente d'insérer le résultat","La transaction tient le verrou.","avec une clé unique ; DB rejette les doublons.","e"]}},{"kind":"p","page":24,"text":{"en":"Your job scheduler runs on 3 instances behind an ALB.","fr":"Votre planificateur de tâches tourne sur trois instances derrière un ALB."}},{"kind":"p","page":24,"text":{"en":"Every 5 minutes, a cron fires the same \"generate-daily-report\" job — and all 3 instances try to grab it.","fr":"Toutes les cinq minutes, cron déclenche la même tâche « generate-daily-report ». Les trois instances essaient de la prendre en charge."}},{"kind":"p","page":24,"text":{"en":"You reach for the classic fix: a Redis SETNX lock.","fr":"Vous employez la solution classique, un verrou Redis SETNX."}},{"kind":"p","page":24,"text":{"en":"SET job:daily-report locked NX EX 300 → only one instance wins. Done.","fr":"SET job:daily-report locked NX EX 300 → une seule instance prend le verrou."}},{"kind":"p","page":24,"text":{"en":"Works perfectly for a month. Until 2am on a Saturday.","fr":"Tout fonctionne pendant un mois. Puis arrive un samedi, à 2 h du matin."}},{"kind":"p","page":24,"text":{"en":"Instance B wins the lock. Starts the job. 60 seconds in, the pod gets OOM-killed. The lock is still there. TTL says 300 seconds. The report runs once every 5 minutes.","fr":"L’instance B prend le verrou et lance la tâche. Au bout de 60 secondes, son pod est arrêté faute de mémoire. Le verrou existe toujours, avec un TTL de 300 secondes. Le rapport tourne toutes les cinq minutes."}},{"kind":"p","page":24,"text":{"en":"Nothing processes that report for 4 more minutes. Then instance A grabs it — but instance B's pod restarted and it's ALSO trying to run it now. Both instances processing the same job.","fr":"Personne ne traite le rapport pendant quatre minutes de plus. L’instance A prend alors le verrou. Le pod B a redémarré et tente lui aussi de relancer la tâche. Deux instances travaillent sur le même rapport."}},{"kind":"p","page":24,"text":{"en":"Worse: a slow GC pause on instance A makes it hold the lock past TTL. Redis quietly hands the lock to instance C. Now A thinks it owns the lock. C also thinks it owns the lock. Both write to the same output.","fr":"Pire, une longue pause du ramasse-miettes fait dépasser à A le TTL de son verrou. Redis l’accorde silencieusement à C. Les deux instances pensent détenir le verrou et écrivent au même endroit."}},{"kind":"p","page":24,"text":{"en":"What's the right pattern here?","fr":"Quel patron choisir ici ?"}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":25,"text":{"en":"Redis SETNX + short TTL + fencing token — monotonically increasing token the downstream resource checks on every write.","fr":"Redis SETNX, un TTL court et un jeton de fencing. La ressource en aval vérifie ce jeton, dont la valeur augmente à chaque acquisition, à chaque écriture."}}]},{"letter":"B","blocks":[{"kind":"p","page":25,"text":{"en":"Redlock — acquire the lock across 5 independent Redis nodes, majority wins.","fr":"Redlock. Acquérir le verrou sur cinq nœuds Redis indépendants et obtenir la majorité."}}]},{"letter":"C","blocks":[{"kind":"p","page":25,"text":{"en":"DB-based pessimistic lock — SELECT ... FOR UPDATE on a jobs table, transaction holds the lock.","fr":"Verrouillage pessimiste en base. Faire un SELECT ... FOR UPDATE sur la table des tâches et conserver le verrou dans la transaction."}}]},{"letter":"D","blocks":[{"kind":"p","page":25,"text":{"en":"Optimistic concurrency — no lock. Each instance tries to insert the result with a unique key; DB rejects duplicates.","fr":"Contrôle de concurrence optimiste. Pas de verrou : chaque instance tente d’insérer le résultat avec une clé unique et la base rejette les doublons."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"figure","page":26,"id":"026-03","width":800,"height":533,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["System Design Lab:","A— SETNX + short TTL + fencing token @","Returns lock","Job Scheduler","“Try acquire lock","instances)","+ fencing token","Downstream","Process","Resource","Redis","[> | 43","Yin ook","job","(08 / Storage)","SET pty epee","Every 5 minutes","@ nolock","Accept write","cron fires","if token >","as","last seen token","© nolock","Instance ©","Why this survives f","res","Key guarantee","the lock holder sori used,","the odinstance wakes up and es","‘The downstream resource","the TTL expires","© Pretnarinstance acquis the ok","nd gets a higher token (9. 44)","twit with token 43, the resource","Ie the source of truth,","rejacts it Only the highest token wns,","not the lock service","Why the others fail in the scenario","ist","lock","+ Stil time-based and unsafe under","If the process des, the DB locks","Provents duplicate final ents,","released — good.","but al instances stl do the work.","process pauses and partons.","+ But along GC pause can stil overlap","+ Martin Kieppmann showed how it can","work, causing duplicate side effects","Wastes resources ad can overwhelm","grant the lock to muitipe cents","Only A (SETNX + short TTL + fencing token) provides correctness under pauses, failures, and partitions.","The fencing token makes the downstream resource the final authority."],"fr":["Laboratoire de conception de système :","A — SETNX + TTL court + jeton de fencing","Retourne le verrou","Job Scheduler","« Essayez d’acquérir le verrou","cas)","+ jeton de fencing","En aval","Processus","Ressource","Redis","[> | 43","Yin ook","emploi","(08 / Stockage)","SET ptyepe","Toutes les 5 minutes","nolock","Accepter l'écriture","cron fires","Si jeton >","en","Dernière vue Token","nolock","Instance","Pourquoi cela survit f","res","Garantie clé","le porte-serrure sori utilisé,","l'odinstance se réveille et es","« La ressource en aval","le TTL expire","Pretnarinstance acquis l'ok","nd obtient un jeton supérieur (9. 44)","twit avec le jeton 43, la ressource","La source de la vérité,","Il n'y a que les plus hauts jetons,","Pas le service de serrure","Pourquoi les autres échouent dans le scénario","ist","serrure","+ Stil basé sur le temps et dangereux","Si le processus des, les verrous DB","Les provendes dupliquent les ents finaux,","Libéré - bien.","mais tous les cas stl faire le travail.","pauses et partons.","+ Mais le long de la pause GC peut stil chevauchement","+ Martin Kieppmann a montré comment il peut","travail, provoquant des effets secondaires en double","Les déchets de ressources peuvent submerger","Accorder la serrure à Muitipe Cents","Seul A (SETNX + short TTL + jeton de fencing) fournit l'exactitude sous les pauses, les échecs et les partitions.","Le jeton de fencing fait de la ressource en aval l'autorité finale."]}},{"kind":"p","page":26,"text":{"en":"Answer: A — SETNX + short TTL + fencing token ✅","fr":"Réponse A : SETNX, TTL court et jeton de fencing ✅"}},{"kind":"p","page":26,"text":{"en":"Here's why, and why the other three trick smart engineers:","fr":"Voici pourquoi cette approche fonctionne et où les trois autres peuvent induire en erreur."}},{"kind":"p","page":26,"text":{"en":"Why A wins (SETNX + TTL + fencing token):","fr":"Pourquoi retenir A, avec SETNX, un TTL et un jeton de fencing ?"}},{"kind":"p","page":26,"text":{"en":"A lock alone can't protect a distributed resource. You need to assume the lock holder might be dead, paused, or partitioned — and the lock might get reassigned while they still think they own it. This is exactly the scenario above: GC pause, TTL expires, Redis gives the lock to someone else, original owner wakes up and keeps writing.","fr":"Un verrou seul ne protège pas une ressource distribuée. Son détenteur peut s’arrêter, être suspendu ou se retrouver isolé par une partition réseau. Le verrou peut être réattribué alors que le détenteur le croit encore valable. Ici, la collecte de mémoire suspend le processus, le TTL expire, Redis attribue le verrou à une autre instance et le premier détenteur reprend ses écritures au réveil."}},{"kind":"p","page":26,"text":{"en":"The fencing token fixes it. Every time a lock is acquired, Redis (or the lock service) hands out a monotonically increasing number — 42, 43, 44. The downstream resource (the DB, the storage system, the output queue) remembers the highest token it's seen and rejects any write with a lower token.","fr":"Le jeton de fencing règle ce problème. À chaque acquisition, Redis ou le service de verrouillage attribue un numéro strictement croissant, par exemple 42, 43, puis 44. La ressource en aval (base, stockage ou file de sortie) mémorise le plus grand jeton reçu et refuse toute écriture portant un jeton inférieur."}},{"kind":"p","page":26,"text":{"en":"So when instance A wakes up from its GC pause holding token 42, and instance C is already writing with token 43, A's write gets rejected by the DB itself. The resource is the source of truth — not the lock service.","fr":"Quand A reprend après la pause du ramasse-miettes avec le jeton 42, C écrit déjà avec le jeton 43. La base refuse elle-même les écritures d’A. La ressource fait foi, indépendamment du service de verrouillage."}},{"kind":"p","page":27,"text":{"en":"This is what Google's Chubby does. It's what Martin Kleppmann recommends in \"How to do distributed locking.\" It's the only pattern on this list that's actually safe against process pauses.","fr":"C’est le mécanisme employé par Chubby chez Google et recommandé par Martin Kleppmann dans « How to do distributed locking ». Parmi les propositions, c’est la seule qui protège contre les pauses du processus."}}],[{"kind":"p","page":27,"text":{"en":"Why B is the trap answer (Redlock):","fr":"Pourquoi B est tentant, avec Redlock"}},{"kind":"p","page":27,"text":{"en":"Redlock is the pattern most senior engineers reach for. It looks rigorous. Martin Kleppmann wrote a now-famous post (2016) showing Redlock is unsafe in the exact scenario above: any process can pause long enough to lose its lock without noticing.","fr":"Beaucoup d’ingénieurs expérimentés se tournent vers Redlock, qui paraît rigoureux. Dans un article de 2016, Martin Kleppmann montre qu’il ne protège pas du scénario décrit. N’importe quel processus peut être suspendu assez longtemps pour perdre le verrou sans s’en apercevoir."}},{"kind":"p","page":27,"text":{"en":"More importantly — Redlock without a fencing token has the same fundamental flaw as SETNX. If your resource can't verify a token on write, Redlock doesn't save you. You're maintaining 5 Redis clusters for a problem a fencing token solves on 1.","fr":"Sans jeton de fencing, Redlock présente le même défaut fondamental que SETNX. Si la ressource ne vérifie pas de jeton à l’écriture, Redlock n’apporte pas la garantie voulue. Vous maintenez cinq clusters Redis pour un problème qu’un seul jeton permet de résoudre avec un cluster."}}],[{"kind":"p","page":27,"text":{"en":"Why C is wrong (DB pessimistic lock):","fr":"Pourquoi C ne convient pas, avec un verrou pessimiste en base"}},{"kind":"p","page":27,"text":{"en":"SELECT ... FOR UPDATE inside a transaction works — for tiny critical sections. The lock auto-releases when the transaction ends or the connection dies.","fr":"SELECT ... FOR UPDATE dans une transaction fonctionne pour une section critique très courte. Le verrou se libère automatiquement à la fin de la transaction ou si la connexion tombe."}},{"kind":"p","page":27,"text":{"en":"But the lock lives inside a single DB transaction. If your job is \"generate a daily report\" that takes 60 seconds of S3 writes and external API calls, you're holding a row lock on your primary DB for 60 seconds per job. Connection pool starved. Every other query blocked behind it.","fr":"Le verrou reste attaché à une seule transaction. Si la génération du rapport prend 60 secondes d’écritures S3 et d’appels d’API externes, vous gardez un verrou de ligne sur le primaire pendant 60 secondes par tâche. Le pool de connexions s’épuise et les requêtes concurrentes attendent."}}],[{"kind":"p","page":27,"text":{"en":"Why D is wrong here (optimistic concurrency):","fr":"Pourquoi D ne convient pas ici, avec le contrôle de concurrence optimiste"}},{"kind":"p","page":27,"text":{"en":"Optimistic concurrency is beautiful when it fits — no lock service, no lock holder, no stale-lock problem. Each instance tries the operation; the DB unique constraint rejects losers.","fr":"La concurrence optimiste convient bien à certaines opérations. Elle élimine le service de verrouillage, le détenteur et les verrous périmés. Chaque instance tente l’écriture et la contrainte d’unicité départage les tentatives."}},{"kind":"p","page":27,"text":{"en":"It breaks when the work isn't idempotent or isn't a single write. Three instances racing to do all of that means triple the S3 writes, triple the Slack pings, triple the compute cost.","fr":"Elle atteint ses limites si le travail n’est pas idempotent ou ne se résume pas à une écriture. Trois instances peuvent tripler les écritures S3, les notifications Slack et le coût du calcul."}}]]},{"day":7,"title":{"en":"Event Ordering in a Message Queue","fr":"Garantir l’ordre des événements dans une file de messages"},"pages":[28,31],"topic":"events","correct":"A","scenario":[{"kind":"figure","page":28,"id":"028-02","width":800,"height":421,"alt":{"en":"Day 7 featured","fr":"Illustration de la question du jour 7"},"transcript":{"en":["System Design Labs","Events arrive out of order on SQS standard.","What do 7 do before Monday?","Events","order.created","| order-eancelled","'5 Workers (consumers)","(0 ordering","guarantee) >","Client","sas","Postgres","(standard)","Keep standard SQS, add a sequence number +","‘Switch to SQS FIFO + MessageGroupld","reorder buffer in the consumer — hold out-of-order","per order_id — let AWS handle ordering per order.","events until the earlier ones arrive.","Replace the event stream with a Saga —","‘Add an event version/timestamp and make","each step waits for the previous step's","the state machine idempotent + order-agnostic —","completion signal before firing the next.","reject stale transitions, accept any arrival order."],"fr":["System Design Labs","Les événements arrivent hors service sur la norme SQS.","Que faire avant lundi ?","Événements","Order.Created","ordre-eancelled","«5 Travailleurs (consommateurs)","(0 commande","garantie) >","Client","sas","Postgres","(standard)","Conserver le SQS standard, ajouter un numéro de séquence +","‘Switch to SQS FIFO + MessageGroupld","reorder tampon dans le consommateur — tenir hors-commande","par order_id — permet à AWS de gérer les commandes par commande.","événements jusqu'à l'arrivée des précédents.","Remplacer le flux d'événements par une Saga","‘Ajouter une version/horodatage d’événement et faire","chaque étape attend l'étape précédente","la machine d'état idempotent + ordre-agnostique","signal d'achèvement avant de tirer le suivant.","rejeter les transitions périmées, accepter tout ordre d'arrivée."]}},{"kind":"p","page":28,"text":{"en":"Your order service publishes 3 events per order: created, paid, cancelled.","fr":"Votre service de commandes publie trois événements par commande : created, paid et cancelled."}},{"kind":"p","page":28,"text":{"en":"Standard SQS queue, 5 consumers, ~2K orders/minute at peak.","fr":"Une file SQS standard, cinq consommateurs, environ 2 000 commandes par minute au pic."}},{"kind":"p","page":28,"text":{"en":"Last night, prod alerted: 47 orders stuck in \"cancelled\" state with no \"created\" record. Customers got refunded for orders that were never marked as placed. Finance is not happy.","fr":"Hier soir, une alerte est remontée de production. 47 commandes restent bloquées à l’état « cancelled » sans trace de création. Des clients ont été remboursés pour des commandes qui n’avaient jamais été enregistrées comme passées. L’équipe finance est mécontente."}},{"kind":"p","page":28,"text":{"en":"You dig in. The order was placed, paid, and cancelled within 400ms. Three messages hit SQS in order. Three consumers picked them up in parallel. \"cancelled\" got processed first. State machine rejected \"created\" as invalid. Data is now wrong.","fr":"Vous enquêtez. La commande a été passée, payée et annulée en moins de 400 ms. Les trois messages sont arrivés dans l’ordre dans SQS, puis trois consommateurs les ont pris en parallèle. « cancelled » a été traité en premier et la machine à états a refusé « created », jugé invalide. Les données sont incohérentes."}},{"kind":"p","page":28,"text":{"en":"Here's the setup:","fr":"Voici la configuration."}},{"kind":"p","page":28,"text":{"en":"OrderService → SQS (standard) → 5 workers → Postgres","fr":"OrderService → SQS (standard) → 5 workers → PostgreSQL"}},{"kind":"p","page":28,"text":{"en":"Events: order.created → order.paid → order.cancelled","fr":"Événements : order.created → order.paid → order.cancelled"}},{"kind":"p","page":28,"text":{"en":"Problem: workers process in parallel, SQS standard doesn't guarantee order, downstream state machine breaks when events arrive out of sequence.","fr":"Les workers travaillent en parallèle. SQS standard ne garantit pas l’ordre et la machine à états en aval échoue si les événements arrivent dans le désordre."}},{"kind":"p","page":28,"text":{"en":"You have until Monday. What do you do?","fr":"Vous avez jusqu’à lundi. Que choisissez-vous ?"}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":29,"text":{"en":"Switch to SQS FIFO + MessageGroupId per order_id — let AWS handle ordering per order.","fr":"Passer à SQS FIFO avec un MessageGroupId par order_id, pour confier à AWS l’ordre par commande."}}]},{"letter":"B","blocks":[{"kind":"p","page":29,"text":{"en":"Keep standard SQS, add a sequence number + reorder buffer in the consumer — hold out-of-order events until the earlier ones arrive.","fr":"Conserver SQS standard et ajouter un numéro de séquence et un tampon de réordonnancement côté consommateur. Les événements en avance attendent les précédents."}}]},{"letter":"C","blocks":[{"kind":"p","page":29,"text":{"en":"Replace the event stream with a Saga — each step waits for the previous step's completion signal before firing the next.","fr":"Remplacer le flux d’événements par une saga. Chaque étape attend le signal de fin de la précédente avant de démarrer."}}]},{"letter":"D","blocks":[{"kind":"p","page":29,"text":{"en":"Add an event version/timestamp and make the state machine idempotent + order-agnostic — reject stale transitions, accept any arrival order.","fr":"Ajouter une version d’événement ou un horodatage. Rendre la machine à états idempotente et indépendante de l’ordre d’arrivée, en refusant les transitions obsolètes."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"figure","page":30,"id":"030-03","width":800,"height":245,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["Per-order ordering guaranteed. High throughput. Minimal changes. Ship it Monday.","‘Amazon SQS FIFO Queve","MessageGroupid = order id","| workers","publish","write","Publishes 3 events","© ordorcrosted","Postgres","FIFO guarantees order within the same MessageGroupi","‘Oniy ante sosmumner procusenn a grup at a tine."],"fr":["Commande par commande garantie. Débit élevé. Changements minimes. Expédiez-le lundi.","«Amazon SQS FIFO Queve","MessageGroupid — identifiant de commande","travailleurs","publier","écrire","Publie 3 événements","ordorcrosted","Postgres","FIFO garantit l'ordre dans le même MessageGroupi","«Oniy ante sosmumner propose un grup à une dent."]}},{"kind":"p","page":30,"text":{"en":"✅ Answer: A — SQS FIFO + MessageGroupId per order_id","fr":"✅ Réponse A : SQS FIFO et MessageGroupId par order_id"}},{"kind":"p","page":30,"text":{"en":"Why A wins:","fr":"Pourquoi A fonctionne"}},{"kind":"p","page":30,"text":{"en":"You don't need global ordering — you need per-order ordering. Set MessageGroupId = order_id. FIFO guarantees messages with the same group ID are delivered in exact send order, with only one consumer processing that group at a time. Your 2K orders/min still fan out across 5 workers — throughput is unchanged. Order #12345's created → paid → cancelled always lands in sequence. Cost: a few ms latency. Ship it Monday.","fr":"Seul l’ordre à l’intérieur de chaque commande vous intéresse. Définissez MessageGroupId = order_id. FIFO remet les messages d’un même groupe dans leur ordre d’envoi, avec un seul consommateur à la fois par groupe. Vos 2 000 commandes par minute restent distribuées entre cinq workers, au même débit. Pour la commande nº 12345, created, paid puis cancelled seront toujours traités dans l’ordre. Le coût est de quelques millisecondes de latence. Livrez lundi."}}],[{"kind":"p","page":30,"text":{"en":"Why B is the trap (reorder buffer):","fr":"Pourquoi B est tentant, avec un tampon de réordonnancement"}},{"kind":"p","page":30,"text":{"en":"Fools senior engineers on the whiteboard. You'd end up building: in-memory buffer per order_id + TTL logic + dead-letter path for gaps + crash recovery + stuck buffer monitoring. You just rebuilt FIFO in app code. With more bugs. And you own every edge case. B is valid only when you can't use FIFO (e.g. Kafka with a taken partition key). That's not this situation.","fr":"Sur un tableau blanc, même des ingénieurs expérimentés se laissent tenter. Il faut pourtant créer un tampon mémoire par order_id, gérer les TTL, définir un circuit de rejet pour les messages manquants, gérer la reprise et surveiller les tampons bloqués. C’est réimplémenter FIFO dans l’application, avec davantage de bogues et de cas limites à gérer. B est utile si vous ne pouvez pas employer FIFO, par exemple si la clé de partition Kafka est déjà imposée. Ce n’est pas le cas ici."}}],[{"kind":"p","page":30,"text":{"en":"Why C is wrong (Saga):","fr":"Pourquoi C ne convient pas, avec une saga"}},{"kind":"p","page":30,"text":{"en":"Saga is for long-running distributed transactions with compensating actions (book flight → charge card → reserve hotel). Your problem is a state stream for one entity — not a multi-service transaction. Forcing it into a Saga turns async events into sync RPC, increases coupling, and still doesn't fix ordering.","fr":"Une saga sert aux transactions distribuées de longue durée avec compensation, comme réserver un vol, débiter une carte puis réserver un hôtel. Vous suivez l’état d’une seule entité. Une saga transformerait des événements asynchrones en RPC synchrones, augmenterait le couplage et laisserait le problème d’ordre entier."}}],[{"kind":"p","page":31,"text":{"en":"Why D is wrong (event versioning):","fr":"Pourquoi D ne convient pas, avec le versionnement des événements"}},{"kind":"p","page":31,"text":{"en":"Partially works — but you'd drop legitimate events. \"cancelled\" arrives first, moves state forward, then \"created\" gets rejected. DB says order is cancelled with no creation record. To make D work correctly you need full event sourcing (6-month rewrite, not a Monday fix).","fr":"Cela fonctionne en partie, mais écarte des événements valables. « cancelled » arrive d’abord et fait avancer l’état, puis « created » est refusé. La base indique une annulation sans trace de création. Il faudrait de l’event sourcing de bout en bout pour résoudre correctement le problème avec D. Comptez six mois de réécriture, pas une livraison lundi."}}]]},{"day":8,"title":{"en":"Keeping Cache and Database in Sync","fr":"Synchroniser le cache et la base de données"},"pages":[32,35],"topic":"data","correct":"C","scenario":[{"kind":"figure","page":32,"id":"032-02","width":800,"height":421,"alt":{"en":"Day 8 featured","fr":"Illustration de la question du jour 8"},"transcript":{"en":["E-commerce product catalog. Redis in front of Postgres.","[\\, system Design Labs","at peak. Cache is leaking stale data in production","mp","Requests","(Cache Hit)","Ga","Clients","(Nodejs)","Data","(Cache)","Redis","Data","(Source of Truth)","Postgres","Adin Pane","Inventory Service","Price Updates)","ce",") (oa","‘Write-through — every write hits cache and","Postgres in the same transaction. Cache is never stale.","‘async worker flushes to Postgres in batches.","‘Write-behind (write-back) — writes land in Redis first,","Postgres, invalidates the cache key, lets the next","Cache-aside (lazy loading) — app writes directly to","Read: through — Redis sits inline, handles its own","ead repopulate,","misses, pulls from Postgres when needed."],"fr":["Catalogue de produits e-commerce. Redis devant Postgres.","[ — , system Design Labs","au pic. Le cache fuit des données périmées en production","mp","Demandes","(Cache Hit)","Ga","Clients","(Nodejs)","Données","(Cache)","Redis","Données","(Source de la vérité)","Postgres","Adin Pane","Service des stocks","Mises à jour des prix)","ce","(oa)","\"Ecrire-à travers - chaque écriture frappe cache et","Postgres dans la même transaction. Le cache n'est jamais vicié.","Le travailleur async affleure à Postgres par lots.","‘Write-behind (write-back) — écrit d’abord la terre dans Redis,","Postgres, invalide la clé de cache, laisse la prochaine","Cache-aside (chargement paresseux) — l'application écrit directement à","Lire: à travers — Redis s'assied en ligne, gère son propre","Ead repeupler,","Misses, tire de Postgres si nécessaire."]}},{"kind":"p","page":32,"text":{"en":"E-commerce product catalog. Redis in front of Postgres. 40K RPS at peak.","fr":"Un catalogue e-commerce. Redis devant PostgreSQL. 40 000 RPS au pic."}},{"kind":"p","page":32,"text":{"en":"In staging, cache hit ratio sits at 94%. Response times under 20ms. Everything looks clean.","fr":"En préproduction, 94 % des lectures aboutissent dans le cache et les réponses prennent moins de 20 ms. Tout semble prêt."}},{"kind":"p","page":32,"text":{"en":"Ship to prod. Within 48 hours, support tickets start rolling in. Customers seeing wrong prices. Old stock counts. Products showing \"available\" that shipped out three hours ago.","fr":"Vous déployez en production. Dans les 48 heures, les tickets affluent. Les clients voient des prix erronés, d’anciens niveaux de stock et des articles « disponibles » alors que le dernier exemplaire est parti il y a trois heures."}},{"kind":"p","page":32,"text":{"en":"Here's the setup:","fr":"Voici la configuration."}},{"kind":"p","page":32,"text":{"en":"App (Node.js) → Redis (cache) → Postgres (source of truth)","fr":"Application (Node.js) → Redis (cache) → PostgreSQL (source de vérité)"}},{"kind":"p","page":32,"text":{"en":"Writes come from: admin panel (price updates), inventory service (stock decrements), order service (purchase events).","fr":"Écritures : interface d’administration pour les prix, service d’inventaire pour décrémenter les stocks, service de commandes pour les achats."}},{"kind":"p","page":32,"text":{"en":"Reads come from: product pages, search results, checkout flow.","fr":"Lectures : fiches produit, résultats de recherche et parcours de paiement."}},{"kind":"p","page":32,"text":{"en":"The cache is leaking stale data in production. Your team is debating the invalidation strategy. What do you ship?","fr":"Le cache renvoie des données périmées en production. L’équipe débat d’une stratégie d’invalidation. Laquelle livrez-vous ?"}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":32,"text":{"en":"Write-through — every write hits cache and Postgres in the same transaction. Cache is never stale.","fr":"Write-through. Chaque écriture touche le cache et PostgreSQL dans la même transaction. Le cache ne devient jamais obsolète."}}]},{"letter":"B","blocks":[{"kind":"p","page":33,"text":{"en":"Write-behind (write-back) — writes land in Redis first, async worker flushes to Postgres in batches.","fr":"Write-behind (write-back). Les écritures arrivent d’abord dans Redis, puis un worker les persiste en lots dans PostgreSQL."}}]},{"letter":"C","blocks":[{"kind":"p","page":33,"text":{"en":"Cache-aside (lazy loading) — app writes directly to Postgres, invalidates the cache key, lets the next read repopulate.","fr":"Cache-aside (chargement à la demande). L’application écrit directement dans PostgreSQL, invalide la clé en cache et laisse la prochaine lecture la recréer."}}]},{"letter":"D","blocks":[{"kind":"p","page":33,"text":{"en":"Read-through — Redis sits inline, handles its own misses, pulls from Postgres when needed.","fr":"Read-through. Redis s’insère dans le circuit des lectures, gère les défauts de cache et charge depuis PostgreSQL au besoin."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"figure","page":34,"id":"034-03","width":800,"height":370,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["ANSWER:","— Cache-aside (lazy loading)","B ‘System Design Labs","App writes to Postgres — invalidates Redis > next read repopulates.","Why C Wins","cache Miss","© Multiple w","rs update","Postgres independently.","Clients","© Each writer invalidates","(Cache)","Redis, Next re","repopulates fresh data.","© Postgres remains the","1. Write to Postgres","single source of truth","@ Redis is disposable. if it","dies, the app still works.","(correct, just slower).","‘Admin Pane","Inventory Service","Order Service","© Battle-tested by Shopity,","Price Updates)","(Stock Decrements)","archase Events)","Etsy, and AWS reference","Postgres","architectures.","(Source of Truth)"],"fr":["RÉPONSE :","Cache-cache (chargement paresseux)","B ‘ System Design Labs","L'application écrit dans Postgres — invalide Redis > next read repeuplates.","Pourquoi C Gagne","cache Miss","Multiple w","rs mise à jour","PostgreSQL indépendamment.","Clients","Chaque écrivain invalide","(Cache)","Redis, Prochaine re","repeuple de nouvelles données.","Postgres reste le","1. Écrire à Postgres","Une seule source de vérité","Redis est jetable.","L'app fonctionne toujours.","(correct, juste plus lent).","«Panneau d’administration","Service des stocks","Service de commande","Testé par Shopity,","Mises à jour des prix)","(Décrements de stock)","archase Events)","Etsy et référence AWS","Postgres","architectures.","(Source de la vérité)"]}},{"kind":"p","page":34,"text":{"en":"✅ Answer: C — Cache-aside","fr":"✅ Réponse C : cache-aside"}},{"kind":"p","page":34,"text":{"en":"Why C wins:","fr":"Pourquoi choisir C"}},{"kind":"p","page":34,"text":{"en":"Multiple write paths (admin panel, inventory service, order service) all hit Postgres independently. Cache-aside fits perfectly: each writer updates Postgres → invalidates the cache key (DEL product:123) → next read misses → fetches fresh data → repopulates Redis. Postgres stays the uncontested source of truth. Redis is just a disposable read accelerator. If Redis dies, the app still works — slower, but correct. This is what Shopify, Etsy, and most AWS reference architectures run in prod.","fr":"Les trois chemins d’écriture atteignent PostgreSQL indépendamment. En cache-aside, chaque service écrit dans PostgreSQL, invalide la clé (DEL product:123), puis la lecture suivante trouve une entrée absente, récupère la donnée fraîche et la met dans Redis. PostgreSQL reste seul à faire foi. Redis accélère les lectures sans devenir indispensable. Si Redis tombe, l’application répond plus lentement, mais les données restent correctes. Shopify, Etsy et la plupart des architectures de référence AWS exploitent ce patron."}}],[{"kind":"p","page":34,"text":{"en":"Why A is the trap (Write-through):","fr":"Pourquoi A est tentant, avec le write-through"}},{"kind":"p","page":34,"text":{"en":"\"We write to both atomically\" — except there's no distributed transaction between Redis and Postgres. You write to Postgres, then write to Redis. If the Redis write fails (network blip, timeout), you have consistent Postgres + stale Redis. The exact bug you were trying to fix. Worse, write-through couples every service to Redis — now your inventory service and order service both need Redis credentials. One Redis outage takes down your entire write path. Works great for single-service/single-writer systems. Falls apart with multiple writers.","fr":"« Nous écrivons dans les deux systèmes de façon atomique. » Il n’existe pourtant aucune transaction distribuée entre Redis et PostgreSQL. Si l’écriture PostgreSQL aboutit et que Redis échoue à cause du réseau ou d’un timeout, la base est correcte et Redis reste périmé. C’est le défaut à résoudre. Le write-through couple aussi chaque service à Redis : inventaire et commandes ont tous deux besoin de ses identifiants. Une panne Redis peut casser toutes les écritures. Le patron convient à un seul service d’écriture. Avec plusieurs services, le couplage devient problématique."}}],[{"kind":"p","page":35,"text":{"en":"Why B is wrong (Write-behind):","fr":"Pourquoi B ne convient pas, avec le write-behind"}},{"kind":"p","page":35,"text":{"en":"Redis becomes your source of truth. Redis loses data during failovers, OOM kills, AOF lag. \"We might lose the last few price updates\" is not defensible in a postmortem when real money is involved. Write-behind belongs in metrics pipelines and analytics counters — not e-commerce write paths.","fr":"Redis fait alors foi et peut perdre des données lors d’un basculement, d’un arrêt faute de mémoire ou d’un retard du journal AOF. Difficile de défendre la perte des derniers prix dans un retour d’incident quand de l’argent est en jeu. L’écriture différée convient aux métriques et compteurs analytiques, beaucoup moins aux écritures e-commerce."}}],[{"kind":"p","page":35,"text":{"en":"Why D is wrong (Read-through):","fr":"Pourquoi D ne convient pas, avec le read-through"}},{"kind":"p","page":35,"text":{"en":"Only solves the read side. Your writes are still going through 3 different services with nothing telling the cache. Read-through doesn't fix stale data from multiple writers — you'd still need invalidation on top, which is just cache-aside with extra steps.","fr":"Ce patron ne couvre que les lectures. Trois services écrivent toujours sans prévenir le cache. Pour corriger les données obsolètes, il faut ajouter une invalidation aux écritures, ce qui revient au cache-aside avec plus d’étapes."}}]]},{"day":9,"title":{"en":"Splitting Read and Write Data Models","fr":"Séparer les modèles de lecture et d’écriture"},"pages":[36,39],"topic":"data","correct":"A","scenario":[{"kind":"figure","page":36,"id":"036-02","width":800,"height":420,"alt":{"en":"Day 9 featured","fr":"Illustration de la question du jour 9"},"transcript":{"en":["‘System Design Labs","Your orders service is a Postgres monolith doing 8K writes/min","and 40K reads/min. What’s the right move?","Orders Service","(Write API)","writes","8K/min","enrich /","External","read-heavy","cache","validate","‘Systems","Object","Goins) —>","Storage","Dashboard /","Postgres","responses","metadata","Reporting","(Orders 08)","writes into a","Full CORS — separate read/write model","dread store (","ieSearch /","‘Add read replicas — point dashboards +","3 fat Postgres read DE)","reports at the replica, keep writes on","between them.","the primary.","Keep one DB, one model — denormalize the write","Keep the schema, add GraphQL + DataLoader","schema itself (flatten line_items into orders, duplicate","batch the N+1 reads at the query layer, leave","‘customer data) so reads stop joining,","the DB alone."],"fr":["«System Design Labs","Votre service de commandes est un monolithe Postgres faisant 8K écrit / min","et 40K lectures / min. Quel est le bon mouvement?","Commandes Service","(Écrire l'API)","écrit","8K/min","enrichir /","Externe","lire-lourd","cache","Valider","«Systèmes","Objet","Goins) — >","Stockage","Tableau de bord /","Postgres","Réponses","métadonnées","Rapports","(Commandes 08)","écrit en a","Full CORS — modèle de lecture/écriture séparé","dread store (","ieSearch /","«Ajouter des répliques lues — tableaux de bord ponctuels +","3 gros Postgres lire DE)","rapports à la réplique, garder écrit sur","entre eux.","Le primaire.","Conservez une base de données, un modèle — dénormalisez l'écriture","Conservez le schéma, ajoutez GraphQL + DataLoader","schéma lui-même (aplatir line_items en ordres, dupliquer","batch les N+1 lit à la couche de requête, laissez","«données client) ainsi lit cesser de se joindre,","La DB seule."]}},{"kind":"p","page":36,"text":{"en":"Your orders service is a Postgres monolith doing 8K writes/min and 40K reads/min.","fr":"Le service de commandes est un monolithe PostgreSQL avec 8 000 écritures et 40 000 lectures par minute."}},{"kind":"p","page":36,"text":{"en":"Same tables. Same schema. Everything's grinding.","fr":"Mêmes tables, même schéma, et tout ralentit."}},{"kind":"p","page":36,"text":{"en":"The write side needs a normalized schema — orders, line_items, payments, shipments, addresses. Clean FKs, ACID, no duplicated data. The read side wants the opposite — the dashboard joins 7 tables to render one order card, and the reporting queries are lighting up the CPU at 85% every morning at 9am.","fr":"Les écritures exigent un schéma normalisé : orders, line_items, payments, shipments et addresses. Les clés étrangères sont propres, les transactions respectent ACID et les données restent sans doublon. Les lectures ont d’autres besoins. Le tableau de bord joint sept tables pour afficher une commande et les rapports font monter le CPU à 85 % tous les matins à 9 h."}},{"kind":"p","page":36,"text":{"en":"You've already tuned indexes. You've already added caching. The fundamental problem isn't hardware — the read model and the write model want different shapes of the same data, and you've been pretending they're the same thing for two years.","fr":"Les index et le cache ont déjà été optimisés. Le matériel n’est pas en cause. Lectures et écritures ont besoin de représentations différentes des mêmes données, alors que vous leur imposez un schéma commun depuis deux ans."}},{"kind":"p","page":36,"text":{"en":"Here's the decision on the table:","fr":"Voici les options."}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":36,"text":{"en":"Full CQRS — separate read/write models, project writes into a denormalized read store (ElasticSearch / a flat Postgres read DB), eventual consistency between them.","fr":"CQRS complet. Séparer les modèles de lecture et d’écriture, projeter les écritures vers un stockage de lecture dénormalisé (Elasticsearch ou une base PostgreSQL à plat) et accepter la cohérence à terme entre les deux."}}]},{"letter":"B","blocks":[{"kind":"p","page":36,"text":{"en":"Add read replicas — point dashboards + reports at the replica, keep writes on the primary.","fr":"Ajouter des répliques de lecture pour les tableaux de bord et les rapports, en conservant les écritures sur le primaire."}}]},{"letter":"C","blocks":[{"kind":"p","page":37,"text":{"en":"Keep one DB, one model — denormalize the write schema itself (flatten line_items into orders, duplicate customer data) so reads stop joining.","fr":"Garder une seule base et dénormaliser le modèle d’écriture. Intégrer line_items dans orders et dupliquer les données client pour éviter les jointures en lecture."}}]},{"letter":"D","blocks":[{"kind":"p","page":37,"text":{"en":"Keep the schema, add GraphQL + DataLoader — batch the N+1 reads at the query layer, leave the DB alone.","fr":"Conserver le schéma et ajouter GraphQL avec DataLoader pour regrouper les lectures N+1 à la couche de requêtes."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"figure","page":38,"id":"038-03","width":800,"height":322,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["System Design Labs","— Separate Read/Write Models","Project writes into a denormalized read store. Eventual consistency.","WRITE MODEL (Normalized, ACI)","READ MODEL (Oenormaize,Optinin fo Res)","Order ard","tae |","© on","ene","em","eis |","Read Model","rier APL","(Prjecter"],"fr":["System Design Labs","Modèles de lecture/écriture séparés","Project écrit dans un magasin de lecture dénormalisé.","MOD — LE D'ÉCRIPTION (normé, ACI)","LIRE LE MOD — LE (Oenormaize,Optinin fo Res)","Commande ard","tae","le","ene","em","eis","Lire le modèle","plus APL","(Prjecteur"]}},{"kind":"p","page":38,"text":{"en":"✅ Answer: A — Full CQRS","fr":"✅ Réponse A : CQRS complet"}},{"kind":"p","page":38,"text":{"en":"Why A wins:","fr":"Pourquoi A fonctionne"}},{"kind":"p","page":38,"text":{"en":"The pain isn't \"reads are slow\" — it's that the write side wants a normalized schema and the read side wants a denormalized one, and you're forcing them to share. No amount of hardware fixes a schema shape mismatch. Write side stays clean: orders, line_items, payments, all normalized, ACID, FK-enforced. Read side is a projection: a flat order_view table (or Elasticsearch index) where every order card renders from one row, zero joins. Projector keeps them in sync (outbox → Kafka → read-model updater, or CDC). You eat eventual consistency — the dashboard might lag by a few hundred ms. For 95% of reads (dashboards, reports, search), that's invisible. For the 5% that needs strong consistency (user's own order confirmation), read from the write side directly.","fr":"Les écritures ont besoin d’un schéma normalisé et les lectures d’un schéma dénormalisé. Une machine plus puissante ne résout pas ce désaccord. À l’écriture, orders, line_items et payments restent normalisées, avec ACID et des clés étrangères. La lecture passe par une projection, par exemple une table order_view à plat ou un index Elasticsearch. Une seule ligne suffit pour afficher une commande, sans jointure. Un composant maintient la projection par outbox, Kafka et processus de mise à jour, ou via CDC. Il faut accepter la cohérence à terme, avec quelques centaines de millisecondes de retard. Pour 95 % des lectures, comme les tableaux de bord, les rapports et la recherche, ce décalage passe inaperçu. Les 5 % qui exigent une cohérence forte, comme une confirmation de commande, lisent directement le modèle d’écriture."}}],[{"kind":"p","page":38,"text":{"en":"Why B is the trap (Read replicas):","fr":"Pourquoi B est tentant, avec des répliques de lecture"}},{"kind":"p","page":38,"text":{"en":"B fixes read load. Not read shape. The 7-table join is still a 7-table join — it just runs on different hardware. You've moved the CPU bill, not removed it. Latency drops for 6 months while traffic grows, then you're back where you started with 3 replicas all running the same expensive joins. B is right when the joins are structurally fine but the primary is overwhelmed. Wrong when the joins themselves are the problem.","fr":"Les répliques déplacent la charge de lecture sur d’autres machines. La jointure de sept tables reste aussi coûteuse. La latence baisse pendant six mois, puis le trafic croît et trois répliques exécutent encore les mêmes jointures. B convient quand les jointures sont raisonnables et que le primaire manque de capacité. Ici, les jointures sont au cœur du problème."}}],[{"kind":"p","page":39,"text":{"en":"Why C is wrong (Denormalize the write model):","fr":"Pourquoi C ne convient pas, avec la dénormalisation des écritures"}},{"kind":"p","page":39,"text":{"en":"Every line-item change now rewrites the order row. Every address update cascades through every order ever placed. Write amplification compounds at 8K writes/min. Schema ossifies — adding a field to line_items means migrating millions of denormalized rows. Classic \"avoid the architecture conversation\" move. Buys a quarter, mortgages two.","fr":"Toute modification d’un article réécrit la ligne de commande. Toute mise à jour d’adresse se propage à toutes les commandes passées. L’amplification des écritures s’accumule à 8 000 écritures par minute. Le schéma devient difficile à modifier. Un nouveau champ dans line_items exige de migrer des millions de lignes dénormalisées. Vous repoussez le choix d’architecture et gagnez un trimestre en hypothéquant les deux suivants."}}],[{"kind":"p","page":39,"text":{"en":"Why D is wrong (GraphQL + DataLoader):","fr":"Pourquoi D ne convient pas, avec GraphQL et DataLoader"}},{"kind":"p","page":39,"text":{"en":"DataLoader batches API calls, not joins. The 7-table join happens in the database, not in the application. 3 months of GraphQL migration later, reads are exactly as slow as before. Right answer when clients are the problem. Wrong answer when the DB schema is.","fr":"DataLoader regroupe des appels d’API. La jointure des sept tables s’effectue toujours en base. Après trois mois de migration GraphQL, les lectures prennent le même temps. Une bonne solution quand les appels des clients posent problème, et pas quand le schéma en est la cause."}}]]},{"day":10,"title":{"en":"Distributed Transactions Across Services","fr":"Gérer les transactions distribuées entre services"},"pages":[40,43],"topic":"events","correct":"B","scenario":[{"kind":"figure","page":40,"id":"040-02","width":800,"height":420,"alt":{"en":"Day 10 featured","fr":"Illustration de la question du jour 10"},"transcript":{"en":["‘System Design Lab","Your checkout flow spans 4 services.","Halfway through, payments succeeds, inventory fails. Now what?","crete","a)","Web / App","Order","Payment","Inventory","Shipping","Service","Service","Service","ice","14:02","Charged","Not","Created","$89.50","Om,","Called","Choreography Saga — each service publishes events,","‘Orchestration Saga — a central orchestrator","backward through the chain.","the next reacts, failures trigger compensating events","‘and dispatches compensations on failure,","{a state machine) calls each service in order","(a","Two-Phase Commit (2PC) — coordinator locks all","‘Outbox + eventual consistency — each service","4 services in PREPARE, then commits atomically","writes locally + an outbox row, a relay publishes","[c","(er aborts)","‘events async, downstream services converge."],"fr":["«System Design Lab","Votre flux de paiement s'étend sur 4 services.","À mi-chemin, les paiements réussissent, l'inventaire échoue.","crete","a)","Web / App","Commande","Paiement","Inventaire","Expédition","Service","Service","Service","glace","14:02","Chargés","Non","Créé","$89.50","Om,","Appelé","Chorégraphie Saga — chaque service publie des événements,","‘Orchestration Saga — un orchestrateur central","Retour en arrière par la chaîne.","le suivant réagit, les échecs déclenchent des événements de compensation","«et envoie des compensations en cas de défaillance,","une machine d'état) appelle chaque service dans l'ordre","(a)","Commit à deux phases (2PC) — le coordinateur verrouille tout","‘Outbox + cohérence éventuelle — chaque service","4 services dans PREPARE, puis s'engage atomiquement","écrit localement + une ligne de sortie, un relais publie","[c","(er avorte)","«Les services asynchrones et en aval convergent."]}},{"kind":"p","page":40,"text":{"en":"Order #4471 just hit your system at 14:02. The flow:","fr":"La commande nº 4471 vient d’arriver à 14 h 02. Voici la séquence."}},{"kind":"list","page":40,"items":{"en":["1. OrderService creates the order (Postgres) ✅","2. PaymentService charges $89.50 to Stripe ✅","3. InventoryService tries to reserve the SKU → fails (oversold by 3 units)","4. ShippingService never gets called"],"fr":["1. OrderService crée la commande dans PostgreSQL. ✅","2. PaymentService prélève 89,50 $ via Stripe. ✅","3. InventoryService tente de réserver le SKU et échoue : trois unités ont été vendues au-delà du stock.","4. ShippingService n’est jamais appelé."]}},{"kind":"p","page":40,"text":{"en":"You're now holding the customer's money, no inventory to ship, and an order stuck in PENDING. In a monolith you'd wrap all 4 in a transaction and ROLLBACK. You can't do that across 4 services with 4 databases.","fr":"Votre client a payé, le stock manque et la commande reste en PENDING. Un monolithe regrouperait les quatre opérations dans une transaction puis ferait ROLLBACK. Quatre services avec quatre bases ne peuvent pas partager cette transaction locale."}},{"kind":"p","page":40,"text":{"en":"What do you reach for?","fr":"Quelle approche choisissez-vous ?"}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":40,"text":{"en":"Choreography Saga — each service publishes events, the next reacts, failures trigger compensating events backward through the chain.","fr":"Saga par chorégraphie. Chaque service publie un événement auquel le suivant réagit. Un échec déclenche des événements de compensation en remontant la chaîne."}}]},{"letter":"B","blocks":[{"kind":"p","page":40,"text":{"en":"Orchestration Saga — a central orchestrator (a state machine) calls each service in order and dispatches compensations on failure.","fr":"Saga orchestrée. Un orchestrateur central, sous forme de machine à états, appelle les services dans l’ordre et déclenche les compensations en cas d’échec."}}]},{"letter":"C","blocks":[{"kind":"p","page":41,"text":{"en":"Two-Phase Commit (2PC) — coordinator locks all 4 services in PREPARE, then commits atomically (or aborts).","fr":"Validation en deux phases (2PC). Le coordinateur verrouille les quatre services pendant PREPARE, puis valide tout atomiquement ou annule."}}]},{"letter":"D","blocks":[{"kind":"p","page":41,"text":{"en":"Outbox + eventual consistency — each service writes locally + an outbox row, a relay publishes events async, downstream services converge.","fr":"Outbox et cohérence à terme. Chaque service écrit localement et ajoute une entrée dans l’outbox. Un relais publie les événements de façon asynchrone et les services en aval convergent."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"figure","page":42,"id":"042-03","width":800,"height":533,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["ANSWER:","hestr.","Saga","(CheckoutSaga Orchestrator (State Machine)","Pace Ont","CB","Web Ao","I (Order #4471)","rv","PaymentService","InventoryService","Fale","ShippingService","Payer","siping","#447","som"],"fr":["RÉPONSE :","hestr.","Saga","(CheckoutSaga Orchestrator (Machine d'état)","Pace Ont","CB","Web Ao","I (Ordre — 4471)","rv","PaymentService","InventaireService","Fale","ShippingService","Payeur","siping","#447","som"]}},{"kind":"p","page":42,"text":{"en":"✅ Answer: B — Orchestration Saga","fr":"✅ Réponse B : saga orchestrée"}},{"kind":"p","page":42,"text":{"en":"Why B wins:","fr":"Pourquoi retenir B ?"}},{"kind":"p","page":42,"text":{"en":"4-step checkout with strict ordering + per-step compensations = exactly what an orchestrator is built for. Stand up a CheckoutSaga state machine (Temporal, AWS Step Functions, Camunda, or hand-rolled). It calls each service in order: OrderService → PaymentService → InventoryService → ShippingService. Each step has a registered compensation: CancelOrder, RefundPayment, ReleaseInventory. When Inventory fails, the orchestrator walks backward and refunds automatically. State is durable, observable, replayable. At 3am you open the orchestrator UI and see exactly which step failed with full inputs/outputs.","fr":"Quatre étapes de paiement imposent un ordre strict, avec leur propre compensation. C’est le rôle d’un orchestrateur. Une machine à états CheckoutSaga, avec Temporal, AWS Step Functions, Camunda ou une implémentation interne, appelle OrderService, PaymentService, InventoryService puis ShippingService. Les compensations CancelOrder, RefundPayment et ReleaseInventory sont enregistrées pour les étapes concernées. Si l’inventaire échoue, l’orchestrateur remonte les étapes et rembourse automatiquement. L’état est durable, observable et rejouable. À 3 h du matin, l’interface montre l’étape en échec et ses entrées et sorties complètes."}}],[{"kind":"p","page":43,"text":{"en":"Why A is the trap (Choreography):","fr":"Pourquoi A est tentant, avec la chorégraphie"}},{"kind":"p","page":43,"text":{"en":"Elegant on paper. Falls apart at 4+ steps with branching compensations. The business logic for \"what happens when inventory fails after payment succeeded\" gets smeared across 3 services that all need to know each other's failure modes. Nobody owns the flow. No single place to see \"what is the state of order #4471?\" At 3am you're piecing it together from events across 4 Kafka topics. Choreography is right for loose, fire-and-forget side effects — not sequential checkouts with specific compensations.","fr":"Élégante sur le papier, elle se complique au-delà de quatre étapes avec des compensations qui divergent. La décision métier à prendre si l’inventaire échoue après le paiement se retrouve répartie sur trois services qui doivent connaître leurs modes de panne respectifs. Aucun ne possède le flux, et aucun écran ne donne l’état de la commande nº 4471. À 3 h du matin, il faut le reconstruire à partir de quatre topics Kafka. La chorégraphie convient aux effets indépendants qu’on déclenche sans attendre leur résultat. Ce paiement a une séquence et des compensations précises."}}],[{"kind":"p","page":43,"text":{"en":"Why C is wrong (2PC):","fr":"Pourquoi C ne convient pas, avec 2PC"}},{"kind":"p","page":43,"text":{"en":"Stripe doesn't speak 2PC. Neither does any shipping carrier API. Beyond that, 2PC holds locks during PREPARE — one slow service stalls everything. At checkout volumes, the lock contention alone takes you down. Textbook answer that dies on contact with reality.","fr":"Stripe et les API des transporteurs ne prennent pas en charge 2PC. De plus, les verrous restent détenus pendant PREPARE. Un service lent peut bloquer les autres et, au volume d’un paiement en ligne, la contention suffit à mettre le système à terre."}}],[{"kind":"p","page":43,"text":{"en":"Why D is wrong (Outbox):","fr":"Pourquoi D ne suffit pas, avec une outbox"}},{"kind":"p","page":43,"text":{"en":"Outbox is infrastructure, not a saga. It solves how to reliably publish events after a local DB commit. It doesn't define step ordering, doesn't define compensations, doesn't answer what happens when Inventory fails. You'd still need a saga on top of it.","fr":"L’outbox fiabilise la publication des événements après une validation locale en base. Elle ne définit ni l’ordre des étapes ni les compensations et ne dit pas quoi faire si l’inventaire échoue. Une saga reste nécessaire au-dessus de cette brique."}}]]},{"day":11,"title":{"en":"Handling Webhook Retries Idempotently","fr":"Traiter les nouvelles tentatives de webhook de façon idempotente"},"pages":[44,47],"topic":"events","correct":"C","scenario":[{"kind":"figure","page":44,"id":"044-02","width":800,"height":420,"alt":{"en":"Day 11 featured","fr":"Illustration de la question du jour 11"},"transcript":{"en":["stem Design Labs","Stripe just sent your server a charge.succeeded","webhook. Your pod was mid-restart. The webhook timed o1","rost","fat","Stripe","= S","(Webhooks)","ALB","Database","Email Service","(Orders)","ECS Service","(4 tasks)","Idempotency key + dedup table —","Retry with exponential backoff +","store every event ID on receipt,","dead-letter queue — never drop a","skip if already seen.","Oo","webhook, process at-least-once.","‘Sequence numbers + reorder buffer —","Verify signature, return 200 immediately,","push to an internal queue —","hold events until the prior sequence","decouple receipt from processing.","IC)","has landed, then process in strict order."],"fr":["stem Design Labs","Stripe vient d'envoyer à votre serveur un charge.succeeded","webhook. Votre pod était en plein redémarrage. Le webhook chronométré o1","rost","matières grasses","Stripe","S","(Webhooks)","ALB","Base de données","Service de messagerie","(Commandes)","ECS Service","(4 tâches)","Clé d'identité + table de décodage","Réessayer avec un backoff exponentiel +","stocker chaque ID d'événement à la réception,","La file d'attente de dead-letter — ne jamais laisser tomber une","Sautez si déjà vu.","Oo","webhook, traite au moins une fois.","«Numéro de séquence + tampon de réordonnancement","Vérifiez la signature, retournez 200 immédiatement,","Pousser vers une file d'attente interne -","Tenir les événements jusqu'à la séquence précédente","découpler la réception du traitement.","IC)","a atterri, puis le processus dans un ordre strict."]}},{"kind":"p","page":44,"text":{"en":"Stripe just sent your server a charge.succeeded webhook.","fr":"Stripe vient d’envoyer un webhook charge.succeeded à votre serveur."}},{"kind":"p","page":44,"text":{"en":"Your pod was mid-restart. The webhook timed out. Stripe will retry — but now you're racing.","fr":"Le pod redémarrait et le webhook a dépassé son délai. Stripe va réessayer et deux traitements risquent de se chevaucher."}},{"kind":"p","page":44,"text":{"en":"Here's the setup:","fr":"Voici la configuration."}},{"kind":"p","page":44,"text":{"en":"NestJS API on ECS, 4 tasks behind an ALB. Stripe POSTs charge.succeeded events to /webhooks/stripe. You have ~10s to return a 200 before Stripe times out and queues a retry. On Black Friday you're handling ~80 webhooks/sec.","fr":"Une API NestJS tourne sur ECS, avec quatre tâches derrière un ALB. Stripe envoie les événements charge.succeeded par POST à /webhooks/stripe. Vous avez environ 10 s pour renvoyer 200, sans quoi Stripe planifie une nouvelle tentative. Au Black Friday, vous recevez environ 80 webhooks par seconde."}},{"kind":"p","page":44,"text":{"en":"Three failure modes are already happening in prod:","fr":"Trois types d’incident sont déjà survenus en production."}},{"kind":"p","page":44,"text":{"en":"• Pod restarts mid-deploy → webhook missed → Stripe retries → you process it, but a second pod also processed the original → double charge confirmation email sent","fr":"• Un pod redémarre pendant le déploiement. Stripe réessaie et vous traitez l’événement, alors qu’un second pod a traité l’original. Le client reçoit deux e-mails de confirmation du prélèvement."}},{"kind":"p","page":44,"text":{"en":"• DB is slow at peak → handler takes 12s → Stripe times out → retries → now you're processing the same event twice while the first one is still running","fr":"• La base ralentit au pic. Le traitement prend 12 s et Stripe réessaie après son timeout. Vous traitez deux fois le même événement, avec une première exécution encore en cours."}},{"kind":"p","page":44,"text":{"en":"• Stripe sends charge.succeeded then charge.refunded 200ms apart → your queue delivers them out of order → you mark the order paid AFTER it was already refunded","fr":"• Stripe envoie charge.succeeded puis charge.refunded à 200 ms d’intervalle. La file les remet dans le désordre et vous marquez la commande comme payée après son remboursement."}},{"kind":"p","page":44,"text":{"en":"The handler is a 30-line function that does the right thing 99% of the time. The 1% is killing you.","fr":"La fonction de traitement fait 30 lignes et fonctionne dans 99 % des cas. Le 1 % restant provoque les incidents."}},{"kind":"p","page":45,"text":{"en":"What do you do?","fr":"Que faites-vous ?"}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":45,"text":{"en":"Idempotency key + dedup table — store every event ID on receipt, skip if already seen.","fr":"Clé d’idempotence et table de déduplication. Enregistrer les identifiants des événements à réception et ignorer ceux déjà vus."}}]},{"letter":"B","blocks":[{"kind":"p","page":45,"text":{"en":"Retry with exponential backoff + dead-letter queue — never drop a webhook, process at-least-once.","fr":"Nouvelles tentatives avec backoff exponentiel et file de rejets. Aucun webhook ne doit être perdu et chacun est traité au moins une fois."}}]},{"letter":"C","blocks":[{"kind":"p","page":45,"text":{"en":"Verify signature, return 200 immediately, push to an internal queue — decouple receipt from processing.","fr":"Vérifier la signature, renvoyer immédiatement 200 et utiliser une file interne pour découpler la réception du traitement."}}]},{"letter":"D","blocks":[{"kind":"p","page":45,"text":{"en":"Sequence numbers + reorder buffer — hold events until the prior sequence has landed, then process in strict order.","fr":"Numéros de séquence et tampon de réordonnancement. Attendre les événements précédents, puis traiter le tout dans l’ordre strict."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"figure","page":46,"id":"046-03","width":800,"height":473,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["Answer: C","System Design Labs","Verify signature, return 200 immediately,","push to an internal queue.","Post","Enque","<5ms","Wiebhook Endpoint","Stripe","(Webhooks)","Internal Queue","Worker Service","Fraud Check","(SQS / Kafka /","Third-Party APs","Redis Streams)","<5ms","Verify signature,","Idempotency key +","Retry with exponential","Sequence numbers +","dedup table — store","backot + dead-letter","reorder buffer — hold","ic)","return 200 immediately,","‘every event ID on","‘queue — never drop @","‘events until the prior","push to an internal queue.","receipt skip if","webhook, process","sequence has landed,","already seen.","at-least-once.","then process in strict order.","© ACK to Stripe in < 108 (usally < 1s)","© Decoupies recsit fom processing","© Great for preventing duplicates,","© Usotu, uti stil processing","Helps ordering, but increases","but does not ole slow","inside the webhook path","latency and complexity","© Survives pod restarts and DB slowness.","processing or timeout.","© Events ae durable; workers handle","«© tit keeps heavy workin the","pod restars, or ordering","retvies and seale independently","problems"],"fr":["Réponse : C","System Design Labs","Vérifiez la signature, retournez 200 immédiatement,","Poussez vers une file d'attente interne.","Poste","Enque","5ms","Wiebhook Endpoint","Stripe","(Webhooks)","File d'attente interne","Service des travailleurs","Vérification de fraude","(SQS / Kafka /","Les tiers aps","Redis Streams)","5ms","Vérifier la signature,","Clé d'identité +","Réessayer avec exponentiel","Séquence +","dedup table — magasin","backot + lettre morte","reorder buffer — conserver","ic)","Rendre 200 immédiatement,","«chaque ID d'événement sur","‘queue — ne jamais laisser tomber","événements jusqu'à ce que le","Poussez vers une file d'attente interne.","réception skip si","webhook, processus","la séquence a atterri,","déjà vu.","Au moins une fois.","puis le processus dans un ordre strict.","ACK à Stripe en — 108 (habituellement — 1s)","Découpages recsit fom traitement","Idéal pour prévenir les doublons,","Usotu, uti stil traitement","Aide à commander, mais augmente","mais ne fait pas ole lent","à l'intérieur du chemin webhook","latence et complexité","Survit aux redémarrages du pod et à la lenteur de la base de données.","Traitement ou délai d'attente.","Événements ae durable; travailleurs manipuler","tit garde le travail lourddans le","pod restars, ou commande","retvies et seale indépendamment","problèmes"]}},{"kind":"p","page":46,"text":{"en":"Answer: C — Verify signature, return 200 immediately, push to an internal queue ✅","fr":"Réponse C : vérifier la signature, accuser réception immédiatement avec un 200 et passer par une file interne ✅"}},{"kind":"p","page":46,"text":{"en":"Here's why, and why the other three trick smart engineers:","fr":"Voici pourquoi cette approche fonctionne et où les trois autres peuvent induire en erreur."}},{"kind":"p","page":46,"text":{"en":"Why C wins (Sync receipt + async processing):","fr":"Pourquoi retenir C, avec réception synchrone et traitement asynchrone ?"}},{"kind":"p","page":46,"text":{"en":"The fundamental problem is that Stripe's clock and your handler's clock are decoupled. Stripe gives you ~10 seconds to ACK. Your DB write, your fraud check, your email send — none of that should live inside that 10-second window. Ever.","fr":"Le délai de Stripe et le temps de votre traitement sont indépendants. Stripe vous donne environ 10 secondes pour accuser réception. L’écriture en base, la vérification antifraude et l’envoi du courriel doivent se faire hors de cette fenêtre."}},{"kind":"p","page":46,"text":{"en":"The pattern: validate the HMAC signature in <5ms, write the raw payload to SQS / Kafka / Redis Streams, return 200. Now your handler is bounded by network + signature verification, not by whatever your downstream services are doing today. Pod restart mid-processing? The message is already durable in the queue — a worker picks it up. DB slow? The webhook endpoint doesn't care — it returned 200 in 8ms. This is what Stripe, Shopify, and GitHub literally tell you to do in their own webhook docs.","fr":"Vérifiez la signature HMAC en moins de 5 ms, enregistrez le payload brut dans SQS, Kafka ou Redis Streams, puis renvoyez 200. Le temps de réponse dépend du réseau et de la vérification de signature, indépendamment de la charge en aval. Si le pod redémarre pendant le traitement, le message est durable dans la file et un worker le récupère. Si la base ralentit, l’endpoint a déjà renvoyé 200 en 8 ms. Les documentations de Stripe, Shopify et GitHub recommandent ce principe."}}],[{"kind":"p","page":47,"text":{"en":"Why A is the trap answer (Idempotency key + dedup table):","fr":"Pourquoi A est tentant, avec une clé d’idempotence et une table de déduplication"}},{"kind":"p","page":47,"text":{"en":"This is the answer that fools senior engineers in interviews — and it's not wrong, it's just incomplete.","fr":"Cette réponse convainc même des ingénieurs expérimentés en entretien. Elle répond à une partie du besoin."}},{"kind":"p","page":47,"text":{"en":"Yes, you absolutely need idempotency. Stripe will deliver the same event ID more than once. A dedup table keyed on event.id with a unique constraint is table stakes. But it doesn't solve the original pain: the handler is still synchronous, still on the critical 10-second path, still getting killed by pod restarts mid-write.","fr":"L’idempotence est indispensable. Stripe peut remettre plusieurs fois le même identifiant. Une table de déduplication indexée sur event.id avec contrainte d’unicité est un minimum. Le traitement reste néanmoins synchrone, soumis au délai de 10 secondes et vulnérable aux redémarrages de pods pendant l’écriture."}},{"kind":"p","page":47,"text":{"en":"If you ship A alone, you've prevented double-processing — but you're still timing out, still triggering retries, still creating the conditions for the race. Idempotency is a property your handler must have, not an architecture. C is the architecture; A lives inside it. The senior engineer trap is treating idempotency as the whole answer when it's one of three layers.","fr":"A seul empêche le double traitement, mais les dépassements de délai et les nouvelles tentatives persistent. L’idempotence est une propriété du traitement. C définit l’architecture dans laquelle A s’insère. Le piège consiste à croire que l’une de ces trois couches règle tout le problème."}}],[{"kind":"p","page":47,"text":{"en":"Why B is wrong as the answer (Retry + DLQ):","fr":"Pourquoi B ne répond pas au problème, avec les nouvelles tentatives et la DLQ"}},{"kind":"p","page":47,"text":{"en":"Stripe is already doing the retry with exponential backoff. That's their job, not yours. Stripe retries failed webhooks for up to 3 days with backoff. You don't need to build that for inbound webhooks — you'd be duplicating provider behavior.","fr":"Stripe effectue déjà les nouvelles tentatives avec backoff exponentiel. Il réessaie les webhooks en échec pendant un maximum de trois jours. Ajouter ce mécanisme pour les webhooks entrants dupliquerait le travail du fournisseur."}},{"kind":"p","page":47,"text":{"en":"Retry + DLQ is the right pattern for your internal queue (the one C creates), not for the webhook endpoint itself. If your worker fails to process a queued event, sure, retry it and DLQ after N attempts. But that's a downstream concern. Putting \"retry logic\" at the webhook receiver level confuses inbound and outbound retry semantics.","fr":"Les nouvelles tentatives et la DLQ conviennent à la file interne créée par C. Si un worker ne traite pas un événement de la file, réessayez, puis envoyez-le en DLQ après N tentatives. C’est un mécanisme en aval. Le placer sur le point de réception mélange les responsabilités côté entrant et côté sortant."}}],[{"kind":"p","page":47,"text":{"en":"Why D is wrong (Sequence numbers + reorder buffer):","fr":"Pourquoi D ne convient pas, avec les numéros de séquence et un tampon de réordonnancement"}},{"kind":"p","page":47,"text":{"en":"This sounds rigorous and it's the answer engineers reach for after they've been burned by ordering once. The problem: most webhook providers don't give you sequence numbers. Stripe doesn't. GitHub doesn't. Even when they do (Shopify's X-Shopify-Webhook-Id), the gaps aren't dense — you can't tell \"missing event 47\" from \"47 was filtered.\"","fr":"La solution paraît rigoureuse à qui a déjà subi des problèmes d’ordre. La plupart des fournisseurs, dont Stripe et GitHub, ne fournissent aucun numéro de séquence. Même avec un identifiant comme X-Shopify-Webhook-Id, les numéros ne se suivent pas nécessairement. Impossible de dire si l’événement 47 a été perdu ou filtré."}},{"kind":"p","page":47,"text":{"en":"More importantly: ordering at the receiver is the wrong layer. You handle ordering at the domain level — when you process charge.refunded, you check the current state of the order before transitioning. If the order is already in refunded, you no-op. State machines beat reorder buffers because they handle the case where events arrive out of order AND the case where one of them never arrives at all. A reorder buffer just means you stall forever when an event gets dropped upstream.","fr":"L’ordre se traite au niveau métier. Au traitement de charge.refunded, vérifiez l’état actuel de la commande. Si elle est déjà remboursée, ne faites rien. Une machine à états couvre à la fois les événements dans le désordre et ceux qui n’arrivent jamais. Un tampon risque de rester bloqué indéfiniment si un événement est perdu en amont."}}]]},{"day":12,"title":{"en":"Indexing a High-Ingest Table","fr":"Indexer une table qui reçoit beaucoup d’écritures"},"pages":[48,51],"topic":"data","correct":"D","scenario":[{"kind":"figure","page":48,"id":"048-02","width":800,"height":420,"alt":{"en":"Day 12 featured","fr":"Illustration de la question du jour 12"},"transcript":{"en":["1m Design Lab","Your events table on PostgreSQL 15 just crossed 200M rows.","What do you do?","Sane 40M rows","P99 wrt latency","‘Moms and climbing","Bex","index","reeds","Ingestion","PostgreSQL 15,","Dashboard","Katka","Service","events","Analytics","Topic","200M+ rows","‘Add a composite B-tree on","‘Add a covering index with INCLUDE","(tenant_id, event_type, created_at).","(user_id, payload) so the query","Standard answer, covers the query, done.","never hits the heap. Index-only scan, blazing reads.","‘Stop adding indexes to the primary.","‘Add a partial index — same columns,","Spin up a read replica and route the","but WHERE event_type ='signup’ AND","dashboard there. Keep the write path lean.","Only the hot slice gets indexed."],"fr":["1m Design Lab","Votre table d'évènements sur PostgreSQL 15 vient de franchir les 200M lignes.","Qu'est-ce que tu fais ?","Sane 40M lignes","latence P99 wrt","« Les mamans et l’escalade","Bex","Indice","roseaux","Ingestion","PostgreSQL 15,","Tableau de bord","Katka","Service","événements","Analyses","Thème","200M+ lignes","« Ajouter un arbre B composite sur","«Ajouter un indice de couverture avec INCLUDE","(location_id, type_événement, created_at).","(user_id, charge utile) donc la requête","Réponse standard, couvre la requête, c'est fait.","Il n'y a que des scans d'index, des lectures flamboyantes.","\"Arrêtez d'ajouter des index au primaire.","«Ajouter un index partiel — mêmes colonnes,","Monter une réplique de lecture et router le","mais O — event_type — 'signup' ET","Gardez le chemin d'écriture lean.","Seule la tranche chaude est indexée."]}},{"kind":"p","page":48,"text":{"en":"Your events table on PostgreSQL 15 just crossed 200M rows.","fr":"La table events de votre PostgreSQL 15 vient de franchir 200 millions de lignes."}},{"kind":"p","page":48,"text":{"en":"Ingestion runs at 8K writes/sec from a Kafka consumer. P99 write latency was 12ms — now it's 140ms and climbing.","fr":"Un consommateur Kafka y écrit 8 000 fois par seconde. Le p99 des écritures est passé de 12 à 140 ms et continue de monter."}},{"kind":"p","page":48,"text":{"en":"The dashboard team is screaming. Their query filters on (tenant_id, event_type, created_at) and scans 40M rows per request. They want an index. Yesterday.","fr":"L’équipe des tableaux de bord s’impatiente. Sa requête filtre sur (tenant_id, event_type, created_at) et parcourt 40 millions de lignes par appel. Elle veut un index au plus vite."}},{"kind":"p","page":48,"text":{"en":"You check pg_stat_user_indexes. The table already has 4 indexes. Each new write touches every one of them. Add a fifth and your ingestion lag becomes ingestion failure.","fr":"Vous consultez pg_stat_user_indexes. La table compte déjà quatre index, tous touchés par chaque écriture. Un cinquième risque de transformer le retard d’ingestion en panne."}},{"kind":"p","page":48,"text":{"en":"But 92% of dashboard queries hit a single tenant's last 7 days of signup events. A tiny slice of a huge table.","fr":"Pourtant, 92 % des requêtes du tableau de bord portent sur les inscriptions d’un seul client au cours des sept derniers jours. C’est une fraction minuscule de la table."}},{"kind":"p","page":48,"text":{"en":"What do you do?","fr":"Que faites-vous ?"}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":48,"text":{"en":"Add a composite B-tree on (tenant_id, event_type, created_at). Standard answer, covers the query, done.","fr":"Ajouter un B-tree composite sur (tenant_id, event_type, created_at). Solution classique qui couvre la requête."}}]},{"letter":"B","blocks":[{"kind":"p","page":48,"text":{"en":"Add a covering index with INCLUDE (user_id, payload) so the query never hits the heap. Index-only scan.","fr":"Ajouter un index couvrant avec INCLUDE (user_id, payload) pour répondre depuis l’index seul, sans consulter la table."}}]},{"letter":"C","blocks":[{"kind":"p","page":48,"text":{"en":"Stop adding indexes to the primary. Spin up a read replica and route the dashboard there. Keep writes lean.","fr":"Laisser le primaire tel quel et orienter le tableau de bord vers une réplique de lecture pour préserver les écritures."}}]},{"letter":"D","blocks":[{"kind":"p","page":49,"text":{"en":"Add a partial index — same columns, but WHERE event_type = 'signup' AND created_at > now() - interval '7 days'. Only the hot slice gets indexed.","fr":"Ajouter un index partiel sur les mêmes colonnes, avec WHERE event_type = 'signup' AND created_at > now() - interval '7 days'. Seule la tranche la plus sollicitée est indexée."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"figure","page":50,"id":"050-03","width":800,"height":471,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["System Design Labs","Add a partial index — same columns,","WHERE event_type =","ignup' AND created_at > now() - interval '7 days’.","929% of queries hit","P99 write latency:","‘one tenants last","‘40ms and climbing","Tedays of signup events","| reads","(OM rows","Dashboard","Producers","Kafka","Ingestion","Service","PostgreSQL 15","‘Analytics","(ops Services)","Topic","events","200M+ rows","‘event ype crested at)","18) Covering index","[v] D) Partial Index (Correct)","INCLUDE (u","id, payload)","(Only indexes rows where event type = signup’ AND","X Even more writes per insert","created at > now) -interval'7 days:","% Every wot updates t","X High write amplcation","% Higher memory & YO","Indexes only the hot sce (-02% of table)","% Wal worsen we latency","2% White path takes the it","LY Inserts outside the predicate pay ero cost","LY Planner uses forthe dashboard query","LY Fast read, minimal write amplification","oes not slow wits on primary","> ‘tll need the index somewhere for fast reads","Trade-off: if the dashboard needs 30 days instead of 7,","X Replication lg won't help real-time dashboard","you rebuild the index. Known cost, nota hidden one."],"fr":["System Design Labs","Ajouter un index partiel — mêmes colonnes,","O — type_événement","ignup' AND created_at > now() - intervalle '7 jours'.","929% des requêtes touchées","P99 écrire latence:","«un locataire en dernier","«40ms et escalade","Les jours des événements d'inscription","lit","(lignes OM","Tableau de bord","Producteurs","Kafka","Ingestion","Service","PostgreSQL 15","«Analytics","(Ops Services)","Thème","événements","200M+ lignes","«événement ype ciseau»","18) Indice de couverture","[v] D) Indice partiel (correct)","INCLURE (u)","id, charge utile)","(N’indexe que les lignes où le type d’événement — signup’","X Encore plus d'écritures par insert","créé à > maintenant) -interval'7 days:","% Toutes les mises à jour","X Haute amplification en écriture","% Mémoire supérieure & YO","Indexe uniquement les sce chaudes (-02% du tableau)","% Wal aggravent la latence","2% Le chemin blanc prend le","LY Insère en dehors du prédicat paie ero coût","LY Planner utilise la requête du tableau de bord","Lecture rapide, amplification minimale en écriture","oes pas lents à la primaire","> > > > > > > > > > > > > > >","Trade-off: si le tableau de bord a besoin de 30 jours au lieu de 7,","X Replication lg n'aidera pas le tableau de bord en temps réel","vous reconstruisez l'index. Coût connu, pas un caché."]}},{"kind":"p","page":50,"text":{"en":"Answer: D — Partial Index ✅","fr":"Réponse D : index partiel ✅"}},{"kind":"p","page":50,"text":{"en":"Here's why, and why the other three trick smart engineers.","fr":"Voici le raisonnement et les limites des autres options."}},{"kind":"p","page":50,"text":{"en":"Why D wins (Partial Index)","fr":"Pourquoi retenir D, l’index partiel ?"}},{"kind":"p","page":50,"text":{"en":"92% of your queries hit one tenant's last 7 days of signup events. A partial index only indexes rows that match its WHERE clause — everything else writes to the table without touching this index at all.","fr":"Les inscriptions des sept derniers jours pour un client représentent 92 % des requêtes. Un index partiel ne contient que les lignes satisfaisant sa clause WHERE. Les autres écritures n’y touchent pas."}},{"kind":"p","page":50,"text":{"en":"The math: if signup events are ~4% of the stream and the 7-day window covers ~5% of the table, your partial index covers roughly 0.2% of rows. Inserts that don't match the predicate cost you nothing on this index. The write amplification is almost entirely gone.","fr":"Si les inscriptions représentent environ 4 % du flux et que la fenêtre de sept jours couvre 5 % de la table, l’index concerne environ 0,2 % des lignes. Les insertions hors du prédicat ne coûtent rien à cet index. La quasi-totalité de l’amplification des écritures disparaît."}},{"kind":"p","page":50,"text":{"en":"PostgreSQL's planner uses the partial index for any query whose WHERE clause is a subset of the index predicate. Your dashboard query gets full coverage. Reads stay fast, writes stay alive.","fr":"Le planificateur PostgreSQL peut utiliser l’index partiel lorsque la clause WHERE de la requête implique son prédicat. La requête du tableau de bord est couverte. Les lectures restent rapides et les écritures continuent."}},{"kind":"p","page":50,"text":{"en":"The catch: when the dashboard team wants 30 days instead of 7, you rebuild. That's a known cost, not a hidden one.","fr":"Si l’équipe passe de sept à trente jours, il faudra reconstruire l’index. C’est un coût identifié d’avance."}}],[{"kind":"p","page":51,"text":{"en":"Why B is the trap (Covering Index with INCLUDE)","fr":"Pourquoi B est tentant, avec un index couvrant et INCLUDE"}},{"kind":"p","page":51,"text":{"en":"This fools senior engineers more than any other option. An index-only scan looks gorgeous in EXPLAIN. The problem is what you stuffed into INCLUDE.","fr":"Un parcours sur l’index seul rend très bien dans EXPLAIN. Le coût dépend des colonnes ajoutées à INCLUDE."}},{"kind":"p","page":51,"text":{"en":"That payload column is probably a JSONB blob averaging a few KB. Every insert now writes the row to the heap and writes a fat index entry containing the full payload. Every UPDATE to user_id or payload rewrites the index entry. You didn't reduce write cost — you multiplied it.","fr":"payload est probablement un document JSONB de quelques kilo-octets. Chaque insertion écrit une ligne dans la table et une grosse entrée d’index avec le payload complet. Un UPDATE sur user_id ou payload réécrit l’entrée. Le coût des écritures augmente."}},{"kind":"p","page":51,"text":{"en":"At 8K writes/sec on a table that's already index-heavy, a covering index with JSONB inside is how you turn 140ms p99 into 800ms p99. INCLUDE is the right call for narrow columns on read-heavy tables. This is neither.","fr":"Sur une table déjà très indexée et à 8 000 écritures par seconde, un index couvrant avec du JSONB peut faire passer le p99 de 140 à 800 ms. INCLUDE convient aux colonnes légères sur des tables surtout lues. Ce cas ne répond à aucun des deux critères."}}],[{"kind":"p","page":51,"text":{"en":"Why A is wrong (Full composite B-tree)","fr":"Pourquoi A ne convient pas, avec un B-tree composite complet"}},{"kind":"p","page":51,"text":{"en":"A (tenant_id, event_type, created_at) index will make the dashboard fast. It will also index every single one of your 8K writes/sec across all tenants and all event types. You're paying full write cost to serve a query that hits 0.2% of the data. That's the definition of a bad tradeoff.","fr":"Un index (tenant_id, event_type, created_at) accélère le tableau de bord, mais sollicite aussi l’index à chacune des 8 000 écritures par seconde, quels que soient le client et le type d’événement. Vous payez le coût de toutes les écritures pour une requête portant sur 0,2 % des données."}}],[{"kind":"p","page":51,"text":{"en":"Why C is wrong (Read replica)","fr":"Pourquoi C ne convient pas, avec une réplique de lecture"}},{"kind":"p","page":51,"text":{"en":"The indexes still have to exist somewhere. Put them on the replica and it falls behind replaying WAL while maintaining indexes. Put them on the primary and you're back to the original problem.","fr":"Les index doivent exister quelque part. Sur la réplique, leur entretien ralentit le rejeu du WAL. Sur le primaire, le problème initial revient."}},{"kind":"p","page":51,"text":{"en":"Read replicas solve \"my primary can't serve all the reads.\" They don't solve \"my write path is bottlenecked by index maintenance.\"","fr":"Les répliques répartissent les lectures quand le primaire n’en tient plus la charge. Le coût de maintenance des index à l’écriture subsiste."}}]]},{"day":13,"title":{"en":"Managing a Shared Connection Pool","fr":"Gérer un pool de connexions partagé"},"pages":[52,56],"topic":"scale","correct":"B","scenario":[{"kind":"figure","page":52,"id":"052-02","width":800,"height":420,"alt":{"en":"Day 13 featured","fr":"Illustration de la question du jour 13"},"transcript":{"en":["System Design Labs","3 workloads. 1 Postgres RDS.","max_connections = 300. How do you pool without breaking any?","Ne","‘800 RPS","10 tasks x 40","lestJS REST API","[— short tx","Connection","ECS Fargate","Pool","Background Job","Long queries","30-90s","Connection","Workers","Pool","Lambda Functions","Bursty","Postgres RDS","(0-200 concurrent","cold starts,","» | Connection","Pool","‘max_connections = 300","PgBouncer session mode for the workers +","PgBouncer transaction mode for everyone:","single pooler in front of RDS, maximum multiplexing,","transaction mode for the REST API: split pooler","config by workload type. Lambda goes through one of them.","RDS Proxy for Lambda + PgBouncer transaction","Separate read replica for the analytics workers +","PgBouncer transaction mode for REST + Lambda:","mode for ECS: hybrid. Route by client type.","isolate the workload at the DB level."],"fr":["System Design Labs","3 charges de travail. 1 Postgres RDS.","max_connections — 300. Comment mettre en commun sans en casser ?","Né","«800 RPS","10 tâches x 40","API de letJS REST","[ — court tx","Connexion","ECS Fargate","Pool","Historique Job","Longues requêtes","30-90s","Connexion","Travailleurs","Pool","Fonctions Lambda","Bursty","Postgres RDS","(0-200 simultané)","démarrage à froid,","» — Connexion","Pool","«max_connections — 300","Mode session PgBouncer pour les travailleurs +","Mode de transaction PgBouncer pour tout le monde:","pooler unique devant RDS, multiplexage maximum,","mode de transaction pour l'API REST : split pooler","config par type de charge de travail. Lambda passe par l'un d'entre eux.","RDS Proxy pour la transaction Lambda + PgBouncer","Réplica en lecture séparée pour les travailleurs analytiques +","Mode de transaction PgBouncer pour REST + Lambda :","mode pour ECS: hybride. Itinéraire par type de client.","isoler la charge de travail au niveau DB."]}},{"kind":"p","page":52,"text":{"en":"You're running 3 workloads against the same Postgres RDS instance. max_connections = 300. They all need a connection pool. None of them want to share.","fr":"Trois charges se partagent la même instance RDS PostgreSQL. max_connections = 300. Chacune a besoin d’un pool de connexions et aucune ne veut le partager."}},{"kind":"p","page":52,"text":{"en":"Here's the setup:","fr":"Voici la configuration."}},{"kind":"p","page":52,"text":{"en":"→ NestJS REST API on ECS Fargate. Short transactions, 800 RPS, 10 tasks × 40 pool = 400 connections requested.","fr":"→ API REST NestJS sur ECS Fargate. Transactions courtes, 800 RPS et une demande de 400 connexions : 10 tâches × 40 connexions par pool."}},{"kind":"p","page":52,"text":{"en":"→ Background job workers. Long-running analytics queries. Hold a connection for 30–90 seconds each.","fr":"→ Workers exécutant des requêtes analytiques longues. Chaque requête monopolise une connexion de 30 à 90 secondes."}},{"kind":"p","page":52,"text":{"en":"→ Lambda functions. Bursty, cold-start heavy, 0–200 concurrent invocations.","fr":"→ Fonctions Lambda. Charge par rafales, nombreux démarrages à froid et de 0 à 200 appels simultanés."}},{"kind":"p","page":52,"text":{"en":"Three clients. One database. 300 max connections. Math doesn't math.","fr":"Trois types de clients, une seule base, 300 connexions au maximum. Les chiffres ne collent pas."}},{"kind":"p","page":52,"text":{"en":"You need to pool without breaking any of them. Pick your poison:","fr":"Quel découpage des pools permettra à ces trois charges de coexister ?"}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":52,"text":{"en":"PgBouncer transaction mode for everyone","fr":"Mode transaction de PgBouncer pour tout le monde"}},{"kind":"p","page":52,"text":{"en":": single pooler in front of RDS, maximum multiplexing.","fr":"Un seul gestionnaire de pool devant RDS, pour un multiplexage maximal."}}]},{"letter":"B","blocks":[{"kind":"p","page":52,"text":{"en":"PgBouncer session mode for the workers + transaction mode for the REST API","fr":"Mode session de PgBouncer pour les workers et mode transaction pour l’API REST"}},{"kind":"p","page":52,"text":{"en":": split pooler config by workload type. Lambda goes through one of them.","fr":"Configurer le pool selon la charge. Lambda passe par l’une des deux configurations."}}]},{"letter":"C","blocks":[{"kind":"p","page":53,"text":{"en":"RDS Proxy for Lambda + PgBouncer transaction mode for ECS","fr":"RDS Proxy pour Lambda et mode transaction de PgBouncer pour ECS"}},{"kind":"p","page":53,"text":{"en":": hybrid. Route by client type.","fr":"Montage hybride avec un routage par type de client."}}]},{"letter":"D","blocks":[{"kind":"p","page":53,"text":{"en":"Separate read replica for the analytics workers + PgBouncer transaction mode for REST + Lambda","fr":"Réplique de lecture séparée pour les workers analytiques et PgBouncer en mode transaction pour REST et Lambda"}},{"kind":"p","page":53,"text":{"en":": isolate the workload at the DB level.","fr":"Isoler les charges au niveau de la base."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"figure","page":54,"id":"054-03","width":800,"height":471,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["Answer: B — PgBouncer session mode for","workers + transaction mode for REST API %","800 RPS.","{API gets multiplexing","short te","(one instance)","Transat Mode Poo!","(oar 6432)","connections","Sesion mage posers tte","Workers keep ther session","long qeres","No one starves","‘Session Mod Poo!","Lam","bursty","(port 6433)","Postgres RDS","cold tats","‘max_connections = 300","(att ong ring)","Stays under 300 conections","rama itn te","eb aii ttn","eater ned. sane sage","‘natn mode 400 cat","pres"],"fr":["Réponse: B — mode de session PgBouncer pour","workers + mode de transaction pour l'API REST %","800 RPS.","API obtient le multiplexage","short te","(un cas)","Transat Mode Poo !","(oar 6432)","connexions","Sesion mage poseurs tte","Les travailleurs gardent leur session","longues qeres","Personne ne meurt de faim","«Session Mod Poo!","Lam","bousillé","(port 6433)","Postgres RDS","Tats froids","«max_connections — 300","(Att ong ring)","Séjours sous 300 conctions","rama itn te","eb aii ttn","Eater Ned, une sage sage","«Natn mode 400 cat","pres"]}},{"kind":"p","page":54,"text":{"en":"Answer: B — PgBouncer session mode for workers + transaction mode for REST API ✅","fr":"Réponse B : PgBouncer en mode session pour les workers et en mode transaction pour l’API REST ✅"}},{"kind":"p","page":54,"text":{"en":"This one separates engineers who've actually run PgBouncer in prod from ones who've only read the docs. Here's the breakdown:","fr":"La distinction ressort surtout quand on a exploité PgBouncer en production. Voici le détail."}},{"kind":"p","page":54,"text":{"en":"Why B wins (split pooler config by workload type):","fr":"Pourquoi retenir B, avec des pools adaptés à chaque charge ?"}},{"kind":"p","page":54,"text":{"en":"The whole point of PgBouncer is multiplexing — one backend Postgres connection serves many client connections, but only when it's safe to hand the connection back between transactions. That's transaction mode.","fr":"Le rôle de PgBouncer est de multiplexer : une connexion PostgreSQL peut servir à plusieurs clients, à condition qu’on puisse la rendre au pool entre les transactions. C’est le mode transaction."}},{"kind":"p","page":54,"text":{"en":"Transaction mode is perfect for the NestJS REST API: short transactions, 800 RPS, no session state, no SET LOCAL, no advisory locks held across queries, no prepared statements that need to survive. The REST API's 400 requested client connections collapse down to ~30–50 actual backend connections to Postgres. Math suddenly maths.","fr":"Il convient à l’API REST NestJS : transactions courtes, 800 RPS, aucun état de session, aucun SET LOCAL, verrou consultatif ou ordre préparé à conserver entre les requêtes. De 400 connexions demandées, on passe à environ 30 à 50 connexions PostgreSQL réelles."}},{"kind":"p","page":54,"text":{"en":"Transaction mode is catastrophic for the analytics workers. Their queries run 30–90 seconds and span multiple transactions — some hold session state, some use temp tables, some use SET search_path, some use cursors. Hand the connection back between transactions and that state is gone. Worse: at 800 RPS from the API side, the worker's chance of getting the same backend connection back on the next transaction is basically zero. The worker silently breaks.","fr":"Le mode transaction pose problème aux workers analytiques. Leurs requêtes durent 30 à 90 secondes et s’étendent sur plusieurs transactions. Elles utilisent parfois un état de session, des tables temporaires, SET search_path ou des curseurs. Rendre la connexion entre deux transactions fait perdre cet état. Avec les 800 RPS de l’API, la probabilité de retrouver la même connexion est presque nulle. Le worker dysfonctionne sans forcément le signaler."}},{"kind":"p","page":55,"text":{"en":"So you give the workers their own PgBouncer pool in session mode — one client connection = one backend connection for the whole session. They get fewer connections, but they hold them, which is what they actually need.","fr":"Attribuez donc aux workers leur propre pool PgBouncer en mode session. Une connexion client conserve la même connexion en base toute la session. Les workers en ont moins, mais les gardent aussi longtemps que nécessaire."}},{"kind":"p","page":55,"text":{"en":"The Lambda traffic goes through the REST API's transaction-mode pool (it's stateless, short-lived — same shape as the API). One pooler instance, two pool configs, two listening ports. PgBouncer supports this natively.","fr":"Le trafic Lambda passe par le pool de l’API en mode transaction : sans état et de courte durée. Une instance, deux configurations de pool et deux ports d’écoute. Selon le livre, PgBouncer prend ce montage en charge nativement."}},{"kind":"p","page":55,"text":{"en":"End state: API gets multiplexing, workers don't starve, total backend connections to Postgres stay under 300, nobody breaks. That's the boring correct answer that wins on call.","fr":"Au final, l’API bénéficie du multiplexage, les workers disposent des connexions nécessaires, le total PostgreSQL reste sous 300 et chaque charge fonctionne. Une configuration simple à exploiter en astreinte."}}],[{"kind":"p","page":55,"text":{"en":"...Why A is the trap (PgBouncer transaction mode for everyone):","fr":"Pourquoi A est tentant, avec le mode transaction pour tous"}},{"kind":"p","page":55,"text":{"en":"This is the answer most engineers reach for because \"transaction mode = best multiplexing.\" It works beautifully for the API. It silently destroys the workers.","fr":"Le mode transaction offre le meilleur multiplexage. Il fonctionne très bien pour l’API et provoque des pannes silencieuses chez les workers."}},{"kind":"p","page":55,"text":{"en":"The moment an analytics query needs anything that doesn't fit in one transaction — a temp table, a session variable, a SET LOCAL, a prepared statement, a cursor that outlives a transaction — PgBouncer hands the connection back to the pool. Next query? Different backend connection. State gone. Query fails or worse, returns wrong results.","fr":"Dès qu’une requête analytique a besoin d’un état au-delà d’une transaction, comme une table temporaire, une variable de session, un SET LOCAL, un ordre préparé ou un curseur persistant, PgBouncer remet la connexion dans le pool. La requête suivante peut utiliser une autre connexion et perdre cet état. Elle échoue ou, pire, renvoie des résultats erronés."}},{"kind":"p","page":55,"text":{"en":"The failure mode is the cruelest kind: it works in dev (low concurrency, same connection by luck), it works in staging (light load), it dies in prod when the API is hammering the pool and the workers can't get a stable connection. You'll find this at 3am during a financial close.","fr":"Ce défaut peut échapper au développement et à la préproduction, où la charge est basse et la connexion parfois réattribuée par hasard. En production, quand l’API monopolise le pool, les workers ne gardent plus leurs connexions. Cela se découvre à 3 h du matin pendant une clôture financière."}}],[{"kind":"p","page":55,"text":{"en":"Why C is wrong (RDS Proxy for Lambda + PgBouncer for ECS):","fr":"Pourquoi C ne convient pas, avec RDS Proxy pour Lambda et PgBouncer pour ECS"}},{"kind":"p","page":55,"text":{"en":"Defensible on paper. RDS Proxy is genuinely good for Lambda — it handles the cold-start connection storm, manages IAM auth, integrates with the VPC. If the question were just \"Lambda + Postgres,\" C is right.","fr":"RDS Proxy convient bien à Lambda : il absorbe les rafales de connexions aux démarrages à froid, gère IAM et s’intègre au VPC. Pour une question limitée à Lambda et PostgreSQL, C conviendrait."}},{"kind":"p","page":55,"text":{"en":"But C doesn't fix the workers. They're still long-running, they still need session state, and you've now introduced a second pooling product to operate, monitor, and pay for. RDS Proxy is also more expensive than PgBouncer per connection-hour, and it doesn't support session pinning across transactions the way session-mode PgBouncer does.","fr":"Les workers restent longtemps connectés et dépendent encore de l’état de session. Vous ajoutez un second produit à exploiter, surveiller et payer. Selon le livre, RDS Proxy coûte aussi plus par heure de connexion et ne conserve pas l’association entre transactions comme PgBouncer en mode session."}},{"kind":"p","page":55,"text":{"en":"C solves the easiest of the three problems and leaves the hardest one untouched.","fr":"C résout le plus simple des trois problèmes et laisse entier le plus difficile."}}],[{"kind":"p","page":56,"text":{"en":"Why D is the senior-engineer trap (read replica for workers):","fr":"Pourquoi D est tentant, avec une réplique de lecture pour les workers"}},{"kind":"p","page":56,"text":{"en":"This is the option that fools experienced engineers, because it pattern-matches to \"isolate the workload.\" And isolating analytics from OLTP at the DB level is genuinely a great idea — for a different problem.","fr":"Séparer l’analytique de l’OLTP en base est une bonne idée quand les charges se gênent. Ce scénario porte sur un autre problème."}},{"kind":"p","page":56,"text":{"en":"D solves read scaling and noisy neighbor on query plans / cache / IO. It does not solve the connection math. Your read replica still has its own max_connections ceiling. Your workers still hold connections for 30–90 seconds. You've just moved the connection exhaustion problem from the primary to the replica — and now you're paying for an extra RDS instance.","fr":"D augmente la capacité de lecture et isole plans de requête, cache et E/S. La réplique a toujours son plafond max_connections et les workers gardent leurs connexions 30 à 90 secondes. Vous déplacez l’épuisement des connexions du primaire à la réplique, avec une instance RDS de plus à payer."}},{"kind":"p","page":56,"text":{"en":"If the problem statement was \"analytics queries are starving the OLTP workload,\" D would be right. The problem statement is \"we don't have enough connections.\" Different pain. Different pattern.","fr":"D conviendrait si les requêtes analytiques privaient l’OLTP de ressources. Ici, il faut gérer le déficit de connexions."}},{"kind":"p","page":56,"text":{"en":"D is what you do after you have B working and you realize analytics is also competing for IOPS and buffer cache.","fr":"D devient pertinent après avoir mis B en place, si l’analytique sature aussi les IOPS et le cache de pages."}}]]},{"day":14,"title":{"en":"Safely Rolling Out a Risky Change","fr":"Déployer un changement risqué en toute sécurité"},"pages":[57,60],"topic":"reliability","correct":"D","scenario":[{"kind":"figure","page":57,"id":"057-02","width":800,"height":421,"alt":{"en":"Day 14 featured","fr":"Illustration de la question du jour 14"},"transcript":{"en":["System Design Labs","Pick the deploy strategy for this Friday checkout","rewrite that charges real cards.","ECS Fargate","sau","Web / Mobile","Clients","ALB","Postgres","Payment Jobs","(Paymentintents","Stipe","(Orders Table)","jeue","Blue/Green — spin up a parallel “green” environment","Canary — route 1% of lve traffic to the new version,","running the new code, smoke-test it, lip the load balancer.","watch error rates and p99 latency for 30 minutes,","Instant rollback by flipping back.","then ramp 5% ~» 25% -» 100%.","Feature Flag — deploy the new cade to 100% of tasks","Rolling — replace ECS tasks one ata time,","behind a fag defaulting to OFF. Then flip the flag for","Until the new version is fully rolled out.","(Old and new versions serve traffic side-by-side","internal users ~> 1% of customers -> 10% —+ 100%,","with an instant kil switch"],"fr":["System Design Labs","Choisissez la stratégie de déploiement pour ce vendredi checkout","réécrire qui charge de vraies cartes.","ECS Fargate","sau","Web / Mobile","Clients","ALB","Postgres","Paiement Emplois","(Paiements)","Stipe","(Tableau des commandes)","jeue","Bleu/Vert – créer un environnement « vert » parallèle","Canary — route 1% du trafic vers la nouvelle version,","exécuter le nouveau code, le tester, lèvre l'équilibreur de charge.","surveiller les taux d'erreur et la latence de p99 pendant 30 minutes,","Retour instantané en retournant.","puis rampe 5% — 25% -» 100%.","Drapeau de fonctionnalité : déployez le nouveau cade sur 100 % des tâches","Rolling — remplacer les tâches ECS une à la fois,","derrière un pédé par défaut à OFF. Puis retournez le drapeau pour","Jusqu'à ce que la nouvelle version soit entièrement déployée.","(Les anciennes et les nouvelles versions desservent le trafic côte à côte)","utilisateurs internes — > 1% des clients -> 10% — + 100%,","avec un interrupteur instantané kil"]}},{"kind":"p","page":57,"text":{"en":"You're shipping a rewrite of your checkout write path on Friday.","fr":"Vous livrez vendredi une réécriture du chemin d’écriture du paiement."}},{"kind":"p","page":57,"text":{"en":"Node.js on ECS Fargate. ~3,000 RPS at peak. Postgres with row-level locking on the orders table. The change touches the line of code that actually charges the customer's card — old path uses Stripe Charges API, new path uses PaymentIntents with 3DS.","fr":"Node.js tourne sur ECS Fargate, avec environ 3 000 RPS au pic et PostgreSQL verrouille les lignes de orders. Le changement touche le prélèvement sur la carte du client. L’ancien chemin utilise Stripe Charges API et le nouveau, PaymentIntents avec 3DS."}},{"kind":"p","page":57,"text":{"en":"The QA env is green. Load test passed. Your staff engineer signs off.","fr":"Les vérifications QA et le test de charge passent. L’ingénieur référent a validé."}},{"kind":"p","page":57,"text":{"en":"But it's checkout. If this breaks, money breaks. And you can't roll back a card that already got charged.","fr":"Il s’agit du paiement. Une panne touche directement l’argent et un rollback de code ne peut pas annuler une carte déjà débitée."}},{"kind":"p","page":57,"text":{"en":"Pick the deploy strategy:","fr":"Quelle stratégie de déploiement choisissez-vous ?"}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":57,"text":{"en":"Blue/Green — spin up a parallel \"green\" environment running the new code, smoke-test it, flip the load balancer. Instant rollback by flipping back.","fr":"Déploiement blue-green. Mettre en place un environnement « green » parallèle avec le nouveau code, effectuer des tests de bon fonctionnement et basculer le répartiteur de charge. Revenir instantanément en basculant dans l’autre sens."}}]},{"letter":"B","blocks":[{"kind":"p","page":57,"text":{"en":"Canary — route 1% of live traffic to the new version, watch error rates and p99 latency for 30 minutes, then ramp 5% → 25% → 100%.","fr":"Déploiement canary. Envoyer 1 % du trafic réel vers la nouvelle version. Observer les erreurs et le p99 pendant 30 minutes, puis passer à 5 %, 25 % et 100 %."}}]},{"letter":"C","blocks":[{"kind":"p","page":58,"text":{"en":"Rolling — replace ECS tasks one at a time. Old and new versions serve traffic side-by-side until the new version is fully rolled out.","fr":"Déploiement progressif. Remplacer les tâches ECS une par une. Ancienne et nouvelle versions servent le trafic ensemble pendant le déploiement."}}]},{"letter":"D","blocks":[{"kind":"p","page":58,"text":{"en":"Feature Flag — deploy the new code to 100% of tasks behind a flag defaulting to OFF. Then flip the flag for internal users → 1% of customers → 10% → 100%, with an instant kill switch.","fr":"Feature flag. Déployer le nouveau code sur toutes les tâches avec le flag désactivé. L’activer pour les utilisateurs internes, puis 1 %, 10 % et 100 % des clients, avec la possibilité de le couper immédiatement."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"figure","page":59,"id":"059-03","width":800,"height":478,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["‘System Design Labs","ANSWER:","Why D wins","Rollback isa","You target who","You can keep the","(Feature Flag):","config push,","Yh sees the new path,","old code path","not a deploy.","not what % of","warm for weeks.","random traffic.","Feature flags decouple","30S edge case on","deploy from release.","‘Sub-second.","{$0.99 customer and $40K","‘a specific issuing","The new code s","sto","No ECS restarts,","bank in Bra","828 customer shouldn't","100% of your ECS tasks —","no LB drain,","{get coin-flipped equally —","those users back while","no ONS TTL.","keeping everyone else","but it's dormant. Nothing","that’s not a strategy,","executes until you flip the flag.","that's hope.","on v2","A Why the other options look right — but quietly fail when the change touches money","Cc) Rolling","(D] Fosture Flag","Fest Fag","Blue","we","10%","= ee","Taek","Taek","Big bang. You ip everyone at once","Random isthe wrong targeting.","(id and new code run side-by-side,","Ifthe new payment Now ha a flaw","You cant contol which customers","cute:","that ony appears unde eal money","banks, regions might bein the","Iitwhich version, Shared OB +","19 — and the blast rau i stil","inconsistent","© Depey once. Release safely","money wt","© Target precisely. Roll back instantly.","with 100% impact","real money","© Keep old path ready a8 a safety net."],"fr":["«System Design Labs","RÉPONSE :","Pourquoi retenir D","Rollback isa","Vous ciblez qui","Vous pouvez garder le","(Caractéristiques du drapeau):","config push,","Yh voit le nouveau chemin,","Chemin d'accès ancien code","Pas un déploiement.","pas quel % de","Chaud pendant des semaines.","trafic aléatoire.","Drapeaux de feature decouple","30S edge case sur","Déploiement depuis Release.","«Sous-seconde.","0.99 $ client et 40K $","«une émission spécifique","Le nouveau code S","sto","Aucun redémarrage ECS,","Banque à Bra","828 clients ne devraient pas","100% de vos tâches ECS","pas de drain LB,","faites voler la monnaie à parts égales","Les utilisateurs sont de retour pendant que","Pas de TTL.","Garder tous les autres","mais c'est dormant. Rien","Ce n’est pas une stratégie,","s'exécute jusqu'à ce que vous retourniez le drapeau.","C'est de l'espoir.","sur v2","A Pourquoi les autres options semblent justes - mais échouent discrètement lorsque le changement touche l'argent","Cc) Roulant","(D) Drapeau Fosture","Fest Fag","Bleu","nous","10%","ee","Taek","Taek","Big bang. Vous ip tout le monde à la fois","Random est le mauvais ciblage.","(id et nouveau code s'exécutent côte à côte,","Si le nouveau paiement a maintenant un défaut","Vous ne pouvez pas indiquer quels clients","mignon:","que l'ony semble unde eal argent","banques, les régions pourraient être","Iitwhich version, Partagé OB+","19 — et le souffle rau i stil","incohérent","Depey une fois. Libérez en toute sécurité","argent wt","Ciblez avec précision. Remontez instantanément.","avec 100% d'impact","argent réel","Garder l'ancien chemin prêt a8 un filet de sécurité."]}},{"kind":"p","page":59,"text":{"en":"Answer: D — Feature Flag ✅","fr":"Réponse D : feature flag ✅"}},{"kind":"p","page":59,"text":{"en":"Here's why, and why the other three look right but quietly fail when the change touches money:","fr":"Voici pourquoi ce choix tient et comment les autres peuvent échouer sans bruit quand de l’argent est en jeu."}},{"kind":"p","page":59,"text":{"en":"Why D wins (Feature Flag):","fr":"Pourquoi retenir D, avec un feature flag ?"}},{"kind":"p","page":59,"text":{"en":"Feature flags decouple deploy from release. The new code ships to 100% of your ECS tasks — but it's dormant. Nothing executes until you flip the flag.","fr":"Un feature flag sépare déploiement et mise à disposition. Le code arrive sur 100 % des tâches ECS et reste inactif jusqu’à l’activation du flag."}},{"kind":"p","page":59,"text":{"en":"• Rollback is a config push, not a deploy. Sub-second. No ECS restarts, no LB drain, no DNS TTL.","fr":"• Pour revenir en arrière, diffusez une configuration. En moins d’une seconde, sans redémarrage ECS, vidage des connexions du répartiteur ni attente du TTL DNS."}},{"kind":"p","page":59,"text":{"en":"• You target who sees the new path, not what % of random traffic. $0.99 customer and $40K B2B customer shouldn't get coin-flipped equally — that's not a strategy, that's hope.","fr":"• Vous choisissez quels clients utilisent le nouveau chemin. Exposer au hasard un client qui paie 0,99 $ et un client B2B qui paie 40 000 $ de la même manière n’est pas une stratégie de risque."}},{"kind":"p","page":59,"text":{"en":"• You can keep the old code path warm for weeks. 3DS edge case on a specific issuing bank in Brazil? Flip those users back while keeping everyone else on v2.","fr":"• L’ancien chemin peut rester prêt pendant des semaines. En cas de problème 3DS avec une banque émettrice au Brésil, vous rebasculez ces seuls utilisateurs, tandis que les autres restent en v2."}}],[{"kind":"p","page":60,"text":{"en":"Why B is the trap (Canary):","fr":"Pourquoi B est tentant, avec un canary"}},{"kind":"list","page":60,"items":{"en":["1. Canary routes by request, not by customer. A B2B billing job hits your 1% canary 50 times in an hour. Bug on their card type? You've charged them 50 times before dashboards catch it.","2. Payment failures don't surface as 5xx errors — they surface as successful 200s that charged the wrong amount. Your error-rate alarm never fires."],"fr":["1. Le canary décrit répartit les requêtes, pas les clients. Une tâche de facturation B2B peut atteindre le canary à 1 % cinquante fois en une heure. Si son type de carte révèle un bogue, cinquante prélèvements partent avant qu’un tableau de bord ne le montre.","2. Les erreurs de paiement peuvent prendre la forme d’un 200 qui prélève le mauvais montant. L’alerte liée au nombre de 5xx ne se déclenche jamais."]}}],[{"kind":"p","page":60,"text":{"en":"Why A is wrong (Blue/Green):","fr":"Pourquoi A ne convient pas, avec un déploiement blue-green"}},{"kind":"p","page":60,"text":{"en":"\"Instant cutover\" is the problem. The moment you flip the LB, 100% of live traffic hits new code — including Stripe webhooks confirming PaymentIntents created by the old code. Cross-version race condition on real money. Rollback doesn't undo a charge.","fr":"La bascule instantanée est le problème. Le répartiteur envoie aussitôt 100 % du trafic au nouveau code, y compris les webhooks Stripe qui confirment des PaymentIntents créés par l’ancien code. C’est une condition de concurrence entre versions sur de vrais prélèvements. Revenir à l’ancienne version n’annule aucun débit."}}],[{"kind":"p","page":60,"text":{"en":"Why C is wrong (Rolling):","fr":"Pourquoi C ne convient pas, avec le déploiement progressif"}},{"kind":"p","page":60,"text":{"en":"For 5–10 minutes, old and new tasks serve checkout simultaneously. \"Create order\" hits v1. \"Confirm payment\" webhook 800ms later hits v2. Inconsistent state written by code that was never tested together.","fr":"Pendant cinq à dix minutes, les deux versions traitent les paiements en parallèle. La création de commande atteint v1. 800 ms plus tard, le webhook de confirmation arrive sur v2. On peut écrire un état incohérent avec deux versions jamais testées ensemble."}}]]},{"day":15,"title":{"en":"Fast “Has the User Seen This?” Checks","fr":"Vérifier rapidement si l’utilisateur a déjà vu un contenu"},"pages":[61,64],"topic":"scale","correct":"A","scenario":[{"kind":"figure","page":61,"id":"061-02","width":800,"height":421,"alt":{"en":"Day 15 featured","fr":"Illustration de la question du jour 15"},"transcript":{"en":["You’re running a content recommendation feed.","System Design Labs","Every API call asks: “has this user already seen post X?”","has user seen","APICall","post x?","(et feed) —>|","Read Replica","(optional)","Feed","seen not seen","Mobile App","(Node js)","Postgres","(user_seen_posts)","Postgres","Read Replica","808+ rows","Redis Cache","Asyne Replication","(General)","Put a Bloom filter per user in Redis.","Cache the full user",".en_posts set per user","Sub-millisecond \"definitely not seen” check,","6a SET. Exact answer,","fall through to Postgres only on a hit.","no false positives.","‘Move the whole table to Cassandra.","Wide-column store handles the row count better.","‘Add a Postgres read replica +","connection pooler. Same data, more horsepower."],"fr":["Vous exécutez un flux de recommandation de contenu.","System Design Labs","Chaque appel d’API demande : « cet utilisateur a-t-il déjà vu le post X ? »","L'utilisateur a vu","APICall","post x ?","(et flux) — >","Lire la réplique","(facultatif)","Flux","vu non vu","App mobile","(Nœud js)","Postgres","(user_seen_posts)","Postgres","Lire la réplique","808+ lignes","Redis Cache","Asyne Replication","(Général)","Mettez un filtre Bloom par utilisateur dans Redis.","Mettre en cache l'utilisateur complet",".fr_posts définis par utilisateur","vérification submilliseconde \"certainement pas vu\",","6a SET. Réponse exacte,","tomber à Postgres seulement sur un coup.","Pas de faux positifs.","Déplacez toute la table vers Cassandre.","Le magasin à large colonne gère mieux le nombre de lignes.","‘Ajouter une réplique de lecture Postgres +","Mêmes données, plus de puissance."]}},{"kind":"p","page":61,"text":{"en":"You're running a content recommendation feed. 50M users.","fr":"Vous exploitez un fil de recommandations de contenu pour 50 millions d’utilisateurs."}},{"kind":"p","page":61,"text":{"en":"Every API call asks: \"has this user already seen post X?\"","fr":"Chaque appel API demande si l’utilisateur a déjà vu la publication X."}},{"kind":"p","page":61,"text":{"en":"Right now you're hitting Postgres on every check. The user_seen_posts table has 80B rows and growing. p99 latency on the feed endpoint just crossed 600ms and your DBA is sending you screenshots of CPU graphs at 2am.","fr":"Chaque contrôle consulte aujourd’hui PostgreSQL. user_seen_posts contient 80 milliards de lignes et continue de grossir. Le p99 de l’endpoint du fil dépasse 600 ms et le DBA vous envoie des graphiques CPU à 2 h du matin."}},{"kind":"p","page":61,"text":{"en":"Here's the setup:","fr":"Voici la configuration."}},{"kind":"p","page":61,"text":{"en":"• Feed service: Node.js, ~120K RPS at peak","fr":"• Le service de fil tourne sous Node.js, avec environ 120 000 RPS au pic."}},{"kind":"p","page":61,"text":{"en":"• \"Already seen\" check: SELECT against Postgres on every recommendation","fr":"• Chaque recommandation entraîne un SELECT dans PostgreSQL pour vérifier si elle a déjà été vue."}},{"kind":"p","page":61,"text":{"en":"• Table: user_seen_posts(user_id, post_id, seen_at) (partitioned, indexed, still slow)","fr":"• La table user_seen_posts(user_id, post_id, seen_at) est partitionnée, indexée et toujours lente."}},{"kind":"p","page":61,"text":{"en":"• Cache hit ratio is fine. The problem is the long tail of cold lookups","fr":"• Le taux de succès du cache est bon. La longue traîne des recherches sur des données froides pose problème."}},{"kind":"p","page":61,"text":{"en":"• False positives on \"already seen\" are tolerable. False negatives (showing the same post twice) are not great but survivable","fr":"• Un faux positif « déjà vu » est tolérable. Un faux négatif qui affiche deux fois la même publication est gênant, mais acceptable."}},{"kind":"p","page":61,"text":{"en":"Product wants p99 under 100ms. You have one sprint. What do you do?","fr":"L’équipe produit exige un p99 inférieur à 100 ms. Vous avez un sprint. Quelle option choisissez-vous ?"}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":62,"text":{"en":"Put a Bloom filter per user in Redis. Sub-millisecond \"definitely not seen\" check, fall through to Postgres only on a hit.","fr":"Placer un filtre de Bloom par utilisateur dans Redis. Répondre en moins d’une milliseconde pour les contenus assurément jamais vus. Consulter PostgreSQL seulement si le filtre indique une présence possible."}}]},{"letter":"B","blocks":[{"kind":"p","page":62,"text":{"en":"Cache the full user_seen_posts set per user in Redis as a SET. Exact answer, no false positives.","fr":"Conserver dans Redis l’ensemble complet user_seen_posts par utilisateur sous forme de SET. La réponse est exacte, sans faux positif."}}]},{"letter":"C","blocks":[{"kind":"p","page":62,"text":{"en":"Move the whole table to Cassandra. Wide-column store handles the row count better.","fr":"Migrer toute la table vers Cassandra. Son stockage à colonnes larges gère mieux ce nombre de lignes."}}]},{"letter":"D","blocks":[{"kind":"p","page":62,"text":{"en":"Add a Postgres read replica + connection pooler. Same data, more horsepower.","fr":"Ajouter une réplique de lecture PostgreSQL et un gestionnaire de pool de connexions. Mêmes données, plus de capacité."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"p","page":63,"text":{"en":"◧ Author's diagram unavailable (source image returned 404)","fr":"◧ Schéma de l’auteur indisponible : l’image source renvoyait une erreur 404."}},{"kind":"p","page":63,"text":{"en":"A — Bloom Filter per user in Redis (THE RIGHT ANSWER)","fr":"A — Un filtre de Bloom par utilisateur dans Redis (bonne réponse)"}},{"kind":"p","page":63,"text":{"en":"Bloom filters give one ironclad guarantee: \"this item is DEFINITELY NOT in the set.\" If the filter says no → skip Postgres entirely. If it says maybe → fall through to confirm.","fr":"Un filtre de Bloom donne une garantie absolue lorsqu’il dit « cet élément n’est pas dans l’ensemble ». Dans ce cas, inutile d’interroger PostgreSQL. S’il indique une présence possible, la base sert à confirmer."}},{"kind":"p","page":63,"text":{"en":"Why it wins here:","fr":"Pourquoi cette solution fonctionne ici"}},{"kind":"p","page":63,"text":{"en":"• ~97% of feed checks are for posts the user has never seen → sub-millisecond \"definitely no\" from Redis, Postgres never touched","fr":"• Environ 97 % des contrôles concernent des publications encore jamais vues. Redis répond « assurément absent » en moins d’une milliseconde sans passer par PostgreSQL."}},{"kind":"p","page":63,"text":{"en":"• Memory math: 10K posts per user in a Bloom filter at 1% false-positive = 12 KB. Same data as a Redis SET = 80 KB+, and grows linearly","fr":"• Pour 10 000 publications par utilisateur, un filtre de Bloom avec 1 % de faux positifs tient dans 12 Ko. Un SET Redis pour les mêmes données demande plus de 80 Ko et croît linéairement."}},{"kind":"p","page":63,"text":{"en":"• At 50M users: Bloom filter = ~600 GB. Redis SET = ~4 TB. That's the difference","fr":"• Pour 50 millions d’utilisateurs, comptez environ 600 Go en filtres de Bloom contre environ 4 To en SET Redis."}},{"kind":"p","page":63,"text":{"en":"• Real-world users: Medium's \"have you read this\", Cassandra's SSTable short-circuit, Bitcoin's SPV wallets","fr":"• Exemples : le contrôle de lecture de Medium, les vérifications rapides de SSTable dans Cassandra et les portefeuilles SPV Bitcoin."}},{"kind":"p","page":63,"text":{"en":"The 1% false positive here means you occasionally skip showing a post the user hasn't seen. Product said that's tolerable. Bloom filters never produce false negatives (showing the same post twice) — which would be the dealbreaker.","fr":"Le taux de 1 % de faux positifs signifie qu’une publication jamais vue sera, à l’occasion, écartée. L’équipe produit accepte ce compromis. Un filtre de Bloom ne produit aucun faux négatif qui ferait réapparaître une publication déjà vue, ce que le corrigé juge rédhibitoire."}}],[{"kind":"p","page":63,"text":{"en":"B — Redis SET per user (SENIOR ENGINEER TRAP)","fr":"B — Un SET Redis par utilisateur (option tentante)"}},{"kind":"p","page":63,"text":{"en":"Looks strictly better on paper — same O(1) speed, plus perfect accuracy, no false positives. SISMEMBER is battle-tested.","fr":"Sur le papier, le SET offre la même vitesse en O(1) et une réponse exacte, sans faux positif. SISMEMBER a fait ses preuves."}},{"kind":"p","page":63,"text":{"en":"The trap: memory explodes on power users. A user with 50K posts seen = 3–4 MB in a Redis SET. Your top 5% users blow up the Redis cluster. You'll either over-provision (expensive) or start evicting hot users (defeats the whole point).","fr":"La mémoire explose chez les gros utilisateurs. Un utilisateur ayant vu 50 000 publications occupe 3 à 4 Mo dans un SET Redis. Les 5 % d’utilisateurs les plus actifs font gonfler le cluster. Il faut surdimensionner Redis ou évincer ces utilisateurs très actifs, ce qui annule le bénéfice."}},{"kind":"p","page":63,"text":{"en":"Rule of thumb: Redis SET when cardinality is small (<1K per key) or false positives are unacceptable. Bloom filter when cardinality is large and \"probably not\" is good enough.","fr":"Utilisez un SET Redis si la cardinalité est faible, par exemple moins de 1 000 éléments par clé, ou si les faux positifs sont inacceptables. Un filtre de Bloom convient aux cardinalités élevées quand une réponse probabiliste suffit."}}],[{"kind":"p","page":64,"text":{"en":"C — Move to Cassandra (RIGHT PATTERN, WRONG PROBLEM)","fr":"C — Migrer vers Cassandra (patron pertinent dans un autre cas)"}},{"kind":"p","page":64,"text":{"en":"Cassandra handles wide-column data and massive row counts fine. But the problem isn't storage — Postgres with proper partitioning handles 80B rows. The problem is read latency under load.","fr":"Cassandra sait gérer les données à colonnes larges et beaucoup de lignes. PostgreSQL bien partitionné peut stocker 80 milliards de lignes. Le problème se manifeste dans la latence de lecture sous charge."}},{"kind":"p","page":64,"text":{"en":"Switching storage engines doesn't fix the read pattern. You're still doing a point lookup per recommendation. Now you've added a multi-quarter migration + new ops skillset to solve what's fixable in a sprint with 12 KB per user in Redis.","fr":"Changer de moteur ne change pas les accès : une recherche ponctuelle par recommandation. Il faudrait plusieurs trimestres et de nouvelles compétences d’exploitation pour un problème réglable en un sprint avec 12 Ko par utilisateur dans Redis."}},{"kind":"p","page":64,"text":{"en":"Cassandra is the answer when the bottleneck is write throughput or wide-row scans. Not for 120K point lookups per second on a hot path.","fr":"Cassandra convient si le débit d’écriture ou le parcours de lignes larges est le goulet d’étranglement. Ici, le chemin critique effectue 120 000 consultations ponctuelles par seconde."}}],[{"kind":"p","page":64,"text":{"en":"D — Postgres read replica + connection pooler (CAPACITY ≠ COST)","fr":"D — Réplique de lecture PostgreSQL et pool de connexions (plus de capacité)"}},{"kind":"p","page":64,"text":{"en":"Replicas buy horsepower, not efficiency. You're still hitting disk on every check, still doing a B-tree lookup, still paying round-trip per request. 3 replicas → maybe 2.5x read throughput before replication lag and connection limits bite.","fr":"Les répliques ajoutent de la capacité. Chaque contrôle implique toujours un accès disque, une recherche B-tree et un aller-retour. Trois répliques multiplient peut-être le débit de lecture par 2,5 avant que le retard de réplication et les plafonds de connexions entrent en jeu."}},{"kind":"p","page":64,"text":{"en":"To hit p99 <100ms at 120K RPS, you don't need more database — you need to not hit the database for the 97% of requests where the answer is \"no.\"","fr":"Pour tenir sous 100 ms au p99 à 120 000 RPS, évitez d’interroger la base dans les 97 % de cas où la réponse est négative."}},{"kind":"p","page":64,"text":{"en":"This is the option chosen by teams who treat every performance problem as a capacity problem.","fr":"Cette option est celle des équipes qui assimilent tout problème de performance à un manque de capacité."}}]]},{"day":16,"title":{"en":"Taming a Hot Partition Key","fr":"Soulager une clé de partition trop sollicitée"},"pages":[65,68],"topic":"scale","correct":"A","scenario":[{"kind":"figure","page":65,"id":"065-02","width":800,"height":420,"alt":{"en":"Day 16 featured","fr":"Illustration de la question du jour 16"},"transcript":{"en":["tem Design","abs","You’re running a multi-tenant analytics pipeline on DynamoDB.","One tenant 100x’s overnight and causes a hot parti","ion.","‘Table: events","DynamoDB","~12K writes/see","total","‘SK: event_timestamp","Hot tenant:","Write","(al)","(single key)","Ingestion","wm B","Producers","Other tenants:","Service","Analytics","Data","(Tenants)","“IS WPS each","Streams","Consumers","Warehouse","Hot Partition","Write sharding — append a random suffix","Jitter the writes — add randomized delay","A]","to the PK (tenant_id#0 ... tenant_id#9),","2)","(0-500ms) on the producer client.","Partition splitting — bump table WCU and","‘Time-bucket the key — change PK to","let DynamoDB auto-split the hot partition","tenant_id#YYYY-MM-DD-HH."],"fr":["tem Design","abs","Vous exécutez un pipeline d'analyse multi-locataires sur DynamoDB.","Un locataire 100x nuit et provoque une partie chaude","ion.","«Tableau: événements","DynamoDB","12K écrit/voit","Total","‘SK: event_timestamp","Locataire :","Ecrire","(al)","(clé unique)","Ingestion","wm B","Producteurs","Autres locataires :","Service","Analyses","Données","(Tenants)","« IS WPS chaque","Flux","Consommateurs","Entrepôt","Partition chaude","Write sharding — ajouter un suffixe aléatoire","Jitter les écritures — ajouter un délai aléatoire","A]","à la PK (locataire_id — 0 ... locataire_id — 9),","2)","(0-500ms) sur le client producteur.","Séparation des partitions — table à bosses","‘Time-bucket la clé — changer PK à","laisser DynamoDB diviser automatiquement la partition chaude","locataire_id — AAAA-MM-JJ-HH."]}},{"kind":"p","page":65,"text":{"en":"You're running a multi-tenant analytics pipeline on DynamoDB. 200 tenants, 12K writes/sec total. Everything is fine — until it isn't.","fr":"Vous exploitez un pipeline analytique multitenant sur DynamoDB. Il dessert 200 tenants pour un total de 12 000 écritures/s. Jusque-là, tout fonctionnait."}},{"kind":"p","page":65,"text":{"en":"One tenant onboards a massive customer overnight. Their event volume 100x's. Now that one tenant is hitting 9K writes/sec on a single partition key. The other 199 tenants sit idle.","fr":"Du jour au lendemain, l’un des tenants accueille un très gros client. Son volume d’événements est multiplié par 100. Il atteint à lui seul 9 000 écritures/s sur une unique clé de partition. Les 199 autres tenants génèrent très peu de trafic."}},{"kind":"p","page":65,"text":{"en":"ProvisionedThroughputExceeded errors start firing. P99 write latency spikes from 8ms to 400ms. Your on-call gets paged. Everyone is getting throttled because of one key.","fr":"Les erreurs ProvisionedThroughputExceeded se multiplient. Le p99 de la latence d’écriture passe de 8 ms à 400 ms. L’équipe d’astreinte reçoit une alerte. Une seule clé suffit à faire brider le trafic de tous les tenants."}},{"kind":"p","page":65,"text":{"en":"Here's the setup:","fr":"Voici la configuration."}},{"kind":"p","page":65,"text":{"en":"• Table: events (DynamoDB, on-demand capacity)","fr":"• Table : events (DynamoDB, capacité à la demande)"}},{"kind":"p","page":65,"text":{"en":"• PK: tenant_id · SK: event_timestamp","fr":"• Clé de partition (PK) : tenant_id · Clé de tri (SK) : event_timestamp"}},{"kind":"p","page":65,"text":{"en":"• Hot tenant: ~9K WPS · All other tenants: ~15 WPS each","fr":"• Tenant très actif : environ 9 000 écritures/s · Autres tenants : environ 15 écritures/s chacun"}},{"kind":"p","page":65,"text":{"en":"• Single partition key absorbing all 9K writes — DynamoDB's per-partition limit is the wall","fr":"• Une seule clé de partition concentre les 9 000 écritures/s et se heurte à la limite par partition de DynamoDB."}},{"kind":"p","page":65,"text":{"en":"Classic hot partition. What do you do?","fr":"C’est un cas classique de partition chaude. Que faites-vous ?"}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":65,"text":{"en":"Write sharding — append a random suffix to the PK (tenant_id#0 … tenant_id#9).","fr":"Sharding en écriture : ajouter un suffixe aléatoire à la clé de partition (tenant_id#0 … tenant_id#9)."}}]},{"letter":"B","blocks":[{"kind":"p","page":66,"text":{"en":"Jitter the writes — add randomized delay (0–500ms) on the producer client.","fr":"Ajouter du jitter aux écritures : le producteur introduit un délai aléatoire de 0 à 500 ms."}}]},{"letter":"C","blocks":[{"kind":"p","page":66,"text":{"en":"Partition splitting — bump table WCU and let DynamoDB auto-split the hot partition.","fr":"Fractionner la partition : augmenter la capacité d’écriture de la table (WCU) et laisser DynamoDB scinder automatiquement la partition chaude."}}]},{"letter":"D","blocks":[{"kind":"p","page":66,"text":{"en":"Time-bucket the key — change PK to tenant_id#YYYY-MM-DD-HH.","fr":"Segmenter la clé par fenêtre de temps : remplacer la clé de partition par tenant_id#YYYY-MM-DD-HH."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"figure","page":67,"id":"067-03","width":800,"height":533,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["System Design Labs","— WRITE SHARDING (THE RIGHT ANSWER)","Append a random suffix to the PK to spread writes across multiple partitions.","10 shards = 900 WPS each | Throttling stops | P99 latency back to single digits","Append random suffix","tenant _id#0.. tenant_id#9","DynamoDB Table: events,","Shard / Parton 0","900 Ws","seem","Shard Parton","100 WPS","8:","Producers","(Tenants)","Shard Parton 2","ynamoDB","Analytics","Data","900 WPS","‘Streams","‘Consumers","Warehouse","Shard / Partin 9","900 WPS","READ PATH (Scatter","@ 10 random sutios (0-8)","Q avery","10 suffixes in parallel","© Wites cistioted across 10 partitions","New Key Design","© -900 WPS per shard (<< it)","Ph","tenant_id#(0.9)","GB Merge resuits and sort by timestamp","© Trotting eiminated","Wirltes are evenly distributed by the hash funetion","@ PooIatency back to single digits","‘ross 10 logical partitions.","This is the canonical fix for hot partitions — and the pattern AWS documents."],"fr":["System Design Labs","ÉCRIVEZ LE BARRI — RE (LA BONNE RÉPONSE)","Ajoutez un suffixe aléatoire au PK pour répartir les écritures sur plusieurs partitions.","10 éclats — 900 WPS chacun — Throttling arrête — latence P99 retour à un seul chiffre","Ajouter un suffixe aléatoire","_id — 0.. _id — 9","DynamoDB Table : événements,","Shard / Parton 0","900 Ws","semble","Shard Parton","100 WPS","8:","Producteurs","(Tenants)","Shard Parton","ynamoDB","Analyses","Données","900 WPS","«Streams","«Consommateurs","Entrepôt","Shard / Partin 9","900 WPS","LIRE LE CHEMIN (Scatter)","10 sutios aléatoires (0-8)","Q avery","10 suffixes en parallèle","Wites cistioted à travers 10 partitions","Nouvelle conception de clé","-900 WPS par fragment ( — it)","Ph","locataire_id — (0,9)","GB Fusionner les poursuites et trier par horodatage","Trotting eiminé","Les wirltes sont uniformément distribuées par la fonction de hachage","PooIatency de retour à un seul chiffre","« 10 partitions logiques.","Il s'agit du correctif canonique pour les partitions à chaud — et le modèle des documents AWS."]}},{"kind":"p","page":67,"text":{"en":"A — Write Sharding (THE RIGHT ANSWER)","fr":"A — Sharding en écriture (bonne réponse)"}},{"kind":"p","page":67,"text":{"en":"DynamoDB hashes the partition key to decide which physical shard handles the write. One PK value = one shard = one wall. When that tenant hits 9K WPS, the shard caps out.","fr":"DynamoDB calcule le hachage de la clé de partition pour choisir le shard physique qui reçoit l’écriture. Une valeur de clé, un shard, une limite. Quand ce tenant atteint 9 000 écritures/s, le shard sature."}},{"kind":"p","page":67,"text":{"en":"The fix: append a random suffix at write time — tenant_id#0 through tenant_id#9. Now the hash function sees 10 different keys and distributes writes across 10 logical partitions (~900 WPS each, well under the limit). Throttling stops, P99 drops back to single digits.","fr":"La solution consiste à ajouter un suffixe aléatoire à l’écriture, de tenant_id#0 à tenant_id#9. La fonction de hachage reçoit désormais dix clés distinctes. Les écritures se répartissent sur dix partitions logiques, à raison d’environ 900 écritures/s chacune, bien en dessous de la limite. Le bridage cesse et le p99 redescend sous les 10 ms."}},{"kind":"p","page":67,"text":{"en":"The read cost: scatter-gather across all 10 suffixes to query that tenant's data. For a write-heavy analytics pipeline, that's the right tradeoff.","fr":"Côté lecture, il faut interroger les dix suffixes et réunir les résultats (scatter-gather) pour consulter les données du tenant. Ce compromis convient à un pipeline analytique qui reçoit surtout des écritures."}},{"kind":"p","page":67,"text":{"en":"This is literally the pattern AWS documents as the canonical fix for hot partitions.","fr":"AWS documente cette approche comme la solution de référence pour les partitions chaudes."}}],[{"kind":"p","page":68,"text":{"en":"C — Partition Splitting (SENIOR ENGINEER TRAP)","fr":"C — Fractionnement de la partition (choix trompeur)"}},{"kind":"p","page":68,"text":{"en":"DynamoDB does auto-split partitions — so this sounds right. But the split is based on throughput, not key cardinality. If one PK value generates 9K WPS, all those writes still hash to the same destination after the split. You can't split a single key across two physical shards.","fr":"DynamoDB sait fractionner automatiquement les partitions, d’où l’attrait de cette option. Le fractionnement dépend toutefois du débit, et non du nombre de valeurs de clé. Si une seule valeur de clé génère 9 000 écritures/s, elles continuent toutes d’être dirigées vers la même destination après le fractionnement. Une valeur de clé ne peut pas être répartie sur deux shards physiques."}},{"kind":"p","page":68,"text":{"en":"You'll see the partition split in CloudWatch, assume the problem is fixed, and then get paged again 10 minutes later. It's the answer that survives the design doc and dies in the war room.","fr":"CloudWatch affichera le fractionnement. Vous penserez avoir résolu le problème, puis une nouvelle alerte arrivera dix minutes plus tard. Une solution plausible sur le papier qui échoue en pleine gestion d’incident."}}],[{"kind":"p","page":68,"text":{"en":"B — Jitter the writes","fr":"B — Ajouter du jitter aux écritures"}},{"kind":"p","page":68,"text":{"en":"Jitter is a real pattern — it solves the thundering herd problem, where N clients fire requests at the same millisecond and create a spike. Spreading those over 500ms smooths the burst.","fr":"Le jitter est une technique éprouvée contre les rafales de requêtes synchronisées (thundering herd). Si N clients envoient leurs requêtes à la même milliseconde, les échelonner sur 500 ms permet de lisser le pic."}},{"kind":"p","page":68,"text":{"en":"But a hot partition is a sustained 9K WPS, not a burst. Adding delay doesn't reduce the rate — DynamoDB still sees 9K WPS on the same partition. You just made every write slower for zero benefit.","fr":"Ici, la partition chaude subit un débit durable de 9 000 écritures/s. Décaler les écritures ne réduit pas le débit : DynamoDB reçoit toujours 9 000 écritures/s sur la même partition. Chaque écriture prend davantage de temps, sans contrepartie."}}],[{"kind":"p","page":68,"text":{"en":"D — Time-bucket the key","fr":"D — Segmenter la clé par fenêtre de temps"}},{"kind":"p","page":68,"text":{"en":"tenant_id#2026-05-21-14 is a real pattern for time-series data — it keeps per-bucket size manageable and enables efficient TTL expiry.","fr":"Une clé comme tenant_id#2026-05-21-14 convient aux séries temporelles : elle limite la taille des segments et facilite l’expiration par TTL."}},{"kind":"p","page":68,"text":{"en":"But at any given hour, you still have one partition key absorbing all 9K WPS for that tenant. You renamed the hot partition to a hot time bucket. Same problem, new name. Plus now your reads have to query 24 different PKs for a day's worth of data.","fr":"Pendant une heure donnée, une seule clé de partition absorbe toujours les 9 000 écritures/s de ce tenant. La partition chaude est simplement devenue un créneau horaire chaud. En plus, il faut désormais interroger 24 clés de partition pour lire une journée de données."}}]]},{"day":17,"title":{"en":"Backpressure on an Overwhelmed Consumer","fr":"Appliquer la contre-pression à un consommateur saturé"},"pages":[69,72],"topic":"reliability","correct":"D","scenario":[{"kind":"figure","page":69,"id":"069-02","width":800,"height":421,"alt":{"en":"Day 17 featured","fr":"Illustration de la question du jour 17"},"transcript":{"en":["‘system Design Labs","The consumer can't keep up. The producer doesn't know it","What do you do?","Producer","Kafka topic","Postgres","External HTTP","5,000 events/sec","Lag: 12 min","Processing -800","‘events/see","write","(bottleneck)","(growing)","(climbing)","Memory: 89%","~4 minutes before JVM GC-thrashing","‘SLA: events mustbe processed,","andthe pod gets OOM-kiled.","Drop events on the floor — fail fast, return early,","Block the producer — make the consumer signal","let the lag burn down. The system stays alive,","‘slow down,” apply backpressure upstream","oO","I)","until it catches up.","Buffer harder","bigger in-memory queue,","Rate-limit + load-shed — cap consumption rate,","larger batch size, scale the consumer","route the overflow to a DLQ or secondary","to absorb the spike.","topic for later replay."],"fr":["«système Design Labs","Le consommateur ne peut pas suivre. Le producteur ne le sait pas","Qu'est-ce que tu fais ?","Producteur","Kafka topic","Postgres","HTTP externe","5 000 événements/sec","Lag: 12 min","Traitement -800","«événements/voir","écrire","(goulot d'étranglement)","(croissance)","(montée)","Mémoire: 89%","4 minutes avant le GC-thrashing de JVM","«SLA: les événements doivent être traités,","et la capsule est grillée.","Drop événements sur le sol - échouer rapidement, revenir tôt,","Bloquer le producteur - faire le signal du consommateur","laisser le lag brûler. Le système reste en vie,","« ralentir », appliquer une contre-pression en amont","oO","I)","Jusqu'à ce qu'il rattrape.","Tampon plus dur","une plus grande file d'attente en mémoire,","Taux-limite + taux de consommation de plafonnement","plus grande taille de lot, mettre à l'échelle le consommateur","router le trop-plein vers un DLQ ou secondaire","pour absorber le pic.","Sujet à rejouer ultérieurement."]}},{"kind":"p","page":69,"text":{"en":"Your Kafka consumer is processing 800 events/sec.","fr":"Votre consommateur Kafka traite 800 événements/s."}},{"kind":"p","page":69,"text":{"en":"The producer just hit 5,000 events/sec and it's not slowing down.","fr":"Le producteur vient d’atteindre 5 000 événements/s et ne ralentit pas."}},{"kind":"p","page":69,"text":{"en":"Lag chart: 12 minutes behind and climbing. Consumer memory: 89% and rising. The on-call alert just fired. You have ~4 minutes before the JVM starts GC-thrashing and the pod gets OOM-killed.","fr":"Le retard de consommation atteint 12 minutes et se creuse. La mémoire du consommateur est utilisée à 89 % et la courbe monte. L’astreinte vient d’être alertée. Il vous reste environ quatre minutes avant que la JVM passe son temps dans le ramasse-miettes et que le pod soit arrêté faute de mémoire (OOM)."}},{"kind":"p","page":69,"text":{"en":"Here's the setup:","fr":"Voici la configuration."}},{"kind":"p","page":69,"text":{"en":"Producer → Kafka topic (5K events/sec, growing)","fr":"Producteur → topic Kafka (5 000 événements/s, en hausse)"}},{"kind":"p","page":69,"text":{"en":"Consumer → spring-kafka @KafkaListener, batch=500, processes ~800 events/sec","fr":"Consommateur → spring-kafka @KafkaListener, batch=500, environ 800 événements traités par seconde"}},{"kind":"p","page":69,"text":{"en":"Downstream → Postgres write + external HTTP call (the real bottleneck)","fr":"En aval → écriture dans PostgreSQL et appel HTTP externe, le vrai goulot d’étranglement"}},{"kind":"p","page":69,"text":{"en":"SLA → events must be processed, not silently dropped","fr":"SLA → tous les événements doivent être traités, sans perte silencieuse."}},{"kind":"p","page":69,"text":{"en":"The consumer can't keep up. The producer doesn't know it. What do you do?","fr":"Le consommateur n’arrive plus à suivre et le producteur n’en sait rien. Que faites-vous ?"}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":69,"text":{"en":"Drop events on the floor — fail fast, return early, let the lag burn down. The system stays alive.","fr":"Abandonner les événements en trop : sortir immédiatement du traitement pour résorber le retard et garder le système en état de marche."}}]},{"letter":"B","blocks":[{"kind":"p","page":70,"text":{"en":"Block the producer — make the consumer signal \"slow down,\" apply backpressure upstream until it catches up.","fr":"Bloquer le producteur : le consommateur lui signale de ralentir et applique de la contre-pression en amont jusqu’à rattraper son retard."}}]},{"letter":"C","blocks":[{"kind":"p","page":70,"text":{"en":"Buffer harder — bigger in-memory queue, larger batch size, scale the consumer to absorb the spike.","fr":"Augmenter le tampon : agrandir la file en mémoire et les lots, puis ajouter des instances du consommateur pour absorber le pic."}}]},{"letter":"D","blocks":[{"kind":"p","page":70,"text":{"en":"Rate-limit + load-shed — cap consumption rate, route the overflow to a DLQ or secondary topic for later replay.","fr":"Limiter le débit et délester : plafonner le débit de consommation et envoyer le surplus vers une DLQ ou un topic secondaire pour le rejouer plus tard."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"figure","page":71,"id":"071-03","width":800,"height":533,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["System Design Labs","@ ANSWER: D — Rate-limit + load-shed","@ Goal: Keep the system healthy, meet the SLA, and process overflow later — not drop, not block.","Consumer (epring-katka)","publish","Kafkalistener, batch=500","Producer","Kafka topic","ibe","Postgres","External HTTP","5,000 events/see","events","(bottleneck)","(growing)","Overflow consumer group","write","© wat this achieves","(off-peak drain)","| @ Producer eens producing","Processes later","© Primary consumer stays heathy","Overflow topic","© SLAmet nothing i cropped","Why others lose:","© why d wins:","‘The SLA says events must be processed — not dropped, not blocked.","Drop events on the floor","Violates the SLA, Events are lost forever.","That kills A and B immediately.","LA","Cap the consumer's intake at ~IK/sec with headroom, route overflow","toa durable secondary topic (events.overflow) with its own consumer","Block the producer","LB)","Kafka doesn't provide consumer + producer backpressure.","‘group that drains during off-peak.","You'd need custom acks/transactions — not this stack.","Producer keeps producing, Primary consumer keeps a steady heartbeat.","Overflow gets processed later. That's graceful degradation,","Buffer harder","‘More memory = faster OOM. Larger batches increase latency","© stripe and Shopity publish architecture posts on this exact pattern","‘and worsen recovery time."],"fr":["System Design Labs","RÉPONSE: D — Limite de débit + délestage","Objectif: Garder le système en bonne santé, rencontrer le SLA, et le processus déborder plus tard - pas laisser tomber, pas bloquer.","Consommateur (epring-katka)","publier","Kafkalistener, batch — 500","Producteur","Kafka topic","ibe","Postgres","HTTP externe","5 000 événements/voir","événements","(goulot d'étranglement)","(croissance)","Groupe de consommateurs de débordement","écrire","ce qui permet de","(Drain hors pointe)","Producteur eens producteur","Processus ultérieurs","Le consommateur primaire reste heathy","Sujet de débordement","SLAmet rien je recadré","Pourquoi les autres perdent :","pourquoi d gagne :","« Le SLA dit que les événements doivent être traités – pas abandonnés, pas bloqués.","Drop événements sur le sol","Viole le SLA, les événements sont perdus pour toujours.","Cela tue A et B immédiatement.","LA","Limiter la consommation du consommateur à — IK/sec avec dégagement, trop-plein","un sujet secondaire durable (events.overflow) avec son propre consommateur","Bloquer le producteur","LB)","Kafka ne fournit pas de contre-pression consommateur + producteur.","« groupe qui draine pendant les heures creuses.","Vous auriez besoin d'un rack/transaction personnalisé, pas de cette pile.","Producteur continue de produire, le consommateur primaire maintient un rythme cardiaque régulier.","Le débordement est traité plus tard.","Tampon plus dur","‘Plus de mémoire — OOM plus rapide. Les lots plus importants augmentent la latence","stripe et Shopity publient des articles d'architecture sur ce modèle exact","\"et d'aggraver le temps de récupération."]}},{"kind":"p","page":71,"text":{"en":"Answer: D — Rate-limit + load-shed ✅","fr":"Réponse : D — Limitation de débit et délestage ✅"}},{"kind":"p","page":71,"text":{"en":"Why D wins:","fr":"Pourquoi D fonctionne"}},{"kind":"p","page":71,"text":{"en":"The SLA says events must be processed — not dropped, not blocked. That kills A and B immediately. Cap the consumer's intake at ~1K/sec with headroom, route overflow to a durable secondary topic (events.overflow) with its own consumer group that drains during off-peak. Producer keeps producing. Primary consumer keeps a steady heartbeat. Overflow gets processed later. That's graceful degradation. Stripe and Shopify publish architecture posts on this exact pattern.","fr":"Le SLA exige que les événements soient traités, sans en perdre ni bloquer leur arrivée. A et B sont donc à écarter. Plafonnez la consommation à environ 1 000 événements/s, avec une marge de capacité. Envoyez le surplus vers un topic secondaire persistant (events.overflow), doté de son propre groupe de consommateurs pour le vider en heures creuses. Le producteur continue à émettre. Le consommateur principal maintient un rythme stable. Le surplus sera traité ultérieurement. C’est une dégradation maîtrisée. Stripe et Shopify ont publié des articles d’architecture sur ce modèle."}}],[{"kind":"p","page":72,"text":{"en":"Why B is the trap answer:","fr":"Pourquoi B est tentant"}},{"kind":"p","page":72,"text":{"en":"This is what fools senior engineers. Backpressure-as-blocking works in Reactor, RxJava, Akka — because the protocol carries the signal. Kafka is pull-based and decoupled. The producer doesn't know your consumer exists. There's no socket-level backpressure signal flowing upstream. Engineers from gRPC streaming or RxJava reach for B because it worked there. In a brokered, decoupled, log-based system — it doesn't apply.","fr":"Même les ingénieurs expérimentés peuvent s’y tromper. Reactor, RxJava et Akka peuvent transmettre un signal de contre-pression jusqu’au producteur et le bloquer, car leur protocole le prévoit. Kafka découple les deux parties et laisse le consommateur venir lire les événements. Le producteur ignore l’existence du consommateur. Aucun signal de contre-pression ne remonte par la connexion. B paraît familier aux personnes qui utilisent le streaming gRPC ou RxJava, mais cette approche ne se transpose pas à un système découplé qui repose sur un broker et un journal."}}],[{"kind":"p","page":72,"text":{"en":"Why A is wrong:","fr":"Pourquoi écarter A"}},{"kind":"p","page":72,"text":{"en":"Drops events. SLA says \"must be processed, not silently dropped.\" Done.","fr":"Cette option perd des événements. Or le SLA impose de les traiter, sans perte silencieuse."}}],[{"kind":"p","page":72,"text":{"en":"Why C is wrong:","fr":"Pourquoi écarter C"}},{"kind":"p","page":72,"text":{"en":"Buffering is a delay tactic. A bigger buffer absorbs a 30-second spike — not a sustained 5K/sec input on an 800/sec consumer. The math: you're 4,200 events behind per second. A 1M-event buffer buys ~4 minutes. Then you're back where you started, but now with a memory exhaustion problem. And the real bottleneck is the external HTTP call — scaling consumers 5x doesn't help if downstream rate-limits you at request #51.","fr":"Le tampon ne fait que gagner du temps. Un plus grand tampon absorbe un pic de 30 secondes, mais un consommateur à 800 événements/s reste débordé face à un débit stable de 5 000 événements/s. Le retard augmente de 4 200 événements/s. Un tampon d’un million d’événements vous donne environ quatre minutes. Vous retrouvez ensuite le même problème, avec une mémoire saturée en plus. Le vrai goulot d’étranglement est l’appel HTTP externe. Multiplier les consommateurs par cinq ne sert à rien si la dépendance aval bride le trafic dès la 51e requête."}}]]},{"day":18,"title":{"en":"Surviving a Cache Stampede","fr":"Éviter une ruée sur le cache"},"pages":[73,76],"topic":"scale","correct":"D","scenario":[{"kind":"figure","page":73,"id":"073-02","width":800,"height":420,"alt":{"en":"Day 18 featured","fr":"Illustration de la question du jour 18"},"transcript":{"en":["System Design Labs","Your Redis cache just expired on a key that 8,000 users","hit every second. What do you do?","60s","200 req/sec","sustained","8,000","req/sec","GET /feed","Node.js","Read","EXPIRED","Users","‘APL","Heed","(Cache)","(Stampede)","Postgres","Bis on its knees","‘Mutex lock — only one request queries","Pro","carly expiry — start randomly","the DB to rebuild the cache, the rest","rebui","the cache before the TTL actually","wait behind it.","hits","Request coalescing — collapse all in-flight","Cache pre-warming — a background job","requests for the same key into a single DB","query, return the same result to all of them.","reaches zero in prod.","rebuilds the key on a schedule, TTL never"],"fr":["System Design Labs","Votre cache Redis vient d'expirer sur une clé que 8 000 utilisateurs","Que fais-tu ?","Années 60","200 req/sec","soutenue","8,000","req/sec","GET /feed","Node.js","Lire","EXPIRED","Utilisateurs","«APL","Heed","(Cache)","(Stampede)","Postgres","Bis sur ses genoux","‘Mutex lock — une seule requête","Pro","Carly Expiration — Démarrer au hasard","la base de données pour reconstruire le cache, le reste","rebui","le cache avant le TTL","Attendez derrière.","hits","Demande de coalescence — effondrement en vol","Cache pre-warming — un travail de fond","Demandes pour la même clé dans un seul DB","requête, retourne le même résultat à tous.","atteint zéro dans prod.","reconstruit la clé sur un calendrier, TTL jamais"]}},{"kind":"p","page":73,"text":{"en":"Your Redis cache just expired on a key that 8,000 users hit every second.","fr":"Une clé Redis consultée 8 000 fois par seconde vient d’expirer."}},{"kind":"p","page":73,"text":{"en":"Every single one of those requests is now flying straight at your database.","fr":"Toutes ces requêtes se reportent aussitôt sur la base de données."}},{"kind":"p","page":73,"text":{"en":"This is the thundering herd. You didn't have a traffic problem — you had a cache problem. Now you have both.","fr":"C’est l’effet de ruée sur le cache (thundering herd). Au départ, seul le cache posait problème. À présent, la base subit aussi un afflux de trafic."}},{"kind":"p","page":73,"text":{"en":"Here's the setup:","fr":"Voici la configuration."}},{"kind":"p","page":73,"text":{"en":"Service → Node.js API, 8,000 req/sec on the /feed endpoint","fr":"Service → API Node.js, 8 000 requêtes/s sur l’endpoint /feed"}},{"kind":"p","page":73,"text":{"en":"Cache → Redis, TTL = 60s on the feed key","fr":"Cache → Redis, TTL de 60 s sur la clé servant le fil"}},{"kind":"p","page":73,"text":{"en":"DB → Postgres, comfortable at ~200 req/sec sustained","fr":"Base → PostgreSQL, à l’aise à environ 200 requêtes/s en continu"}},{"kind":"p","page":73,"text":{"en":"What happened → TTL expired at peak traffic, all 8,000 req/sec hit Postgres simultaneously","fr":"Incident → le TTL a expiré au pic de trafic. Les 8 000 requêtes/s ont toutes atteint PostgreSQL simultanément."}},{"kind":"p","page":73,"text":{"en":"The DB is on its knees. You have minutes before it falls over. And the next TTL expiry is in 60 seconds.","fr":"La base est saturée. Elle risque de tomber dans les prochaines minutes, et la prochaine expiration est dans 60 secondes."}},{"kind":"p","page":73,"text":{"en":"What do you do?","fr":"Que faites-vous ?"}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":73,"text":{"en":"Mutex lock — only one request queries the DB to rebuild the cache, the rest wait behind it.","fr":"Verrou d’exclusion mutuelle (mutex) : une seule requête reconstruit le cache à partir de la base. Les autres attendent."}}]},{"letter":"B","blocks":[{"kind":"p","page":74,"text":{"en":"Probabilistic early expiry — start randomly rebuilding the cache before the TTL actually hits zero.","fr":"Expiration anticipée probabiliste : déclencher de façon aléatoire la reconstruction du cache avant que le TTL n’atteigne zéro."}}]},{"letter":"C","blocks":[{"kind":"p","page":74,"text":{"en":"Request coalescing — collapse all in-flight requests for the same key into a single DB query, return the same result to all of them.","fr":"Regroupement des requêtes : mutualiser les requêtes en cours pour une même clé en une seule lecture en base, puis renvoyer le même résultat à toutes."}}]},{"letter":"D","blocks":[{"kind":"p","page":74,"text":{"en":"Cache pre-warming — a background job rebuilds the key on a schedule, TTL never reaches zero in prod.","fr":"Préchauffage du cache : une tâche d’arrière-plan rafraîchit la clé à intervalles réguliers pour qu’elle n’expire jamais en production."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"figure","page":75,"id":"075-03","width":800,"height":471,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["};\\, System Design Labs","D) Answer: D — Cache pre-warming @","Pre-warm before TTL expires.","Pre-warming Job","eer","(Cron / Lambda / Worker)","@ why Dwins","Refresh data","Rebuild before","from DB","‘Eliminates the thundering","¥ TT (every ~45s)","herd at the root","VY The key never goes cold","8,000","in production","req/sec","Y_No expiry cif for 8,000","GET /feed","Read","requests","8,000","Moed","Redis","No expiry cif","Postgres","Users","(Cache)","no herd!","(0B)","YY Background cost: a job","runs every ~45 seconds","Pair with stale-while-revalidate","Le response","(cache hit)","for extra safety","© Probabitsi cary expiry","X Allrequest wait","Sti lows simultaneous","Works only while requests","Real world","are night.","Why the","Randomness # gurantee.","‘Once cold ew requests","\"Netflix pre-warms metadata.","others fail","X Rsk flock timeouts","188,000 req/oe, you can","stl pile up.","Twitter pre-bulds timelines.","under load","and stampedes,","‘The pattern is everywhere."],"fr":["; — , Laboratoires de conception de systèmes","D) Réponse: D — Cache pré-chauffage","Préchauffé avant l'expiration du TTL.","Pré-chauffage","eer","(Cron / Lambda / Travailleur)","pourquoi Dwins","Actualiser les données","Reconstruire avant","à DB","« Élimine le tonnerre","TT (tous les 45 — )","Le troupeau à la racine","VY La clé ne se refroidit jamais","8,000","en production","req/sec","Y_Pas de caf d'expiration pour 8 000","GET /feed","Lire","Demandes","8,000","Moed","Redis","Pas d'expiration cif","Postgres","Utilisateurs","(Cache)","Pas de troupeau !","(0B)","YY Coût d'arrière-plan : un emploi","Fonctionne toutes les — 45 secondes","Paire avec vielle-while-revalidate","Le réponse","(cache hit)","pour plus de sécurité","Probabitsi cary expiration","X Allrequest attente","Sti bas simultanés","Fonctionne uniquement pendant les demandes","Le monde réel","sont la nuit.","Pourquoi","Aléatoire — garantie.","« Une fois que les demandes sont froides","\"Netflix préchauffe les métadonnées.","D'autres échouent","X Délais d'attente du troupeau Rsk","188.000 req/oe, vous pouvez","Stl pile.","Twitter pré-bullds calendriers.","sous charge","et de stampedes,","« Le modèle est partout."]}},{"kind":"p","page":75,"text":{"en":"Answer: D — Cache pre-warming ✅","fr":"Réponse : D — Préchauffage du cache ✅"}},{"kind":"p","page":75,"text":{"en":"Here's why, and why the other three trick smart engineers:","fr":"Voici pourquoi cette approche fonctionne et où les trois autres peuvent induire en erreur."}},{"kind":"p","page":75,"text":{"en":"Why D wins (Cache pre-warming):","fr":"Pourquoi choisir D (préchauffage du cache)"}},{"kind":"p","page":75,"text":{"en":"Pre-warming eliminates the thundering herd at the root. A background job — a cron, a scheduled Lambda, a Sidekiq worker — rebuilds the cache key on a fixed schedule that's shorter than the TTL. The key never goes cold in production. There's no expiry cliff for 8,000 requests to fall off.","fr":"Le préchauffage évite la ruée à la source. Une tâche d’arrière-plan, par exemple un cron, une Lambda planifiée ou un worker Sidekiq, rafraîchit la clé à intervalles fixes, plus courts que le TTL. La clé reste toujours disponible en production. Les 8 000 requêtes ne se retrouvent jamais sans entrée de cache au même instant."}},{"kind":"p","page":75,"text":{"en":"You know the data is hot. You know when it expires. You have the compute to rebuild it proactively. The cost is a background job running every ~45 seconds; the benefit is your database never sees the spike. Netflix pre-warms content metadata. Twitter pre-builds timelines for high-follower accounts. The pattern is everywhere — it's just not glamorous enough to make it into most architecture posts.","fr":"Vous savez que la donnée est très sollicitée et quand elle expire, et vous avez la capacité de la recalculer à l’avance. Le coût se résume à une tâche d’arrière-plan exécutée environ toutes les 45 secondes, et la base ne voit jamais le pic. Netflix précharge les métadonnées de ses contenus. Twitter précalcule les fils des comptes très suivis. Cette technique est répandue, même si elle est rarement mise en avant dans les articles d’architecture."}},{"kind":"p","page":75,"text":{"en":"One detail that matters: pair it with stale-while-revalidate. Serve the stale value while the background job refreshes, so a slightly-late rebuild never causes a miss.","fr":"Associez le préchauffage à stale-while-revalidate : renvoyez la valeur périmée pendant que la tâche rafraîchit le cache. Un léger retard du recalcul ne provoquera ainsi aucun défaut de cache."}}],[{"kind":"p","page":76,"text":{"en":"Why C is the trap answer (Request coalescing):","fr":"Pourquoi C est tentant (regroupement des requêtes)"}},{"kind":"p","page":76,"text":{"en":"Coalescing sounds most sophisticated — collapse all concurrent requests for the same key into one DB query, return the same result to all of them. No stampede, no lock contention. Elegant.","fr":"Le regroupement paraît élégant : toutes les requêtes concurrentes sur la même clé partagent une seule lecture en base et reçoivent le même résultat. Pas de ruée ni de contention sur un verrou."}},{"kind":"p","page":76,"text":{"en":"Here's where it breaks: coalescing requires in-process coordination. It works beautifully on a single server. On 50 Node.js instances behind a load balancer, each instance coalesces independently — so now you have 50 concurrent DB queries instead of 8,000. Better, but still a 50x spike at every TTL expiry. To coalesce across instances you need a distributed coordination layer, and now you've built something nearly as complex as a mutex without the simplicity.","fr":"Le regroupement demande toutefois une coordination au sein du processus. Il fonctionne très bien sur un serveur unique. Avec 50 instances Node.js derrière un répartiteur de charge, chaque instance regroupe ses requêtes de son côté. La base reçoit donc 50 requêtes concurrentes au lieu de 8 000. C’est mieux, mais chaque expiration du TTL provoque encore un pic d’un facteur 50. Regrouper les requêtes entre instances suppose une coordination distribuée, presque aussi complexe qu’un mutex et moins simple à mettre en œuvre."}},{"kind":"p","page":76,"text":{"en":"Right answer for a single-process server. Partial solution at scale that engineers convince themselves is complete.","fr":"C’est une bonne réponse pour un serveur doté d’un seul processus. À grande échelle, le regroupement ne résout qu’une partie du problème."}}],[{"kind":"p","page":76,"text":{"en":"Why A is wrong (Mutex lock):","fr":"Pourquoi écarter A (mutex)"}},{"kind":"p","page":76,"text":{"en":"Mutex looks clean: one request gets the lock, rebuilds the cache, everyone else waits. No duplicate DB queries.","fr":"Le mutex semble simple : une requête acquiert le verrou et reconstruit le cache. Les autres attendent. Aucune lecture en base n’est dupliquée."}},{"kind":"p","page":76,"text":{"en":"The problem is \"everyone else waits.\" Under 8,000 req/sec, waiting means API threads blocked, request queue filling up, p99 latency spiking to seconds. You've traded a DB overload for an application-layer backup. The database survives; the user experience dies. And if the lock holder is slow — DB is struggling, rebuild takes 500ms — every request in the system stalls for that window.","fr":"C’est justement l’attente qui pose problème. À 8 000 requêtes/s, les threads de l’API restent bloqués, la file des requêtes se remplit et la latence p99 grimpe à plusieurs secondes. La saturation se déplace vers la couche applicative. La base tient, mais l’expérience utilisateur se dégrade. Si le détenteur du verrou est lent, par exemple parce que la base sous pression met 500 ms à rafraîchir la clé, toutes les requêtes restent bloquées pendant ce délai."}}],[{"kind":"p","page":76,"text":{"en":"Why B is wrong (Probabilistic early expiry):","fr":"Pourquoi écarter B (expiration anticipée probabiliste)"}},{"kind":"p","page":76,"text":{"en":"XFetch / jitter-based expiry is clever: as the TTL counts down, each cache read has a small random chance of triggering a rebuild early. No lock, no coordination layer. Elegant math.","fr":"L’expiration basée sur XFetch ou le jitter est astucieuse. À mesure que le TTL diminue, chaque lecture du cache a une faible probabilité de déclencher un rafraîchissement anticipé. Ni verrou ni couche de coordination."}},{"kind":"p","page":76,"text":{"en":"The problem is it's probabilistic, not guaranteed. Under the exact wrong timing (low traffic right before TTL, then a sudden spike) the key still expires cold. You've reduced the probability of a thundering herd without eliminating it. For an endpoint running at 8,000 req/sec 24/7, you want a deterministic guarantee — not good odds.","fr":"Cette approche réduit un risque sans offrir de garantie. Si peu de requêtes arrivent juste avant l’expiration, puis qu’un pic survient, la clé peut tout de même expirer sans avoir été régénérée. Le risque de ruée diminue, mais subsiste. Pour un endpoint qui reçoit 8 000 requêtes/s jour et nuit, il faut une garantie déterministe."}}]]},{"day":19,"title":{"en":"Read-Your-Writes with Read Replicas","fr":"Relire ses propres écritures avec des répliques de lecture"},"pages":[77,80],"topic":"data","correct":"A","scenario":[{"kind":"figure","page":77,"id":"077-02","width":800,"height":421,"alt":{"en":"Day 19 featured","fr":"Illustration de la question du jour 19"},"transcript":{"en":["System Design Labs","Your checkout endpoint has a 400ms P95.","You added a read replica and now seeing stale data. What do you do?","Replication","Primary","(Database)","Request","Checkout","Client","Service","L READ __»","replication lag ~200ms","(100% of reads)","oR","+ handling 100% of reads","+ Affected flows > profile updates,","Replica","(Read Only)","Read-your-wri","s consistency: route a","‘Synchronous repli","tion:","ake pri","ary wait","user's reads to primary for a short window","for replica to confirm before ACI","19 the write.","after they write.","[A","Monitor replica lag + retry: detect when","lag exceeds a threshold and fall back to","Route critical reads to primary: replicas only","serve non-critical reads like analytics.","[ic","primary."],"fr":["System Design Labs","Votre endpoint de paiement a un P95 de 400ms.","Vous avez ajouté une réplique en lecture et vous voyez maintenant des données périmées. Que faites-vous ?","Réplication","Primaire","(Base de données)","Demande","Checkout","Client","Service","L LIRE __»","délai de réplication — 200ms","(100% des lectures)","oR","+ gestion de 100% des lectures","+ Flux concernés > mises à jour de profil,","Réplique","(lecture seule)","Lire-votre-wri","Cohérence : route a","«Réplique synchrone","tion:","ake pri","ary attends","lectures de l'utilisateur à primaire pour une courte fenêtre","pour réplique à confirmer avant ACI","19 l'écriture.","après avoir écrit.","[A","Moniteur de replie lag + réessayer: détecter quand","Dépasse un seuil et retombe","Lectures critiques de la route vers le primaire : réplicas uniquement","servir des lectures non critiques comme des analyses.","[IC]","primaire."]}},{"kind":"p","page":77,"text":{"en":"Your checkout endpoint has a 400ms P95. Profiling shows 70% of that is DB reads.","fr":"Le p95 de votre endpoint de paiement atteint 400 ms. Le profilage indique que les lectures en base représentent 70 % de cette durée."}},{"kind":"p","page":77,"text":{"en":"You add a read replica and point all SELECT queries at it. P95 drops to 90ms. The team celebrates.","fr":"Vous ajoutez une réplique de lecture et lui envoyez toutes les requêtes SELECT. Le p95 baisse à 90 ms. L’équipe fête le résultat."}},{"kind":"p","page":77,"text":{"en":"Two hours later, support tickets flood in. Customers update their shipping address but see the old one on the confirmation screen. One customer gets charged twice because the \"order already exists\" check read stale data and missed the duplicate.","fr":"Deux heures plus tard, les tickets affluent. Des clients modifient leur adresse de livraison, puis retrouvent l’ancienne sur l’écran de confirmation. Un client est prélevé deux fois : la vérification censée détecter une commande existante a lu des données obsolètes et laissé passer le doublon."}},{"kind":"p","page":77,"text":{"en":"Here's the setup:","fr":"Voici la configuration."}},{"kind":"p","page":77,"text":{"en":"• Primary → handles all writes, replication lag ~200ms","fr":"• Primaire → toutes les écritures, retard de réplication d’environ 200 ms"}},{"kind":"p","page":77,"text":{"en":"• Replica → handling 100% of reads","fr":"• Réplique → 100 % des lectures"}},{"kind":"p","page":77,"text":{"en":"• Affected flows → profile updates, order dedup, payment idempotency","fr":"• Flux touchés → mises à jour des profils, déduplication des commandes et idempotence des paiements"}},{"kind":"p","page":77,"text":{"en":"The replica is working exactly as designed. That's the problem.","fr":"La réplique fonctionne comme prévu. C’est bien le problème."}},{"kind":"p","page":77,"text":{"en":"What do you do?","fr":"Que faites-vous ?"}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":77,"text":{"en":"Read-your-writes consistency: route a user's reads to primary for a short window after they write.","fr":"Garantir la lecture de ses propres écritures : envoyer brièvement les lectures d’un utilisateur vers le primaire après une écriture."}}]},{"letter":"B","blocks":[{"kind":"p","page":78,"text":{"en":"Synchronous replication: make primary wait for replica to confirm before ACKing the write.","fr":"Réplication synchrone : le primaire attend la confirmation de la réplique avant d’accuser réception de l’écriture."}}]},{"letter":"C","blocks":[{"kind":"p","page":78,"text":{"en":"Monitor replica lag + retry: detect when lag exceeds a threshold and fall back to primary.","fr":"Surveiller le retard de réplication et réessayer : au-delà d’un seuil de retard, réorienter les lectures vers le primaire."}}]},{"letter":"D","blocks":[{"kind":"p","page":78,"text":{"en":"Route critical reads to primary: replicas only serve non-critical reads like analytics.","fr":"Diriger les lectures critiques vers le primaire : réserver les répliques aux lectures non critiques, par exemple analytiques."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"figure","page":79,"id":"079-03","width":800,"height":533,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["‘System Design Labs","ANSWER:","— Read-your-writes consistency:","route a user’s reads to primary for a short window after they write.","Write Flow","Read Flow (Per User)","Why A wins","Solves stale reads","write","| after write","‘The user who wrote sees","‘Within window","their own updates immediately.","(e,2-58) or","READ. is","Client","untilageatches up","Primary","(User)","Primary","Preserves performance","tes)","(Strong Read)","Only a small window of reads","{90 to primary; everyone else","uses the replica","READ,","Lag","indow","Scales with traffic","‘orlag caught up","Eth","‘The window is short (seconds)","Replica","‘or until replication catches up.","(Fast Read)","Covers critical flows","Other users no recent write) read","Fixes profile updates, order","MW) from the replica as usual","<dedup, and payment idempotency","Replica","without sacrificing the win","(Read Only)","Key idea: After a user performs a write, their subsequent reads are routed to the primary","for a short window: typically a few seconds, or until repli","lag catches up.","Everyone else reads from the replica. The performance win is preserved for the vast majority of traffic."],"fr":["«System Design Labs","RÉPONSE :","Lire-votre-écrit la cohérence:","acheminer les lectures d’un utilisateur vers la primaire pendant une courte fenêtre après qu’il ait écrit.","Ecrire le flux","Lire le flux (par utilisateur)","Pourquoi retenir A","Solves stale lit","écrire","après avoir écrit","« L’utilisateur qui écrit voit","«Dans la fenêtre","leurs propres mises à jour immédiatement.","(e,2-58) ou","Lire. est","Client","uptoupir","Primaire","(Utilisateur)","Primaire","Préserve les performances","tes)","(Forte lecture)","Une petite fenêtre de lecture","90 à la primaire; tous les autres","Utilise la réplique","LIRE,","Lag","indiow","Balances avec trafic","«Orlag rattrapé","Eth","La fenêtre est courte (secondes)","Réplique","« ou jusqu’à ce que la réplication rattrape.","(Lu rapidement)","Couvre les flux critiques","Autres utilisateurs no recent write) lire","Corrige les mises à jour de profil, commande","MW) de la réplique comme d'habitude","dedup, et paiement idempotency","Réplique","Sans sacrifier la victoire","(lecture seule)","Idée clé: Après qu'un utilisateur effectue une écriture, leurs lectures suivantes sont acheminées vers le primaire.","pour une fenêtre courte: généralement quelques secondes, ou jusqu'à ce que repli","Le lag rattrape.","Tout le monde lit la réplique. La victoire de performance est préservée pour la grande majorité du trafic."]}},{"kind":"p","page":79,"text":{"en":"Why A wins:","fr":"Pourquoi A fonctionne"}},{"kind":"p","page":79,"text":{"en":"After a user performs a write, their subsequent reads are routed to the primary for a short window: typically a few seconds, or until replica lag catches up. Everyone else reads from the replica. The performance win is preserved for the vast majority of traffic.","fr":"Après une écriture de l’utilisateur, ses lectures sont dirigées vers le primaire pendant un court délai, typiquement quelques secondes ou jusqu’à ce que la réplique ait rattrapé son retard. Les autres utilisateurs continuent à lire sur la réplique. La grande majorité du trafic conserve le gain de performance."}}],[{"kind":"p","page":79,"text":{"en":"Why D is the trap:","fr":"Pourquoi D est tentant"}},{"kind":"p","page":79,"text":{"en":"\"Critical\" is not a stable category. The primary read list quietly shrinks, stale read bugs come back, and you spend the next quarter playing whack-a-mole with consistency bugs. You've traded a systematic solution for a per-feature judgment call.","fr":"La notion de lecture « critique » évolue. Peu à peu, la liste des lectures envoyées au primaire se raccourcit et les problèmes de données obsolètes reviennent. Vous passez le trimestre suivant à corriger des incohérences au cas par cas. Une règle systématique a cédé la place à des décisions prises fonctionnalité par fonctionnalité."}}],[{"kind":"p","page":80,"text":{"en":"Why B is wrong:","fr":"Pourquoi écarter B"}},{"kind":"p","page":80,"text":{"en":"Synchronous replication means the primary waits for the replica to confirm every write. Replica lag goes to zero, but your write P95 goes from 20ms to 80–120ms. Worse, you've coupled your primary's availability to your replica's health.","fr":"En réplication synchrone, le primaire attend que la réplique confirme chaque écriture. Le retard de réplication tombe à zéro, mais le p95 des écritures passe de 20 ms à 80–120 ms. De plus, la disponibilité du primaire dépend désormais de l’état de la réplique."}}],[{"kind":"p","page":80,"text":{"en":"Why C is wrong:","fr":"Pourquoi écarter C"}},{"kind":"p","page":80,"text":{"en":"Average lag isn't your problem. Your problem is that a user reads their own write within 200ms of making it. The lag metric looks fine (200ms is \"normal\"), but the data the user needs is still in transit.","fr":"La moyenne du retard de réplication n’explique pas le problème. L’utilisateur relit ses données dans les 200 ms qui suivent son écriture. La métrique paraît normale, puisque 200 ms est le retard habituel, mais la donnée dont il a besoin est encore en transit."}}]]},{"day":20,"title":{"en":"Containing a Failing Downstream Dependency","fr":"Isoler une dépendance aval en panne"},"pages":[81,85],"topic":"reliability","correct":"D","scenario":[{"kind":"figure","page":81,"id":"081-02","width":800,"height":420,"alt":{"en":"Day 20 featured","fr":"Illustration de la question du jour 20"},"transcript":{"en":["stem Design Labs","Your checkout service calls a 3rd-party fraud-check API","on every order. That API just started timing out at 30s...","'50-connection pool","All connections blocked (30s timeouts)","99 /eheckout: 286","Bock","| HTTPS:","Checkout Service","HTTPS)","Fraud API","Web / Mobile","(Nests Pods)","Fraud Check","Timing out (305)","Gra Party)","{impact","New requests pileup in queue |","‘Orders Service","Customers retry","Pods OOM","+ Entire checkout down","| =E","| (GE","‘Add a Circuit Breaker that opens after N failures,","‘3 retries with exponential backoft","Drop the timeout to 2s and add","then half-opens with a single probe request","before fully closing","Bulkhead the fraud API calls into a separate","‘connection pool / thread pool so they can't","Both B and C — circuit breaker forthe falling","starve the rest of checkout","‘dependency, bulkhead to isolate the blast radius."],"fr":["stem Design Labs","Votre service de paiement appelle une API de vérification de fraude tierce","sur chaque commande. Cette API vient de commencer à timing à 30s...","'50-connection pool","Toutes les connexions sont bloquées (30s timeouts)","99 /eheckout: 286","Bock","HTTPS :","Service de caisse","HTTPS)","API Fraude","Web / Mobile","(Nests Pods)","Vérification de fraude","Horaire (305)","Gra Party)","impact","Nouvelles requêtes en file d'attente","«Service des commandes","Les clients réessayent","Pods","+ Paiement complet vers le bas","E","(GE)","‘Ajouter un disjoncteur qui s’ouvre après N défaillances,","«3 tentatives avec retour exponentiel","Déposez le délai d'attente à 2s et ajoutez","puis demi-ouverture avec une seule demande de sonde","Avant fermeture complète","Bulkhead les appels d'API de fraude dans un séparé","« pool de connexion / pool de threads donc ils ne peuvent pas","Disjoncteur B et C — pour la chute","Le reste de la vie","«dépendance, cloison pour isoler le rayon de souffle."]}},{"kind":"p","page":81,"text":{"en":"Your checkout service calls a 3rd-party fraud-check API on every order.","fr":"Votre service de paiement appelle une API tierce de détection de fraude à chaque commande."}},{"kind":"p","page":81,"text":{"en":"That API just started timing out at 30s instead of its usual 200ms.","fr":"Cette API atteint désormais le délai maximal de 30 s, alors qu’elle répond habituellement en 200 ms."}},{"kind":"p","page":81,"text":{"en":"Your Node.js checkout pods have a 50-connection pool. Within 90 seconds, every connection is parked waiting on the fraud API. New checkout requests pile up in the queue. P99 latency on /checkout goes from 300ms to 28s. Customers retry. Pods OOM. The fraud API is degraded — your entire checkout is down.","fr":"Les pods Node.js qui gèrent le paiement disposent d’un pool de 50 connexions. En 90 secondes, toutes les connexions restent occupées à attendre l’API antifraude. Les nouvelles requêtes de paiement s’accumulent dans la file. Le p99 de /checkout passe de 300 ms à 28 s. Les clients réessaient et les pods tombent à court de mémoire. L’API tierce fonctionne en mode dégradé, et tout votre parcours de paiement est hors service."}},{"kind":"p","page":81,"text":{"en":"Here's the setup:","fr":"Voici la configuration."}},{"kind":"p","page":81,"text":{"en":"• Checkout (NestJS) → Fraud API (3rd party) — 30s timeouts","fr":"• Paiement (NestJS) → API antifraude tierce, avec un délai maximal de 30 s"}},{"kind":"p","page":81,"text":{"en":"• Same pods also handle /cart, /orders, /health — all healthy dependencies","fr":"• Les mêmes pods servent /cart, /orders et /health, dont les dépendances fonctionnent normalement."}},{"kind":"p","page":81,"text":{"en":"• Fraud API's own dashboard says it'll be back in ~10 minutes","fr":"• D’après son tableau de bord, l’API antifraude devrait être rétablie dans environ 10 minutes."}},{"kind":"p","page":81,"text":{"en":"• Your SLO budget for the quarter is about to evaporate","fr":"• Vous êtes sur le point d’épuiser le budget d’erreur de votre SLO pour le trimestre."}},{"kind":"p","page":81,"text":{"en":"You need to stop the bleeding without losing the rest of checkout. What do you do?","fr":"Vous devez endiguer l’incident tout en maintenant le reste du service de paiement. Que faites-vous ?"}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":81,"text":{"en":"Drop the timeout to 2s and add 3 retries with exponential backoff.","fr":"Réduire le délai maximal à 2 s et effectuer trois nouvelles tentatives avec temporisation exponentielle."}}]},{"letter":"B","blocks":[{"kind":"p","page":82,"text":{"en":"Add a Circuit Breaker that opens after N failures, then half-opens with a single probe request before fully closing.","fr":"Ajouter un circuit breaker qui s’ouvre après N échecs, puis passe à l’état semi-ouvert pour laisser passer une requête de test avant de se refermer complètement."}}]},{"letter":"C","blocks":[{"kind":"p","page":82,"text":{"en":"Bulkhead the fraud API calls into a separate connection pool / thread pool so they can't starve the rest of checkout.","fr":"Isoler les appels à l’API antifraude dans un pool dédié de connexions ou de threads pour qu’ils ne monopolisent pas les ressources du reste du service."}}]},{"letter":"D","blocks":[{"kind":"p","page":82,"text":{"en":"Both B and C — circuit breaker for the failing dependency, bulkhead to isolate the blast radius.","fr":"Combiner B et C : un circuit breaker pour la dépendance en panne et un bulkhead pour en limiter le périmètre d’impact."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"figure","page":83,"id":"083-03","width":800,"height":533,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["Lat","orrect Answer: D — Circuit Breaker + Bulkhead, together @","‘Why D wins: Circuit Breaker stops the bleeding. Bulkhead contains the blast radius.","Fraud API dashboard","‘Together, they keep the rest of checkout healthy while the fraud API is degraded.","Back in -10 minutes","Checkout Service Nests Pods).","HTTP","Fraud APL","(Grd Party)","Web / Mobile","Main Poo! (40 connections)","Fraud Poo! (10 connections)","Fraud Check","Timing out (30s)","Clients","Hands heathy endpoints","© Resute with","ean","© \"Nomore 30s timeouts held in main pool","| seat","pce eet","© ‘cart, orders, helth stay fast and healthy","© Fraud checks a fast with flack","© system remains up, SLO protected","Drop the timeout to 2s and add 3 retries","‘Add a Circuit Breaker that opens aftr N failures,","with exponential backot","then half-opens with a single probe request","© Worse: More requests, more load, more rere.","before full closing","You amply the outage and bum erources faster","A, Bete, but not enough: Without bulkhead the fraud","‘oo! can stil starve the ret of checkout","connection pool / thread pool so they can't","‘Bulkhead the fraud API calls into a separate","Both B and C — circuit breaker forthe failing","starve the ret of checkout.","dependency, bulkhead to isolate the blast radius.","‘A. Better ication, but without a cet breaker youl sti","© best outcome: Stop hammering the downed dependency","‘wat ful 0s timeouts and exhaust the fraud ook","+ protect the est of your service. Thies whet ships","| LD"],"fr":["Lat","orrect Réponse: D — disjoncteur + cloison, ensemble","‘Pourquoi retenir D : Circuit Breaker arrête le saignement. Bulkhead contient le rayon d’explosion.","Tableau de bord de l'API Fraude","Ensemble, ils maintiennent le reste de la caisse en bonne santé pendant que l’API de fraude est dégradée.","Retour en -10 minutes","Service de caisse Nests Pods).","HTTP","Fraude APL","(Grd Party)","Web / Mobile","Main Poo! (40 connexions)","Fraud Poo! (10 connexions)","Vérification de fraude","Timing out (30s)","Clients","Points finaux de heathy des mains","Resute avec","ean","\"Nomore 30s timeouts tenue dans la piscine principale","siège","pce eet","‘cart, les ordres, helth rester rapide et en bonne santé","Fraude vérifie un rapide avec flack","le système reste en place, SLO protégé","Déposez le délai d'attente à 2s et ajoutez 3 tentatives","« Ajouter un disjoncteur qui ouvre N défaillances,","Avec un backot exponentiel","puis demi-ouverture avec une seule demande de sonde","Pire: plus de demandes, plus de charge, plus de rere.","avant fermeture complète","Vous amplement la panne et les fesses erources plus vite","A, Bete, mais pas assez: Sans cloison la fraude","‘oo! peut encore affamer le ret de la caisse","pool de connexion / pool de threads donc ils ne peuvent pas","« L’API de fraude appelle dans un","Disjoncteur B et C — pour la défaillance","Affamez le ret de la caisse.","dépendance, cloison pour isoler le rayon de souffle.","«A. Mieux vaut ica, mais sans un ice breaker youl sti","Meilleur résultat: Arrêtez de marteler la dépendance abattue","'wat ful 0s timeouts et épuiser la fraude ook","+ protégez l'est de votre service. Thies whet navires","LD"]}},{"kind":"p","page":83,"text":{"en":"Answer: D — Circuit Breaker + Bulkhead, together ✅","fr":"Réponse : D — Combiner circuit breaker et bulkhead ✅"}},{"kind":"p","page":83,"text":{"en":"Here's why, and why the other three trick smart engineers:","fr":"Voici pourquoi cette approche fonctionne et où les trois autres peuvent induire en erreur."}},{"kind":"p","page":83,"text":{"en":"Why D wins (Circuit Breaker + Bulkhead):","fr":"Pourquoi choisir D (circuit breaker et bulkhead)"}},{"kind":"p","page":83,"text":{"en":"These two patterns solve two different failure modes, and you need both.","fr":"Les deux mécanismes répondent chacun à un mode de défaillance différent. Les deux sont nécessaires."}},{"kind":"p","page":83,"text":{"en":"The Circuit Breaker stops you from hammering a dead dependency. After N consecutive failures (or a failure rate threshold over a rolling window), it flips to OPEN — every subsequent call to the fraud API fails instantly with a fallback. No 30s wait. No connection held hostage. After a cooldown (say 30s), it goes HALF-OPEN: it allows exactly one probe request through. If that probe succeeds, the breaker closes and traffic resumes. If it fails, back to OPEN for another cooldown. Half-open is the part most tutorials gloss over — it's what prevents the thundering herd from re-killing a service that's just coming back up.","fr":"Le circuit breaker évite de solliciter sans relâche une dépendance indisponible. Après N échecs consécutifs, ou si le taux d’échec dépasse un seuil sur une fenêtre glissante, il passe à l’état OUVERT. Chaque nouvel appel vers l’API antifraude échoue immédiatement et déclenche une solution de repli, sans attente de 30 s ni connexion immobilisée. Après une période de temporisation, par exemple 30 s, il passe à l’état SEMI-OUVERT et laisse passer exactement une requête de test. Si le test réussit, il se ferme et le trafic reprend. Sinon, il se rouvre pour une nouvelle période de temporisation. L’état semi-ouvert, souvent survolé dans les tutoriels, empêche un afflux de requêtes de faire retomber un service à peine rétabli."}},{"kind":"p","page":83,"text":{"en":"The Bulkhead is the part most engineers forget exists until they get burned. It isolates resource pools. Your fraud API gets its own dedicated pool of, say, 10 connections — separate from the 40 connections that serve /cart, /orders, /health. When the fraud API hangs, it can saturate its 10 connections, but the other 40 stay free. /cart keeps working. /health keeps working. The blast radius stops at the fraud feature. The ship doesn't sink because one compartment flooded — that's literally where the name comes from.","fr":"Le bulkhead cloisonne les pools de ressources. L’API antifraude obtient son propre pool, par exemple de dix connexions, distinct des 40 connexions qui desservent /cart, /orders et /health. Si l’API antifraude ne répond plus, elle peut saturer ses dix connexions. Les 40 autres restent disponibles. /cart et /health continuent de fonctionner. L’incident se limite à la fonction antifraude. Le nom vient des cloisons étanches d’un navire, qui empêchent l’inondation d’un compartiment de faire sombrer l’ensemble."}},{"kind":"p","page":84,"text":{"en":"Resilience4j, Polly (.NET), and Hystrix (legacy) all ship both. AWS App Mesh + Envoy give you bulkheads at the proxy layer. Netflix wrote Hystrix specifically because they learned this lesson the hard way: a single slow dependency cascading through shared thread pools took down recommendations during peak hours.","fr":"Resilience4j, Polly (.NET) et Hystrix, un ancien outil, proposent les deux mécanismes. AWS App Mesh associé à Envoy permet le cloisonnement au niveau du proxy. Netflix a écrit Hystrix après en avoir fait l’expérience : une seule dépendance lente avait propagé sa panne via des pools de threads partagés et mis le système de recommandations hors service en heure de pointe."}}],[{"kind":"p","page":84,"text":{"en":"Why B alone is the staff-engineer trap answer:","fr":"Pourquoi B paraît suffisant"}},{"kind":"p","page":84,"text":{"en":"A circuit breaker without a bulkhead is the answer that sounds complete in an interview. It's the most-mentioned pattern in resilience talks. And it does fix the specific failure described — once the breaker opens, fraud calls fail fast and stop tying up connections.","fr":"En entretien, un circuit breaker seul semble une réponse complète. C’est le mécanisme le plus souvent cité lorsqu’on parle de résilience. Une fois le circuit ouvert, les appels antifraude échouent vite et libèrent les connexions."}},{"kind":"p","page":84,"text":{"en":"But here's the production reality: between failure #1 and the breaker tripping (failure #N), every one of those N requests is still holding a connection from the shared pool. If your threshold is 20 failures over 10 seconds, you can still saturate a 50-connection pool before the breaker even notices. You've reduced the outage window, not eliminated the cascade.","fr":"En production, entre le premier échec et celui qui ouvre le circuit, chacune des N requêtes continue d’occuper une connexion du pool partagé. Avec un seuil de 20 échecs en 10 secondes, votre pool de 50 connexions peut saturer avant même le déclenchement du circuit breaker. Vous avez réduit la fenêtre de panne, sans empêcher l’effet domino."}},{"kind":"p","page":84,"text":{"en":"Bulkheads make the breaker's threshold latency-tolerant. They give you slack to detect and react without the rest of the system already being on fire.","fr":"Le cloisonnement laisse au circuit breaker le temps d’atteindre son seuil. Il vous donne une marge pour détecter l’incident et réagir avant que le reste du système soit touché."}},{"kind":"p","page":84,"text":{"en":"This is the trap because B is right and incomplete. Senior engineers stop at B in design reviews because it sounds sufficient. Staff engineers ship D because they've seen B fail in production at 3am.","fr":"B est une réponse valable mais incomplète. En revue de conception, il est facile de s’en contenter. Les ingénieurs qui ont vu cette option échouer en production à trois heures du matin choisissent D."}}],[{"kind":"p","page":84,"text":{"en":"Why C alone is partial:","fr":"Pourquoi C ne règle qu’une partie du problème"}},{"kind":"p","page":84,"text":{"en":"Bulkhead alone is better than nothing — it contains the damage. But your 10 dedicated fraud connections will still spend 30 seconds each waiting on doomed calls. You're paying full latency cost on every checkout, just on a smaller pool. Customers still see slow checkouts; you just don't lose /cart with them.","fr":"Le cloisonnement limite les dégâts. Vos dix connexions antifraude dédiées attendront tout de même 30 secondes chacune sur des appels voués à échouer. Le délai de paiement reste le même pour le client. Le reste du service, comme /cart, demeure disponible."}},{"kind":"p","page":84,"text":{"en":"Bulkhead without a breaker = \"the leak is contained, but the room is still flooding.\"","fr":"Un bulkhead seul empêche la fuite de se propager. Le compartiment, lui, continue de se remplir."}}],[{"kind":"p","page":85,"text":{"en":"Why A is wrong (and dangerous):","fr":"Pourquoi A risque d’aggraver l’incident"}},{"kind":"p","page":85,"text":{"en":"Lower timeout + retries with backoff is the single worst thing you can do to a degraded dependency. It's the canonical anti-pattern.","fr":"Raccourcir le délai maximal et ajouter des tentatives avec temporisation est un antipattern pour une dépendance déjà dégradée."}},{"kind":"p","page":85,"text":{"en":"The fraud API is already struggling. You just decided to send it 3x the traffic. Every retry storm from every checkout pod converges on a service that needs less load to recover. This is how a partial outage becomes a total outage — and how a 10-minute incident becomes a 4-hour incident. Retries belong on transient errors (a single 503, a connection reset), not on systemic degradation. And they always need a circuit breaker upstream of them to cap the blast.","fr":"L’API antifraude est déjà en difficulté et elle va maintenant recevoir trois fois plus de trafic. Les vagues de nouvelles tentatives de tous les pods convergent sur un service qui a besoin d’une baisse de charge pour se rétablir. Une panne partielle peut alors devenir générale, et un incident de dix minutes peut en durer quatre heures. Réessayez sur des erreurs transitoires, par exemple un 503 isolé ou une connexion réinitialisée. Face à une dégradation généralisée, un circuit breaker placé en amont des nouvelles tentatives est indispensable pour limiter l’impact."}},{"kind":"p","page":85,"text":{"en":"If you've ever read a postmortem with the phrase \"retry storm contributed to extended recovery time\" — this is what they meant.","fr":"C’est le sens d’un compte rendu d’incident qui indique qu’« une tempête de nouvelles tentatives a prolongé le rétablissement »."}}]]},{"day":21,"title":{"en":"Choosing a Real-Time Streaming Transport","fr":"Choisir un transport de streaming en temps réel"},"pages":[86,89],"topic":"events","correct":"B","scenario":[{"kind":"figure","page":86,"id":"086-02","width":800,"height":421,"alt":{"en":"Day 21 featured","fr":"Illustration de la question du jour 21"},"transcript":{"en":["System Design Labs","You're shipping an Al chat product. The LLM streams ~40 tokens/sec","per user. 50,000 concurrent users on launch day. Browser clients only.","‘Send prompt","‘eontext","Stream","(server pushes","tokens)","Browser","ALB","FastAPI","LLM Provider","Browser","Clients","(pplication","Services","(eg, Opens","Clients","(React)","Load Balancer)","(Python)","(Render tokens)","WebSockets — the default for ‘real-time,","Server-Sent Events (SSE) — one-way","full-duplex, every chat app uses it.","HTTP stream, native browser EventSource,","auto-reconnect built in,","RPC server streaming — HTTP/2,","binary frames, backpressure","Long polling — boring, battle-tested,","handled for you.","‘works through every proxy on earth."],"fr":["System Design Labs","Vous expédiez un produit de chat Al. Le LLM diffuse — 40 jetons / s","par utilisateur. 50 000 utilisateurs simultanés le jour du lancement. Navigateur client uniquement.","«Envoyer","«eontext","Flux","(serveur pousse","jetons)","Navigateur","ALB","FastAPI","LLM Provider","Navigateur","Clients","(application","Services","(par exemple, ouvre","Clients","(Réagir)","Balance de charge)","(Python)","(Render tokens)","WebSockets — la valeur par défaut pour ‘real-time,","Server-Sent Events (SSE) — à sens unique","full-duplex, chaque application de chat l'utilise.","Flux HTTP, navigateur natif EventSource,","reconnexion automatique intégrée,","Serveur RPC en streaming — HTTP/2,","cadres binaires, contrepression","Long sondage - ennuyeux, testé au combat,","manipulés pour vous.","« Travaille à travers chaque proxy sur la terre."]}},{"kind":"p","page":86,"text":{"en":"You're shipping an AI chat product. The LLM streams ~40 tokens/sec per user.","fr":"Vous lancez un assistant conversationnel. Le LLM produit environ 40 tokens par seconde et par utilisateur en streaming."}},{"kind":"p","page":86,"text":{"en":"50,000 concurrent users on launch day. Browser clients only. Tokens flow one way: server → user.","fr":"Vous attendez 50 000 utilisateurs simultanés le jour du lancement, tous sur navigateur. Les tokens ne circulent que dans un sens : du serveur vers l’utilisateur."}},{"kind":"p","page":86,"text":{"en":"Your team meets to pick the transport. Everyone shows up with a strong opinion.","fr":"Votre équipe se réunit pour choisir le protocole de transport. Chacun a un avis bien arrêté."}},{"kind":"p","page":86,"text":{"en":"Here's the setup:","fr":"Voici la configuration."}},{"kind":"p","page":86,"text":{"en":"• Frontend: React in the browser","fr":"• Frontend : React dans le navigateur"}},{"kind":"p","page":86,"text":{"en":"• Backend: Python (FastAPI) behind an ALB","fr":"• Backend : Python (FastAPI) derrière un ALB"}},{"kind":"p","page":86,"text":{"en":"• Payload: UTF-8 text tokens, ~5–20 bytes each","fr":"• Données : tokens de texte UTF-8, d’environ 5 à 20 octets chacun"}},{"kind":"p","page":86,"text":{"en":"• Direction: server pushes, client just renders","fr":"• Direction : le serveur envoie les données et le client les affiche."}},{"kind":"p","page":86,"text":{"en":"• Reconnects must be invisible (mobile networks drop constantly)","fr":"• Les reconnexions doivent être transparentes pour les utilisateurs, car les réseaux mobiles se coupent souvent."}},{"kind":"p","page":86,"text":{"en":"The team lead says \"WebSockets, obviously.\" The platform engineer pushes back. What do you ship?","fr":"Votre responsable technique estime que le choix des WebSockets va de soi. L’ingénieur plateforme n’est pas convaincu. Quelle option mettez-vous en production ?"}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":86,"text":{"en":"WebSockets — the default for \"real-time,\" full-duplex, every chat app uses it.","fr":"WebSockets : le choix habituel pour le temps réel, avec une communication bidirectionnelle simultanée, comme dans les applications de messagerie."}}]},{"letter":"B","blocks":[{"kind":"p","page":87,"text":{"en":"Server-Sent Events (SSE) — one-way HTTP stream, native browser EventSource, auto-reconnect built in.","fr":"Server-Sent Events (SSE) : flux HTTP unidirectionnel, API EventSource intégrée au navigateur et reconnexion automatique."}}]},{"letter":"C","blocks":[{"kind":"p","page":87,"text":{"en":"gRPC server streaming — HTTP/2, binary frames, backpressure handled for you.","fr":"Streaming serveur gRPC : HTTP/2, trames binaires et gestion intégrée de la contre-pression."}}]},{"letter":"D","blocks":[{"kind":"p","page":87,"text":{"en":"Long polling — boring, battle-tested, works through every proxy on earth.","fr":"Long polling : une technique classique et éprouvée qui passe par tous les proxys."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"figure","page":88,"id":"088-03","width":800,"height":533,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["System Design Labs","RIGHT ANSWER: B) SSE","Server-Sent Events (SSE) — one-way HTTP stream,","native browser EventSource, auto-reconnect built in.","One-way traffic.","Server pushes tokens,","client renders. Perfect match","sst","Send prompt","for SSE.","Built-in auto-reconnect.","EventSource reconnects and","Auto-reconnect","sends Last-Event-ID so the","Browser","server ean resume from there,","Client","ALB","LLM Provider","Application","(Python)","Load Balancer","‘Simpler and more reliable.","40 tokens","No protocol upgrade. No new","framing. No new auth path","Lee code. Fewer bugs.","WebSockets","Server-Sent Events (SSE)","‘QRPC server streaming","Long polling","the defauit for “real-time;","‘one-way HTTP stream,","HITR/2, binary frames,","boring, batte-tested,","full-duplex, every chat","native browser EventSource,","backpressure handled","works through every","proxy on earth.","X Overkil for one-way trafic","X Browser support is poor","X High overhead and latency","X Manual reconnect & resume logic","‘Automatic reconnect with","X- Extra complexity for text tokens","Last-Event-ID","X_ Higher infra and operational cost","X Harder to operate at scale","X Not real-time enough","Simple efficent, and reliable"],"fr":["System Design Labs","REPONSE DROITE: B) ESS","Événements envoyés par le serveur (SSE) — flux HTTP unidirectionnel,","navigateur natif EventSource, reconnexion automatique intégrée.","Trafic à sens unique.","Le serveur pousse des jetons,","rendu du client.","sst","Envoyer l'invite","pour SSE.","Reconnexion automatique intégrée.","EventSource se reconnecte et","Reconnexion automatique","envoie Last-Event-ID donc le","Navigateur","serveur ean reprendre de là,","Client","ALB","LLM Provider","Demande","(Python)","Balanceur de charge","« Plus simple et plus fiable.","40 jetons","Pas de mise à niveau du protocole.","Pas de nouveau chemin d'auth","Le code Lee. Moins de bugs.","WebSockets","Événements envoyés par le serveur (SSE)","‘QRPC server streaming","Longs sondages","le défaut de « temps réel » ;","«flux HTTP unidirectionnel,","HITR/2, trames binaires,","Ennuyeux, testé sur batterie,","full-duplex, chaque tchat","navigateur natif EventSource,","contre-pression manipulée","Fonctionne à travers chaque","proxy sur Terre.","X Overkil pour le trafic unidirectionnel","X Le support du navigateur est médiocre","X Frais généraux et latence élevés","X Manuel reconnecter & reprendre la logique","Reconnecter automatiquement avec","X- Complexité supplémentaire pour les jetons de texte","Last-Event-ID","X_ Coûts d'infrastructure et d'exploitation plus élevés","X Plus difficile à utiliser à grande échelle","X Pas assez en temps réel","Simple, efficace et fiable"]}},{"kind":"p","page":88,"text":{"en":"Why B wins (SSE):","fr":"Pourquoi choisir B (SSE)"}},{"kind":"p","page":88,"text":{"en":"The traffic is one-way. Server pushes tokens, client renders. That's it. The client never sends a token back mid-stream — user input goes through a separate POST. So you're paying for full-duplex on a half-duplex problem.","fr":"Le flux est unidirectionnel : le serveur envoie les tokens et le client les affiche. Le client ne renvoie aucun token pendant le streaming, car la saisie de l’utilisateur est transmise par une requête POST séparée. Une connexion bidirectionnelle simultanée serait donc superflue."}},{"kind":"p","page":88,"text":{"en":"SSE is built for exactly this shape. One long-lived HTTP connection, text/event-stream, server writes, browser's native EventSource reads. No protocol upgrade. No new framing. No new auth path.","fr":"SSE est conçu pour ce type de flux. Le serveur écrit au format text/event-stream sur une connexion HTTP de longue durée et l’API EventSource du navigateur lit le flux. Aucun changement de protocole, nouveau format de trames ou nouveau mécanisme d’authentification n’est nécessaire."}},{"kind":"p","page":88,"text":{"en":"The killer feature: automatic reconnect with Last-Event-ID. Browser drops, mobile switches from WiFi to LTE — EventSource reconnects on its own and tells the server the last event it saw. You replay from there. With WebSockets, you write that logic yourself, and you write it wrong the first three times.","fr":"L’avantage décisif est la reconnexion automatique avec Last-Event-ID. Si le navigateur perd la connexion ou que le téléphone passe du Wi-Fi à la LTE, EventSource se reconnecte et communique au serveur le dernier événement reçu. Le serveur peut rejouer les événements suivants. Avec WebSockets, ce mécanisme est à implémenter et à fiabiliser soi-même."}},{"kind":"p","page":88,"text":{"en":"OpenAI's streaming API? SSE. Anthropic's streaming API? SSE.","fr":"Les API de streaming d’OpenAI et d’Anthropic utilisent SSE."}}],[{"kind":"p","page":89,"text":{"en":"Why A is the trap (WebSockets):","fr":"Pourquoi A est tentant (WebSockets)"}},{"kind":"p","page":89,"text":{"en":"The word \"chat\" tricks people. User-to-user chat (Slack, WhatsApp) is bidirectional. An AI chat app is a unidirectional token stream with a separate POST for the prompt. Different shape, different transport.","fr":"Le terme « chat » prête à confusion. Une messagerie comme Slack ou WhatsApp échange des données dans les deux sens. Un assistant IA expose ici un flux unidirectionnel de tokens et reçoit le prompt dans une requête POST distincte. Ces deux échanges appellent des transports différents."}},{"kind":"p","page":89,"text":{"en":"The cost at 50K connections:","fr":"Les coûts à 50 000 connexions :"}},{"kind":"p","page":89,"text":{"en":"• Sticky sessions on the ALB","fr":"• Affinité de session sur l’ALB"}},{"kind":"p","page":89,"text":{"en":"• Hand-rolled reconnect + replay logic","fr":"• Logique de reconnexion et de rejeu à développer soi-même"}},{"kind":"p","page":89,"text":{"en":"• Heartbeats and ping/pong to detect dead connections","fr":"• Signaux de vie et échanges ping/pong pour détecter les connexions perdues"}},{"kind":"p","page":89,"text":{"en":"• Higher per-connection memory for buffers you'll never use","fr":"• Mémoire supplémentaire par connexion pour des tampons inutilisés"}},{"kind":"p","page":89,"text":{"en":"Every one of those turns into an on-call page.","fr":"Chacun de ces points risque de devenir une nouvelle alerte d’astreinte."}}],[{"kind":"p","page":89,"text":{"en":"Why C is wrong (gRPC streaming):","fr":"Pourquoi écarter C (streaming gRPC)"}},{"kind":"p","page":89,"text":{"en":"Browsers don't speak gRPC. You'd need Envoy + gRPC-Web, which downgrades the streaming model and adds a proxy hop. You're now operating Envoy and debugging Protobuf frames in the network tab — to ship UTF-8 tokens. Great for service-to-service. Wrong tool for browsers.","fr":"Les navigateurs ne prennent pas nativement en charge gRPC. Il faut ajouter Envoy et gRPC-Web, qui réduisent les capacités du streaming et introduisent un saut de proxy. Vous vous retrouvez à exploiter Envoy et à déboguer des trames Protobuf dans l’onglet réseau du navigateur pour transmettre des tokens UTF-8. Le transport convient aux échanges entre services, mais mal à des clients web."}}],[{"kind":"p","page":89,"text":{"en":"Why D is wrong (Long polling):","fr":"Pourquoi écarter D (long polling)"}},{"kind":"p","page":89,"text":{"en":"At 40 tokens/sec, every poll cycle burns a full HTTP request. 50K users × 40 req/sec = 2M RPS just to render text. It's a valid fallback when SSE/WS are blocked. It's not your primary transport in 2026.","fr":"À 40 tokens/s, chaque cycle de polling consomme une requête HTTP entière. À 50 000 utilisateurs, cela fait deux millions de requêtes par seconde rien que pour afficher du texte. C’est une solution de repli si SSE et WebSockets sont bloqués. En 2026, il y a de meilleurs choix par défaut."}}]]},{"day":22,"title":{"en":"Reliable Messaging Across Services","fr":"Fiabiliser la messagerie entre services"},"pages":[90,93],"topic":"events","correct":"D","scenario":[{"kind":"figure","page":90,"id":"090-02","width":800,"height":421,"alt":{"en":"Day 22 featured","fr":"Illustration de la question du jour 22"},"transcript":{"en":["‘System Design Labs","Your payment service just charged a customer.","What do you build?","HTTP call","Pay","Send","nede","GO","Email","PaymentService","NotificationService","(Go)","Email","Client","Timeouts /","Provider","Write","504s","Retry with exponential backoff until NotficationService","Wrap both in a distributed transaction (2PC) —","returns 200. If you keep retrying until you get an ACK,","PaymentService and NotificationService commit","you know it arrived","together or neither does.","Outbox pattern — PaymentService writes the","Push to SQS with at-least-once delivery.","notification event to an outbox table in the same DB","NotificationService deduplicates on a stable","transaction as the payment. A relay process delivers","idempotency key. Accept you might send twice,","it separately","ihe","but never miss"],"fr":["«System Design Labs","Votre service de paiement vient de facturer un client.","Que construisez-vous ?","Appel HTTP","Rémunération","Envoyer","nede","GO","Adresse électronique","PaymentService","NotificationService","(Go)","Adresse électronique","Client","Délais d'attente /","Fournisseur","Ecrire","504s","Réessayez avec un backoff exponentiel jusqu'à NotficationService","Enveloppez les deux dans une transaction distribuée (2PC)","Si vous continuez à réessayer jusqu'à ce que vous obteniez un ACK,","PaymentService et NotificationService commit","Vous savez qu'il est arrivé","Ensemble ou pas.","Modèle de boîte d'envoi — PaymentService écrit le","Poussez vers SQS avec au moins une livraison.","événement de notification à une table d'outbox dans la même base de données","NotificationService déduplique sur une écurie","transaction en tant que paiement. Un processus de relais livre","Acceptez que vous puissiez envoyer deux fois,","elle séparément","ihe","mais ne manquez jamais"]}},{"kind":"p","page":90,"text":{"en":"Your payment service just charged a customer.","fr":"Votre service de paiement vient de débiter un client."}},{"kind":"p","page":90,"text":{"en":"It writes to the DB. Now it needs to tell the notification service: \"Send the confirmation email.\"","fr":"Après l’écriture en base, il doit demander au service de notifications d’envoyer l’e-mail de confirmation."}},{"kind":"p","page":90,"text":{"en":"The HTTP call times out. Did it arrive? You don't know. You retry. Customer gets two emails.","fr":"L’appel HTTP atteint son délai maximal. La demande est-elle arrivée ? Impossible de le savoir. Vous réessayez et le client reçoit deux e-mails."}},{"kind":"p","page":90,"text":{"en":"You've just hit the Two Generals Problem. It's not a bug. It's a proof.","fr":"C’est le problème des deux généraux, un résultat démontré qui s’applique même lorsque votre implémentation fonctionne comme prévu."}},{"kind":"p","page":90,"text":{"en":"No protocol over an unreliable channel can guarantee both sides agree on the final message. Not HTTP. Not TCP. Not your retry loop. The uncertainty is mathematically irreducible.","fr":"Aucun protocole sur un canal non fiable ne peut garantir que les deux parties s’accordent sur la réception du dernier message. Ni HTTP, ni TCP, ni une boucle de nouvelles tentatives ne lèvent cette incertitude."}},{"kind":"p","page":90,"text":{"en":"Here's the setup:","fr":"Voici la configuration."}},{"kind":"p","page":90,"text":{"en":"PaymentService (Node.js, PostgreSQL) → NotificationService (Go)","fr":"PaymentService (Node.js, PostgreSQL) → NotificationService (Go)"}},{"kind":"p","page":90,"text":{"en":"~40ms p99 latency, occasional 504s under load.","fr":"Latence p99 d’environ 40 ms, avec des erreurs 504 occasionnelles sous charge."}},{"kind":"p","page":90,"text":{"en":"You need to send exactly one confirmation email per payment — no double-sends, no missed sends.","fr":"Vous devez envoyer exactement un e-mail de confirmation par paiement, sans doublon ni omission."}},{"kind":"p","page":90,"text":{"en":"What do you build?","fr":"Que mettez-vous en place ?"}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":90,"text":{"en":"Retry with exponential backoff until NotificationService returns 200. If you keep retrying until you get an ACK, you know it arrived.","fr":"Réessayer avec temporisation exponentielle jusqu’à ce que NotificationService renvoie un 200. Une fois l’accusé de réception obtenu, vous savez que la demande est arrivée."}}]},{"letter":"B","blocks":[{"kind":"p","page":91,"text":{"en":"Wrap both in a distributed transaction (2PC) — PaymentService and NotificationService commit together or neither does.","fr":"Regrouper les deux opérations dans une transaction distribuée (2PC) : PaymentService et NotificationService valident tous les deux ou aucun ne valide."}}]},{"letter":"C","blocks":[{"kind":"p","page":91,"text":{"en":"Outbox pattern — PaymentService writes the notification event to an outbox table in the same DB transaction as the payment. A relay process delivers it separately.","fr":"Utiliser une outbox transactionnelle : PaymentService enregistre l’événement de notification dans une table outbox, dans la même transaction que le paiement. Un processus relais le transmet séparément."}}]},{"letter":"D","blocks":[{"kind":"p","page":91,"text":{"en":"Push to SQS with at-least-once delivery. NotificationService deduplicates on a stable idempotency key. Accept you might send twice, but never miss.","fr":"Publier dans SQS avec une garantie de remise au moins une fois. NotificationService déduplique les messages avec une clé d’idempotence stable. Un message peut être remis deux fois, mais aucun ne doit manquer."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"figure","page":92,"id":"092-03","width":800,"height":533,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["Push to SQS with at-least-once delivery.","@ correct","NotificationService deduplicates on a stable idempotency key.","Accept you might send twice, but never miss.","iver 1.","Publish","Send","nede","Consume","Email","PaymentService","Message","NotificationService","Client","{payment_id,","(Go)","Write","‘email, v1,","‘Amazon SOS","Provider","ane","‘and send email","key exists","Retry / Red","ery","Idempotency Key","Dedup Table","payment_id:email:vi","‘Accept the reality","Queue absorbs","Idempotency absorbs","Outcome","Network + systems are","duplicates","\"No missed sends,","SOS durably stores","Dedup table with key","No double-sends","willbe delivered —","the message and","(payment_id:email:v3)","‘maybe more than once.","once delivery.","‘makes replays a no-op,","* Thi","how Stri","ind AWS handl","Queue + Id","ctl","nc","fects in practice."],"fr":["Poussez vers SQS avec au moins une livraison.","correct","NotificationService déduplique sur une clé idempotency stable.","Acceptez que vous pourriez envoyer deux fois, mais ne manquez jamais.","Iver 1.","Publier","Envoyer","nede","Consommer","Adresse électronique","PaymentService","Message","NotificationService","Client","payment_id,","(Go)","Ecrire","«email, v1,","«Amazon SOS","Fournisseur","ane","« et envoyer un courriel","La clé existe","Réessayer / Rouge","ery","Clé d'identité","Dedup Table","paiement_id:email:vi","« Accepter la réalité","File d'attente absorbe","L’identité absorbe","Résultat","Les systèmes réseau + sont","doublons","\"Pas d'envoi manqué,","SOS durablement","Table avec clé","Pas de double-envoi","Sera livré -","Le message et","(payment_id:email:v3)","« Peut-être plus d’une fois.","une fois la livraison.","«fait des replays une non-op,","* Thi","Comment Stri","ind AWS handl","File d'attente + ID","ctl","nc","des défauts dans la pratique."]}},{"kind":"p","page":92,"text":{"en":"D — SQS + at-least-once + idempotency key (CORRECT)","fr":"D — SQS, remise au moins une fois et clé d’idempotence (bonne réponse)"}},{"kind":"p","page":92,"text":{"en":"The only answer that accepts the impossibility and designs around it. At-least-once means the message will arrive — maybe twice. Idempotency on the consumer side (payment_id:email:v1 in a dedup table) makes the second delivery a no-op. No missed sends, no double-sends in practice. This is exactly how Stripe and AWS handle it. The queue absorbs the uncertainty. Idempotency absorbs the duplicates.","fr":"Cette réponse accepte l’impossibilité d’une remise certaine et conçoit le système en conséquence. La garantie « au moins une fois » signifie que le message arrive, éventuellement en double. L’idempotence du consommateur, assurée ici par une table de déduplication avec la clé payment_id:email:v1, fait que la deuxième remise ne déclenche aucune opération. En pratique, ni envoi oublié ni envoi en double. Stripe et AWS suivent cette approche. La file prend en charge l’incertitude de livraison et l’idempotence neutralise les doublons."}}],[{"kind":"p","page":92,"text":{"en":"A — Retry until ACK (SENIOR ENGINEER TRAP)","fr":"A — Réessayer jusqu’à l’accusé de réception (choix trompeur)"}},{"kind":"p","page":92,"text":{"en":"Feels airtight. It's not. What if the 200 response is what timed out — not the request? NotificationService sent the email AND returned 200, but you never saw the response. So you retry. Second email sent. Now you need to confirm your ACK arrived too... which is the Two Generals recursion. No finite number of retries closes this loop. More handshakes = more latency and more failure surfaces, not more certainty.","fr":"Cela semble infaillible. Mais si c’est la réponse 200 qui n’est jamais arrivée, alors que la requête a bien été reçue ? NotificationService a envoyé l’e-mail et répondu 200, sans que vous voyiez la réponse. Vous réessayez et un second e-mail part. Il vous faut désormais confirmer la réception de l’accusé de réception, et ainsi de suite. Aucune suite finie de nouvelles tentatives ne résout le problème des deux généraux. Ajouter des échanges augmente la latence et les possibilités de défaillance sans apporter de certitude."}}],[{"kind":"p","page":93,"text":{"en":"B — 2PC (WRONG)","fr":"B — Validation en deux phases (2PC)"}},{"kind":"p","page":93,"text":{"en":"The coordinator is a single point of failure. If it crashes between Phase 1 (prepare) and Phase 2 (commit), both services are stuck with locks held, waiting for a decision that never comes. You've traded message uncertainty for coordinator-failure uncertainty — same problem, more complexity.","fr":"Le coordinateur devient un point unique de défaillance. S’il tombe entre la phase 1 (préparation) et la phase 2 (validation), les deux services conservent leurs verrous et attendent une décision qui ne vient pas. L’incertitude sur la livraison est remplacée par celle sur le coordinateur, avec davantage de complexité."}}],[{"kind":"p","page":93,"text":{"en":"C — Outbox Pattern (CORRECT but heavier)","fr":"C — Outbox transactionnelle (valable, mais plus lourde)"}},{"kind":"p","page":93,"text":{"en":"Actually solid — atomicity at the DB level, event and payment always in sync. But you're now running a relay process + CDC pipeline + outbox cleanup. For most teams with SQS already in place, D gets 95% of the same guarantees with a fraction of the infrastructure. C shines at scale or when strict ordering matters. D is the right answer for most teams today.","fr":"L’approche est solide : au niveau de la base, l’atomicité maintient le paiement et son événement en phase. Il faut néanmoins exploiter un processus relais, un pipeline CDC et un mécanisme de nettoyage de l’outbox. Pour la plupart des équipes qui utilisent déjà SQS, D offre environ 95 % des mêmes garanties avec une fraction de l’infrastructure. C se distingue à grande échelle ou lorsque l’ordre strict des événements compte. D est le choix adapté à la plupart des équipes aujourd’hui."}}]]},{"day":23,"title":{"en":"Feed Fanout for Celebrity Accounts","fr":"Diffuser les publications des comptes très suivis dans les fils d’actualité"},"pages":[94,97],"topic":"scale","correct":"C","scenario":[{"kind":"figure","page":94,"id":"094-02","width":800,"height":420,"alt":{"en":"Day 23 featured","fr":"Illustration de la question du jour 23"},"transcript":{"en":["ym Design Labs","Your feed service was reading at 20ms.","Then a celebrity with 2M followers posted. Now you're at 4 seconds.","| deliver /","| write","read","Read","Replicas","fanout read aa","(0 ‘App","Celebrity post — fanout read","‘across 2M follower rows","Fanout on Wi","— push to every","Fanout on Read — no precomputation.","follower’s cache on post. Reads instant.","Fetch + merge at read time. Simple writes","Celebrity post =","IM cache writes.","Painful at scale.","Mat","lized feed table — denormalized","Hybrid fanout — fanout on write for","regular users, fanout on read for celebri","Per-user feed row, updated async via","Merge at read time only for the celebrity slice.","|e","event stream. One table read, eventual consistency."],"fr":["ym Design Labs","Votre service d'alimentation lisait à 20ms.","Puis une célébrité avec 2M followers posté. Maintenant vous êtes à 4 secondes.","livrer /","écrire","lire","Lire","Répliques","fanout lire aa","(0 «App","Célébrité post — fanout lire","«sur 2M lignes suiveuses","Fanout sur Wi","poussez à chaque","Fanout on Read - pas de précalcul.","cache du suiveur sur le post. Lecture instantanée.","Récupérer + fusionner au moment de la lecture.","Celebrity post","IM cache écrit.","Douleur à l'échelle.","Mat","Table d'alimentation lisée — dénormalisée","Hybrid fanout — fanout sur écrire pour","utilisateurs réguliers, fanout en lecture pour celebri","Ligne de flux par utilisateur, mise à jour async via","Fusionner au moment de la lecture seulement pour la tranche de célébrité.","e","flux d'événements. Une table de lecture, cohérence éventuelle."]}},{"kind":"p","page":94,"text":{"en":"Your feed service was reading at 20ms.","fr":"Les lectures de votre service de fil d’actualité prenaient 20 ms."}},{"kind":"p","page":94,"text":{"en":"Then a celebrity with 2M followers posted.","fr":"Puis une célébrité suivie par deux millions de personnes a publié un message."}},{"kind":"p","page":94,"text":{"en":"Now you're at 4 seconds. P99 is on fire.","fr":"Les lectures prennent maintenant quatre secondes. La latence p99 s’envole."}},{"kind":"p","page":94,"text":{"en":"Here's the setup:","fr":"Voici la configuration."}},{"kind":"p","page":94,"text":{"en":"10M users. ~50k posts/day. One account: 2M followers.","fr":"10 millions d’utilisateurs. Environ 50 000 publications par jour. Un compte cumule deux millions d’abonnés."}},{"kind":"p","page":94,"text":{"en":"Every time that account posts, your feed query fans out across 2M follower rows, sorts by timestamp, and buries your read replicas.","fr":"À chaque publication de ce compte, votre requête parcourt les deux millions de lignes des abonnés, trie par horodatage et sature les répliques de lecture."}},{"kind":"p","page":94,"text":{"en":"Your team is debating how to fix the delivery model — not the query, the architecture.","fr":"Votre équipe discute d’une refonte du mode de diffusion des publications à l’échelle de l’architecture."}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":94,"text":{"en":"Fanout on Write — push to every follower's cache on post. Reads instant. Celebrity post = 2M cache writes.","fr":"Fanout en écriture : à chaque publication, alimenter le cache de chaque abonné. Les lectures sont instantanées. La publication d’une célébrité entraîne deux millions d’écritures dans le cache."}}]},{"letter":"B","blocks":[{"kind":"p","page":94,"text":{"en":"Fanout on Read — no precomputation. Fetch + merge at read time. Simple writes. Painful at scale.","fr":"Fanout en lecture : aucun précalcul. Récupérer et fusionner les publications à la lecture. Les écritures sont simples, mais l’approche devient coûteuse à grande échelle."}}]},{"letter":"C","blocks":[{"kind":"p","page":94,"text":{"en":"Hybrid fanout — fanout on write for regular users, fanout on read for celebrities. Merge at read time only for the celebrity slice.","fr":"Fanout hybride : diffuser à l’écriture pour les comptes ordinaires et à la lecture pour les célébrités. Seules les publications des célébrités doivent être ajoutées à la lecture."}}]},{"letter":"D","blocks":[{"kind":"p","page":95,"text":{"en":"Materialized feed table — denormalized per-user feed row, updated async via event stream. One table read, eventual consistency.","fr":"Table de fil matérialisée : une ligne dénormalisée par utilisateur, mise à jour de façon asynchrone via un flux d’événements. Une lecture dans la table, avec cohérence à terme."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"figure","page":96,"id":"096-03","width":800,"height":480,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["Why C wins","ANSWER","© Avoids 2M synchronous writes","Fanout on write for regular users, fanout on read for celebrities.","© Keeps reads fast (P99)","@ Bounded fanout at read time","Merge at read time only for the celebrity slice.","© Used by Twitter at scale","PATH (pe","te","Fast path for","User Feed Cache","Instant ead","Service","‘Skip Fanout","> Celebrity Poste","(Celebrity)","Store","‘oid 2M writes","READ PATH","et home","‘Fetch from coche (regular users)","User Fond Cache","Tei)","Merge","Feed","G Hers strat","Celery see","Service","(sort ine)","tal & bended","709 stay fot","Celery Posts","Store","Iti shes about bt are made:","10k followers","Result","Fanouton-wite egret ormost users","Fact on write","Fart P50 / POD","(bounded coe)"],"fr":["Pourquoi retenir C","ANSWER","Évite les écritures synchrones 2M","Fanout sur écrire pour les utilisateurs réguliers, fanout sur lire pour les célébrités.","Conserve une lecture rapide (P99)","Fanout lié à la lecture","Fusionner au moment de la lecture seulement pour la tranche de célébrité.","Utilisé par Twitter à grande échelle","PATH (p","te","Voie rapide pour","Cache de flux utilisateur","Instant ead","Service","«Skip Fanout","> Celebrity Poste","(Célébrité)","Stocker","« oi 2M écrit","LIRE LE CHEMIN","et home","«Retirer de la coche (utilisateurs réguliers)","User Fond Cache","Tei)","Fusionner","Flux","G Hers strat","Céleri voir","Service","(tri ine)","tal & plié","709 séjours","Céleri Posts","Stocker","Iti shes sur bt sont faites:","10 000 abonnés","Résultat","Fanouton-wite aigrette ormost utilisateurs","Faits sur l'écriture","Fart P50 / POD","(Coefficients limités)"]}},{"kind":"p","page":96,"text":{"en":"Answer: C — Hybrid fanout","fr":"Réponse : C — Fanout hybride"}},{"kind":"p","page":96,"text":{"en":"Why C wins:","fr":"Pourquoi choisir C"}},{"kind":"p","page":96,"text":{"en":"This is how Twitter actually solved it — they published the architecture. The insight: fanout-on-write is fast for readers but catastrophic for high-follower accounts. Fanout-on-read is simple but destroys latency at scale. Hybrid is honest about both failure modes.","fr":"C’est l’architecture publiée par Twitter. Le fanout en écriture accélère les lectures, mais devient ingérable pour les comptes très suivis. Le fanout en lecture simplifie les choses, au prix d’une forte hausse de la latence à grande échelle. L’approche hybride tient compte des deux cas."}},{"kind":"p","page":96,"text":{"en":"When a post is created → check follower count. Under 10k? Fan out immediately to all followers' Redis feed caches. Over 10k (celebrity)? Skip the fanout. At read time, fetch from two sources: precomputed cache (regular accounts) + real-time query for celebrity accounts. Merge + deduplicate. The celebrity slice is small and bounded. Result: P99 stays fast, no 2M synchronous writes on celebrity posts.","fr":"À chaque publication, vérifiez le nombre d’abonnés. En dessous de 10 000, diffusez aussitôt la publication dans les caches Redis des abonnés. Au-dessus, traitez le compte comme une célébrité et sautez cette étape. À la lecture, consultez deux sources : le cache précalculé des comptes ordinaires et une requête en direct pour les célébrités. Fusionnez et dédupliquez les résultats. Le nombre de publications des célébrités qu’il faut traiter est faible et borné. Le p99 reste bas et la publication d’une célébrité ne déclenche plus deux millions d’écritures synchrones."}}],[{"kind":"p","page":97,"text":{"en":"Why A is the trap (Fanout on Write):","fr":"Pourquoi A est tentant (fanout en écriture)"}},{"kind":"p","page":97,"text":{"en":"Looks perfect. Reads are instant. Until Cristiano Ronaldo posts and you're writing to 500M caches in parallel. At 2M followers, even 1ms per write = 2,000 seconds of write work. Cache cluster saturates. Write queue backs up. Thundering herd on every celebrity post.","fr":"Sur le papier, les lectures sont instantanées. Puis Cristiano Ronaldo publie et vous devez écrire dans 500 millions de caches en parallèle. Avec deux millions d’abonnés, même à 1 ms par écriture, cela représente 2 000 secondes de travail d’écriture cumulé. Le cluster de cache sature et la file d’écritures s’engorge. Chaque publication d’une célébrité déclenche une ruée."}},{"kind":"p","page":97,"text":{"en":"Teams implement this, it works great at 1M users, then hits the celebrity problem when it's already in production. That's the trap.","fr":"Les équipes mettent cette approche en place et constatent qu’elle fonctionne à un million d’utilisateurs. Le problème des comptes très suivis ne se manifeste qu’une fois en production."}}],[{"kind":"p","page":97,"text":{"en":"Why B is wrong (Fanout on Read):","fr":"Pourquoi écarter B (fanout en lecture)"}},{"kind":"p","page":97,"text":{"en":"500 accounts followed = 500 queries (or one giant JOIN), sorted in memory, before returning anything. You can cache the result — but now you're doing expensive computation to fill a cache that expires in 30s. That's just a slow fanout-on-write with extra latency. Doesn't survive 10M users.","fr":"Suivre 500 comptes implique 500 requêtes ou une énorme jointure, avec un tri en mémoire avant de renvoyer le moindre résultat. Vous pouvez mettre le résultat en cache, mais il faut un calcul coûteux pour alimenter un cache qui expire après 30 s. Cela revient à reporter le travail de diffusion sur le chemin de lecture en y ajoutant de la latence. L’approche ne tient pas à dix millions d’utilisateurs."}}],[{"kind":"p","page":97,"text":{"en":"Why D is wrong (Materialized feed table):","fr":"Pourquoi écarter D (table de fil matérialisée)"}},{"kind":"p","page":97,"text":{"en":"Sounds clean — denormalized row per user, updated async via CDC/event stream. But a celebrity post still triggers 2M row updates, just asynchronously. You haven't solved write amplification, you've deferred it. Plus: operational complexity of an event stream + idempotent consumers + reconciliation logic. More moving parts for the same problem.","fr":"Une ligne dénormalisée par utilisateur, mise à jour de façon asynchrone via le CDC ou un flux d’événements semble une bonne idée. Mais la publication d’une célébrité entraîne toujours deux millions de mises à jour de lignes, simplement en différé. L’amplification des écritures demeure. À cela s’ajoute la complexité d’exploitation du flux, des consommateurs idempotents et de la logique de rapprochement. Les mêmes problèmes requièrent davantage de composants."}}]]},{"day":24,"title":{"en":"Paginating Large Result Sets Efficiently","fr":"Paginer efficacement des résultats volumineux"},"pages":[98,102],"topic":"scale","correct":"A","scenario":[{"kind":"figure","page":98,"id":"098-02","width":800,"height":420,"alt":{"en":"Day 24 featured","fr":"Illustration de la question du jour 24"},"transcript":{"en":["System D","Labs","Your API returns 10 million orders.","The frontend asks for “page 5.”","¥ es your fix?","50M rows","Indexed on","created_at,","o=] |","HTTPS","Query","(pages, >| 5","(status,","Sorted by","filters)","sort, page)","bil","created_at —>","DESC","Ge","Admin","API","PostgreSQL","Result Set","Dashboard","Service","(orders table)","(10 rows)","Cursor pagination — encode the last seen","Keyset pagination —","created _at + id into a token, use it as a","WHERE (created_at, id) < (last_created_at,","WHERE clause anchor","last_id) directly","Deferred join — fetch the IDs first with","Keep offset pagination but add a covering","offset, then join back to get full rows","index on (status, created_at, id)"],"fr":["Système D","Labs","Votre API renvoie 10 millions de commandes.","Le frontend demande « page 5 ».","est votre solution?","50M lignes","Indexé sur","created_at,","o — ]","HTTPS","Requête","(pages, > — 5","(statut,","Trié par","filtres)","tri, page)","bil","created_at — >","DESC","Ge","Admin","API","PostgreSQL","Ensemble de résultats","Tableau de bord","Service","(tableau des commandes)","(10 rangées)","Cursor pagination — encode la dernière fois","Keyset pagination","créé _at + id dans un jeton, utilisez-le comme un","WHERE (created_at, id) — (last_created_at,","WHERE clause ancre","last_id) directement","Deferred join — récupérer les identifiants en premier avec","Gardez la pagination offset mais ajoutez une couverture","offset, puis rejoins-nous pour obtenir des lignes complètes","index sur (statut, created_at, id)"]}},{"kind":"p","page":98,"text":{"en":"Your API returns 10 million orders.","fr":"Votre API renvoie dix millions de commandes."}},{"kind":"p","page":98,"text":{"en":"The frontend asks for \"page 5.\"","fr":"Le frontend demande la « page 5 »."}},{"kind":"p","page":98,"text":{"en":"Offset 40, limit 10. Simple enough — until your DBA messages you at 2 AM.","fr":"Décalage de 40, limite de 10. Cela paraît simple, jusqu’au message de votre DBA à deux heures du matin."}},{"kind":"p","page":98,"text":{"en":"Query time: 4.2 seconds. Table scans climbing. Prod is lagging.","fr":"Temps de requête : 4,2 secondes. Le nombre de parcours de table augmente. La production ralentit."}},{"kind":"p","page":98,"text":{"en":"Here's the stack: PostgreSQL, 50M rows in orders, sorted by created_at DESC. Users can filter by status. You're paginating an admin dashboard used by 200 concurrent support agents.","fr":"Vous utilisez PostgreSQL. La table orders contient 50 millions de lignes triées par created_at DESC. Les utilisateurs peuvent filtrer par statut. Vous paginez les résultats d’un tableau de bord d’administration utilisé par 200 agents du support simultanément."}},{"kind":"p","page":98,"text":{"en":"Offset pagination worked fine at 10K rows. At 50M, it's reading and discarding 40 million rows just to return 10.","fr":"La pagination par décalage fonctionnait à 10 000 lignes. À 50 millions, la base lit et écarte 40 millions de lignes pour en renvoyer dix."}},{"kind":"p","page":98,"text":{"en":"You need to fix this before the next sprint ships the customer-facing version — which will have 10x the traffic.","fr":"Le prochain sprint met la version destinée aux clients en production, avec dix fois plus de trafic. Il faut régler le problème d’ici là."}},{"kind":"p","page":98,"text":{"en":"Here's your setup:","fr":"Voici la configuration :"}},{"kind":"p","page":98,"text":{"en":"• Table: orders — 50M rows, indexed on created_at, user_id, status","fr":"• Table : orders, 50 millions de lignes, avec des index sur created_at, user_id et status"}},{"kind":"p","page":98,"text":{"en":"• Query: sorted by created_at DESC, filtered by status","fr":"• Requête : tri par created_at DESC, filtre sur status"}},{"kind":"p","page":98,"text":{"en":"• Client: needs \"previous/next\" navigation + jump-to-page","fr":"• Client : navigation « précédent/suivant » et accès direct à une page"}},{"kind":"p","page":99,"text":{"en":"• SLA: p99 < 200ms","fr":"• SLA : p99 < 200 ms"}},{"kind":"p","page":99,"text":{"en":"Four engineers propose four different approaches:","fr":"Quatre ingénieurs proposent chacun une approche :"}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":99,"text":{"en":"Cursor pagination — encode the last seen created_at + id into a token, use it as a WHERE clause anchor","fr":"Pagination par curseur : encoder les dernières valeurs de created_at et id dans un jeton, puis les utiliser comme point de reprise de la clause WHERE."}}]},{"letter":"B","blocks":[{"kind":"p","page":99,"text":{"en":"Keyset pagination — paginate using WHERE (created_at, id) < (last_created_at, last_id) directly","fr":"Pagination par clé : paginer directement avec WHERE (created_at, id) < (last_created_at, last_id)."}}]},{"letter":"C","blocks":[{"kind":"p","page":99,"text":{"en":"Deferred join — fetch the IDs first with offset, then join back to get full rows","fr":"Jointure différée : récupérer d’abord les identifiants avec le décalage, puis faire une jointure pour obtenir les lignes complètes."}}]},{"letter":"D","blocks":[{"kind":"p","page":99,"text":{"en":"Keep offset pagination but add a covering index on (status, created_at, id)","fr":"Conserver la pagination par décalage et ajouter un index couvrant sur (status, created_at, id)."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"figure","page":100,"id":"100-03","width":800,"height":533,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["ANSWER:","J systemesign tbs","Encode the last seen (created_at, id) into a token.","Use it as an anchor for the next query.","50M rows","Indexed 09","seri tats","‘Query with","anchor + fters","Index seek","cursor token)","WHERE stato = statue","Admin","API","{at anchor)","Result Set","Dashboard","Service","order table","(10 rows)","‘ORDER BY created. a DESC, ld DESC","Return rows + next cursor token (opaque)","HOW THE CURSOR TOKEN WORKS","Used innoxt","Laat om","‘Query always hits the index at the anchor point —","request","no sean, no discard","ented ot","encode","Decade [","99 stays flat whether you're on page 1","Py","‘r page 50,000.","Works with the status filter","UX TRADEOFF","WHERE status =","pending’ AND erste tid) < (anchor)","‘THE BOTTOM LINE","nt ters","Only previous/nent.","cursor pagination isthe only approach","Butthis isthe ight wadeott","that hits p99 < 200me reliably,","The cursor is position-stabe: new rows inserted","forthe dashboard. Suppor","before your cursor don't shift your page","agents navigate sequential","ge 3.947\"","p99<200ms 7”"],"fr":["RÉPONSE :","J systemesign tbs","Encodez le dernier vu (created_at, id) dans un jeton.","Utilisez-le comme ancre pour la prochaine requête.","50M lignes","Indexé 09","seri tats","«Demande avec","ancre + pieds","Index recherche","jeton de curseur)","O — stato — statue","Admin","API","à l'ancre)","Ensemble de résultats","Tableau de bord","Service","tableau de commande","(10 rangées)","«ORDRE PAR créé. un DESC, ld DESC","Retourne les lignes + le jeton du curseur suivant (opaque)","COMMENT FONCTIONNE LE CURSEUR","Utilisé innoxt","Laat om","« Interrogez toujours l’index au point d’ancrage...","demande","pas de sean, pas de rejet","Ented ot","encoder","Décennie [","99 reste à plat si vous êtes à la page 1","Py","«R page 50 000.","Fonctionne avec le filtre d'état","UX TRADEOFF","O — statut","(ancre) — (ancre)","«LA LIGNE FONDAMENTALE","nt ters","Uniquement précédent/nant.","La pagination du curseur est la seule approche","Mais c'est le ight wadeott","qui frappe p99 — 200me de manière fiable,","Le curseur est position-stabe : nouvelles lignes insérées","pour le tableau de bord.","avant votre curseur ne déplacez pas votre page","Les agents naviguent séquentiellement","ge 3.947\"","p99 — 200ms 7”"]}},{"kind":"p","page":100,"text":{"en":"Option A — Cursor pagination ✅ CORRECT","fr":"Option A — Pagination par curseur ✅ Bonne réponse"}},{"kind":"p","page":100,"text":{"en":"Encode the last seen (created_at, id) into an opaque token. On the next request, decode it and use WHERE created_at < :last_ts OR (created_at = :last_ts AND id < :last_id) as your anchor.","fr":"Encodez le dernier couple (created_at, id) lu dans un jeton opaque. À la requête suivante, décodez-le et reprenez à partir de WHERE created_at < :last_ts OR (created_at = :last_ts AND id < :last_id)."}},{"kind":"p","page":100,"text":{"en":"Why this wins here:","fr":"Pourquoi cette option fonctionne ici :"}},{"kind":"p","page":100,"text":{"en":"• Query always hits the index at the anchor point — no scan, no discard","fr":"• La requête reprend dans l’index au point décrit par le curseur, sans parcourir ni écarter les entrées précédentes."}},{"kind":"p","page":100,"text":{"en":"• p99 stays flat whether you're on page 1 or page 50,000","fr":"• Le p99 reste stable de la page 1 à la page 50 000."}},{"kind":"p","page":100,"text":{"en":"• Works with the status filter: WHERE status = 'pending' AND (created_at, id) < (anchor)","fr":"• Le filtre par statut fonctionne : WHERE status = 'pending' AND (created_at, id) < (anchor)."}},{"kind":"p","page":100,"text":{"en":"• The cursor is position-stable: new rows inserted before your cursor don't shift your page","fr":"• Le curseur conserve sa position : les insertions de lignes avant celle-ci ne décalent pas votre page."}},{"kind":"p","page":100,"text":{"en":"The UX tradeoff: no jump-to-page. Only previous/next. But this is the right tradeoff for the dashboard. Support agents navigate sequentially. Nobody needs \"jump to page 3,847.\"","fr":"Côté expérience utilisateur, on ne peut plus accéder directement à une page : la navigation se fait avec « précédent » et « suivant ». Le compromis convient à ce tableau de bord. Les agents du support parcourent les résultats dans l’ordre. Ils n’ont pas besoin de sauter à la page 3 847."}},{"kind":"p","page":100,"text":{"en":"At 50M rows with concurrent filters, cursor pagination is the only approach that hits p99 < 200ms reliably.","fr":"À 50 millions de lignes et avec plusieurs filtres actifs, la pagination par curseur est la seule option qui maintient de façon fiable le p99 sous 200 ms."}}],[{"kind":"p","page":101,"text":{"en":"Option B — Keyset pagination","fr":"Option B — Pagination par clé"}},{"kind":"p","page":101,"text":{"en":"Keyset looks identical to cursor on the surface. The difference is subtle: keyset is a query pattern, cursor is a product decision.","fr":"À première vue, la pagination par clé ressemble à la pagination par curseur. La différence tient au niveau où l’on se place : l’une décrit la formulation d’une requête, l’autre un choix de conception côté produit."}},{"kind":"p","page":101,"text":{"en":"Keyset uses WHERE (created_at, id) < (val1, val2) as a SQL construct. Cursor wraps that into an encoded token the client can't inspect or manipulate.","fr":"La pagination par clé repose sur une expression SQL comme WHERE (created_at, id) < (val1, val2). La pagination par curseur l’encapsule dans un jeton encodé, que le client n’est pas censé interpréter ni modifier."}},{"kind":"p","page":101,"text":{"en":"Here's where it falls apart: the status filter breaks row-tuple comparison in most query planners. WHERE status = 'pending' AND (created_at, id) < (anchor) doesn't use a composite index efficiently in PostgreSQL when the equality column (status) isn't part of the tuple comparison. You end up with a partial index scan that degrades under high cardinality filters.","fr":"Le filtre par statut complique la comparaison des tuples dans la plupart des planificateurs de requêtes. WHERE status = 'pending' AND (created_at, id) < (anchor) exploite mal un index composite dans PostgreSQL si la colonne testée par égalité, status, ne fait pas partie du tuple comparé. On obtient un parcours partiel de l’index qui se dégrade avec des filtres à forte cardinalité."}},{"kind":"p","page":101,"text":{"en":"Cursor pagination handles this by encoding the full WHERE context, not just the positional anchor. That's the gap. It's subtle, and it's the thing that bites you in production three months after you ship it....","fr":"La pagination par curseur encode le contexte complet de la clause WHERE, y compris les filtres, au-delà de la seule position. Ce détail passe facilement inaperçu et peut vous rattraper en production trois mois après le déploiement."}}],[{"kind":"p","page":102,"text":{"en":"Option C — Deferred join","fr":"Option C — Jointure différée"}},{"kind":"code","page":102,"text":{"en":"SELECT o.*\nFROM orders o JOIN ( SELECT id\nFROM orders\nWHERE status = 'pending'\nORDER BY created_at DESC\nOFFSET 500000\nLIMIT 10 ) ids ON o.id = ids.id","fr":"SELECT o.*\nFROM orders o JOIN ( SELECT id\nFROM orders\nWHERE status = 'pending'\nORDER BY created_at DESC\nOFFSET 500000\nLIMIT 10 ) ids ON o.id = ids.id"}},{"kind":"p","page":102,"text":{"en":"This is a legitimate optimization for offset pagination. The inner query fetches only IDs (fits in index, much faster), then the outer join fetches full rows for just 10 records.","fr":"C’est une vraie optimisation pour la pagination par décalage. La sous-requête récupère seulement les identifiants, directement dans l’index, ce qui est bien plus rapide. La jointure externe lit ensuite les lignes complètes des dix enregistrements renvoyés."}},{"kind":"p","page":102,"text":{"en":"It's real. It works. Shopify uses a version of this.","fr":"Cette technique fonctionne en pratique. Shopify en utilise une variante."}},{"kind":"p","page":102,"text":{"en":"But: you still pay O(offset) cost on the inner query at deep pages. It helps — it does not solve. At page 50,000, you're still scanning 500,000 index entries. You shaved 80% of the cost and kept 20% of the problem.","fr":"Le coût de la sous-requête reste en O(offset) pour les pages éloignées. À la page 50 000, vous parcourez toujours 500 000 entrées d’index. Vous économisez 80 % du coût, mais 20 % du problème subsiste."}}],[{"kind":"p","page":102,"text":{"en":"Option D — Covering index","fr":"Option D — Index couvrant"}},{"kind":"p","page":102,"text":{"en":"Adding CREATE INDEX ON orders(status, created_at DESC, id DESC) is a good idea regardless of which approach you pick. It removes heap fetches for status-filtered queries.","fr":"Ajouter CREATE INDEX ON orders(status, created_at DESC, id DESC) est judicieux quelle que soit l’approche. Pour les requêtes filtrées par statut, cela évite d’aller chercher les lignes dans la table (heap)."}},{"kind":"p","page":102,"text":{"en":"But an index doesn't change the algorithmic complexity of OFFSET. It makes your table scans faster, not shorter. This is the \"throw hardware at it\" answer. It buys you time, not a solution.","fr":"Un index ne change pas la complexité algorithmique d’OFFSET. Il accélère le parcours sans réduire le nombre d’entrées à parcourir. Tout comme ajouter du matériel, cette option fait gagner du temps sans résoudre le problème de fond."}}]]},{"day":25,"title":{"en":"Queue Backpressure Under a Traffic Spike","fr":"Gérer la contre-pression d’une file lors d’un pic de trafic"},"pages":[103,105],"topic":"reliability","correct":"C","scenario":[{"kind":"figure","page":103,"id":"103-02","width":800,"height":420,"alt":{"en":"Day 25 featured","fr":"Illustration de la question du jour 25"},"transcript":{"en":["‘System Design Labs","Your order processing service runs on SQS.","You need to handle this backpressure. What do you do?","publish","poll","wad / write","“4,000 orders/in","Downstream","Producers","‘Amazon SQS","Consumers","Database","(Order Service)","(Lambda /EC2 Workers)","Set avis","timeout and route failures","‘Scale consumers horizontally — add more","Lambda functions / EC2 workers to chew","to a dead-letter queue to protect against","through the backlog faster.","poison pills.","Rate-limit producers at the source — use","‘Switch to SQS delay queues — defer","a token bucket or sliding window to cap","message vi","lity to spread out delivery","how fast messages enter the queue.","and reduce consumer pressure."],"fr":["«System Design Labs","Votre service de traitement des commandes fonctionne sur SQS.","Tu dois gérer cette contre-pression.","publier","sondage","wad / écrire","« 4 000 commandes/en","En aval","Producteurs","«Amazon SQS","Consommateurs","Base de données","(Service de commande)","(Lambda /EC2 Travailleurs)","Définir avis","Défaillances de timeout et d'itinéraire","«Échelle horizontale des consommateurs — ajouter plus","Fonctions Lambda / EC2 à mâcher","à une file d'attente de lettres mortes pour se protéger","par le biais du backlog plus rapidement.","Des pilules empoisonnées.","Producteurs de limite de taux à la source","‘Switch to SQS delay queues — defer","un seau à jetons ou une fenêtre coulissante à coiffer","message vi","Lity pour étaler la livraison","la vitesse à laquelle les messages entrent dans la file d'attente.","et réduire la pression des consommateurs."]}},{"kind":"p","page":103,"text":{"en":"Your order processing service runs on SQS.","fr":"Votre service de traitement des commandes s’appuie sur SQS."}},{"kind":"p","page":103,"text":{"en":"Normal load: 200 orders/min. Consumers keep up fine.","fr":"Charge normale : 200 commandes/min. Les consommateurs suivent sans difficulté."}},{"kind":"p","page":103,"text":{"en":"Then Black Friday hits. Producers start pushing 4,000 orders/min. Queue depth climbs to 80,000 messages in 20 minutes. Your downstream DB is at 95% CPU. Consumers are falling behind and you're watching the queue grow in real time.","fr":"Arrive le Black Friday. Les producteurs montent à 4 000 commandes/min. En 20 minutes, la file atteint 80 000 messages. La base de données en aval tourne à 95 % de CPU. Les consommateurs prennent du retard et la file grossit sous vos yeux."}},{"kind":"p","page":103,"text":{"en":"You need to handle this backpressure. What do you do?","fr":"Vous devez gérer la contre-pression. Que faites-vous ?"}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":103,"text":{"en":"Scale consumers horizontally — add more Lambda functions / EC2 workers to chew through the backlog faster.","fr":"Mettre les consommateurs à l’échelle horizontalement : ajouter des fonctions Lambda ou des workers EC2 pour résorber le retard plus rapidement."}}]},{"letter":"B","blocks":[{"kind":"p","page":103,"text":{"en":"Set a visibility timeout and route failures to a dead-letter queue to protect against poison pills.","fr":"Configurer un délai d’invisibilité et envoyer les messages en échec vers une file de rejets, afin qu’un message impossible à traiter ne passe pas en boucle."}}]},{"letter":"C","blocks":[{"kind":"p","page":103,"text":{"en":"Rate-limit producers at the source — use a token bucket or sliding window to cap how fast messages enter the queue.","fr":"Limiter le débit des producteurs à la source : utiliser un seau à jetons ou une fenêtre glissante pour plafonner le rythme d’arrivée des messages dans la file."}}]},{"letter":"D","blocks":[{"kind":"p","page":103,"text":{"en":"Switch to SQS delay queues — defer message visibility to spread out delivery and reduce consumer pressure.","fr":"Passer aux files différées de SQS : retarder la visibilité des messages pour étaler leur livraison et soulager les consommateurs."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"figure","page":104,"id":"104-03","width":800,"height":450,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["‘TOP BAND (user path, fast)","submit order","Order Service","User","write","succes (stat) @","Orders DB","write","BOTTOM BAND (event pat, throttled)","roti)","ix","Event Relay","DC / poll","Consumers","‘Amazon SQS","Lambda /EC2","Downstream DB","@ Tre ses ok comes rom the DB wit net the queve Trot the enter, not the checkout"],"fr":["‘TOP BAND (chemin d’accès utilisateur, rapide)","Soumettre une commande","Service de commande","Utilisateur","écrire","Succès (stat)","Commandes DB","écrire","BANDE À BOUTEILLE (événement pat, étranglé)","roti)","ix","Relais événementiel","DC / sondage","Consommateurs","«Amazon SQS","Lambda /EC2","Downstream DB","Tre ses ok vient rom la DB wit net la queve Trot l'entrée, pas la caisse"]}},{"kind":"p","page":104,"text":{"en":"Why C wins, and why it doesn't wreck UX","fr":"Pourquoi C fonctionne sans dégrader l’expérience utilisateur"}},{"kind":"p","page":104,"text":{"en":"The queue grows because the producer is winning the race. 4,000 in, 200 out. You can scale consumers all day and that gap won't close on its own, especially with the DB already sitting at 95% CPU.","fr":"La file grossit parce que le producteur émet plus vite que le consommateur ne traite : 4 000 entrées pour 200 sorties. Ajouter des consommateurs ne suffira pas à combler cet écart, surtout avec une base déjà à 95 % de CPU."}},{"kind":"p","page":104,"text":{"en":"The fix is upstream. Rate-limit the producer with a token bucket or sliding window. In AWS that's API Gateway usage plans, Lambda reserved concurrency, or throttle middleware inside the service. Queue depth stabilizes, consumers catch up at their natural pace, and the DB stops cooking.","fr":"Intervenez en amont. Limitez le débit du producteur avec un seau à jetons ou une fenêtre glissante. Sur AWS, vous pouvez utiliser les plans d’utilisation d’API Gateway, la concurrence réservée de Lambda ou un middleware de limitation dans le service. La taille de la file se stabilise, les consommateurs rattrapent leur retard à leur rythme et la pression sur la base retombe."}},{"kind":"p","page":104,"text":{"en":"The mental model: slow the tap, don't just widen the drain.","fr":"Imaginez un évier : réduisez le débit du robinet au lieu d’agrandir seulement l’évacuation."}},{"kind":"p","page":104,"text":{"en":"Now the part the diagram glossed over: the \"producer\" isn't your user.","fr":"Le schéma passe vite sur un point important : le « producteur » n’est pas votre utilisateur."}},{"kind":"p","page":104,"text":{"en":"In most real systems the order flow is decoupled. A user submits an order, it's written to the DB, and they get their success response right away. A separate processor then reads those events (polling or CDC) and emits them to the queue. That emitter is the producer you throttle.","fr":"Dans la plupart des systèmes, la prise de commande et le traitement sont découplés. Un utilisateur passe une commande, elle est écrite en base et l’utilisateur reçoit aussitôt une confirmation. Un autre processus récupère ensuite les événements, par polling ou CDC, et les publie dans la file. C’est cet émetteur dont vous limitez le débit."}},{"kind":"p","page":104,"text":{"en":"So rate-limiting never touches checkout. The user already has their ack from the write. You're capping how fast events flow into the queue, not how fast users can order. UX stays intact; the queue just stops outrunning your consumers.","fr":"La limitation n’intervient donc jamais au paiement. L’utilisateur a déjà reçu un accusé de réception de l’écriture. Vous plafonnez la vitesse d’arrivée des événements dans la file, tandis que les utilisateurs continuent à passer commande normalement. L’expérience utilisateur reste intacte et les consommateurs peuvent suivre."}},{"kind":"p","page":105,"text":{"en":"That's what backpressure actually is: the downstream system telling the upstream to slow down. The queue depth is the signal. You react to it upstream.","fr":"C’est la logique de la contre-pression : l’aval indique à l’amont qu’il doit ralentir. La taille de la file sert de signal, et l’action se prend en amont."}}],[{"kind":"p","page":105,"text":{"en":"Why A is the trap answer (Scale consumers):","fr":"Pourquoi A est tentant (ajouter des consommateurs)"}},{"kind":"p","page":105,"text":{"en":"This is the instinct answer, and it's close enough to fool senior engineers.","fr":"C’est la réponse intuitive, assez plausible pour convaincre des ingénieurs expérimentés."}},{"kind":"p","page":105,"text":{"en":"Yes, more consumers means more throughput. But you're treating a rate mismatch as a capacity problem. If your producer can always generate faster than your consumers can process — and on Black Friday it can — you're in an arms race you can't win. You spin up 10x Lambda functions, hit DynamoDB write throughput limits, hammer your RDS connection pool, and the queue still grows. Just slower, and now your infra bill doubled.","fr":"Ajouter des consommateurs augmente le débit. Mais le problème vient du déséquilibre entre les deux débits, que vous traitez comme un manque de capacité. Si le producteur peut toujours émettre plus vite que les consommateurs ne traitent, comme le jour du Black Friday, vous ne rattraperez jamais le retard en ajoutant des instances. Vous lancez dix fois plus de fonctions Lambda, atteignez les limites d’écriture de DynamoDB, saturez le pool de connexions RDS, et la file continue de grossir. Plus lentement, avec une facture d’infrastructure qui a doublé."}},{"kind":"p","page":105,"text":{"en":"Consumer scaling works when your bottleneck is compute. It doesn't work when the problem is unbounded producer rate.","fr":"Ajouter des consommateurs fonctionne quand le calcul est le goulot d’étranglement. Cela ne suffit pas lorsque le débit du producteur est sans limite."}}],[{"kind":"p","page":105,"text":{"en":"Why B is wrong (Visibility timeout + DLQ):","fr":"Pourquoi écarter B (délai d’invisibilité et DLQ)"}},{"kind":"p","page":105,"text":{"en":"This is failure handling, not backpressure.","fr":"Ces mécanismes traitent les échecs. La contre-pression répond à un autre problème."}},{"kind":"p","page":105,"text":{"en":"DLQ catches poison pills — messages that fail processing repeatedly and would otherwise loop forever. Visibility timeout controls how long a message stays invisible after a consumer picks it up (preventing double-processing). Neither of these slows the producer or reduces queue depth growth.","fr":"Une DLQ reçoit les messages dont le traitement échoue systématiquement et qui tourneraient sinon en boucle. Le délai d’invisibilité détermine le temps pendant lequel un message pris en charge est masqué aux autres consommateurs, afin de prévenir un double traitement. Aucun des deux mécanismes ne ralentit le producteur ni la croissance de la file."}},{"kind":"p","page":105,"text":{"en":"Mixing up backpressure with retry/error handling is one of the most common architecture confusions I see. They solve completely different problems.","fr":"Confondre contre-pression, nouvelles tentatives et gestion des erreurs est fréquent en architecture. Ces mécanismes répondent à des besoins différents."}}],[{"kind":"p","page":105,"text":{"en":"Why D is wrong (SQS delay queues):","fr":"Pourquoi écarter D (files différées SQS)"}},{"kind":"p","page":105,"text":{"en":"Delay queues defer message visibility, not message creation. Your producer still pushes 4,000 msg/min. Messages pile up invisibly, then become visible in bursts when the","fr":"Les files différées retardent la visibilité des messages, tandis que le producteur continue d’en créer 4 000 par minute. Les messages s’accumulent sans être visibles."}},{"kind":"p","page":105,"text":{"en":"delay expires. You haven't reduced backpressure — you've deferred it and made the delivery pattern spikier.","fr":"À l’expiration du délai, ils deviennent visibles par rafales. Vous avez reporté la pression et rendu la livraison plus irrégulière."}},{"kind":"p","page":105,"text":{"en":"This is like covering a flooding sink with a lid and calling it fixed. The water is still rising....","fr":"C’est comme poser un couvercle sur un évier qui déborde : l’eau continue de monter."}}]]},{"day":26,"title":{"en":"Write-Path Cache Consistency","fr":"Préserver la cohérence du cache lors des écritures"},"pages":[106,109],"topic":"data","correct":"D","scenario":[{"kind":"figure","page":106,"id":"106-02","width":800,"height":421,"alt":{"en":"Day 26 featured","fr":"Illustration de la question du jour 26"},"transcript":{"en":["nLab","ur cache a","DB are out of sy!","What do you","inge’","Read","Redis","(Cache)","{= Manual invalidate","HTTP","(Cache Key)","Client","Requests","API","Write","(80 req/s)","PostgreSQL","(Source of Truth)","Write-through — write to cache and DB","Write-behind — write to cache first,","together, synchronously. Cache is always","async flush to DB. Fast writes, eventual","warm, always consistent.","persistence.","Write-around — skip the cache on writes","Dual-write with an outbox — write to DB +","entirely. Write to DB only. Cache fills on","publish an event. A consumer updates","next read miss.","the cache from the event log."],"fr":["nLab","ur cache a","Les DB sont hors du sy!","Qu'est-ce que vous","inge»","Lire","Redis","(Cache)","Invalidation manuelle","HTTP","(Cache-clé)","Client","Demandes","API","Ecrire","(80 req/s)","PostgreSQL","(Source de la vérité)","Write-through — écrire dans le cache et la base de données","Write-behind — écrire d'abord dans le cache","ensemble, synchrone. Le cache est toujours","async flush à DB. Fast écrit, éventuellement","Chaleureux, toujours cohérent.","Persistance.","Write-around — ignore le cache sur les écritures","Dual-write avec une outbox — écrire à DB +","entièrement. Écrivez à DB seulement. Cache remplit sur","publier un événement. Une mise à jour pour les consommateurs","Prochaine lecture Miss.","le cache du journal des événements."]}},{"kind":"p","page":106,"text":{"en":"Your cache and DB are out of sync. Again.","fr":"Encore une fois, le cache et la base ne sont plus synchronisés."}},{"kind":"p","page":106,"text":{"en":"A user updates their profile. The cache still serves the old name for the next 10 minutes. Support gets a ticket. You patch it with a cache flush. It happens again next week.","fr":"Un utilisateur modifie son profil. Pendant dix minutes, le cache continue de renvoyer son ancien nom. Le support reçoit un ticket. Vous videz le cache. Le problème revient la semaine suivante."}},{"kind":"p","page":106,"text":{"en":"You're asked to fix write consistency before it becomes a customer-facing incident.","fr":"Vous devez fiabiliser les écritures avant qu’un incident plus grave ne touche les clients."}},{"kind":"p","page":106,"text":{"en":"Here's the setup:","fr":"Voici la configuration."}},{"kind":"p","page":106,"text":{"en":"NestJS API → PostgreSQL (source of truth) + Redis (cache)","fr":"API NestJS → PostgreSQL (source de vérité) + Redis (cache)"}},{"kind":"p","page":106,"text":{"en":"~600 req/s reads, ~80 req/s writes at peak","fr":"Environ 600 lectures/s et 80 écritures/s en pointe"}},{"kind":"p","page":106,"text":{"en":"Current pattern: write to DB, manually invalidate cache key on success","fr":"Approche actuelle : écrire en base, puis invalider explicitement la clé de cache si l’écriture réussit."}},{"kind":"p","page":106,"text":{"en":"3 incidents this month — all traced back to stale cache after writes","fr":"Trois incidents ce mois-ci, tous dus à une valeur de cache obsolète après une écriture."}},{"kind":"p","page":106,"text":{"en":"You need a strategy that survives race conditions, retries, and partial failures","fr":"La stratégie doit résister aux conditions de concurrence, aux nouvelles tentatives et aux échecs partiels."}},{"kind":"p","page":106,"text":{"en":"What do you change?","fr":"Quel changement apportez-vous ?"}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":106,"text":{"en":"Write-through — write to cache and DB together, synchronously. Cache is always warm, always consistent.","fr":"Write-through : écrire dans le cache et en base de façon synchrone. Le cache reste alimenté et cohérent."}}]},{"letter":"B","blocks":[{"kind":"p","page":107,"text":{"en":"Write-behind — write to cache first, async flush to DB. Fast writes, eventual persistence.","fr":"Write-behind : écrire d’abord dans le cache, puis répercuter l’écriture en base de façon asynchrone. Les écritures répondent vite et la persistance se fait plus tard."}}]},{"letter":"C","blocks":[{"kind":"p","page":107,"text":{"en":"Write-around — skip the cache on writes entirely. Write to DB only. Cache fills on next read miss.","fr":"Write-around : écrire uniquement en base, en contournant le cache. Le cache se remplit à la prochaine lecture qui ne trouve pas la donnée."}}]},{"letter":"D","blocks":[{"kind":"p","page":107,"text":{"en":"Dual-write with an outbox — write to DB + publish an event. A consumer updates the cache from the event log.","fr":"Double écriture avec outbox : écrire en base et publier un événement. Un consommateur met à jour le cache à partir du journal d’événements."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"figure","page":108,"id":"108-03","width":800,"height":533,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["ANSWE","WRITE WITH AN OUTBOX #","abs","HOW IT WORKS","© Eliminates the dual-rit race condition:","[DB write and outbox event rein the","same atomic transaction,","come","ite","© The cache update becomes a consequence","ofthe DB write, nota sibling operation.","® ge |","‘Gent","PI","Reds","© Survives crashes, reties, and partial","Coe","(coche)","failures,","@ Provides replay: if Reiss down and","comes back, re-process the outbox","tases ears stay he oe","and eatehup.","‘DUAL-WRITE WITH AN OUTBOX","pds the cach fom the veto","ry","© Fat bt dangerous","(© Sete sale cache by ot ting","(© tthediis down, doyou eck heuer?","Dash ot wes gore","\"ave made Rei shard dependency","© Survives crushes eis, nd","your wt pth.","© Reptyabe and eventual consistent"],"fr":["ANSWE","ÉCRIVEZ AVEC UN OUTBOX","abs","Comment ça marche","Élimine la condition de course à double rit:","[DB write et outbox event","même transaction atomique,","venir","ite","La mise à jour du cache devient une conséquence","de l'écriture DB, nota opération sœur.","ge","«Gent","PI","Rouges","Survit aux accidents, aux reties et aux partiels","Coe","(coche)","les échecs,","Fournit la rediffusion : si Reiss est en panne et","revient, re-traite la boîte d'envoi","Tases Oreilles rester il oe","et Eatehup.","«DOUBLE-ÉCRIRE AVEC UNE BO — TE","pds le cach fom le veto","ry","Fat bt dangereux","( — Cache de vente Sete par ot ting","( — a tombe, tu veux bien ?","Dash ot wes gore","\"Rei shard est devenu dépendant.","Survives crushes eis, nd","Votre pth.","Reptyabe et éventuellement cohérent"]}},{"kind":"p","page":108,"text":{"en":"Answer: D — Dual-write with an outbox","fr":"Réponse : D — Double écriture avec outbox"}},{"kind":"p","page":108,"text":{"en":"The core problem isn't \"which order to write in\" — it's \"what happens when one write succeeds and the other fails?\"","fr":"Posez la question en termes d’échec partiel : que se passe-t-il si l’une des écritures réussit et que l’autre échoue ?"}},{"kind":"p","page":108,"text":{"en":"Why D wins: Every naive dual-write has the same race condition: write to DB, write to cache, crash between the two → stale cache indefinitely. The outbox makes the cache update a consequence of the DB write, not a sibling operation. One atomic DB transaction: record + outbox event. A consumer updates Redis from the event. Also gives you replay — if Redis goes down and comes back, re-process the outbox.","fr":"Pourquoi D fonctionne : toute double écriture naïve a la même faille. Si le processus s’arrête entre l’écriture en base et celle dans le cache, le cache peut rester obsolète indéfiniment. Avec l’outbox, la mise à jour du cache découle de l’écriture en base. Une seule transaction atomique enregistre la donnée et l’événement dans l’outbox. Un consommateur met à jour Redis à partir de cet événement. Et vous pouvez rejouer les événements : si Redis tombe puis redémarre, traitez à nouveau l’outbox."}}],[{"kind":"p","page":108,"text":{"en":"Why A fails (Write-through): Looks safest. Is the most dangerous at scale. Two synchronous I/Os on every write. If Redis is slow, your write API is slow. If Redis is down, do you block the user? You've made Redis a hard dependency of your write path.","fr":"Pourquoi A échoue (write-through) : cette option paraît sûre, mais elle est risquée à grande échelle. Chaque écriture requiert deux entrées-sorties synchrones. Si Redis ralentit, l’API d’écriture ralentit avec lui. Si Redis tombe, devez-vous bloquer l’utilisateur ? Redis devient une dépendance incontournable du chemin d’écriture."}}],[{"kind":"p","page":109,"text":{"en":"Why B fails (Write-behind): Fast, but: if the async worker crashes before DB flush, that write is gone. Acceptable for analytics counters. Never acceptable for a source of truth.","fr":"Pourquoi B échoue (write-behind) : l’écriture répond vite, mais si le worker asynchrone tombe avant de répercuter la modification en base, celle-ci est perdue. C’est acceptable pour des compteurs analytiques, pas pour une source de vérité."}}],[{"kind":"p","page":109,"text":{"en":"Why C is a partial fix (Write-around): Solves stale cache by not writing to cache at all. Clean — but read-after-write is broken under replica lag, and high-write workloads tank your cache hit rate.","fr":"Pourquoi C ne règle qu’une partie du problème (write-around) : en n’écrivant jamais dans le cache, vous évitez d’y inscrire une valeur périmée. Mais le retard de réplication peut compromettre la lecture après écriture, et une charge dominée par les écritures fait chuter le taux de succès du cache."}}]]},{"day":27,"title":{"en":"Keeping an LLM’s Answers Up to Date","fr":"Maintenir à jour les réponses d’un LLM"},"pages":[110,113],"topic":"ai","correct":"A","scenario":[{"kind":"figure","page":110,"id":"110-02","width":800,"height":421,"alt":{"en":"Day 27 featured","fr":"Illustration de la question du jour 27"},"transcript":{"en":["System Design Labs","Your LLM answers are w","ng.","What do you do?","Ask","Forward","Retrieve","Knowledge","Updated 1","{Now pricing new","ures, dprecated |","SS","Context","‘tows","Users:","NestJS API","Openal GPT-4","PostgreSQL","(Product Knowledge Base)","RAG — embed your knowledge base,","Fine-tune the base model — train GPT-4","retrieve relevant chunks at query time,","(or open-source equivalent) on your","inject into context. Model stays the same,","product docs. The model internalizes,","knowledge is always fresh,","your domain.","Fine-tune + RAG hybrid —","tune for","Prompt engineering only — detailed","style/tone/domain fluency, RAG for","system prompt + few-shot examples.","factual grounding. Best of both worlds","[No infra, no training, just better instructions."],"fr":["System Design Labs","Vos réponses LLM sont w","ng.","Qu'est-ce que tu fais ?","Demandez","En avant","Récupère","Connaissances","Mise à jour 1","Maintenant prix nouveau","ures, dprécisées","SS","Contexte","«remorques","Utilisateurs :","API NestJS","GPT-4 ouvert","PostgreSQL","(Base de connaissances produit)","RAG — intègre votre base de connaissances,","Ajuster le modèle de base — train GPT-4","récupérer les morceaux pertinents au moment de la requête,","(ou équivalent open-source) sur votre","injecter dans le contexte. Le modèle reste le même,","Le modèle intériorise, le modèle internalise,","La connaissance est toujours fraîche,","votre domaine.","Réglage fin + RAG hybride","tune pour","Ingénierie rapide seulement - détaillée","style/ton/domaine fluency, RAG pour","system prompt + quelques exemples.","base factuelle. Le meilleur des deux mondes","[Pas d'infra, pas de formation, juste de meilleures instructions."]}},{"kind":"p","page":110,"text":{"en":"Your LLM answers are wrong. Not hallucination-wrong — outdated-wrong.","fr":"Votre LLM répond à côté. Ses réponses sont obsolètes, même lorsqu’il n’hallucine pas."}},{"kind":"p","page":110,"text":{"en":"You shipped a customer support bot on GPT-4. It's trained through early 2024. Your product changed 14 times since then. Every week, users get answers that were accurate 8 months ago and are flat-out wrong today.","fr":"Vous avez déployé un bot de support client sur GPT-4, dont l’entraînement couvre la période allant jusqu’au début de 2024. Depuis, votre produit a changé 14 fois. Chaque semaine, des utilisateurs reçoivent des réponses qui étaient justes il y a huit mois et sont fausses aujourd’hui."}},{"kind":"p","page":110,"text":{"en":"The team is debating the fix.","fr":"L’équipe discute de la façon de corriger le problème."}},{"kind":"p","page":110,"text":{"en":"Here's the setup:","fr":"Voici la configuration."}},{"kind":"p","page":110,"text":{"en":"NestJS API → OpenAI GPT-4 + PostgreSQL (product knowledge base)","fr":"API NestJS → OpenAI GPT-4 + PostgreSQL (base de connaissances produit)"}},{"kind":"p","page":110,"text":{"en":"~2,000 support queries/day, 15% return wrong answers tied to stale knowledge","fr":"Environ 2 000 demandes au support par jour. Dans 15 % des cas, la réponse est erronée à cause de connaissances obsolètes."}},{"kind":"p","page":110,"text":{"en":"Knowledge base updates weekly — new pricing, new features, deprecated flows","fr":"La base de connaissances évolue chaque semaine : nouveaux tarifs, nouvelles fonctionnalités et anciens parcours abandonnés."}},{"kind":"p","page":110,"text":{"en":"Budget: mid-size startup, not training custom models from scratch","fr":"Budget : celui d’une startup de taille intermédiaire, sans les moyens d’entraîner un modèle maison à partir de zéro."}},{"kind":"p","page":110,"text":{"en":"You need accurate, up-to-date answers without re-training on every product update","fr":"Vous voulez des réponses exactes et à jour sans réentraîner le modèle à chaque évolution du produit."}},{"kind":"p","page":110,"text":{"en":"What do you do?","fr":"Que faites-vous ?"}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":110,"text":{"en":"RAG — embed your knowledge base, retrieve relevant chunks at query time, inject into context. Model stays the same, knowledge is always fresh.","fr":"RAG : créer des embeddings de la base de connaissances, retrouver les passages pertinents au moment de la requête et les ajouter au contexte. Le modèle ne change pas et ses sources restent à jour."}}]},{"letter":"B","blocks":[{"kind":"p","page":111,"text":{"en":"Fine-tune the base model — train GPT-4 (or open-source equivalent) on your product docs. The model internalizes your domain.","fr":"Affiner le modèle de base : poursuivre l’entraînement de GPT-4 ou d’un équivalent open source sur votre documentation produit. Le modèle assimile les connaissances du domaine."}}]},{"letter":"C","blocks":[{"kind":"p","page":111,"text":{"en":"Fine-tune + RAG hybrid — fine-tune for style/tone/domain fluency, RAG for factual grounding. Best of both worlds.","fr":"Approche hybride : recourir au fine-tuning pour le style, le ton et la maîtrise du vocabulaire métier, puis au RAG pour fonder les réponses sur des faits."}}]},{"letter":"D","blocks":[{"kind":"p","page":111,"text":{"en":"Prompt engineering only — detailed system prompt + few-shot examples. No infra, no training, just better instructions.","fr":"Se limiter à l’ingénierie des prompts : utiliser un prompt système détaillé et quelques exemples (few-shot). Il suffit de meilleures instructions, sans infrastructure ni entraînement supplémentaire."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"figure","page":112,"id":"112-03","width":800,"height":533,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["System Design Lab","Answer: A — RAG","Separate knowledge from reasoning. Keep the model frozen.","‘Solves the real problem","No retraining cost","Knowledge is decoupled","Pipeline, not model problem","‘Th iesue is feshness, not","Mode stays frozen","Your knowiedge fives ina","‘You've tured this into a","No fine-tuning eyes,","data pipeline problem —","understanding, RAG gives","HO vector store Update r-erbed,","joes","the model up-to-date facts","no redeployment.","done, Bot knows immediatly","‘something every team","aeady knows","How RAG Works at Runtime","Embed query","Retive top-K","Model reasons over","relevant chunks","‘content","frech context,","‘newer","Vector Store","Prompt + Context","en eran","Whats our","eve gn Fw","Pro Kowladge see)","Aways rsh","AS","‘Accurate & grounded","Engineering leverage","Why RAG","Update docs","re-embed","No taining ri","Answers ae grounded in","ai","No GPU hours","‘embedding, etre","is the right call","Ne cepoymerteces.","Bottom i","date,","rat","sin","Fic freshness atthe data lay","it"],"fr":["Laboratoire de conception système","Réponse: A — RAG","Séparez la connaissance du raisonnement. Gardez le modèle gelé.","« Résoudre le vrai problème","Pas de frais de recyclage","La connaissance est découplée","Pipeline, pas problème de modèle","« La feshness, c’est","Le mode reste gelé","Vos cinq connaissances ina","« Vous avez transformé cela en un","Pas d'yeux fins,","problème de pipeline de données","comprendre, RAG donne","HO vector store Mise à jour r-erbed,","joes","Le modèle des faits à jour","Pas de redéploiement.","fait, Bot sait immédiatement","« Quelque chose que chaque équipe","Aeady sait","Comment RAG fonctionne à l'exécution","Incorporer une requête","Retive top-K","Raisons modèles plus","les morceaux pertinents","«contenu","contexte frech,","«plus récent","Vector Store","Prompt + Contexte","en eran","C'est notre","FW","Pro Kowladge voir)","Aways rsh","AS","« Précis & ancré","Effet de levier","Pourquoi RAG","Mise à jour docs","re-embed","Sans contamination ri","Réponses fondées sur","ai","Pas d'heures GPU","«embedding, etre","est le bon appel","Ne cepoymerteces.","Bas i","date,","rat","sin","Fic fraîcheur à la base de données","il"]}},{"kind":"p","page":112,"text":{"en":"Answer: A — RAG","fr":"Réponse : A — RAG"}},{"kind":"p","page":112,"text":{"en":"The problem is freshness — the model doesn't know what changed, not that it doesn't understand your domain.","fr":"Le modèle comprend votre domaine. Il lui manque les informations sur ce qui a changé."}},{"kind":"p","page":112,"text":{"en":"RAG separates knowledge from reasoning. The model stays frozen (no retraining cost, no deployment cycle). Your knowledge base lives in a vector store — update a doc, re-embed it, done. New pricing ships Monday, your bot knows it by Monday.","fr":"Le RAG sépare les connaissances du raisonnement. Le modèle reste figé, sans coût de réentraînement ni nouveau cycle de déploiement. La base de connaissances est indexée dans une base vectorielle. Lorsqu’un document change, recalculez son embedding. Si les nouveaux tarifs entrent en vigueur lundi, le bot en dispose dès lundi."}},{"kind":"p","page":112,"text":{"en":"At runtime: user asks → embed query → retrieve top-K relevant chunks → inject into context → model reasons over fresh, accurate content.","fr":"À l’exécution : l’utilisateur pose une question → calculer son embedding → récupérer les k passages les plus pertinents → les ajouter au contexte → laisser le modèle raisonner à partir de contenu exact et récent."}},{"kind":"p","page":112,"text":{"en":"You've turned a model problem into a data pipeline problem. Every engineering team already knows how to solve data pipelines.","fr":"Ce qui semblait demander un changement de modèle relève désormais du pipeline de données, un problème que les équipes d’ingénierie savent déjà résoudre."}}],[{"kind":"p","page":113,"text":{"en":"B — Fine-tuning (the trap answer)","fr":"B — Fine-tuning (choix trompeur)"}},{"kind":"p","page":113,"text":{"en":"Feels like the obvious upgrade. Makes the problem worse.","fr":"Le fine-tuning semble le moyen évident d’améliorer le modèle. Ici, il aggrave le problème."}},{"kind":"p","page":113,"text":{"en":"Fine-tuning bakes knowledge into weights. Those weights are static until you retrain. Weekly product updates = weekly retraining at real cost (time + money) + real risk of catastrophic forgetting (new training can degrade recall of old content if not carefully managed).","fr":"Le fine-tuning encode les connaissances dans les poids, qui restent ensuite fixes jusqu’au prochain entraînement. Des mises à jour produit hebdomadaires imposeraient un entraînement hebdomadaire, coûteux en temps et en argent. Elles introduisent aussi un risque d’oubli catastrophique : faute de précautions, un nouveau cycle d’entraînement peut réduire la capacité du modèle à restituer les contenus appris auparavant."}},{"kind":"p","page":113,"text":{"en":"Fine-tuning is the right answer for behavioral changes — tone, format, domain fluency, internal jargon. It teaches the model how to behave, not what to know. Wrong tool for a freshness problem.","fr":"Le fine-tuning convient aux changements de comportement : ton, format, aisance dans le domaine et jargon interne. Il apprend au modèle comment répondre, et n’est pas adapté à l’actualisation régulière des connaissances."}}],[{"kind":"p","page":113,"text":{"en":"C — Fine-tune + RAG hybrid (overkill)","fr":"C — Combiner fine-tuning et RAG (trop lourd à ce stade)"}},{"kind":"p","page":113,"text":{"en":"Genuinely powerful architecture — but it's step 3, not step 1.","fr":"C’est une architecture puissante, à envisager après avoir établi les bases."}},{"kind":"p","page":113,"text":{"en":"You can't productively fine-tune for style until your factual grounding is solid first. The hybrid is what you reach for after you've shipped RAG cleanly and hit the ceiling of what retrieval alone can do.","fr":"Affiner le style apporte peu tant que les réponses ne s’appuient pas sur des sources fiables. L’approche hybride devient pertinente lorsqu’un RAG fonctionne déjà et que vous atteignez les limites de la recherche seule."}},{"kind":"p","page":113,"text":{"en":"For a startup with a 15% wrong-answer rate due to stale knowledge, shipping a hybrid is a 3-month project when a 2-week RAG implementation fixes the actual problem.","fr":"Pour une startup où 15 % des réponses sont erronées à cause de connaissances périmées, l’approche hybride représente un projet de trois mois. Un RAG réalisable en deux semaines résout le problème."}}],[{"kind":"p","page":113,"text":{"en":"D — Prompt engineering only (hits the ceiling fast)","fr":"D — Se limiter à l’ingénierie des prompts (vite insuffisant)"}},{"kind":"p","page":113,"text":{"en":"Fastest to ship, first to break.","fr":"C’est l’option la plus rapide à mettre en production et celle qui montre le plus vite ses limites."}},{"kind":"p","page":113,"text":{"en":"A detailed system prompt can set tone and format. It cannot inject 400 pages of updated product docs without hitting token limits — and manually picking which docs to include is just RAG without the retrieval infrastructure.","fr":"Un prompt système détaillé peut fixer un ton et un format. Il ne peut pas accueillir 400 pages de documentation produit à jour sans dépasser la limite de tokens. Sélectionner manuellement les documents à joindre revient à faire du RAG sans infrastructure de recherche."}},{"kind":"p","page":113,"text":{"en":"Prompt engineering works when the model already knows what it needs to know. It can't fix a knowledge gap.","fr":"L’ingénierie des prompts fonctionne quand le modèle détient déjà les connaissances nécessaires. Elle ne suffit pas à combler un manque de connaissances."}}]]},{"day":28,"title":{"en":"Choosing a Vector Store for Semantic Search","fr":"Choisir une base vectorielle pour la recherche sémantique"},"pages":[114,117],"topic":"ai","correct":"D","scenario":[{"kind":"figure","page":114,"id":"114-02","width":800,"height":420,"alt":{"en":"Day 28 featured","fr":"Illustration de la question du jour 28"},"transcript":{"en":["‘System Design Labs","You’re building a semantic search feature","for a B2B SaaS product.","Vector","Query","Search","Fetch","(Natural","Results","Language)","(Top «)","(Ds) |","Data","Vector","Web / App","Backend","Database","(Metadata &","Redis","(1536-4)","Content)","(Caching)","Store /Update","Embeddings","pgvector extension on your existing PostgreSQL —","Pinecone — fully managed vector database,","store embeddings in a new column, query with <->","serverless tier, no infra to run.","cosine similarity","Weaviate — open-source vector DB, self-hosted","Qdrant — open-source vector DB, Rust-based,","on Kubernetes, full control over indexing.","self-hosted or cloud, optimized for high-throughput","filtering."],"fr":["«System Design Labs","Vous créez une fonction de recherche sémantique","pour un produit SaaS B2B.","Vecteur","Requête","Rechercher","Récupère","(Naturel","Résultats","Langue)","(Top «)","(Ds)","Données","Vecteur","Web / App","Backend","Base de données","(Métadonnées &","Redis","(1536-4)","Contenu)","(Cachage)","Stocker / Mettre à jour","Incorporations","extension pgvector sur votre PostgreSQL — existant","Pinecone — base de données vectorielles entièrement gérée,","stocker les incorporations dans une nouvelle colonne, requête avec — ->","serverless tier, pas d'infra à exécuter.","cosinus similarité","Weaviate — vecteur open-source DB, auto-hébergé","Qdrant — vecteur open-source DB, basé sur la rouille,","sur Kubernetes, contrôle total de l'indexation.","Auto-hébergé ou cloud, optimisé pour un haut débit","filtrage."]}},{"kind":"p","page":114,"text":{"en":"You're building a semantic search feature for a B2B SaaS product.","fr":"Vous développez une fonction de recherche sémantique pour un SaaS B2B."}},{"kind":"p","page":114,"text":{"en":"The corpus: 4 million support articles, docs, and user-generated tickets. Users type natural language queries. They expect Google-quality results — not keyword matching.","fr":"Le corpus regroupe quatre millions d’articles d’assistance, de documents et de tickets créés par les utilisateurs. Les requêtes sont formulées en langage naturel. Les utilisateurs s’attendent à des résultats de la qualité de Google, au-delà d’une simple correspondance de mots-clés."}},{"kind":"p","page":114,"text":{"en":"Your current stack: PostgreSQL 15, Redis, and a Node.js backend. The search team says ILIKE and pg_trgm aren't cutting it. Embeddings are the answer. Now you need a place to store and query 1536-dimensional vectors (OpenAI ada-002) at <100ms p99.","fr":"Vous utilisez PostgreSQL 15, Redis et un backend Node.js. Pour l’équipe de recherche, ILIKE et pg_trgm ne suffisent plus. Elle mise sur les embeddings. Il faut maintenant stocker et interroger des vecteurs de 1 536 dimensions produits par OpenAI ada-002, avec un p99 inférieur à 100 ms."}},{"kind":"p","page":114,"text":{"en":"4 million rows. ~24GB of raw embeddings. Query volume: 300 req/s with weekend spikes to 900 req/s.","fr":"Quatre millions de lignes. Environ 24 Go d’embeddings bruts. Le débit est de 300 requêtes/s et peut atteindre 900 requêtes/s le week-end."}},{"kind":"p","page":114,"text":{"en":"Where do you store and query those vectors?","fr":"Où stocker et interroger ces vecteurs ?"}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":114,"text":{"en":"pgvector extension on your existing PostgreSQL — store embeddings in a new column, query with <-> cosine similarity.","fr":"Extension pgvector sur votre instance PostgreSQL actuelle : stocker les embeddings dans une nouvelle colonne et interroger avec <-> pour la similarité cosinus."}}]},{"letter":"B","blocks":[{"kind":"p","page":114,"text":{"en":"Pinecone — fully managed vector database, serverless tier, no infra to run.","fr":"Pinecone : base de données vectorielle entièrement managée, proposée en serverless, sans infrastructure à exploiter."}}]},{"letter":"C","blocks":[{"kind":"p","page":114,"text":{"en":"Weaviate — open-source vector DB, self-hosted on Kubernetes, full control over indexing.","fr":"Weaviate : base vectorielle open source, autohébergée sur Kubernetes, avec un contrôle complet de l’indexation."}}]},{"letter":"D","blocks":[{"kind":"p","page":115,"text":{"en":"Qdrant — open-source vector DB, Rust-based, self-hosted or cloud, optimized for high-throughput filtering.","fr":"Qdrant : base vectorielle open source écrite en Rust, autohébergée ou hébergée dans le cloud, optimisée pour filtrer à haut débit."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"figure","page":116,"id":"116-03","width":800,"height":533,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["‘System Design Labs","Why D wins:","Qdrant is the right fit","© Qdrant","Qdrant handles vector search + metadata","er in one pass.","Query","Vector Search","q Qdrant","Content","(Natural","+ Payload Filtor","Vector Database","Resuts","Lookup","(HNSW index)","(Top K)","(IDs + Scores)","PostgreSQL 15","Nodes","Redis","Web / App","Backend","(Motadata &","(Caching)","Content)","Index","Feng","(Rust Core)","Store / Update","Embeddings & Payloads","Rust cor","Ww latency and","Ina B2B product, users search","Self-hosted gives you full control","predictable memory under load,","within a workspace, tenant, or","‘over HNSW params (m,","‘At 300 req/s you need an index","product line — not globally","cf construction), memory","that handles concurrent ANN","Qdrant handles vector search +","mapping, and on-disk indexing —","‘queries without degrading —","metadata filter in one pas.","critical when your corpus grows:","drant’s HNSW implementation","Every other option forces post-","past RAM,","is tuned for this.","filtering, which blows up recall","and adds round-trips"],"fr":["«System Design Labs","Pourquoi retenir D :","Qdrant est le bon choix","Qdrant","Qdrant gère la recherche vectorielle + les métadonnées","en un seul passage.","Requête","Recherche de vecteur","q Qdrant","Contenu","(Naturel","+ Filtre de charge utile","Base de données vectorielles","Resuts","Recherche","(indice HNSW)","(Top K)","(ID + scores)","PostgreSQL 15","Noeuds","Redis","Web / App","Backend","(Motadata et","(Cachage)","Contenu)","Indice","Feng","(Rust Core)","Store / Mise à jour","Embeddings & Payloads","Rust cor","Latence et","Produit B2B Ina, recherche d'utilisateurs","Auto-hébergé vous donne le contrôle total","une mémoire prévisible sous charge,","dans un espace de travail, un locataire, ou","«sur les paramètres HNSW (m,","À 300 req/s, vous avez besoin d'un index","ligne de produits – pas globalement","cf construction), mémoire","qui gère simultanément ANN","Qdrant gère la recherche vectorielle +","mapping, et indexation sur disque","«Requêtes sans dégradation»","filtre de métadonnées dans un pas.","lorsque votre corpus grandit :","La mise en œuvre HNSW de drant","Toutes les autres options sont post-","RAM passé,","Il est accordé pour cela.","filtrage, qui fait exploser le rappel","et ajoute des allers-retours"]}},{"kind":"p","page":116,"text":{"en":"Why D wins (Qdrant):","fr":"Pourquoi choisir D (Qdrant)"}},{"kind":"p","page":116,"text":{"en":"Qdrant is purpose-built for exactly this workload. Rust core = low latency and predictable memory under load. At 300 req/s you need an index that handles concurrent ANN queries without degrading — Qdrant's HNSW implementation is tuned for this.","fr":"Qdrant est conçu pour cette charge de travail. Son cœur en Rust maintient une faible latence et une consommation mémoire prévisible sous charge. À 300 requêtes/s, l’index doit supporter des recherches ANN simultanées sans dégradation. L’implémentation HNSW de Qdrant est optimisée pour ce cas."}},{"kind":"p","page":116,"text":{"en":"The killer feature here is payload filtering. In a B2B product, users search within a workspace, tenant, or product line — not globally. Qdrant handles vector search + metadata filter in one pass. Every other option forces post-filtering, which blows up recall and adds round-trips.","fr":"L’atout décisif est le filtrage sur les métadonnées. Dans un produit B2B, les utilisateurs font leurs recherches dans un espace de travail, un tenant ou une gamme de produits. Qdrant combine la recherche vectorielle et le filtre de métadonnées en une seule passe. Les autres options imposent un filtrage après la recherche, ce qui dégrade fortement le rappel et multiplie les allers-retours."}},{"kind":"p","page":116,"text":{"en":"Self-hosted gives you full control over HNSW params (m, ef_construction), memory mapping, and on-disk indexing — critical when your corpus grows past RAM.","fr":"L’autohébergement donne la main sur les paramètres HNSW (m, ef_construction), le mappage mémoire et l’indexation sur disque. C’est déterminant lorsque le corpus dépasse la RAM."}}],[{"kind":"p","page":117,"text":{"en":"Why A is the trap (pgvector):","fr":"Pourquoi A est tentant (pgvector)"}},{"kind":"p","page":117,"text":{"en":"pgvector is great for getting started — under ~500k vectors it's often the right call because you already own PostgreSQL. But at 4M rows and 300 req/s, the HNSW index runs inside Postgres's buffer pool, competing with your transactional workload. Latency goes non-linear under concurrency. VACUUM on a large embeddings table is painful.","fr":"pgvector convient bien pour démarrer. En dessous d’environ 500 000 vecteurs, c’est souvent un bon choix puisque vous disposez déjà de PostgreSQL. Mais à quatre millions de lignes et 300 requêtes/s, l’index HNSW utilise le pool de tampons de PostgreSQL et entre en concurrence avec la charge transactionnelle. Sous concurrence, la latence augmente de façon non linéaire. VACUUM devient coûteux sur une grande table d’embeddings."}},{"kind":"p","page":117,"text":{"en":"Rule of thumb: pgvector under 500k vectors + low concurrency = fine. Above that, you're borrowing against future pain.","fr":"Comme règle pratique, pgvector convient sous 500 000 vecteurs lorsque la concurrence est faible. Au-delà, vous risquez de reporter les difficultés opérationnelles."}}],[{"kind":"p","page":117,"text":{"en":"Why B loses (Pinecone):","fr":"Pourquoi écarter B (Pinecone)"}},{"kind":"p","page":117,"text":{"en":"Pinecone works and teams ship with it fast. But the cost model bites hard at 300 req/s sustained — serverless tier prices per query unit, you're looking at thousands of dollars/month. There's also proprietary lock-in: no standard wire protocol, so migrating means re-implementing your ingestion pipeline from scratch.","fr":"Pinecone fonctionne et permet aux équipes de livrer rapidement. Son modèle de tarification devient toutefois onéreux à 300 requêtes/s en continu : l’offre serverless facture par unité de requête, ce qui revient à plusieurs milliers de dollars par mois. Le protocole d’échange propriétaire crée aussi une dépendance au fournisseur. Migrer implique de réécrire le pipeline d’ingestion à partir de zéro."}},{"kind":"p","page":117,"text":{"en":"Right tool when: speed to market matters more than cost, and query volume is under ~50 req/s.","fr":"Ce choix convient si la rapidité de mise sur le marché prime sur le coût et si le trafic reste en dessous d’environ 50 requêtes/s."}}],[{"kind":"p","page":117,"text":{"en":"Why C loses (Weaviate):","fr":"Pourquoi écarter C (Weaviate)"}},{"kind":"p","page":117,"text":{"en":"Weaviate is solid with good hybrid search (BM25 + vector) and multi-modal support. But the Kubernetes footprint is heavier than Qdrant for this use case. For a team not already running K8s for their vector layer, the operational overhead is real. Weaviate shines for multi-modal search or semantic graph relationships — for pure dense vector search with filtering, Qdrant is leaner.","fr":"Weaviate est solide, avec une bonne recherche hybride (BM25 et vectorielle) et une prise en charge multimodale. Pour cet usage, son déploiement Kubernetes est plus lourd que celui de Qdrant. Une équipe qui n’exploite pas déjà Kubernetes pour sa couche vectorielle doit prévoir ce coût d’exploitation. Weaviate se distingue pour la recherche multimodale et les relations dans les graphes sémantiques. Pour une recherche vectorielle dense avec filtres, Qdrant est plus léger."}}]]},{"day":29,"title":{"en":"Coordinating a Multi-Agent Workflow","fr":"Orchestrer un workflow multi-agent"},"pages":[118,121],"topic":"ai","correct":"C","scenario":[{"kind":"figure","page":118,"id":"118-02","width":800,"height":420,"alt":{"en":"Day 29 featured","fr":"Illustration de la question du jour 29"},"transcript":{"en":["System Design Labs","You have an Al product with 4 specialized agents:","a Planner, a Researcher, a Coder, and a Reviewer.","submit","context","code","resuit","Request","User","Breaks","Researcher","Coder","Final","“he task","Implements","Timeouts","state Store","(Per Step)","Centralized orchestrator — one controller calls","Choreography via event bus — agents","‘each agent in sequence, owns retry logic,","Publish/subscribe to events, no central","state in a DB, times out per step individual","Controller, each agent triggers the next autonomously.","DAG-based execution — model the pipeline as a","Supervisor pattern — a meta-agent monitors all","directed acyclic graph, paralielize independent","others, detects failures, decides whether to retry,","steps, block only on real dependencies.","reroute, or escalate to a human."],"fr":["System Design Labs","Vous avez un produit Al avec 4 agents spécialisés :","un planificateur, un chercheur, un codeur et un réviseur.","soumettre","contexte","code","resuit","Demande","Utilisateur","Pauses","Chercheur","Codeur","Finale","« La tâche","Exécutions","Délais d'attente","magasin d' état","(par pas)","Orchestrateur centralisé - un contrôleur appelle","Chorégraphie via event bus — agents","«chaque agent en séquence, possède une logique de réessai,","Publier/s'abonner à des événements, pas de central","état dans un DB, temps écoulés par étape","Contrôleur, chaque agent déclenche le suivant de manière autonome.","Exécution basée sur DAG — modélisez le pipeline en tant que","Superviseur pattern — un méta-agent surveille tout","graphe acyclique dirigé, paralielize indépendant","autres, détecte les défaillances, décide s'il faut réessayer,","pas, bloquez uniquement sur les dépendances réelles.","tre réorienté, ou s’élever vers un être humain."]}},{"kind":"p","page":118,"text":{"en":"You have an AI product with 4 specialized agents: a Planner, a Researcher, a Coder, and a Reviewer.","fr":"Votre produit IA repose sur quatre agents spécialisés : Planner pour la planification, Researcher pour la recherche, Coder pour l’implémentation et Reviewer pour la revue."}},{"kind":"p","page":118,"text":{"en":"The Planner breaks down the task. The Researcher pulls context. The Coder implements. The Reviewer catches bugs.","fr":"Planner découpe la tâche. Researcher rassemble le contexte. Coder implémente. Reviewer repère les erreurs."}},{"kind":"p","page":118,"text":{"en":"Simple on paper. In production, it's falling apart.","fr":"Sur le papier, c’est simple. En production, le système se désorganise."}},{"kind":"p","page":118,"text":{"en":"Here's what's happening:","fr":"Voici les dysfonctionnements :"}},{"kind":"p","page":118,"text":{"en":"• The Researcher sometimes returns before the Planner finishes → Coder gets incomplete context","fr":"• Researcher termine parfois avant Planner : Coder reçoit un contexte incomplet."}},{"kind":"p","page":118,"text":{"en":"• The Reviewer flags issues → but there's no retry loop, so bugs ship anyway","fr":"• Reviewer signale des problèmes, mais sans boucle de nouvelle tentative, certains défauts atteignent quand même la production."}},{"kind":"p","page":118,"text":{"en":"• One agent timeout hangs the entire pipeline for 40 seconds","fr":"• Le dépassement de délai d’un agent bloque tout le pipeline pendant 40 secondes."}},{"kind":"p","page":118,"text":{"en":"• You have no visibility into which agent failed or why","fr":"• Vous ignorez quel agent a échoué et pourquoi."}},{"kind":"p","page":118,"text":{"en":"You need to redesign the orchestration layer. What do you do?","fr":"Vous devez revoir l’orchestration. Que mettez-vous en place ?"}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":118,"text":{"en":"Centralized orchestrator — one controller calls each agent in sequence, owns retry logic, tracks state in a DB, times out per step individually.","fr":"Orchestrateur centralisé : un contrôleur appelle les agents à tour de rôle, gère les nouvelles tentatives, conserve l’état en base et applique un délai maximal à chaque étape."}}]},{"letter":"B","blocks":[{"kind":"p","page":118,"text":{"en":"Choreography via event bus — agents publish/subscribe to events, no central controller, each agent triggers the next autonomously.","fr":"Chorégraphie via un bus d’événements : les agents publient des événements et s’y abonnent. Sans contrôleur central, chaque agent déclenche le suivant de façon autonome."}}]},{"letter":"C","blocks":[{"kind":"p","page":119,"text":{"en":"DAG-based execution — model the pipeline as a directed acyclic graph, parallelize independent steps, block only on real dependencies.","fr":"Exécution basée sur un DAG : modéliser le pipeline comme un graphe orienté acyclique, exécuter les étapes indépendantes en parallèle et attendre uniquement les résultats indispensables."}}]},{"letter":"D","blocks":[{"kind":"p","page":119,"text":{"en":"Supervisor pattern — a meta-agent monitors all others, detects failures, decides whether to retry, reroute, or escalate to a human.","fr":"Patron superviseur : un méta-agent surveille les autres agents, détecte les échecs et décide de réessayer, de rediriger la tâche ou de faire intervenir une personne."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"figure","page":120,"id":"120-03","width":800,"height":469,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["System Design Labs","Correct Answe'","Your pipeline has hard dependencies (Coder must wait for BOTH Planner AND Researcher)","AND needs retry loops (Reviewer —> Coder on failure).","What this solves directly:","fe","2)","Race condition","DAG blocks Coder uni both upstream","(Pe","‘odes complete, No manual checks","Timeout hanging pipeline","> Coder","Implements","ach node has ts ovmn deadline, One","‘agent imeout doesn freeze everything","Researcher","Puls","No retry loop.","Retry i afrst-class edge in the graph,","context","Retry on failure","‘No visibility","DAG engines give you a full execution","trace per run","Centralized orchestrator — one controler calls","Choreography via event bus — agents","‘each agent in sequence, owns retry logic, tracks","publish/subscribe to events, no centr","LA","state in a DB, times out per stop individually","Controller, each agent triggers the next autonomously.","DAG-based execution — model the pipeline as a","Supervisor patter","— a meta-agont monitors all","directed acyclic graph, parallelize independent","others, detects failures, decides whether to retry,","steps, block only on real dependencies.","LD","reroute, or escalate to a human.","[c]","They all converge on this model because it makes","dependencies visible, failures local, and execution testable"],"fr":["System Design Labs","Correct Answe","Votre pipeline a des dépendances dures (le codeur doit attendre à la fois le planificateur et le chercheur)","ET a besoin de retry loops (Reviewer — > Coder en cas d'échec).","Ce que cela résout directement :","fé","2)","État de la course","DAG blocs Coder uni à la fois en amont","(Pe","«odes complètes, Pas de contrôles manuels","Timeout pipeline suspendu","> Codeur","Exécutions","ach noeud a ts ovmn deadline, Un","L'agent imeout gèle tout","Chercheur","Puls","Pas de boucle de réessai.","Réessayer i afrst-classe edge dans le graphique,","contexte","Réessayer en cas d'échec","«Pas de visibilité","Les moteurs DAG vous donnent une exécution complète","trace par course","Orchestrateur centralisé – un contrôleur appelle","Chorégraphie via event bus — agents","«chaque agent en séquence, possède une logique de réessai, des pistes","Publier/s'abonner à des événements, pas de centr","LA","état dans un DB, temps morts par arrêt individuellement","Contrôleur, chaque agent déclenche le suivant de manière autonome.","Exécution basée sur DAG — modélisez le pipeline en tant que","Supervisor patter","une méta-agone surveille tous","graphe acyclique dirigé, paralléliser indépendant","autres, détecte les défaillances, décide s'il faut réessayer,","pas, bloquez uniquement sur les dépendances réelles.","LD","tre réorienté, ou s’élever vers un être humain.","[c]","Ils convergent tous sur ce modèle parce qu'il fait","dépendances visibles, échecs locaux et exécution testable"]}},{"kind":"p","page":120,"text":{"en":"Correct Answer: C — DAG-based execution","fr":"Bonne réponse : C — Exécution basée sur un DAG"}},{"kind":"p","page":120,"text":{"en":"Your pipeline has hard dependencies (Coder must wait for BOTH Planner AND Researcher) AND needs retry loops (Reviewer → Coder on failure).","fr":"Le pipeline comporte des dépendances strictes : Coder doit attendre à la fois Planner et Researcher. Il faut aussi pouvoir relancer certaines étapes : si la revue échoue, Reviewer renvoie le travail à Coder."}},{"kind":"p","page":120,"text":{"en":"A DAG models this explicitly:","fr":"Un DAG rend ces dépendances explicites :"}},{"kind":"p","page":120,"text":{"en":"Planner ──┐ ├──► Coder ──► Reviewer Researcher┘ │ ◄───────── (retry on failure)","fr":"Planner et Researcher → Coder → Reviewer. En cas d’échec de la revue : Reviewer redemande une exécution à Coder."}},{"kind":"p","page":120,"text":{"en":"What this solves directly:","fr":"Ce que cette approche résout :"}},{"kind":"p","page":120,"text":{"en":"• Race condition → DAG blocks Coder until both upstream nodes complete. No manual checks.","fr":"• Condition de concurrence : le DAG attend la fin des deux tâches en amont avant de lancer Coder, sans vérification manuelle."}},{"kind":"p","page":120,"text":{"en":"• Timeout hanging pipeline → each node has its own deadline. One agent timeout doesn't freeze everything.","fr":"• Blocage du pipeline : chaque nœud a son propre délai maximal. Le dépassement de délai d’un agent ne fige pas tout le système."}},{"kind":"p","page":120,"text":{"en":"• No retry loop → retry is a first-class edge in the graph, not bolted-on logic.","fr":"• Relances absentes : le graphe modélise explicitement la relance, plutôt que de la traiter comme un ajout à part."}},{"kind":"p","page":120,"text":{"en":"• No visibility → DAG engines give you a full execution trace per run.","fr":"• Manque de visibilité : le moteur du DAG fournit une trace complète pour chaque exécution."}},{"kind":"p","page":121,"text":{"en":"Real implementations: LangGraph, Temporal, AWS Step Functions, Prefect, Dagster. They all converge on this model because it makes dependencies visible, failures local, and execution testable.","fr":"LangGraph, Temporal, AWS Step Functions, Prefect et Dagster proposent des mises en œuvre. Ces outils convergent vers ce modèle parce qu’il rend les dépendances visibles, isole les échecs et permet de tester l’exécution."}}],[{"kind":"p","page":121,"text":{"en":"A — Centralized orchestrator (senior engineer trap)","fr":"A — Orchestrateur centralisé (choix trompeur)"}},{"kind":"p","page":121,"text":{"en":"This is the closest wrong answer. A central controller with per-step timeouts and DB state feels right — it's structured, it has retry logic, it has visibility.","fr":"C’est l’autre réponse la plus plausible. Un contrôleur central avec un délai par étape et un état persistant en base semble adapté : l’exécution est structurée, observable et prévoit des relances."}},{"kind":"p","page":121,"text":{"en":"The problem: it's sequential by default. Planner and Researcher still run one after the other unless you explicitly add parallel execution logic. You're basically hand-building a DAG imperatively, and you'll do it badly. Every new dependency becomes a code change.","fr":"Le défaut est l’exécution séquentielle par défaut. Planner et Researcher s’exécutent l’un après l’autre si vous n’ajoutez pas explicitement la logique de parallélisation. Vous reconstruisez, dans du code impératif, une version artisanale d’un DAG. Chaque nouvelle dépendance exige une modification du code."}},{"kind":"p","page":121,"text":{"en":"Why it traps senior engineers: it looks like \"proper architecture\" but it's just imperative orchestration with extra ceremony.","fr":"Cette option peut convaincre des ingénieurs expérimentés parce qu’elle donne l’impression d’une architecture bien structurée. En pratique, elle habille surtout une orchestration impérative."}}],[{"kind":"p","page":121,"text":{"en":"B — Choreography via event bus","fr":"B — Chorégraphie via un bus d’événements"}},{"kind":"p","page":121,"text":{"en":"Works well for loosely coupled, fire-and-forget pipelines (order placed → invoice generated → email sent). But your pipeline has tight dependencies — Coder literally cannot start without both Planner AND Researcher finishing.","fr":"L’approche fonctionne pour des pipelines faiblement couplés où chaque étape peut se terminer sans attendre les suivantes, par exemple commande passée → facture générée → e-mail envoyé. Ici, les dépendances sont étroites : Coder ne peut démarrer qu’une fois Planner et Researcher terminés."}},{"kind":"p","page":121,"text":{"en":"With pure choreography, there's no natural \"wait for these two\" primitive. You'd have to build coordination logic inside the agents themselves. Now your Coder is doing orchestration work. That's worse than your current problem.","fr":"Une chorégraphie pure n’offre pas naturellement de mécanisme pour attendre les deux résultats. Il faudrait intégrer la coordination dans les agents eux-mêmes. Coder se retrouverait à orchestrer le pipeline, ce qui aggraverait votre problème."}},{"kind":"p","page":121,"text":{"en":"Rule of thumb: choreography for independence, orchestration for dependency.","fr":"Règle pratique : la chorégraphie convient aux étapes indépendantes, l’orchestration aux dépendances explicites."}}],[{"kind":"p","page":121,"text":{"en":"D — Supervisor pattern","fr":"D — Patron superviseur"}},{"kind":"p","page":121,"text":{"en":"A supervisor meta-agent that monitors, detects failures, and reroutes is a great layer on top of C — for human escalation, anomaly detection, or dynamic rerouting when the DAG can't handle it.","fr":"Un méta-agent qui surveille, détecte les échecs et redirige le travail complète bien C pour faire intervenir une personne, repérer les anomalies ou réorienter dynamiquement le traitement si le DAG ne sait pas le faire."}},{"kind":"p","page":121,"text":{"en":"As a base orchestration model? It adds latency (every decision goes through the supervisor), a single point of failure, and doesn't solve the dependency problem at all. The supervisor still needs to know the execution order — which is just an implicit DAG inside the supervisor's brain.","fr":"Comme modèle principal, le superviseur ajoute de la latence, puisque toutes les décisions passent par lui, et crée un point unique de défaillance. Il ne règle pas les dépendances : il doit quand même connaître l’ordre d’exécution, ce qui revient à maintenir un DAG implicite dans le superviseur."}},{"kind":"p","page":121,"text":{"en":"Use it as resilience on top of C. Not instead of C.","fr":"Utilisez le superviseur en complément de C pour améliorer la résilience."}}]]},{"day":30,"title":{"en":"Choosing a File Storage Backend","fr":"Choisir une solution de stockage de fichiers"},"pages":[122,125],"topic":"architecture","correct":"A","scenario":[{"kind":"figure","page":122,"id":"122-02","width":800,"height":420,"alt":{"en":"Day 30 featured","fr":"Illustration de la question du jour 30"},"transcript":{"en":["System De","nLabs","You’re building a file upload service.","What do you pick?","aa","Upload","Store","Mobile + Web","Upload Service","Clients","(NestJS)","File Storage","Audit Service","(aws)","fend Access) |","s3—","ject storage, infi","ite scale,","EBS — block storage, SSD-backed,","pay per GB, no servers to manage.","attach to your EC2, low latency reads.","|a","EFS — managed NFS, shared across","MinlO on EC2 — S3-compatible self-hosted","multiple EC2 instances simultaneously.","object storage, you own the infra."],"fr":["System De","nLabs","Vous créez un service de téléchargement de fichiers.","Qu'est-ce que tu choisis ?","aa","Télécharger","Stocker","Mobile + Web","Service de téléchargement","Clients","(NestJS)","Stockage de fichiers","Service de la vérification des comptes","(aws)","fend Access)","s3","stockage, infi","à l'échelle,","Stockage de bloc EBS — , SSD,","payer par Go, pas de serveurs à gérer.","attacher à votre EC2, faible latence lit.","a","EFS — géré NFS, partagé entre","MinlO sur EC2 — S3 compatible auto-hébergé","plusieurs instances EC2 simultanément.","stockage d'objets, vous possédez l'infra."]}},{"kind":"p","page":122,"text":{"en":"You're building a file upload service. 10TB of user files today. 100TB in 12 months.","fr":"Vous développez un service d’envoi de fichiers. Les utilisateurs stockent aujourd’hui 10 To. Vous prévoyez 100 To dans douze mois."}},{"kind":"p","page":122,"text":{"en":"Your team is having a fight.","fr":"Les avis divergent dans l’équipe."}},{"kind":"p","page":122,"text":{"en":"The backend lead says: \"Just use S3. Done.\"","fr":"Le responsable backend propose de choisir simplement S3."}},{"kind":"p","page":122,"text":{"en":"The DevOps engineer says: \"Mount an EBS volume. Simpler, faster.\"","fr":"L’ingénieur DevOps propose de monter un volume EBS, qu’il juge plus simple et plus rapide."}},{"kind":"p","page":122,"text":{"en":"The platform architect says: \"We need EFS — multiple services need to read the same files.\"","fr":"L’architecte plateforme penche pour EFS : plusieurs services doivent lire les mêmes fichiers."}},{"kind":"p","page":122,"text":{"en":"The startup CTO says: \"We can't afford cloud storage at scale. Self-host with MinIO.\"","fr":"Le CTO de la startup juge le stockage cloud trop cher à grande échelle et propose d’autohéberger MinIO."}},{"kind":"p","page":122,"text":{"en":"All four have shipped this in production. All four have opinions backed by scars.","fr":"Les quatre ont déjà mis ces solutions en production et tirent leurs convictions de cette expérience."}},{"kind":"p","page":122,"text":{"en":"Here's the setup:","fr":"Voici la configuration."}},{"kind":"p","page":122,"text":{"en":"— Upload service (NestJS) receives files from mobile + web clients","fr":"— Le service NestJS reçoit les fichiers des clients mobiles et web."}},{"kind":"p","page":122,"text":{"en":"— ML pipeline needs to read uploaded images for processing","fr":"— Le pipeline de ML doit lire les images transmises pour les traiter."}},{"kind":"p","page":122,"text":{"en":"— Audit service needs read access to the same files","fr":"— Le service d’audit doit pouvoir lire ces mêmes fichiers."}},{"kind":"p","page":122,"text":{"en":"— Files range from 5KB profile pics to 2GB video exports","fr":"— La taille des fichiers va de 5 Ko pour des photos de profil à 2 Go pour des exports vidéo."}},{"kind":"p","page":122,"text":{"en":"— You're on AWS","fr":"— Vous utilisez AWS."}},{"kind":"p","page":123,"text":{"en":"What do you pick?","fr":"Quelle option choisissez-vous ?"}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":123,"text":{"en":"S3 — object storage, infinite scale, pay per GB, no servers to manage.","fr":"S3 : stockage objet à capacité extensible, facturé au Go, sans serveur à gérer."}}]},{"letter":"B","blocks":[{"kind":"p","page":123,"text":{"en":"EBS — block storage, SSD-backed, attach to your EC2, low latency reads.","fr":"EBS : stockage bloc sur SSD, rattaché à une instance EC2, avec une faible latence en lecture."}}]},{"letter":"C","blocks":[{"kind":"p","page":123,"text":{"en":"EFS — managed NFS, shared across multiple EC2 instances simultaneously.","fr":"EFS : service NFS managé que plusieurs instances EC2 peuvent utiliser simultanément."}}]},{"letter":"D","blocks":[{"kind":"p","page":123,"text":{"en":"MinIO on EC2 — S3-compatible self-hosted object storage, you own the infra.","fr":"MinIO sur EC2 : stockage objet autohébergé, compatible avec S3. Vous exploitez l’infrastructure."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"figure","page":124,"id":"124-03","width":800,"height":469,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["JK, system Design Labs","(A) A WINS","The right choice for this file upload service.","Massive Scale, No Limits","without any changes.","Cost Efficient at Scale","Pay only for what you use","Upto","Store","| 9","Lifecycte to Glacier","Automatialy move cold les to","Mobile + Web","Chante","‘Amazon $3","Glacier Save upto 90%","(Nests)","(Bucket)","Event Driven","the moment fl nds,","3 events tigger you ML pipeline","Built-in Security & Compliance","Metadata 08","3 Events","(Object Creates)","For greenfield cloud services,","‘hiss the defaut","53 — object storage,","EBS — block storage,","FS — managed NFS,","Mit0 on EC2 — $9-compatible","Infinite scale, pay per GB,","‘SSD-becked, attach to","shared across multiple","sel-hosted object storage,","no servers to manage.","your EC2 low latency reads.","EC? netancessiuitaneoushy,","you own the infra","(4)"],"fr":["JK, system Design Labs","(A) UN VINS","Le bon choix pour ce service de téléchargement de fichiers.","Échelle massive, aucune limite","sans aucun changement.","Rentable à l'échelle","Payez uniquement pour ce que vous utilisez","Jusqu'à","Stocker","| 9","La Salle to Glacier","Automatiquement déplacer les froids à","Mobile + Web","Chante","« Amazon $3","Glacier Économisez jusqu'à 90 %","(Nests)","(Bucket)","Événement Driven","le moment fl nds,","3 événements vous tigger ML pipeline","Sécurité et conformité intégrées","Métadonnées 08","3 Événements","(Object Creates)","Pour les services cloud greenfield,","«Hiss the defaut","53 — stockage d'objets,","EBS — stockage en bloc,","FS — géré NFS,","Mit0 sur EC2 — compatible à 9 $","Échelle infinie, salaire par Go,","«SSD-becked, attachez à","partagé entre plusieurs","stockage d'objets hébergés sel,","Pas de serveurs à gérer.","votre EC2 lit à faible latence.","CE — netancessiuitaneoushy,","Vous possédez l'infra","(4)"]}},{"kind":"p","page":124,"text":{"en":"Why A wins (S3):","fr":"Pourquoi choisir A (S3)"}},{"kind":"p","page":124,"text":{"en":"One storage layer. Zero capacity planning. Every service reads from the same bucket using the S3 key stored in your DB.","fr":"Une seule couche de stockage et aucune capacité à provisionner. Chaque service lit dans le même bucket avec la clé S3 stockée en base."}},{"kind":"p","page":124,"text":{"en":"At 100TB → ~$2,300/month. Lifecycle policies move cold files to Glacier automatically. S3 events trigger your ML pipeline the moment a file lands. Versioning, encryption, audit logs — all built in, zero extra work.","fr":"Pour 100 To, comptez environ 2 300 $ par mois. Les politiques de cycle de vie déplacent automatiquement les fichiers peu consultés vers Glacier. Les événements S3 déclenchent le pipeline ML dès qu’un fichier arrive. La gestion des versions, le chiffrement et les journaux d’audit sont intégrés."}},{"kind":"p","page":124,"text":{"en":"For greenfield cloud services, this is the default. You only deviate when you have a specific reason not to.","fr":"Pour un nouveau service dans le cloud, c’est le choix par défaut, sauf exigence particulière."}}],[{"kind":"p","page":125,"text":{"en":"Why B destroys your architecture quietly (EBS):","fr":"Pourquoi EBS compromet cette architecture en grandissant"}},{"kind":"p","page":125,"text":{"en":"EBS is a disk. A fast, reliable disk — attached to one EC2 instance at a time.","fr":"EBS fournit un disque rapide et fiable, rattaché à une instance EC2 à la fois dans cette configuration."}},{"kind":"p","page":125,"text":{"en":"The moment your ML pipeline runs on a different instance than your upload service, it can't read those files. Add auto-scaling? Each new instance gets a blank disk. Deploy across two AZs? Same problem.","fr":"Si le pipeline de ML tourne sur une autre instance que le service d’envoi, il ne peut pas lire les fichiers. En mise à l’échelle automatique, chaque nouvelle instance démarre avec un disque vide. Le même problème se pose avec deux zones de disponibilité."}},{"kind":"p","page":125,"text":{"en":"Works perfectly in dev. Silently breaks the moment you scale horizontally. The team that picks EBS here usually discovers this 6 months later when they're doing a painful migration under pressure.","fr":"Tout fonctionne en développement, puis cesse de fonctionner silencieusement dès que vous ajoutez des instances. Les équipes qui choisissent EBS dans ce cas le découvrent souvent six mois plus tard, au moment d’une migration difficile et urgente."}}],[{"kind":"p","page":125,"text":{"en":"Why C is great — but not here (EFS):","fr":"Pourquoi EFS convient à d’autres usages"}},{"kind":"p","page":125,"text":{"en":"EFS is genuinely powerful. Shared NFS, multiple EC2 instances mount it simultaneously, full POSIX semantics.","fr":"EFS est une solution robuste : un partage NFS montable par plusieurs instances EC2 en même temps, avec la sémantique complète de POSIX."}},{"kind":"p","page":125,"text":{"en":"The problem: $0.30/GB/month. At 100TB that's $30,000/month vs S3's $2,300/month. A 13x cost difference.","fr":"Le problème est le coût : 0,30 $/Go par mois. Pour 100 To, cela représente 30 000 $/mois contre 2 300 $/mois sur S3, soit environ 13 fois plus."}},{"kind":"p","page":125,"text":{"en":"EFS is the right answer when your legacy app is hardcoded to open() / read() / write() filesystem calls and can't be refactored. For a greenfield NestJS service with an S3 SDK? You're paying 13x for filesystem semantics you don't need.","fr":"EFS convient lorsqu’une application historique dépend des appels de système de fichiers open(), read() et write() et ne peut pas être refactorisée. Pour un nouveau service NestJS doté du SDK S3, payer 13 fois plus pour cette sémantique est superflu."}}],[{"kind":"p","page":125,"text":{"en":"Why D is a cost-savings trap (MinIO):","fr":"Pourquoi les économies de MinIO sont trompeuses"}},{"kind":"p","page":125,"text":{"en":"MinIO is a real product used at hyperscale. S3-compatible API, high throughput, runs on your own hardware.","fr":"MinIO est utilisé à très grande échelle. Il expose une API compatible S3, offre un débit élevé et peut tourner sur votre propre matériel."}},{"kind":"p","page":125,"text":{"en":"But self-hosted means you own availability, disk failures, backups, capacity planning, and 3am incidents. At 10–100TB, the engineering cost of running MinIO reliably exceeds S3 spend by a wide margin. You're not saving money — you're converting cloud spend into engineering hours, which cost more.","fr":"En autohébergement, vous assumez la disponibilité, les pannes de disques, les sauvegardes, la planification de la capacité et les incidents à trois heures du matin. Entre 10 et 100 To, le coût d’exploitation fiable de MinIO dépasse largement la facture S3. La dépense cloud est remplacée par des heures d’ingénierie, plus coûteuses."}},{"kind":"p","page":125,"text":{"en":"MinIO makes sense at petabyte scale with dedicated infra teams and painful egress bills. Not here.","fr":"MinIO peut être pertinent à l’échelle du pétaoctet, avec une équipe d’infrastructure spécialisée et des frais de trafic sortant importants. Ce scénario est différent."}}]]},{"day":31,"title":{"en":"Cutting Cross-Region Latency","fr":"Réduire la latence entre régions"},"pages":[126,129],"topic":"scale","correct":"B","scenario":[{"kind":"figure","page":126,"id":"126-02","width":800,"height":420,"alt":{"en":"Day 31 featured","fr":"Illustration de la question du jour 31"},"transcript":{"en":["System Design Li","Your e-commerce platform just crossed 2M daily active users.","European latency is 380ms to your US-East region. What do you do?","Read/Write","Ros","round-trip","Users","(Primary)","0%)","API Gateway","edie","Cache","(0%)","us-east","‘Active-Active multi-region — deploy the full stack in","‘eu-west-1, use a distributed database (CockroachDB","‘Active-Passive with read replicas — keep us-east-{ as.","primar","spin up eu-west-1 as a hot standby with read","‘or Aurora Global), route users to the nearest region,","rplicas. European reads go local, writes stil go to US.","‘CDN + Edge caching — keep the single region, push","Active-Active with eventual consistency — deploy full","stack in both regions, allow each region to own its writes,","static assets and cacheable API responses to","syne asynchronously, Accept that a European user might","CloudFront edge nodes in Europe. No database changes.","see US write 200m lat."],"fr":["Conception système Li","Votre plateforme e-commerce vient de croiser 2M d’utilisateurs actifs quotidiens.","La latence européenne est de 380ms pour votre région USA-Est. Que faites-vous ?","Lire/écrire","Ros","aller-retour","Utilisateurs","(primaire)","0%)","API Gateway","edie","Cache","(0%)","us-east","‘Active-Active multi-régions — déployer la pile complète dans","«eu-west-1, utiliser une base de données distribuée (CockroachDB)","‘Active-Passif avec des répliques en lecture — gardez-nous-est- — comme.","primar","spin up eu-west-1 comme un standby chaud avec lecture","‘or Aurora Global), acheminent les utilisateurs vers la région la plus proche,","rplicas. Lectures européennes vont local, écrit encore aller aux États-Unis.","‘CDN + Edge cache — garder la seule région, pousser","Active-Active avec une cohérence éventuelle - déployer complètement","empiler dans les deux régions, permettre à chaque région de posséder ses écritures,","des ressources statiques et des réponses d'API en cache à","syne asynchrone, accepter qu'un utilisateur européen puisse","Noeuds périphériques CloudFront en Europe. Aucune base de données ne change.","voir nous écrire 200m lat."]}},{"kind":"p","page":126,"text":{"en":"Your e-commerce platform just crossed 2M daily active users. 70% are in the US, 30% in Europe.","fr":"Votre plateforme de commerce en ligne vient de dépasser les 2 millions d’utilisateurs actifs par jour. 70 % sont aux États-Unis et 30 % en Europe."}},{"kind":"p","page":126,"text":{"en":"Latency complaints are piling up from European users — 380ms average round-trip to your US-East region. Support tickets are up 40%. Black Friday is in 6 weeks.","fr":"Les utilisateurs européens se plaignent de plus en plus de la lenteur : le temps d’aller-retour moyen vers votre région US East atteint 380 ms. Les demandes au support ont augmenté de 40 %. Le Black Friday est dans six semaines."}},{"kind":"p","page":126,"text":{"en":"Your infrastructure: single AWS us-east-1 region, RDS PostgreSQL (primary), Redis cache, 12 microservices behind an API Gateway.","fr":"Votre infrastructure tient dans une seule région AWS, us-east-1 : une base RDS PostgreSQL primaire, un cache Redis et 12 microservices derrière une passerelle API."}},{"kind":"p","page":126,"text":{"en":"You need to get European latency under 80ms. The engineering team is debating four approaches.","fr":"Vous devez ramener la latence sous les 80 ms en Europe. L’équipe d’ingénierie hésite entre quatre approches."}},{"kind":"p","page":126,"text":{"en":"Here's your constraint: you cannot afford a full database rewrite, and you need this shipped before Black Friday.","fr":"Vous n’avez pas les moyens de refondre entièrement la base de données et vous devez déployer la solution avant le Black Friday."}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":126,"text":{"en":"Active-Active multi-region — deploy the full stack in eu-west-1, use a distributed database (CockroachDB or Aurora Global), route users to the nearest region. Writes go to both regions simultaneously.","fr":"Actif-actif multirégion — déployer toute la stack dans eu-west-1, utiliser une base de données distribuée (CockroachDB ou Aurora Global) et diriger les utilisateurs vers la région la plus proche. Les écritures sont envoyées simultanément aux deux régions."}}]},{"letter":"B","blocks":[{"kind":"p","page":126,"text":{"en":"Active-Passive with read replicas — keep us-east-1 as primary, spin up eu-west-1 as a hot standby with read replicas. European reads go local, writes still go to US. Failover in minutes if US goes down.","fr":"Actif-passif avec répliques de lecture — conserver us-east-1 comme région primaire et faire tourner des répliques de lecture dans eu-west-1, prête à prendre le relais. Les lectures européennes restent locales et les écritures continuent de passer par les États-Unis. Si la région américaine tombe, le basculement se fait en quelques minutes."}}]},{"letter":"C","blocks":[{"kind":"p","page":126,"text":{"en":"CDN + Edge caching — keep the single region, push static assets and cacheable API responses to CloudFront edge nodes in Europe. No database changes.","fr":"CDN et cache en périphérie — conserver une seule région et distribuer les ressources statiques et les réponses API pouvant être mises en cache sur les nœuds périphériques de CloudFront en Europe. La base de données reste telle quelle."}}]},{"letter":"D","blocks":[{"kind":"p","page":127,"text":{"en":"Active-Active with eventual consistency — deploy full stack in both regions, allow each region to own its writes, sync asynchronously. Accept that a European user might see a US write 200ms late.","fr":"Actif-actif avec cohérence à terme — déployer toute la stack dans les deux régions, laisser chacune gérer ses écritures et les synchroniser de façon asynchrone. Un utilisateur européen peut voir une écriture américaine avec 200 ms de retard."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"figure","page":128,"id":"128-03","width":800,"height":533,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["Qy System Design Labs","Why","Fastest way to get European read latency under 80ms — without rewriting the database.","B) Active-Passive","with read replicas","round-tip","Us Users","os","European reads golocak~15ms","(70%)","(vs 380m today)","API","Ship before ack Friday","Gateway","Microservices","(eat","~380ms","EU Users","pane","Promate EU replica in minutes","rounds","(0%)","(today)","ifUS goes down","edie Cache","Solves the real problem","Fastest path to ship","Good enough consistency","‘Bonus: real fllover story","Spring up an ROS read repli","Wee sti goto uses","Ihe US region goes down,","in evestt costs 1-2 days of","promote the EU epi in","products checking ere stats,","ifastrctre work. You canbe","‘minutes and eepeervng","losing thei proie. Those are","in production wel beloe Back","reads,","Fay,","tinder 100m","Bis the pragmatic, low-risk move that meets the constr","ts: no database rewrite, sl","in 6 woeks,","‘and get European read latency under 80ms."],"fr":["Qy System Design Lab","Pourquoi","Le moyen le plus rapide d'obtenir une latence de lecture européenne inférieure à 80ms - sans réécrire la base de données.","B) Actif-passif","avec des répliques en lecture","Round-tip","Us Utilisateurs","os","Lectures européennes golocak — 15ms","(70%)","(vs 380m aujourd'hui)","API","Expédition avant vendredi","Passerelle","Microservices","(manger","380ms","Utilisateurs de l'UE","panneau","Promate réplique UE en quelques minutes","rounds","(0%)","(aujourd'hui)","ifUS descend","edie Cache","Résoudre le vrai problème","Le chemin le plus rapide pour naviguer","Assez de cohérence","‘Bonus: histoire vraie de flover","Faire jaillir un ROS lire repli","Wee sti goto utilise","La région des États-Unis est en baisse,","dans evestt coûte 1-2 jours de","promouvoir l'epi de l'UE dans","produits vérifiant les stats,","Vous pouvez être sûr de vous.","Minutes et eepeervng","Je suis en train de perdre la proie.","en production wel beloe Retour","lire,","Fay,","tinder 100m","C'est le mouvement pragmatique, à faible risque, qui rencontre la constr","ts : pas de réécriture de base de données, sl","dans 6 woeks,","\"et obtenez une latence de lecture européenne inférieure à 80ms."]}},{"kind":"p","page":128,"text":{"en":"Why B wins:","fr":"Pourquoi retenir B ?"}},{"kind":"p","page":128,"text":{"en":"The constraint is the answer. You can't rewrite the database, and you have 6 weeks.","fr":"La contrainte tranche : vous avez six semaines, sans possibilité de refondre la base."}},{"kind":"p","page":128,"text":{"en":"European users are complaining about read latency — browsing products, checking order status, loading their profile. Those are reads. An RDS read replica in eu-west-1 costs you 1–2 days of infra work and immediately moves European reads to ~15ms instead of 380ms. Writes still go to us-east-1 (acceptable — users tolerate slightly higher write latency for checkout). Replication lag is typically under 100ms.","fr":"Les utilisateurs européens se plaignent du temps nécessaire pour consulter les produits, suivre une commande ou charger leur profil. Dans chaque cas, il s’agit de lectures. Mettre en place une réplique de lecture RDS dans eu-west-1 demande un à deux jours de travail côté infrastructure. Dès sa mise en service, les lectures européennes passent de 380 ms à environ 15 ms. Les écritures continuent vers us-east-1, ce qui reste acceptable : les utilisateurs tolèrent une latence d’écriture un peu plus élevée lors du paiement. Le retard de réplication est généralement inférieur à 100 ms."}},{"kind":"p","page":128,"text":{"en":"Active-passive also gives you a real failover story: US goes down → promote EU replica in minutes.","fr":"L’actif-passif permet aussi un véritable basculement : si la région américaine tombe, vous pouvez promouvoir la réplique européenne en quelques minutes."}}],[{"kind":"p","page":129,"text":{"en":"Why A is the trap (Active-Active + distributed DB):","fr":"Le piège de A — actif-actif avec base de données distribuée"}},{"kind":"p","page":129,"text":{"en":"This is the \"correct at scale\" answer that kills teams before Black Friday. Migrating from RDS PostgreSQL to CockroachDB or Aurora Global under a 6-week deadline is a multi-quarter project — distributed transactions, global clock skew, new failure modes to test. Right architecture for the long term. Wrong answer for the problem as stated.","fr":"Cette approche tient la charge à grande échelle, mais elle risque de faire rater le Black Friday à l’équipe. Passer de RDS PostgreSQL à CockroachDB ou Aurora Global avec une échéance à six semaines pose problème : c’est un chantier de plusieurs trimestres, entre les transactions distribuées, les écarts d’horloge entre régions et les nouveaux modes de panne à tester. Cette architecture peut convenir à long terme. Dans le délai imparti, elle ne convient pas."}}],[{"kind":"p","page":129,"text":{"en":"Why C is wrong (CDN + Edge caching):","fr":"Pourquoi écarter C — CDN et cache en périphérie ?"}},{"kind":"p","page":129,"text":{"en":"CDN solves static asset latency — images, JS, CSS. It does nothing for dynamic reads (user cart, order history, account data) and zero for write latency. It's a layer you add on top of a real solution, not instead of one. Partial credit, not the answer.","fr":"Le CDN réduit la latence des ressources statiques, comme les images et les fichiers JS et CSS. Les lectures dynamiques, comme le panier, l’historique des commandes et les données du compte, restent lentes, tout comme les écritures. Le CDN peut compléter la solution principale. À lui seul, il ne répond que partiellement au besoin."}}],[{"kind":"p","page":129,"text":{"en":"Why D is dangerous (Active-Active + eventual consistency):","fr":"Le risque de D — actif-actif avec cohérence à terme"}},{"kind":"p","page":129,"text":{"en":"Most honest version of multi-region — and the most dangerous to deploy without prep. Eventual consistency across regions means a European user places an order and your US region sees a different inventory count for 200ms. For limited stock = oversell. For checkout = duplicate charges. Conflict resolution is a product problem disguised as an infra problem.","fr":"C’est l’option qui assume le plus clairement les compromis d’une architecture multirégion. C’est aussi la plus risquée à déployer sans préparation. Avec la cohérence à terme entre régions, un utilisateur européen peut commander alors que la région américaine affiche encore un stock différent pendant 200 ms. Si le stock est limité, vous risquez de vendre plus d’articles que vous n’en avez. Au paiement, vous risquez de débiter deux fois le client. La résolution des conflits exige des décisions produit qui dépassent le choix de l’infrastructure."}}]]},{"day":32,"title":{"en":"Managing Secrets and Credentials","fr":"Gérer les secrets et les identifiants"},"pages":[130,133],"topic":"architecture","correct":"A","scenario":[{"kind":"figure","page":130,"id":"130-02","width":800,"height":420,"alt":{"en":"Day 32 featured","fr":"Illustration de la question du jour 32"},"transcript":{"en":["‘System Design Labs","Where are your database passwords,","API keys, and service tokens stored?","sa","uy","Mc screts in","NestsS APL","(Database","ian","» Soff","08","~ (ge J","SDK calls at runtime, IAM controls access,","‘Move everything to AWS Secrets Manager","fine-grained policies, works across","Use HashiCorp Vault — dynamic secrets,","auto-rotation built in.","any cloud or on-prem.","Use environment variables injected at deploy","Encrypt secrets with KMS and store ciphertext","time via C/CD — secrets stored in GitHub","‘Actions / GitLab Cl secrets vault, never touch disk.","full control.","in your own database — decrypt at runtime,"],"fr":["«System Design Labs","Où sont vos mots de passe de base de données,","Clés API et jetons de service stockés?","sa","uy","Mc Screts dans","NestS APL","(Base de données","ian","» Soff","08","(ge J","Appels SDK à l'exécution, IAM contrôle l'accès,","Tout transférer vers AWS Secrets Manager","politiques fines, fonctionne à travers","Utilisez les secrets dynamiques HashiCorp Vault — ,","auto-rotation intégrée.","n'importe quel nuage ou sur site.","Utiliser les variables d'environnement injectées au déploiement","Chiffrer des secrets avec KMS et stocker du texte chiffré","temps via les secrets C/CD — stockés dans GitHub","‘Actions / GitLab Cl coffre-fort secret, ne touchez jamais le disque.","contrôle total.","dans votre propre base de données — décrypter à l'exécution,"]}},{"kind":"p","page":130,"text":{"en":"Your startup just got its first SOC 2 audit.","fr":"Votre startup vient de passer son premier audit SOC 2."}},{"kind":"p","page":130,"text":{"en":"The auditor asks: \"Where are your database passwords, API keys, and service tokens stored?\"","fr":"L’auditeur demande : « Où stockez-vous les mots de passe des bases de données, les clés API et les jetons de service ? »"}},{"kind":"p","page":130,"text":{"en":"Your senior engineer goes quiet.","fr":"Votre ingénieur senior ne répond pas."}},{"kind":"p","page":130,"text":{"en":"Turns out half of them are in .env files committed to git 18 months ago. Three are hardcoded in Lambda environment variables. One is in a Slack message from 2023.","fr":"La moitié de ces secrets se trouve dans des fichiers .env ajoutés à Git il y a 18 mois. Trois valeurs sont inscrites en dur dans les variables d’environnement de Lambda. Une autre figure dans un message Slack de 2023."}},{"kind":"p","page":130,"text":{"en":"You have 6 services in production, 4 environments, and zero rotation policy.","fr":"Vous avez six services en production, quatre environnements et aucune politique de rotation des secrets."}},{"kind":"p","page":130,"text":{"en":"Here's the setup:","fr":"Voici la configuration."}},{"kind":"p","page":130,"text":{"en":"• NestJS API → Postgres (password in env var)","fr":"• API NestJS → Postgres (mot de passe dans une variable d’environnement)"}},{"kind":"p","page":130,"text":{"en":"• NestJS API → Stripe (API key in env var)","fr":"• API NestJS → Stripe (clé API dans une variable d’environnement)"}},{"kind":"p","page":130,"text":{"en":"• Background workers → SQS, S3 (AWS credentials in env var)","fr":"• Workers en arrière-plan → SQS, S3 (identifiants AWS dans des variables d’environnement)"}},{"kind":"p","page":130,"text":{"en":"• 3rd-party webhooks → HMAC secrets in env var","fr":"• Webhooks tiers → secrets HMAC dans des variables d’environnement"}},{"kind":"p","page":130,"text":{"en":"• Zero rotation. Zero audit trail. Zero centralized access control.","fr":"• Aucune rotation, aucune piste d’audit et aucun contrôle d’accès centralisé."}},{"kind":"p","page":130,"text":{"en":"You need to fix this. And you can't take downtime.","fr":"Vous devez corriger la situation sans interrompre le service."}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":131,"text":{"en":"Move everything to AWS Secrets Manager — SDK calls at runtime, IAM controls access, auto-rotation built in.","fr":"Tout déplacer vers AWS Secrets Manager — les services appellent le SDK à l’exécution, IAM contrôle les accès et la rotation automatique est intégrée."}}]},{"letter":"B","blocks":[{"kind":"p","page":131,"text":{"en":"Use HashiCorp Vault — dynamic secrets, fine-grained policies, works across any cloud or on-prem.","fr":"Utiliser HashiCorp Vault — secrets dynamiques, politiques d’accès fines et fonctionnement sur n’importe quel cloud ou sur site."}}]},{"letter":"C","blocks":[{"kind":"p","page":131,"text":{"en":"Use environment variables injected at deploy time via CI/CD — secrets stored in GitHub Actions / GitLab CI secrets vault, never touch disk.","fr":"Injecter les variables d’environnement au déploiement via la CI/CD — conserver les secrets dans le coffre de GitHub Actions ou de GitLab CI pour qu’ils ne soient jamais écrits sur disque."}}]},{"letter":"D","blocks":[{"kind":"p","page":131,"text":{"en":"Encrypt secrets with KMS and store ciphertext in your own database — decrypt at runtime, full control.","fr":"Chiffrer les secrets avec KMS et conserver le texte chiffré dans votre propre base de données — déchiffrer à l’exécution et garder la maîtrise de l’ensemble."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"figure","page":132,"id":"132-03","width":800,"height":471,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["System Design","AWS Secrets Manager","Labs","Secure. Scalable. Native. Audit-ready.","Centralized Secrets Management","Why AWS Secrets Manager?","Centralized Encrypted Storage","Al secrets stored securely","and encrypted with AWS","AWS Secrets Manager","Fetch sorte","KMS.","IAM-Based Access Control","Fine-gained access per","secret per service.","i+ 8","fay &","ares","‘Auto-Rotation","lente","Native rotation for ROS,","custom Lambda otators","for everything ose","Audit & Compliance","‘Background Workers","Every access logged in","one)","CloudTral — perfect for","00 2 audits","Zero-Downtime Migra","No downtime.","@ Cost: ~$0.40 / secret / month","No risk.","Deploy","Very new","Rotate ld","For 20 secrets that’s ~ $8 / month"],"fr":["Conception du système","AWS Secrets Manager","Labs","Sécurisé. Évolutif. Natif. Prêt pour l'audit.","Gestion centralisée des secrets","Pourquoi choisir AWS Secrets Manager ?","Stockage crypté centralisé","Al secrets stockés en toute sécurité","et crypté avec AWS","AWS Secrets Manager","Récupérer la sortie","KMS.","Contrôle d'accès basé sur IAM","Accès finement gagné par","secret par service.","i+ 8","fay &","ares","«Auto-rotation","lente","Rotation native pour ROS,","Otateurs Lambda personnalisés","Pour tout Ose","Audit et conformité","«Travailleurs de fond","Chaque accès connecté","un)","CloudTral — parfait pour","00 2 audits","Zero-Downtime Migra","Pas de temps mort.","Coût: — 0,40 $ / secret / mois","Pas de risque.","Déployer","Très nouveau","Faire pivoter ld","Pour 20 secrets qui sont — 8 / mois"]}},{"kind":"p","page":132,"text":{"en":"A — AWS Secrets Manager (correct)","fr":"A — AWS Secrets Manager (bonne réponse)"}},{"kind":"p","page":132,"text":{"en":"You're already AWS-native (Lambda, SQS, S3). Secrets Manager gives you:","fr":"Votre infrastructure utilise déjà les services AWS Lambda, SQS et S3. Secrets Manager vous apporte :"}},{"kind":"p","page":132,"text":{"en":"• Centralized encrypted storage (KMS-backed)","fr":"• Un stockage chiffré et centralisé, adossé à KMS."}},{"kind":"p","page":132,"text":{"en":"• IAM-based access control per secret per service","fr":"• Un contrôle d’accès avec IAM, pour chaque secret et chaque service."}},{"kind":"p","page":132,"text":{"en":"• Native auto-rotation for RDS + custom Lambda rotators for everything else","fr":"• La rotation automatique intégrée pour RDS et des fonctions Lambda personnalisées pour la rotation des autres secrets."}},{"kind":"p","page":132,"text":{"en":"• Every access logged in CloudTrail → exactly what your SOC 2 auditor wants","fr":"• La journalisation de chaque accès dans CloudTrail, comme le demande l’auditeur SOC 2."}},{"kind":"p","page":132,"text":{"en":"Migration is zero-downtime: swap env vars for getSecretValue() calls, deploy, rotate the old creds after confirming the new ones work. Cost: ~$0.40/secret/month. For 20 secrets that's $8/month.","fr":"La migration se fait sans interruption. Remplacez les variables d’environnement par des appels à getSecretValue(), déployez, puis remplacez les anciens identifiants une fois les nouveaux validés. Le coût est d’environ 0,40 $ par secret et par mois, soit 8 $ par mois pour 20 secrets."}}],[{"kind":"p","page":133,"text":{"en":"B — HashiCorp Vault (senior engineer trap)","fr":"B — HashiCorp Vault (le piège pour les ingénieurs expérimentés)"}},{"kind":"p","page":133,"text":{"en":"Vault is more powerful — dynamic secrets (a fresh Postgres credential per-request that expires in 1h) is one of the most elegant patterns in production infra.","fr":"Vault est plus puissant. Ses secrets dynamiques permettent, par exemple, de créer des identifiants Postgres à chaque requête et de les faire expirer au bout d’une heure. C’est une approche particulièrement élégante en production."}},{"kind":"p","page":133,"text":{"en":"But Vault is infrastructure you own and operate. You need a Raft cluster (3+ nodes), a storage backend, unsealing procedures, DR planning, and an ops team that knows Vault. If Vault goes down, secrets become inaccessible — services fail.","fr":"Il vous revient toutefois d’administrer et d’exploiter Vault. Il faut prévoir un cluster Raft d’au moins trois nœuds, un stockage persistant, des procédures de déverrouillage, un plan de reprise après sinistre et une équipe qui maîtrise Vault. Si Vault tombe, les services n’accèdent plus aux secrets et tombent à leur tour."}},{"kind":"p","page":133,"text":{"en":"When Vault wins: Multi-cloud, on-prem requirements, dynamic secrets at scale, or you have a dedicated infra team. If you're AWS-native under 50 engineers — Secrets Manager first, always.","fr":"Vault prend l’avantage si vous utilisez plusieurs clouds, si vous devez héberger sur site, si vous avez besoin de secrets dynamiques à grande échelle ou si vous disposez d’une équipe d’infrastructure dédiée. Pour une équipe de moins de 50 ingénieurs qui travaille déjà entièrement sur AWS, commencez par Secrets Manager."}}],[{"kind":"p","page":133,"text":{"en":"C — CI/CD Injected Env Vars (partially right, wrong scope)","fr":"C — Variables injectées par la CI/CD (pertinent pour une partie des secrets)"}},{"kind":"p","page":133,"text":{"en":"GitHub Actions / GitLab CI secrets are the right place for build-time and deploy-time secrets — Docker Hub creds, Terraform tokens, deploy keys.","fr":"Les coffres de GitHub Actions et de GitLab CI conviennent aux secrets utilisés au build et au déploiement : identifiants Docker Hub, jetons Terraform et clés de déploiement."}},{"kind":"p","page":133,"text":{"en":"They're wrong for runtime secrets — the DB password your app needs at 3 AM, the Stripe key for a live webhook. Those get injected as env vars into ECS task definitions or Lambda config — harder to rotate atomically, no audit trail on runtime access.","fr":"Ils conviennent mal aux secrets utilisés à l’exécution : le mot de passe dont l’application a besoin pour accéder à la base à trois heures du matin, par exemple, ou la clé Stripe utilisée par un webhook en production. Ces secrets sont injectés dans les définitions de tâches ECS ou la configuration de Lambda. Leur rotation atomique est plus difficile et les accès à l’exécution ne sont pas audités."}},{"kind":"p","page":133,"text":{"en":"C complements A or B. It doesn't replace them.","fr":"C peut compléter A ou B."}}],[{"kind":"p","page":133,"text":{"en":"D — DIY KMS + own database (wrong)","fr":"D — Développer un coffre maison avec KMS et une base de données (à écarter)"}},{"kind":"p","page":133,"text":{"en":"This is reinventing Secrets Manager badly. You now own: encryption key management, rotation logic, access control, audit logging, and a database that itself needs credentials to connect to.","fr":"Vous reconstruisez Secrets Manager en moins bien. Vous devez gérer les clés de chiffrement, la rotation, le contrôle d’accès, la journalisation d’audit et les identifiants de connexion à la base de données elle-même."}},{"kind":"p","page":133,"text":{"en":"The meta-problem: what secret protects the secret store? You end up with a bootstrapping problem that managed secret stores are specifically designed to solve. This is what teams built in 2012 before managed options existed.","fr":"Une question se pose alors : quel secret protège le coffre ? C’est précisément ce problème d’amorçage que les coffres de secrets managés résolvent. En 2012, avant que ces services existent, les équipes devaient encore construire ce type de solution."}}]]},{"day":33,"title":{"en":"Reconstructing State with Event Sourcing","fr":"Reconstruire l’état avec l’event sourcing"},"pages":[134,137],"topic":"data","correct":"A","scenario":[{"kind":"figure","page":134,"id":"134-02","width":800,"height":420,"alt":{"en":"Day 33 featured","fr":"Illustration de la question du jour 33"},"transcript":{"en":["‘System Design Labs","What’s your approach when redesigning","this service?","place / update /","‘cancel / refund","Overwritten","Client","OrderService","Postgres","Rows","(current state only)","Events","| pl",", updates","(ean","Event Sourcing — append-only event log","‘Change Data Capture (CDC) — keep Postgres","as the source of truth, current state","as-is, but stream all row changes","derived from replay","1g events.","to Kafka for an audit trail","‘Add an audit_log table — trigger-based","Dual-write — write to both the current-state","shadow writes on every","table and a separate events table","INSERT/UPDATE/DELETE.","on every operation,"],"fr":["«System Design Labs","Quelle est votre approche lors de la refonte","ce service ?","lieu / mise à jour /","«annulation / remboursement","Remplacée","Client","OrderService","Postgres","Lignes","(état actuel uniquement)","Événements","pl",", mises à jour","(Ean","Event Sourcing — journal des événements append-only","« Change Data Capture (CDC) — conservez Postgres","comme source de vérité, état actuel","en l'état, mais stream tous les changements de ligne","dérivé de replay","1g événements.","à Kafka pour une piste d'audit","‘Ajouter une table audit_log — trigger-based","Dual-write - écrire à la fois l'état actuel","ombre écrit sur chaque","table et une table d'événements séparés","INSCRIRE/MISE À JOUR/SUPPRIMER.","à chaque opération,"]}},{"kind":"p","page":134,"text":{"en":"Your order service takes 200 writes/sec at peak.","fr":"Votre service de commandes absorbe jusqu’à 200 écritures par seconde."}},{"kind":"p","page":134,"text":{"en":"You audit 6 months of data. Something's off — two orders show the same ID, different totals.","fr":"En contrôlant six mois de données, vous repérez une anomalie : deux commandes portent le même identifiant, mais leurs montants diffèrent."}},{"kind":"p","page":134,"text":{"en":"You have the current state. You don't have how it got there.","fr":"Vous connaissez l’état actuel, sans savoir comment vous y êtes arrivé."}},{"kind":"p","page":134,"text":{"en":"Your DB is a graveyard of overwritten rows.","fr":"Dans la base, chaque nouvelle version a écrasé la précédente."}},{"kind":"p","page":134,"text":{"en":"Here's the system:","fr":"Voici le système actuel :"}},{"kind":"p","page":134,"text":{"en":"• OrderService → Postgres (current state only)","fr":"• OrderService → Postgres (état actuel uniquement)"}},{"kind":"p","page":134,"text":{"en":"• Events: placed, updated, cancelled, refunded","fr":"• Événements : placed, updated, cancelled, refunded"}},{"kind":"p","page":134,"text":{"en":"• Every UPDATE overwrites the previous row","fr":"• Chaque UPDATE écrase la version précédente de la ligne."}},{"kind":"p","page":134,"text":{"en":"• No audit log. No event history. No replay.","fr":"• Aucun journal d’audit, aucun historique des événements et aucun moyen de les rejouer."}},{"kind":"p","page":134,"text":{"en":"A billing dispute just landed. You need to reconstruct exactly what happened to Order #8471. You can't.","fr":"Un litige de facturation vient d’arriver. Vous devez retracer précisément ce qui s’est passé pour la commande nº 8471, mais les données conservées ne le permettent pas."}},{"kind":"p","page":134,"text":{"en":"Instead of storing the current state, you store the sequence of events that produced it.","fr":"Au lieu de conserver seulement l’état actuel, vous décidez d’enregistrer la suite d’événements qui l’a produit."}},{"kind":"p","page":134,"text":{"en":"What's your approach when redesigning this service?","fr":"Quelle approche adoptez-vous pour repenser ce service ?"}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":135,"text":{"en":"Event Sourcing — append-only event log as the source of truth, current state derived from replaying events.","fr":"Event sourcing — prendre comme source de vérité un journal d’événements immuable, auquel on peut seulement ajouter des entrées. Rejouer les événements pour obtenir l’état courant."}}]},{"letter":"B","blocks":[{"kind":"p","page":135,"text":{"en":"Change Data Capture (CDC) — keep Postgres as-is, but stream all row changes to Kafka for an audit trail.","fr":"Change Data Capture (CDC) — conserver Postgres tel quel et transmettre chaque changement de ligne à Kafka pour constituer une piste d’audit."}}]},{"letter":"C","blocks":[{"kind":"p","page":135,"text":{"en":"Add an audit_log table — trigger-based shadow writes on every INSERT/UPDATE/DELETE.","fr":"Ajouter une table audit_log — utiliser des triggers pour journaliser en parallèle chaque INSERT, UPDATE ou DELETE."}}]},{"letter":"D","blocks":[{"kind":"p","page":135,"text":{"en":"Dual-write — write to both the current-state table and a separate events table on every operation.","fr":"Double écriture — à chaque opération, écrire dans la table de l’état courant et dans une table d’événements distincte."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"figure","page":136,"id":"136-03","width":800,"height":533,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["ystem Design Labs","ANSWER: A — EVENT SOURCING","ni","nly event log a","he","roe of","th; ¢","rent","te deriv","d from replaying events.","place / update /","append","project","‘cancel / refund","rents","state","Event Store","Queries &","Client","OrderService","(append-only fog)","Read Model","Reporting","(Postgres)","aa","Events (immutable)","placed, updated, cancelled, refunded","(timestamped, ordered)","CHANGE DATA","ADD AN AUDIT_LOG","TABLE","© cue","Ca} EVENT SOURCING","‘Append-only event log","CAPTURE (CDC)","as the source of truth;","Keep Postgres as-","‘Trigger-based shadow","Write to both the","‘current state derived","but stream all row","writes on eve","ccurrent-state table and","‘changes to Kafka for","ase","rate events table","from replaying events.","‘an audit tral","INSERT/UPDATE/DELETE.","fon every operation,","© Full replay & time travel","‘Misses in-app context","Easy to bypass or break","Dual-write inconsistency","‘and intent","[Adds write overhead,","© Projection flexibility","Hard to reconstruct","Requires distributed","business events","tohot path","transactions or outbox","Captures data changes,","Lag, ordering & schema","rot business events","Complex failure modes","© True source of truth","‘evolution challenges","Its stil a side channel","‘Schema coupling &","Not guaranteed sequence","rot the source of truth","maintenance burden","‘or completeness"],"fr":["ystem Design Labs","RÉPONSE : A — SOURCING D'ÉVÉNEMENT","ni","nly journal des événements a","il","ufs","th;","loyer","te dérivé","D de rejouer les événements.","lieu / mise à jour /","ajouter","projet","«annulation / remboursement","loyers","état","Event Store","Requêtes &","Client","OrderService","(uniquement en annexe)","Lire le modèle","Rapports","(Postgres)","aa","Événements (immuables)","placé, mis à jour, annulé, remboursé","(horodaté, commandé)","MODIFICATION DES DONNÉES","AJOUTER UN AUdité_LOG","TABLE","cue","Ca — EVENT SOURCING","‘Append-only journal des événements","CAPTURE (CDC)","comme source de vérité,","Gardez Postgres as-","«Shadow à base de déclencheur","Ecrire aux deux","«État actuel dérivé","mais stream toutes les lignes","écrit à la veille","Tableau ccurrent-state","« Changements à Kafka pour","ase","tableau des événements de taux","de rejouer les événements.","«un bilan","INSCRIRE/MISE À JOUR/SUPPRIMER.","à chaque opération,","Replay complet et voyage dans le temps","«Contexte in-app de Miss","Facile à contourner ou à casser","Incohérence de double écriture","«et l’intention","[Ajout d'une note de frais généraux,","Flexibilité de projection","Difficile à reconstruire","Nécessite une distribution","événements d'affaires","Chemin Tohot","transactions ou outbox","Capturer les changements de données,","Lag, commande et schéma","rot business events","Modes de défaillance complexes","Véritable source de vérité","«Les défis de l’évolution","Son stil un canal latéral","«Schéma de couplage &","Séquence non garantie","La source de la vérité","charge d'entretien","«ou complétude"]}},{"kind":"p","page":136,"text":{"en":"Answer: A — Event Sourcing ✅","fr":"Réponse : A — Event sourcing ✅"}},{"kind":"p","page":136,"text":{"en":"Here's why, and why the other three look reasonable but miss the point:","fr":"Voici pourquoi A convient et où les trois autres approches passent à côté du besoin."}},{"kind":"p","page":136,"text":{"en":"Why A wins (Event Sourcing):","fr":"Pourquoi retenir A — event sourcing ?"}},{"kind":"p","page":136,"text":{"en":"Event Sourcing flips the model entirely. Instead of storing the latest state and losing how you got there, you store every event that ever happened. The current state is a projection — computed by replaying events from the beginning (or from a snapshot).","fr":"L’event sourcing inverse le modèle : vous conservez chaque événement pour préserver le chemin qui a mené au résultat. L’état actuel est une projection, obtenue en rejouant les événements depuis le début ou à partir d’un instantané."}},{"kind":"p","page":136,"text":{"en":"For Order #8471: you don't query a row. You replay OrderPlaced, OrderUpdated, PaymentCaptured, RefundInitiated. Every mutation is preserved, timestamped, immutable. You can reconstruct state at any point in time. You can build new projections (e.g., \"total revenue by SKU last 90 days\") without changing the core model — just replay and project differently.","fr":"Pour la commande nº 8471, vous rejouez OrderPlaced, OrderUpdated, PaymentCaptured et RefundInitiated. Chaque modification est conservée, horodatée et immuable. Vous pouvez reconstruire l’état à tout moment de l’historique. Pour créer de nouvelles projections, par exemple le chiffre d’affaires par SKU sur les 90 derniers jours, il suffit de rejouer les mêmes événements et de calculer un autre résultat. Le modèle central reste le même."}},{"kind":"p","page":136,"text":{"en":"This is what Axon, EventStoreDB, and the event-sourced layers in most serious fintech/e-commerce systems do. It's not a log — it's the primary data model.","fr":"C’est le principe qu’appliquent Axon, EventStoreDB et les couches d’event sourcing de nombreux systèmes établis dans la fintech et le commerce en ligne. Les événements constituent le modèle de données principal."}}],[{"kind":"p","page":137,"text":{"en":"Why B is the trap (CDC):","fr":"Le piège de B — CDC"}},{"kind":"p","page":137,"text":{"en":"CDC is powerful and often underrated. Tools like Debezium + Kafka let you stream every Postgres row change downstream without touching your app. It looks like Event Sourcing from the outside — you have a sequence of changes.","fr":"La CDC est puissante et souvent sous-estimée. Avec Debezium et Kafka, vous pouvez transmettre chaque changement de ligne Postgres aux systèmes en aval sans toucher à l’application. Vue de l’extérieur, cette suite de modifications ressemble à de l’event sourcing."}},{"kind":"p","page":137,"text":{"en":"But here's the trap: CDC captures state deltas, not business events. You get total changed from 89.99 to 79.99 — not DiscountApplied by coupon SAVE10. The semantic meaning is lost. You can reconstruct what changed, not why it changed. That distinction kills you during disputes and compliance audits.","fr":"La CDC capture les changements d’état, sans leur contexte métier. Elle indique que le total est passé de 89,99 à 79,99, mais vous ne voyez pas l’événement DiscountApplied avec le code SAVE10. L’information sémantique est perdue. Vous pouvez reconstruire ce qui a changé, mais pas pourquoi. C’est déterminant en cas de litige ou d’audit de conformité."}},{"kind":"p","page":137,"text":{"en":"CDC is a great complement to Event Sourcing for propagation. It's not a substitute for it.","fr":"La CDC complète bien l’event sourcing pour diffuser des changements aux systèmes en aval."}}],[{"kind":"p","page":137,"text":{"en":"Why C is wrong (audit_log table):","fr":"Pourquoi écarter C — table audit_log ?"}},{"kind":"p","page":137,"text":{"en":"Trigger-based audit logs are the classic band-aid. The problem: you're treating the row as source of truth and logging changes as a side effect.","fr":"Le journal d’audit alimenté par des triggers est un correctif courant. La ligne reste la source de vérité et son historique dépend d’un effet secondaire de chaque modification."}},{"kind":"p","page":137,"text":{"en":"Side effects break. Triggers get disabled during migrations. Bulk imports skip them. Schema changes orphan the trigger. Six months later, the audit_log has gaps — exactly when you need it most. It's a shadow, not a foundation.","fr":"Les triggers peuvent être désactivés pendant une migration, contournés lors d’un import massif ou rendus inopérants par un changement de schéma. Six mois plus tard, audit_log présente des trous au moment où vous en avez le plus besoin. L’historique reste un sous-produit fragile du modèle de données."}}],[{"kind":"p","page":137,"text":{"en":"Why D is wrong (Dual-write):","fr":"Pourquoi écarter D — double écriture ?"}},{"kind":"p","page":137,"text":{"en":"Dual-write seems reasonable. But you've created a distributed consistency problem inside your own service. If the state write succeeds and the events write fails — network hiccup, crash, OOM — you've got state with no corresponding event. Audit trail unreliable by design.","fr":"La double écriture semble raisonnable, mais elle introduit un problème de cohérence distribuée au sein même du service. Si l’écriture de l’état aboutit et que l’enregistrement de l’événement échoue à cause du réseau, d’un crash ou d’un manque de mémoire (OOM), vous obtenez un état sans événement correspondant. La piste d’audit est donc fragile par conception."}},{"kind":"p","page":137,"text":{"en":"This is the exact problem the Outbox Pattern was invented to solve. But if you're going that far, you're halfway to proper Event Sourcing anyway.","fr":"Le pattern outbox résout précisément ce problème. En arrivant à ce niveau de complexité, vous avez déjà fait la moitié du chemin vers l’event sourcing."}}]]},{"day":34,"title":{"en":"Improving LLM Classification Accuracy","fr":"Améliorer la précision de classification d’un LLM"},"pages":[138,141],"topic":"ai","correct":"B","scenario":[{"kind":"figure","page":138,"id":"138-02","width":800,"height":420,"alt":{"en":"Day 34 featured","fr":"Illustration de la question du jour 34"},"transcript":{"en":["Your Al feature works in the demo.","system Design Labs","It fails in production 3 weeks later. WI","(Ss ome","cleaty [S| route","Support","Ingestion","Ticket","Al Triage","Classification","Internal","Channels","‘APL","Queue","Servi","Store","Teams","ume","(rr","Zero-shot with a bi","er system prompt —","Few-shot exar","— add 3-5 real classified","the instructi","\\s, add explicit category","tickets directly","1e prompt. One example","definitions, specify edge case rules. No examples.","per category edge case.","Chain-of-Thought","add\"","ink step-by-step","before answering\" to the prompt. Force the model","Self-Consistency — run each ticket through","to reason through the ticket before outputting","the model 5 times with temperature=0.7,","the category.","take the majority vote across outputs."],"fr":["Votre fonction Al fonctionne dans la démo.","système Design Labs","Il échoue en production 3 semaines plus tard. WI","(Ss ome","cleaty [S — itinéraire","Appui","Ingestion","Billet","Al Triage","Classement","Interne","Canaux","«APL","File d'attente","Servi","Stocker","Équipes","ume","(rr","Zero-shot avec un bi","er system prompt","Few-shot exar","ajouter 3-5 réels classés","Les Instructi","s, ajouter une catégorie explicite","Billets directement","1e prompt. Un exemple","définitions, spécifiez des règles de cas de bord. Pas d'exemples.","par catégorie cas de bord.","Chaîne de pensée","ajouter\"","encre étape par étape","avant de répondre\" à l'invite. Forcer le modèle","Auto-cohérence - exécuter chaque ticket à travers","raisonner à travers le ticket avant de sortir","le modèle 5 fois avec la température — 0,7,","la catégorie.","vote majoritaire sur tous les produits."]}},{"kind":"p","page":138,"text":{"en":"Your AI feature works in the demo.","fr":"Votre fonctionnalité d’IA fonctionne bien en démonstration."}},{"kind":"p","page":138,"text":{"en":"It fails in production 3 weeks later. Nobody touched the model. Nobody changed the code.","fr":"Trois semaines plus tard, elle échoue en production. Personne n’a touché au modèle ou modifié le code."}},{"kind":"p","page":138,"text":{"en":"The only thing that changed: the inputs got messier.","fr":"Seules les entrées ont changé : elles sont moins bien structurées."}},{"kind":"p","page":138,"text":{"en":"Here's the setup:","fr":"Voici la configuration."}},{"kind":"p","page":138,"text":{"en":"You're at a SaaS company. 50,000 support tickets a week. Your team builds an AI triage system — GPT-4o classifies each ticket into 6 categories (billing, bug, feature request, account access, security, other) so the right team gets it instantly.","fr":"Vous travaillez dans une entreprise SaaS qui reçoit 50 000 tickets de support par semaine. Votre équipe conçoit un système de tri par IA : GPT-4o classe chaque ticket dans l’une de six catégories (facturation, bug, demande de fonctionnalité, accès au compte, sécurité, autre) pour le transmettre immédiatement à l’équipe concernée."}},{"kind":"p","page":138,"text":{"en":"In dev, it nails 71% accuracy. You need 90%+ to cut manual review.","fr":"En développement, le modèle classe correctement 71 % des tickets. Il faut dépasser les 90 % pour réduire les vérifications manuelles."}},{"kind":"p","page":138,"text":{"en":"The model is locked. The budget for inference isn't unlimited. You need to close the 19-point gap.","fr":"Le modèle est imposé et le budget d’inférence est limité. Vous devez combler cet écart de 19 points."}},{"kind":"p","page":138,"text":{"en":"Here are your four options:","fr":"Quatre options s’offrent à vous :"}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":138,"text":{"en":"Zero-shot with a better system prompt — rewrite the instructions, add explicit category definitions, specify edge case rules. No examples.","fr":"Zero-shot avec un meilleur prompt système — réécrire les instructions, définir les catégories explicitement et préciser les règles pour les cas limites, sans ajouter d’exemple."}}]},{"letter":"B","blocks":[{"kind":"p","page":138,"text":{"en":"Few-shot examples — add 3–5 real classified tickets directly in the prompt. One example per category edge case.","fr":"Exemples few-shot — ajouter directement dans le prompt trois à cinq tickets réels déjà classés, en couvrant les cas limites des catégories."}}]},{"letter":"C","blocks":[{"kind":"p","page":139,"text":{"en":"Chain-of-Thought — add \"think step-by-step before answering\" to the prompt. Force the model to reason through the ticket before outputting the category.","fr":"Chain-of-Thought — ajouter au prompt « réfléchis étape par étape avant de répondre » pour que le modèle raisonne sur le ticket avant de renvoyer la catégorie."}}]},{"letter":"D","blocks":[{"kind":"p","page":139,"text":{"en":"Self-Consistency — run each ticket through the model 5 times with temperature=0.7, take the majority vote across outputs.","fr":"Self-Consistency — soumettre chaque ticket cinq fois au modèle avec temperature=0.7, puis retenir la catégorie majoritaire."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"p","page":140,"text":{"en":"B — Few-shot Best answer here","fr":"B — Few-shot : le meilleur choix ici"}},{"kind":"p","page":140,"text":{"en":"Accuracy: 88–93%. Cost increase: near-zero.","fr":"Exactitude : 88 à 93 %. Surcoût quasi nul."}},{"kind":"p","page":140,"text":{"en":"Few-shot shifts the model from reading rules to pattern-matching against real examples. Fundamentally stronger signal.","fr":"Avec le few-shot, le modèle peut s’appuyer sur des exemples réels pour reconnaître les bonnes catégories. Ce signal est plus fort que des règles seules."}},{"kind":"p","page":140,"text":{"en":"The part most teams get wrong: they pick the obvious examples. A crystal-clear billing ticket. A textbook bug report. Those teach the model nothing it didn't already know.","fr":"La plupart des équipes se trompent dans le choix des exemples. Un ticket de facturation sans ambiguïté ou un rapport de bug typique n’apprend rien au modèle qu’il ne sache déjà."}},{"kind":"p","page":140,"text":{"en":"You want the ambiguous ones. The ticket that looks like billing but is account access. The feature request that reads like a bug. Those are where the model currently fails — and those are the examples that close the gap.","fr":"Choisissez les cas ambigus : un ticket qui semble relever de la facturation alors qu’il s’agit d’un problème d’accès au compte, ou une demande de fonctionnalité formulée comme un bug. Le modèle se trompe sur ces cas, et ce sont ces exemples qui permettent de combler l’écart."}},{"kind":"p","page":140,"text":{"en":"Get the selection right, you close most of the 19 points without touching anything else.","fr":"Une bonne sélection suffit à récupérer l’essentiel des 19 points sans changer le reste."}}],[{"kind":"p","page":140,"text":{"en":"A — Zero-shot with a better system prompt","fr":"A — Zero-shot avec un meilleur prompt système"}},{"kind":"p","page":140,"text":{"en":"Accuracy ceiling: ~78–82%.","fr":"Plafond d’exactitude : environ 78 à 82 %."}},{"kind":"p","page":140,"text":{"en":"This is where every team starts. You iterate the prompt, add category definitions, enumerate edge cases. It feels like progress. And for a while it is.","fr":"Les équipes commencent généralement ici : elles affinent le prompt, définissent les catégories et énumèrent les cas limites. Les résultats s’améliorent pendant un temps."}},{"kind":"p","page":140,"text":{"en":"The hard wall: instructions describe categories. They can't show the model where the ambiguous cases land.","fr":"Les instructions décrivent les catégories, mais elles ne montrent pas au modèle comment trancher les cas ambigus."}},{"kind":"p","page":140,"text":{"en":"Real example: you define \"billing\" as anything about charges or invoices. Then you get this ticket — \"I can't log in and I was charged twice last month.\" Billing? Account access? Both?","fr":"Exemple réel : vous définissez la catégorie « facturation » comme tout ce qui concerne les paiements ou les factures. Puis ce ticket arrive : « Je ne peux pas me connecter et j’ai été débité deux fois le mois dernier. » Faut-il le classer dans « facturation », dans « accès au compte », ou dans les deux ?"}},{"kind":"p","page":140,"text":{"en":"No amount of rewriting tells the model which bucket that gets. It guesses wrong 20–25% of the time on edge cases. And your dataset is full of edge cases. The ceiling is real.","fr":"Reformuler les instructions ne suffit pas à indiquer au modèle quelle catégorie retenir. Il se trompe dans 20 à 25 % des cas limites, qui sont nombreux dans votre jeu de données. Cela fixe un plafond aux gains possibles."}}],[{"kind":"p","page":141,"text":{"en":"C — Chain-of-Thought","fr":"C — Chain-of-Thought"}},{"kind":"p","page":141,"text":{"en":"Accuracy delta: ±2%. Latency: +200–400ms.","fr":"Variation d’exactitude : ±2 %. Latence supplémentaire : 200 à 400 ms."}},{"kind":"p","page":141,"text":{"en":"CoT is the most misapplied technique in production AI right now. Teams add \"think step-by-step\" to everything. For some tasks it works. Not this one.","fr":"La Chain-of-Thought (CoT) est l’une des techniques d’IA les plus souvent utilisées à mauvais escient en production. Les équipes ajoutent « réfléchis étape par étape » partout. Cela aide sur certaines tâches. Ici, l’effet est limité."}},{"kind":"p","page":141,"text":{"en":"Why it struggles here: the model generates a reasoning chain, then commits to a label. On ambiguous tickets, that chain becomes a liability. \"Mentions a charge... but also a login issue... charge is mentioned first... probably billing.\" It picks billing. Right answer is account access.","fr":"Le modèle produit une chaîne de raisonnement, puis se fixe sur une catégorie. Sur un ticket ambigu, ce raisonnement peut l’égarer : « Il est question d’un débit, mais aussi d’un problème de connexion. Le débit apparaît en premier, donc c’est probablement de la facturation. » Le modèle choisit « facturation » alors que le ticket relève de l’accès au compte."}},{"kind":"p","page":141,"text":{"en":"CoT helps when the answer emerges from reasoning — math, debugging, planning. For classification, the answer emerges from calibration. Reasoning doesn't substitute for calibration.","fr":"La CoT aide lorsque la réponse découle d’un raisonnement, par exemple en mathématiques, en débogage ou en planification. Pour la classification, c’est le calibrage des catégories qui importe. Le raisonnement seul ne peut pas fournir ce calibrage."}},{"kind":"p","page":141,"text":{"en":"Layer it on top of few-shot if you're still missing edge cases. Don't reach for it first.","fr":"Vous pouvez ajouter la CoT au few-shot si des cas limites restent mal traités. Commencez avec les exemples."}}],[{"kind":"p","page":141,"text":{"en":"D — Self-Consistency","fr":"D — Self-Consistency"}},{"kind":"p","page":141,"text":{"en":"Accuracy: 93–96%. Cost: 5x. Latency: 5x.","fr":"Exactitude : 93 à 96 %. Coût et latence multipliés par cinq."}},{"kind":"p","page":141,"text":{"en":"Run the same ticket 5–10x at temperature=0.7, take the majority vote. Works because each run samples a slightly different path — noise cancels out across runs.","fr":"Soumettez le même ticket 5 à 10 fois avec temperature=0.7 et retenez le résultat majoritaire. Chaque exécution échantillonne un chemin un peu différent, ce qui atténue le bruit."}},{"kind":"p","page":141,"text":{"en":"The math is good. The cost is brutal.","fr":"Le principe fonctionne, mais coûte cher."}},{"kind":"p","page":141,"text":{"en":"50K tickets/week × $0.002 × 5 runs = $500/week vs $100/week with few-shot. You're paying $400/week extra for a 3–5% gain on the hardest cases.","fr":"50 000 tickets par semaine × 0,002 $ × 5 exécutions = 500 $ par semaine, contre 100 $ avec le few-shot. Vous dépensez 400 $ de plus par semaine pour gagner 3 à 5 % sur les cas les plus difficiles."}},{"kind":"p","page":141,"text":{"en":"Worth it when being wrong is expensive: fraud detection (a missed flag costs hundreds), medical triage (wrong category = real harm). For support routing, a misclassified ticket costs ~$0.10 of human rerouting time. Use B.","fr":"Ce coût se justifie si une erreur a de graves conséquences, par exemple en détection de fraude, où une alerte manquée coûte des centaines de dollars, ou en triage médical, où une mauvaise catégorie peut faire du tort. Au support, un ticket mal classé coûte environ 0,10 $ de temps humain pour le réorienter. Retenez B."}}]]},{"day":35,"title":{"en":"Geospatial “Find Nearby Drivers” at Scale","fr":"Trouver les chauffeurs à proximité à grande échelle"},"pages":[142,147],"topic":"scale","correct":"D","scenario":[{"kind":"figure","page":142,"id":"142-02","width":800,"height":421,"alt":{"en":"Day 35 featured","fr":"Illustration de la question du jour 35"},"transcript":{"en":["1 Design Labs","You're building the \"find nearby drivers\" feature","for a ride-hailing app.","(GPS Update","Write / Update","Location","(within nd","(9)","Driver App","Ingestion","Driver Location","Nearby Drivers","Rider App","Servic","‘Store","Service","(100K as)","(600K+ Active Drivers)","eed Fetch","Nearby Drivers","Geohash partitioning — Encode each driver's","PostGIS with spatial indexes — Add a PostGIS","location into a geohash string. Index by","‘extension to Postgres. Use a proper R-tree/GiST","spatial index for bounding-box and","A]","geohash prefix. Proximity queries become a","radius que","string lookup on th","‘Quadtree in memory —","active driver","3 hexagonal grid (Uber's eystom) — Divide","positions in a quadtree di","structure in a","the earth into hexagonal cells at mul","Redi","backed in-memory service. Decompose","resolutions. Assign each driver toa","‘Queri","space recursively until each cell has = N drivers.","check the target cell +6 neighbors at the right"],"fr":["1 Design Labs","Vous construisez la fonction \"trouver les conducteurs à proximité\"","pour une application de ride-hailing.","(mise à jour GPS)","Écrire / Mettre à jour","Emplacement","(dans la","(9)","Driver App","Ingestion","Emplacement du conducteur","Conducteurs à proximité","Rider App","Servic","«Store","Service","(100K as)","(600K+ Pilotes actifs)","eed Fetch","Conducteurs à proximité","Geohash partitionnement — Encoder chaque pilote","PostGIS avec index spatiaux — Ajouter un PostGIS","dans une chaîne de caractères geohash. Index by","Utilisez un arbre R/GiST approprié.","un indice spatial pour le bounding-box et","A]","préfixe geohash. Les requêtes de proximité deviennent","rayon que","string lookup sur la","«Quadtree en mémoire","conducteur actif","3 quadrillage hexagonal (eystom d'Uber) — Diviser","positions dans un quadtree di","structure en a","la terre en cellules hexagonales à mul","Redi","service en mémoire sauvegardé. Decompose","résolution. Assigner chaque conducteur","«Queri","espace récursivement jusqu'à ce que chaque cellule ait — N pilotes.","vérifier la cellule cible +6 voisins à droite"]}},{"kind":"p","page":142,"text":{"en":"You're building the \"find nearby drivers\" feature for a ride-hailing app.","fr":"Vous développez la fonctionnalité « trouver les chauffeurs à proximité » d’une application de VTC."}},{"kind":"p","page":142,"text":{"en":"At peak, you have 500,000 active drivers updating their GPS location every 5 seconds. Riders query for drivers within 2km. At scale, you're doing ~100,000 proximity queries per second.","fr":"En période de pointe, 500 000 chauffeurs actifs mettent à jour leur position GPS toutes les cinq secondes. Les passagers cherchent des chauffeurs dans un rayon de 2 km. À grande échelle, cela représente environ 100 000 requêtes de proximité par seconde."}},{"kind":"p","page":142,"text":{"en":"Your naive implementation does this:","fr":"Votre première implémentation utilise cette requête :"}},{"kind":"code","page":142,"text":{"en":"SELECT *\nFROM drivers\nWHERE lat BETWEEN ? AND ? AND lng BETWEEN ? AND ?","fr":"SELECT *\nFROM drivers\nWHERE lat BETWEEN ? AND ? AND lng BETWEEN ? AND ?"}},{"kind":"p","page":142,"text":{"en":"It works fine at 1,000 drivers. At 500,000, it's a full table scan on every query. Latency hits 800ms. Riders see a spinner. Drivers miss trips.","fr":"À 1 000 chauffeurs, tout va bien. À 500 000, chaque requête parcourt toute la table. La latence atteint 800 ms. Les passagers attendent sur l’écran de chargement et les chauffeurs ratent des courses."}},{"kind":"p","page":142,"text":{"en":"Your team proposes 4 approaches to fix this:","fr":"L’équipe propose quatre approches :"}}],"postScenario":[{"kind":"p","page":143,"text":{"en":"You need sub-50ms p99 latency, real-time updates, and it has to stay accurate at cell boundaries.","fr":"La latence p99 doit rester sous les 50 ms. Les positions doivent être mises à jour en temps réel et les recherches doivent rester précises aux frontières entre cellules."}}],"choices":[{"letter":"A","blocks":[{"kind":"p","page":142,"text":{"en":"Geohash partitioning — Encode each driver's location into a geohash string. Index by geohash prefix. Proximity queries become a string lookup on the index.","fr":"Partitionnement par geohash — encoder la position de chaque chauffeur dans une chaîne geohash et indexer les préfixes. Rechercher les chauffeurs proches revient à consulter les chaînes dans l’index."}}]},{"letter":"B","blocks":[{"kind":"p","page":143,"text":{"en":"PostGIS with spatial indexes — Add a PostGIS extension to Postgres. Use a proper R-tree/GiST spatial index for bounding-box and radius queries.","fr":"PostGIS avec index spatiaux — ajouter l’extension PostGIS à Postgres. Utiliser un index spatial R-tree ou GiST pour les requêtes par rectangle englobant et par rayon."}}]},{"letter":"C","blocks":[{"kind":"p","page":143,"text":{"en":"Quadtree in memory — Keep all active driver positions in a quadtree data structure in a Redis-backed in-memory service. Decompose space recursively until each cell has ≤ N drivers.","fr":"Quadtree en mémoire — stocker les positions des chauffeurs actifs dans un quadtree au sein d’un service en mémoire adossé à Redis. Subdiviser l’espace de façon récursive jusqu’à ce que chaque cellule contienne au plus N chauffeurs."}}]},{"letter":"D","blocks":[{"kind":"p","page":143,"text":{"en":"H3 hexagonal grid (Uber's system) — Divide the earth into hexagonal cells at multiple resolutions. Assign each driver to a cell. Queries check the target cell + 6 neighbors at the right resolution.","fr":"Grille hexagonale H3 (le système d’Uber) — diviser le globe en cellules hexagonales à plusieurs niveaux de résolution. Associer chaque chauffeur à une cellule. Pour une requête, examiner la cellule cible et ses six voisines à la résolution appropriée."}}]}],"afterChoices":[],"answerIntro":[{"kind":"p","page":144,"text":{"en":"Every option here ships with its own diagram, so no single image marks the answer; the author's pick is D — H3 Hexagonal Grid (Answer 1 below).","fr":"Chaque option a son propre schéma, sans que l’un d’eux signale à lui seul la bonne réponse. Le choix de l’auteur est D, la grille hexagonale H3 (voir la réponse 1 ci-dessous)."}}],"explanations":[[{"kind":"figure","page":144,"id":"144-07","width":800,"height":533,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["System Design Labs","ANSWER: D — H3 Hexagonal Grid","\" at scale.","Best for accurate, low-latency “find nearby driver","itant","K-ring guarantees","‘Sub-10ms lookups","Proven at seale","neighbors","From continent to","accuracy","at millions","Used by Uber, yt","Target cel «6 neighbors","€2)","fing query + Redia","‘Aironb, DoorDash","(0% closer tan","‘eindexing needed.","no misses at","squares)","boundaries,","Ds.","sete","Hexagons > Squares","Hexagons hve 6 equistant neighbor, Squares (ahah)","bad","have corner neighbors ~40% farther, istorting “within en”","(0)","Diver Ae","Nearby Drivers","Rider App","ors","Service","No misses at boundaries","‘The ketng (argt cell + 6 neighbors) covers the entire aes","within the rads. Drivers near edges are never mizeed","Fetch er","Multi-resoltion, no reindexing","Ha provides 16 resolutions. Zoam in/out by picking ferent","rea» no data migration or eindexing,","as","calls Gneighbors","Blazing fast at sca","© vein","Get els in kcring — pipeline fetch diver set from Reis +","Net quai","‘ear boundaries,","Battle-tested","ATA","User open-sourced H3 fortis exact use cas, Used by","elton","Uber, ft Arbab, DorDach,nstacar, and more,","GLANCE","UNE: H3 gh","urate, oundar","mult","lution pe","with sub:","om","atmassive"],"fr":["System Design Labs","RÉPONSE: D — H3 Grille hexagonale","\" à l'échelle.","Idéal pour précis, à faible latence “trouver le conducteur à proximité","itant","Garanties K-ring","«Recherche de Sub-10ms","Prouvé à Seale","voisins","Du continent à","précision","en millions","Utilisé par Uber, yt","Cible cel «6 voisins","€2)","Requête fing + Redia","«Aironb, DoorDash","(0% bronzage plus proche)","« L’indexation est nécessaire.","Aucun manque à","carrés)","frontières,","Ds.","sete","hexagones > carrés","Hexagons hve 6 equistant neighbor, Squares (ahah)","Mauvais","ont des voisins d'angle — 40% plus loin, istorting \"inside en\"","(0)","Diver Ae","Conducteurs à proximité","Rider App","ors","Service","Ne manquez pas les frontières","Le ketng (cellule d'arc + 6 voisins) couvre l'ensemble des aes","Dans les rads. Les conducteurs proches des bords ne sont jamais confondus","Récupérer","Multi-résolution, pas de réindexation","Ha fournit 16 résolutions. Zoam in/out en choisissant ferent","aucune migration ou eindexation des données,","en","appelle Gneighbors","Blazing rapide à sca","veine","Obtenez els dans kcring — pipeline fetch diver set from Reis +","Net quai","«frontières de l'oreille,","Test de combat","ATA","Utilisateur open-source H3 fortis utilisation exacte cas, Utilisé par","elton","Uber, ft Arbab, DorDach, nstacar, et plus encore,","GLANCE","UNE: H3 gh","urate, oundar","mult","lution pe","avec sub:","om","atmassif"]}},{"kind":"p","page":144,"text":{"en":"Answer: D — H3 Hexagonal Grid","fr":"Réponse : D — Grille hexagonale H3"}},{"kind":"p","page":144,"text":{"en":"Why D wins:","fr":"Pourquoi D fonctionne"}},{"kind":"p","page":144,"text":{"en":"Uber open-sourced H3 for exactly this problem. Hexagons have 6 neighbors, all equidistant from the center. Squares (geohash) have corner neighbors that are ~40% farther — this distorts \"within 2km\" queries. H3 also has 16 resolution levels (no reindexing on zoom changes). The killer feature: the k-ring query (target cell + 6 neighbors) guarantees no driver gets missed near a boundary. Uber does sub-10ms lookups at millions of drivers: get cells in ring → fetch IDs from Redis set keyed by cell. Lyft, Airbnb, DoorDash all use variants.","fr":"Uber a publié H3 en open source précisément pour ce problème. Un hexagone a six voisins à égale distance de son centre. Pour les cellules carrées du geohash, les voisins en diagonale sont environ 40 % plus éloignés, ce qui fausse les recherches « dans un rayon de 2 km ». H3 propose aussi 16 niveaux de résolution, ce qui évite de réindexer les données à chaque changement de zoom. Le point décisif est la requête k-ring : en examinant la cellule cible et ses six voisines, on évite de rater un chauffeur près d’une frontière. Uber effectue des recherches en moins de 10 ms sur des millions de chauffeurs : le système trouve les cellules de l’anneau, puis récupère leurs identifiants dans des ensembles Redis indexés par cellule. Lyft, Airbnb et DoorDash utilisent des variantes de cette approche."}}],[{"kind":"figure","page":145,"id":"145-01","width":800,"height":533,"alt":{"en":"Answer 2 diagram","fr":"Schéma de l’explication 2"},"transcript":{"en":["System Design Lal","ANSWER:","Production-grade, widely used — and wrong for real-time, sub-km proximity.","Boundary misses","Zeorder curve problem","Good for partitioning,","Latency suffers","Divers part can nd","not proximity","boundary mises","ty eo, Wong fra","‘ancy and eos","time sub em oka.","Not boundary-safe","1011","on | HS","Edges and comers cause misses","Diver Bre","Pon iter","ents","Fetch te De","Unpredictable coverage","ie","ry","eatery ses","(610 40+), More cle = more eade+ firing","rey","5 EXAMPLE","Higher latency at scale","More prefs —+ more date ead —+ mere posttering,","Dara","‘wort retin bth,","No built-in neighbor guarantee","[om [Of | |","lon >","You must manually compute which ajacent prefies","tence. Eos to get wrong, ill nt perfect.","| ow","‘Wrong tool forthe job","Great for coarse partioning / sharing aching by region","Wong fr ea-ime, accurate, sub-km proxy search.","Bottom line:","Geohash isthe trap It looks simple, works at low sca","bait guarantees missos atthe boundaries.","‘At 100K GPS with sub-2km accuracy requirements it will hurt riders and drivers.","like H3 (hex grid) instead,"],"fr":["System Design Lal","RÉPONSE :","Production de qualité, largement utilisé - et mal pour le temps réel, sous-km de proximité.","Boundary miss","Problème de courbe de Zeorder","Bon pour le partage,","La latence souffre","Divers partie peut nd","pas de proximité","Mises limites","ty eo, Wong fra","«ancy et eos","temps sub em oka.","Pas de limite de sécurité","1011","sur — HS","Bords et comers provoquent des miss","Diver Bre","Pon iter","ents","Fetch te De","Couverture imprévisible","ie","ry","Eatery Ses","(610 40+), Plus de cle — plus de tir eade+","rey","5 EXEMPLE","Une latence plus élevée à l'échelle","Plus prefs — plus date ead — simple posttering,","Dara","«doivent être retin bth,","Aucune garantie de voisin intégrée","[Om [De","lon >","Vous devez calculer manuellement ce qui précède acent","Eos se trompe, il est parfait.","ow","«Le mauvais outil pour le travail","Idéal pour cloisonnement grossier / partage douloureux par région","Wong fr ea-ime, précis, recherche par proxy sub-km.","Bottom line:","Geohash estle piège Il semble simple, fonctionne à faible sca","appât garantit missos aux limites.","« À 100K GPS avec des exigences de précision inférieures à 2 km, cela nuira aux coureurs et aux conducteurs.","comme H3 (hex grid) à la place,"]}},{"kind":"p","page":145,"text":{"en":"Why A is the trap (Geohash):","fr":"Le piège de A — geohash"}},{"kind":"p","page":145,"text":{"en":"Production-grade, widely used — and wrong here. Geohash uses a Z-order curve (interleaved bits) that doesn't guarantee geographic adjacency for adjacent prefix strings. Two drivers 1 meter apart can have entirely different prefix strings if they straddle a cell boundary. This becomes a systematic miss rate at 100k queries/sec. Geohash is right for coarse partitioning (sharding by region), wrong for real-time sub-km proximity.","fr":"Le geohash est largement utilisé en production. Il s’appuie sur une courbe de Morton (Z-order), qui entrelace des bits. Des préfixes voisins dans cet ordre ne garantissent pas la proximité géographique. Deux chauffeurs séparés d’un mètre peuvent avoir des préfixes très différents s’ils se trouvent de part et d’autre d’une frontière. À 100 000 requêtes par seconde, ces recherches manquées deviennent systématiques. Le geohash convient pour du partitionnement grossier, par exemple du sharding par région. Il convient mal aux recherches de proximité subkilométriques en temps réel."}}],[{"kind":"figure","page":146,"id":"146-01","width":800,"height":533,"alt":{"en":"Answer 3 diagram","fr":"Schéma de l’explication 3"},"transcript":{"en":["System Design Labs","ANSWER:","PostGiS is correct — just not for 500k drivers updating every 5 seconds.","Write-heavy workload","GIST inex is","Database burns","Hard to scale","Latency sutfers","‘capacity on index","writes","under load","(600k avers = 12","ery write updates","al","Content, VACUUM,","rule nex pages.","owe sale wos","Bet, and ck","> SS","106,000 wrte/see","GIST index write amplification","spans GIST index","touches mate nex peg,","rh","Database becomes write-bound","cy","‘8 100 wtes/ec, most CPU, IOS, and memory goto index","rs tte","maintenance, not serving que,","Vertes scaling hits","wal","Postret/PstGS sales up not out Bigger box = temporary","+ Each tutes abe Tier","Operational overiead grows","1 nd ot grows VACUUM cr hep","Not bul for real-time, label, massive sale","Great for thousands to toe ofhouzande Noto SOK divers","‘POSTGIS 6 THE STARTING POINT,","NOT THE DESTINATION","| @ cooane","BOTTOM LINE","0k ete vere","Posts ie","right tool for comet","+ owe 5000 ste","But at 500K cvers wth 100k wrtes/ne ft becomes the bottleneck,","+ Ane pt oes","‘You spend mor te iting the databae than bln fests.","+ tera tle","cee)","Use PostGi to validate. Use H3 + Reds to scale."],"fr":["System Design Labs","RÉPONSE :","PostGiS est correct, mais pas pour les pilotes 500k mis à jour toutes les 5 secondes.","Charge de travail lourde","GIST inex est","Brûlures de base de données","Difficile à mettre à l'échelle","Sutfers de latence","«Capacité sur indice","écrit","sous charge","(600k avers — 12","ery écrire des mises à jour","al","Contenu, VACUUM,","Les pages nex.","wealth sale wos","Pari, et ck","> SS","106 000 wrte/voir","Amplification de l'écriture de l'indice GIST","Spans indice GIST","Touche Peg Mate Nexus,","rh","Base de données devient write-bound","cy","‘8 100 wtes/ec, la plupart des CPU, IOS, et l’index goto de mémoire","rs tte","entretien, ne servant que,","Vertes scaling hits","wal","Les ventes de Postret/PstGS ne sortent pas plus grandes — temporaire","+ Chaque tutes abe Tier","L’excès opérationnel grandit","1 nd ot cultive VACUUM cr hep","Pas bul pour le temps réel, étiquette, vente massive","Idéal pour des milliers de plongeurs Noto SOK","«POSTGIS 6 LE POINT DE DÉPART,","PAS LA DESTINATION","cooane","LIGNE DE FAUTE","0k ete vere","Postes ie","bon outil pour la comète","+ doit 5000 ste","Mais à 500K cvers wth 100k wrtes/ne ft devient le goulot d'étranglement,","+ Ane pt oes","«Vous dépensez beaucoup plus pour les databae que pour les fests.","+ téra tle","cee)","Utilisez PostGi pour valider. Utilisez H3 + Reds pour mettre à l'échelle."]}},{"kind":"p","page":146,"text":{"en":"Why B fails at scale (PostGIS):","fr":"Pourquoi B atteint ses limites à grande échelle — PostGIS"}},{"kind":"p","page":146,"text":{"en":"PostGIS is correct — it's the right answer for 5,000 trucks on a fleet dashboard. Not for 500k drivers updating every 5s. The math: 500k × 12 updates/min = 100k writes/sec against a GiST index. GiST indexes are write-expensive. Your DB burns half its capacity on index maintenance. And you can't easily scale Postgres writes horizontally. PostGIS is the starting point — H3 + Redis is where you land when it breaks.","fr":"PostGIS convient pour suivre 5 000 camions sur un tableau de bord de flotte. Avec 500 000 chauffeurs qui actualisent leur position toutes les cinq secondes, le calcul change : 500 000 × 12 mises à jour par minute, soit 100 000 écritures par seconde sur un index GiST. La maintenance de cet index coûte cher en écriture et absorbe la moitié de la capacité de la base. Il est en outre difficile de répartir horizontalement les écritures Postgres. PostGIS est un bon point de départ. H3 avec Redis prend le relais à cette échelle."}}],[{"kind":"figure","page":147,"id":"147-01","width":800,"height":533,"alt":{"en":"Answer 4 diagram","fr":"Schéma de l’explication 4"},"transcript":{"en":["‘System Design Labs","ANSWER:","Great in theory (O(log n)). Breaks under ride-hailing scale and real-world density.","‘tog operations","High harm rte","Sane bry pian","rt et, ad","Sider cy","22)","x%","ep ire","High wit amplification","Diver Ae","anda Drier","ines ter ound cl ge. Sal GPS nla ~ vances","por","4 fate an center","cae vy en","(usr becomes og Kwa","sepals alto gt it","BOTTOM LINE","Bice te hang ssl ite churn, boundary ves an inbaance","1 sc Sm 601A","Deets + rar + (Maybe) Rabalnce","= Mion of rode pute","Ite bling block ~ not the fil elton HS Rei wn.","| A"],"fr":["«System Design Labs","RÉPONSE :","Grande en théorie (O (log n)). Pauses sous l'échelle de conduite et la densité du monde réel.","«opérations tog","Risques élevés","Sane bry pian","rt et, ad","Sidercy","22)","x%","ep ire","Amplification élevée de l'esprit","Diver Ae","anda Drier","ines ter onde cl ge. Sal GPS nla — ances","por","4 destin un centre","cae vy en","(usr devient og Kwa","sépales alto gt il","LIGNE DE FAUTE","Bice te hang ssl ite churn, boundary ves an inbaance","1 sc Sm 601A","Deets + rar + (Peut-être) Rabalnce","Mion de rode pute","Ite bling block — pas le fil elton HS Rei wn.","A"]}},{"kind":"p","page":147,"text":{"en":"Why C almost works (Quadtree):","fr":"Pourquoi C peut presque convenir — quadtree"}},{"kind":"p","page":147,"text":{"en":"O(log n) insert/query, great in theory. Breaks at ride-hailing density: driver crossing a cell boundary = delete + reinsert + potential rebalancing, 100k times per second. Same rectangular boundary problem as geohash. Dense cities create deep uneven trees. A quadtree is a building block — not a complete solution at this scale.","fr":"Les insertions et les recherches sont en O(log n), ce qui est intéressant en théorie. À la densité d’un service de VTC, chaque franchissement de frontière entraîne une suppression, une réinsertion et éventuellement un rééquilibrage, jusqu’à 100 000 fois par seconde. Les frontières rectangulaires posent le même problème qu’avec le geohash. Les villes denses produisent des arbres profonds et irréguliers. Le quadtree peut servir de brique de base. À cette échelle, il ne suffit pas à lui seul."}}]]},{"day":36,"title":{"en":"Choosing HTTP/3 vs HTTP/2 at the Edge","fr":"Choisir entre HTTP/3 et HTTP/2 à l’edge"},"pages":[148,151],"topic":"scale","correct":"D","scenario":[{"kind":"figure","page":148,"id":"148-02","width":800,"height":420,"alt":{"en":"Day 36 featured","fr":"Illustration de la question du jour 36"},"transcript":{"en":["m Design|","You're seeing 800ms+ p99 latency in high packet-loss networks.","Your CDN supports HTTP/2 and HTTP/3. What do you enable?","HTTPS","ms)","Mobile App","CON","Load Balancer","Origin","HTTP/2 only — multiplexing over a single TCP","HTTP/3 only — built on QUIC (UDP), eliminates","connection eliminates the old HTTP/1.1","TCP head-of-jine blocking entirely, 0-RTT","head-of-line problem. Proven, widely supported.","connection resumption. Modern clients handle it fine.","HTTP/2.to origin, HTTP/2 to clients — maximize","HTTP/3 to clients, HTTP/2 to origin — QUIC","multiplexing end-to-end, avoid QUIC instability","handles the lossy last mile, HTTP/2 handles","in enterprise firewalls","the stable datacenter leg."],"fr":["m Design","Vous voyez 800ms + p99 latence dans les réseaux à forte perte de paquets.","Votre CDN prend en charge HTTP/2 et HTTP/3. Qu'activez-vous ?","HTTPS","ms)","App mobile","CON","Balanceur de charge","Origine","HTTP/2 uniquement — multiplexage sur un seul TCP","HTTP/3 uniquement — construit sur QUIC (UDP), élimine","La connexion élimine l'ancien HTTP/1.1","Blocage TCP tête de jine entièrement, 0-RTT","problème de tête de ligne. Prouvé, largement soutenu.","reprise de connexion. Les clients modernes le gèrent bien.","HTTP/2.to origin, HTTP/2 pour les clients — maximiser","HTTP/3 aux clients, HTTP/2 à l'origine — QUIC","multiplexage de bout en bout, éviter l'instabilité QUIC","gère le dernier kilomètre perdu, poignées HTTP/2","dans les pare-feu d'entreprise","la jambe stable du centre de données."]}},{"kind":"p","page":148,"text":{"en":"Your API response went from 320ms to 95ms after a CDN switch.","fr":"Le temps de réponse de votre API est passé de 320 ms à 95 ms après un changement de CDN."}},{"kind":"p","page":148,"text":{"en":"Nothing changed on the server. Same origin. Same payload.","fr":"Côté serveur, rien n’a changé : même origine, même contenu de la réponse."}},{"kind":"p","page":148,"text":{"en":"The only difference: the CDN started speaking HTTP/3 to your clients.","fr":"Seul le protocole a changé : le CDN communique désormais en HTTP/3 avec les clients."}},{"kind":"p","page":148,"text":{"en":"Here's the setup:","fr":"Voici la configuration."}},{"kind":"p","page":148,"text":{"en":"Mobile app → Load Balancer → Origin (NestJS) → DB","fr":"Application mobile → répartiteur de charge → serveur d’origine (NestJS) → base de données"}},{"kind":"p","page":148,"text":{"en":"Every request goes through the CDN first. Latency is acceptable — until high packet-loss environments (mobile 4G → 5G transitions, flaky WiFi, Asia-Pacific routes). You're seeing 800ms+ tail latency for the p99. The CDN supports HTTP/2 and HTTP/3. What do you enable?","fr":"Toutes les requêtes passent d’abord par le CDN. La latence est acceptable, sauf lorsque le réseau perd beaucoup de paquets : transition entre 4G et 5G, Wi-Fi instable ou routes vers l’Asie-Pacifique. La latence p99 dépasse 800 ms. Le CDN prend en charge HTTP/2 et HTTP/3. Quelle configuration activez-vous ?"}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":148,"text":{"en":"HTTP/2 only — multiplexing over a single TCP connection eliminates the old HTTP/1.1 head-of-line problem. Proven, widely supported.","fr":"HTTP/2 uniquement — multiplexer les flux sur une seule connexion TCP pour résoudre l’ancien problème de blocage en tête de ligne d’HTTP/1.1. L’approche est éprouvée et largement prise en charge."}}]},{"letter":"B","blocks":[{"kind":"p","page":148,"text":{"en":"HTTP/3 only — built on QUIC (UDP), eliminates TCP head-of-line blocking entirely, 0-RTT connection resumption. Modern clients handle it fine.","fr":"HTTP/3 uniquement — utiliser QUIC sur UDP pour éliminer le blocage en tête de ligne lié à TCP et reprendre une connexion en 0-RTT. Les clients modernes le prennent en charge."}}]},{"letter":"C","blocks":[{"kind":"p","page":149,"text":{"en":"HTTP/2 to origin, HTTP/2 to clients — maximize multiplexing end-to-end, avoid QUIC instability in enterprise firewalls.","fr":"HTTP/2 vers l’origine et vers les clients — profiter du multiplexage de bout en bout et éviter les problèmes que QUIC peut rencontrer avec les pare-feu d’entreprise."}}]},{"letter":"D","blocks":[{"kind":"p","page":149,"text":{"en":"HTTP/3 to clients, HTTP/2 to origin — QUIC handles the lossy last mile, HTTP/2 handles the stable datacenter leg.","fr":"HTTP/3 vers les clients et HTTP/2 vers l’origine — laisser QUIC gérer le dernier kilomètre, sujet aux pertes, et utiliser HTTP/2 sur le segment stable du centre de données."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"figure","page":150,"id":"150-03","width":800,"height":533,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["tom De","— HTTP/3 to clients, HTTP/2 to origin","Last Mile","Datacenter Link","High Loss","Low Loss","sat","HTTP/3","(quic / upp)","(reP/T1s)","Mobile App","CDN (Edge)","Load Balancer","Origin","DB","CLIENT SIDE (LAST MILE) — HTTP/3 over QUIC","‘The problem i the last mil","‘Stable, low-oss private network","HTTP/2 over TCP","‘TePSs transport-layer HOL blocking","kis performance on lossy mobile","connections","aa","HTTP/2's proven and highl efficient","(vs)","een","Lower CPU overhead","oops other streams moving","‘QUIC encrypts everything at the","transport ayer — no cleartext, ever.","‘One lost packet","‘tals ALL streams","tals ONLY that stream","leverages a stable network and","(other steams keep flowing)","Datacenter fre","nd toting","avoids QUIC' crypto CPU overhead.","Better compatibility with existing","‘This isthe production pattern used","O-RTT Resumption","by Cloudare,Fastly, and Akama","Saves 1-2 ound trips. on ever reconnect","Industry Standard: Major CONs use HTTP/3 onthe edge-facng side and HTTP/2 on the rign-facing side","It deivers the best performance where it matters, wth the right tradeoffs where it doesnt."],"fr":["tom De","HTTP/3 aux clients, HTTP/2 à l'origine","Last Mile","Datacenter Link","Perte élevée","Faible perte","sat","HTTP/3","(quic / upp)","(reP/T1)","App mobile","CDN (bord)","Balanceur de charge","Origine","DB","Côté client (dernier mile) — HTTP/3 sur QUIC","Le problème du dernier mil","« Réseau privé stable et à faible encombrement","HTTP/2 sur TCP","Blocage HOL de la couche de transport TePSs","kis performance sur lossy mobile","connexions","aa","HTTP/2 est éprouvé et très efficace","(vs)","een","Dépassement du CPU inférieur","oups d'autres flux en mouvement","QUIC crypte tout au","transport ayer — pas de texte clair, jamais.","«Un paquet perdu","«tous les flux","Uniquement ce flux","d’un réseau stable et","(d'autres vapeurs continuent à couler)","Datacenter fre","nd toting","évite la surcharge du CPU cryptographique de QUIC.","Meilleure compatibilité avec les systèmes existants","«C’est le modèle de production utilisé","O-RTT Reprise","par Cloudare, Fastly et Akama","Économise 1-2 voyages d'ound. sur jamais reconnecter","Norme de l'industrie: Les principaux clients utilisent HTTP/3 du côté de l'interface de bord et HTTP/2 du côté du trucn","Il offre la meilleure performance là où il importe, avec les bons compromis là où il ne l'est pas."]}},{"kind":"p","page":150,"text":{"en":"Answer: D — HTTP/3 to clients, HTTP/2 to origin","fr":"Réponse : D — HTTP/3 côté clients, HTTP/2 côté serveur d’origine"}},{"kind":"p","page":150,"text":{"en":"The problem is the last mile. Mobile clients on lossy connections are where TCP falls apart.","fr":"Le problème se joue sur le dernier kilomètre : lorsque les clients mobiles perdent des paquets, TCP les ralentit."}},{"kind":"p","page":150,"text":{"en":"HTTP/2 fixed HTTP/1.1's application-layer head-of-line blocking by multiplexing streams over one TCP connection. But TCP itself still has head-of-line blocking at the transport layer. A single lost packet stalls ALL streams until it's retransmitted. On a 4G connection dropping 2% of packets, your 20-stream HTTP/2 connection grinds to a halt.","fr":"HTTP/2 a supprimé le blocage en tête de ligne d’HTTP/1.1 au niveau applicatif en multiplexant les flux sur une même connexion TCP. Le blocage subsiste au niveau transport de TCP : la perte d’un seul paquet bloque tous les flux jusqu’à sa retransmission. Sur une connexion 4G qui perd 2 % de ses paquets, vos 20 flux HTTP/2 se retrouvent ralentis ensemble."}},{"kind":"p","page":150,"text":{"en":"HTTP/3 runs on QUIC (UDP). Each stream is independent. A dropped packet stalls only that stream, the other 19 keep flowing. Add 0-RTT resumption (subsequent connections skip the handshake entirely) and you shave 1-2 round trips on every reconnect. That's where the latency gains come from.","fr":"HTTP/3 repose sur QUIC, au-dessus d’UDP. Les flux sont indépendants. Si un paquet est perdu, seul le flux concerné est bloqué, pendant que les 19 autres continuent. La reprise de connexion en 0-RTT permet en outre de reprendre les échanges sans attendre la fin de la négociation. Vous épargnez un à deux allers-retours à chaque reconnexion. C’est de là que vient le gain de latence."}},{"kind":"p","page":150,"text":{"en":"But your datacenter leg (CDN to origin) is a different story. It's a stable, low-loss private network. QUIC's benefits disappear on reliable connections. HTTP/2 multiplexing is mature, well-optimized, and doesn't carry QUIC's CPU overhead for cryptography (QUIC encrypts everything at the transport layer, no cleartext, ever).","fr":"Le segment entre le CDN et l’origine traverse un réseau privé stable, avec très peu de pertes. Sur une liaison fiable, QUIC perd son avantage. Le multiplexage HTTP/2 est mûr et bien optimisé. Il évite aussi le surcoût CPU du chiffrement de QUIC, qui chiffre toutes les communications au niveau transport."}},{"kind":"p","page":151,"text":{"en":"This is exactly how Cloudflare, Fastly, and Akamai operate: HTTP/3 on the edge-facing side, HTTP/2 (or even HTTP/1.1 with keepalive) on the origin-facing side.","fr":"C’est l’approche de Cloudflare, Fastly et Akamai : HTTP/3 côté utilisateurs, HTTP/2, voire HTTP/1.1 avec keepalive, côté origine."}}],[{"kind":"p","page":151,"text":{"en":"Why A falls short (HTTP/2 only):","fr":"La limite de A — HTTP/2 uniquement"}},{"kind":"p","page":151,"text":{"en":"HTTP/2 multiplexing is a genuine improvement over HTTP/1.1, but it doesn't solve TCP head-of-line blocking. On lossy mobile connections, you're still at the mercy of the TCP retransmission window. For p99 tail latency on bad networks, HTTP/2 won't move the needle.","fr":"Le multiplexage d’HTTP/2 améliore réellement HTTP/1.1, mais il laisse subsister le blocage en tête de ligne de TCP. Sur un réseau mobile sujet aux pertes, les flux restent tributaires des délais de retransmission de TCP. Le p99 évoluera peu sur les réseaux de mauvaise qualité."}}],[{"kind":"p","page":151,"text":{"en":"Why B is wrong (HTTP/3 only):","fr":"Pourquoi écarter B — HTTP/3 uniquement ?"}},{"kind":"p","page":151,"text":{"en":"HTTP/3 to origin introduces real operational risk. Enterprise firewalls and some cloud load balancers block UDP port 443 or rate-limit it. Your origin infra isn't the bottleneck, the last mile is. Fixing the origin leg with QUIC doesn't help the problem; it just adds complexity and potential breakage.","fr":"Utiliser HTTP/3 jusqu’à l’origine introduit un risque d’exploitation. Les pare-feu d’entreprise et certains répartiteurs de charge cloud bloquent le port UDP 443 ou en limitent le débit. Le goulet d’étranglement est sur le dernier kilomètre. Adopter QUIC sur le segment vers l’origine ajoute de la complexité et des risques de panne sans traiter cette cause."}}],[{"kind":"p","page":151,"text":{"en":"Why C is wrong (HTTP/2 end-to-end):","fr":"Pourquoi écarter C — HTTP/2 de bout en bout ?"}},{"kind":"p","page":151,"text":{"en":"Same problem as A. You've done nothing about the last mile. Consistent HTTP/2 end-to-end sounds clean, but \"clean\" doesn't show up in your p99.","fr":"C présente la même limite que A : la liaison avec le client reste telle quelle. Uniformiser HTTP/2 de bout en bout peut sembler soigné, mais cela ne réduit pas votre latence p99."}}]]},{"day":37,"title":{"en":"Multi-Writer Conflicts in Collaborative Editing","fr":"Résoudre les conflits d’écriture en édition collaborative"},"pages":[152,155],"topic":"data","correct":"C","scenario":[{"kind":"figure","page":152,"id":"152-02","width":800,"height":420,"alt":{"en":"Day 37 featured","fr":"Illustration de la question du jour 37"},"transcript":{"en":["Two users edit the same document at 9:03 AM.","em Design Labs","No locking. Both changes hit your server 300ms apart.","edit (9:03:00)","Client A","edit (9:03:00.300)","Application","‘Server","Document","Replica","Store","(Other Region)","read / write","“Client B","Last-Write-Wins (LWW) — highest timestamp","vector Clocks","track causality per replica,","takes the record. Loser's change disappears","detect conflict","versions, surface them to","silently.","the application for resolution,","CRDTs (Conflict-free Replicated Data Types) —","Operational Transformation (OT) — transform","data structures that mathematically merge","each operation relative to concurrent","concurrent writes without coordination.","operations before applying, keeping intent intact."],"fr":["Deux utilisateurs éditent le même document à 9h03.","em Design Labs","Pas de verrouillage. Les deux changements frappent votre serveur à 300ms d'intervalle.","Edit (9:03:00)","Client A","Edit (9:03:00.300)","Demande","«Serveur","Document","Réplique","Stocker","(Autre région)","lire / écrire","« Client B","Last-Write-Wins (LWW) — date la plus récente","vector Horloges","causalité de piste par réplique,","prend le record. Le changement du perdant disparaît","Détecter les conflits","versions, les faire surface pour","silencieusement.","la demande de résolution,","CRDTs (Types de données répliquées sans conflit)","Transformation opérationnelle (OT) — transformation","Des structures de données qui fusionnent mathématiquement","chaque opération par rapport à concurrent","écrit sans coordination.","opérations avant l'application, en gardant l'intention intacte."]}},{"kind":"p","page":152,"text":{"en":"Two users edit the same document at 9:03 AM.","fr":"À 9 h 03, deux utilisateurs modifient le même document."}},{"kind":"p","page":152,"text":{"en":"No locking. No coordination. Just two clients writing to the same record.","fr":"Aucun verrou ni coordination : les deux clients écrivent sur le même enregistrement."}},{"kind":"p","page":152,"text":{"en":"Both changes hit your server 300ms apart. One lands first. The other overwrites it.","fr":"Les deux modifications arrivent sur le serveur à 300 ms d’intervalle. La première est enregistrée, puis la seconde l’écrase."}},{"kind":"p","page":152,"text":{"en":"User A's work is gone. They never get an error. They just… lose their change.","fr":"L’utilisateur A a perdu son travail sans même recevoir de message d’erreur. Sa modification a simplement disparu."}},{"kind":"p","page":152,"text":{"en":"This is the multi-writer conflict problem. Every collaborative system hits it eventually. Your choices:","fr":"Voilà le problème des écritures concurrentes, auquel finit par se heurter tout système collaboratif. Quatre choix s’offrent à vous :"}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":152,"text":{"en":"Last-Write-Wins (LWW) — highest timestamp takes the record. Loser's change disappears silently.","fr":"Last-Write-Wins (LWW) — conserver la version dont l’horodatage est le plus récent. L’autre modification disparaît sans signalement."}}]},{"letter":"B","blocks":[{"kind":"p","page":152,"text":{"en":"Vector Clocks — track causality per replica, detect conflicting versions, surface them to the application for resolution.","fr":"Horloges vectorielles — suivre les relations de causalité par réplique, repérer les versions en conflit et les transmettre à l’application pour résolution."}}]},{"letter":"C","blocks":[{"kind":"p","page":152,"text":{"en":"CRDTs (Conflict-free Replicated Data Types) — data structures that mathematically merge concurrent writes without coordination.","fr":"CRDT (types de données répliquées sans conflit) — employer des structures de données dont les propriétés mathématiques permettent de fusionner les écritures concurrentes sans coordination."}}]},{"letter":"D","blocks":[{"kind":"p","page":152,"text":{"en":"Operational Transformation (OT) — transform each operation relative to concurrent operations before applying, keeping intent intact.","fr":"Transformation opérationnelle (OT) — ajuster chaque opération en fonction des opérations concurrentes avant de l’appliquer, pour préserver l’intention d’origine."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"figure","page":153,"id":"153-03","width":800,"height":533,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["/stem Design Labs.","@) CRDTs wins at scale","Any","0 repli","‘as can always be merged — mathematically, w","hout coordination.","Key insight: if operations are","‘Multiple Replicas","commutative, associative,","update","| Jal","Converged State","and idempotent, conflicts","structurally cant exist.","Client A","Hello","update","cROT Merge","World","Client 8","All replicas","converge","jj","{G-Counter: only increments","‘CROTS constrain your data model","take max per replica","Figma’s canvas runs on CROTs","Not everything maps cleanly.","Always converges.","‘Some operations (ike moving a fle","LWW-Element-Set: union of adds","between directories) are notoriously","‘+ removes with timestamps,","hard to express without losing intent.","‘Ax milions of concurrent writers","RGA / YATA (sequence CROTS):","‘cross distributed regions,","leach character gets unique ID,","every node converges","2]","‘concurrent inert are deterministically","independently — 2er0","‘ordered — this is collaborative","test eating,","coordination required.","Bottom line: CROTs are the foundation of modern large-scale collaborative systems,","‘They trade data model freedom for convergence guarantees at global scale."],"fr":["/stem Design Labs.",") Les CRDT gagnent à grande échelle","Tous","0 repli","« Comme on peut toujours fusionner — mathématiquement, w","coordination de bout.","Principaux éléments : si les opérations sont","«Replicas multiples","commutatif, associatif,","mise à jour","Jal","État convergent","et idempotent, conflits","structurellement n'existent pas.","Client A","Hello","mise à jour","cROT Fusionner","Monde","Client 8","Toutes les répliques","convergente","jj","G-Counter: seulement incréments","« Les CROTS limitent votre modèle de données","prendre max par réplique","La toile de Figma court sur des CROTs","Tout n'est pas mappé proprement.","Converge toujours.","«Certaines opérations (comme déplacer un","LWW-Element-Set : union d'ajouts","entre les répertoires) sont notoirement","«+ supprime avec des horodatages,","Difficile à exprimer sans perdre son intention.","« Des millions d’écrivains concurrents","RGA / YATA (CROTS de séquence):","«entre régions réparties,","caractère de lixiviation obtient ID unique,","Chaque nœud converge","2]","« Les inerties concurrentes sont déterministes.","indépendamment — 2er0","« Commandé – c’est collaboratif","Tester l’alimentation,","coordination nécessaire.","Bottom line: Les CROT sont la base des systèmes collaboratifs modernes à grande échelle,","Ils échangent la liberté du modèle de données pour des garanties de convergence à l’échelle mondiale."]}},{"kind":"p","page":153,"text":{"en":"Answer: C — CRDTs (but the real answer depends on your conflict model — full breakdown below)","fr":"Réponse : C — CRDT (le choix précis dépend de votre modèle de résolution des conflits, comme expliqué ci-dessous)"}},{"kind":"p","page":153,"text":{"en":"C — CRDTs wins at scale","fr":"C — Les CRDT s’imposent à grande échelle"}},{"kind":"p","page":153,"text":{"en":"CRDTs are data structures designed so any two replicas can always be merged — mathematically, without coordination. The key insight: if operations are commutative, associative, and idempotent, conflicts structurally can't exist.","fr":"Les CRDT sont des structures de données conçues pour permettre la fusion de deux répliques sans coordination. Le principe : avec des opérations commutatives, associatives et idempotentes, le modèle exclut structurellement les conflits."}},{"kind":"p","page":153,"text":{"en":"Examples:","fr":"Quelques exemples :"}},{"kind":"p","page":153,"text":{"en":"• G-Counter: only increments. Merge = take max per replica. Always converges.","fr":"• G-Counter : le compteur augmente uniquement. La fusion retient le maximum pour chaque réplique, ce qui assure la convergence."}},{"kind":"p","page":153,"text":{"en":"• LWW-Element-Set: union of adds + removes with timestamps.","fr":"• LWW-Element-Set : union des ajouts et des suppressions horodatés."}},{"kind":"p","page":153,"text":{"en":"• RGA / YATA (sequence CRDTs): each character gets a unique ID, concurrent inserts are deterministically ordered — this is collaborative text editing.","fr":"• RGA et YATA (CRDT de séquence) : chaque caractère reçoit un identifiant unique et les insertions concurrentes sont ordonnées de façon déterministe. Ce mécanisme permet l’édition de texte collaborative."}},{"kind":"p","page":153,"text":{"en":"Figma's canvas runs on CRDTs. Notion's block model is CRDT-based. At millions of concurrent writers across distributed regions, every node converges independently — zero coordination required.","fr":"Le canvas de Figma utilise des CRDT. Le modèle par blocs de Notion repose lui aussi sur des CRDT. Avec des millions d’utilisateurs écrivant simultanément dans plusieurs régions, chaque nœud converge indépendamment, sans coordination."}},{"kind":"p","page":154,"text":{"en":"The catch: CRDTs constrain your data model. Not everything maps cleanly. Some operations (like moving a file between directories) are notoriously hard to express without losing intent.","fr":"Les CRDT imposent des contraintes au modèle de données. Certaines opérations s’y expriment difficilement. Déplacer un fichier d’un répertoire à un autre, par exemple, est particulièrement difficile à modéliser tout en préservant l’intention initiale."}}],[{"kind":"p","page":154,"text":{"en":"D — Operational Transformation (OT) ⚠ impressive but hard","fr":"D — Transformation opérationnelle (OT) ⚠ ambitieuse et difficile à mettre en œuvre"}},{"kind":"p","page":154,"text":{"en":"OT was Google Docs' original approach. When two operations arrive concurrently, you transform each one relative to the other before applying it. User A inserts at position 5, User B deletes at position 3 simultaneously — OT adjusts A's insert position to account for B's delete. Intent preserved.","fr":"L’OT était l’approche initiale de Google Docs. Quand deux opérations arrivent simultanément, chacune est transformée en fonction de l’autre avant son application. Supposons que A insère du texte en position 5 pendant que B supprime du texte en position 3. L’OT décale l’insertion de A pour tenir compte de la suppression de B. L’intention de chaque utilisateur est préservée."}},{"kind":"p","page":154,"text":{"en":"That's why Google Docs felt magical in 2009.","fr":"C’est ce qui rendait l’expérience Google Docs si impressionnante en 2009."}},{"kind":"p","page":154,"text":{"en":"But OT is operationally brutal. The transformation functions are notoriously hard to get right — the original OT papers had bugs. Every new operation type adds transformation pairs that grow quadratically. OT also requires a centralized server to sequence operations; it doesn't distribute cleanly.","fr":"L’OT est toutefois difficile à mettre en œuvre. Les fonctions de transformation sont délicates à concevoir, au point que les articles fondateurs sur l’OT contenaient des erreurs. Avec les nouveaux types d’opérations, le nombre de couples de transformation augmente de façon quadratique. L’OT nécessite aussi un serveur central pour ordonner les opérations, ce qui complique sa distribution."}},{"kind":"p","page":154,"text":{"en":"Modern Google Docs has moved toward a hybrid incorporating CRDT-like ideas. OT alone doesn't scale to full distribution.","fr":"Google Docs a évolué vers une approche hybride qui reprend des idées des CRDT. Distribuer complètement un système fondé uniquement sur l’OT reste difficile."}}],[{"kind":"p","page":154,"text":{"en":"B — Vector Clocks honest but incomplete","fr":"B — Horloges vectorielles : approche rigoureuse, mais incomplète"}},{"kind":"p","page":154,"text":{"en":"Vector clocks track causality. Each write carries a version vector — one counter per replica. When two writes have no causal relationship (neither \"happened before\" the other), you know you have a conflict. Both versions surface to the application layer, which resolves them.","fr":"Les horloges vectorielles suivent les relations de causalité. Chaque écriture transporte un vecteur de versions, avec un compteur par réplique. Lorsque deux écritures n’ont aucun lien de causalité et qu’aucune ne précède l’autre, il y a conflit. L’application reçoit les deux versions et doit les départager."}},{"kind":"p","page":154,"text":{"en":"Amazon's internal Dynamo used this. It's correct and transparent. The problem: conflict resolution is now your job. You write merge logic for every data type. For shopping carts it's manageable (union the items). For arbitrary documents? It breaks down fast.","fr":"Le Dynamo interne d’Amazon utilisait cette approche. Elle est correcte et rend les conflits visibles. Il vous revient d’écrire une logique de fusion pour chaque type de donnée. Pour un panier, c’est faisable en prenant l’union des articles. Pour des documents de structure quelconque, les choses se compliquent vite."}},{"kind":"p","page":154,"text":{"en":"Vector clocks tell you where conflicts are. They don't tell you how to fix them.","fr":"Les horloges vectorielles détectent les conflits et laissent leur résolution à l’application."}}],[{"kind":"p","page":155,"text":{"en":"A — Last-Write-Wins (LWW) ❌ dangerous","fr":"A — Last-Write-Wins (LWW) ❌ Risqué"}},{"kind":"p","page":155,"text":{"en":"Simple. Brutally simple. Highest timestamp wins. The loser's change vanishes — no error, no notification, just gone.","fr":"La règle est radicalement simple : la version la plus récente l’emporte. L’autre modification disparaît, sans erreur ni notification."}},{"kind":"p","page":155,"text":{"en":"Cassandra defaults to this. For append-only workloads (metrics, event logs, telemetry) it's totally fine. For anything a human edited? It's silent data loss with a timestamp attached. The treacherous part: users never get an error. Their work just stops being there.","fr":"C’est le comportement par défaut de Cassandra. Pour des données auxquelles on ajoute seulement des entrées, comme les métriques, les journaux d’événements ou la télémétrie, cela convient. Pour des données modifiées par une personne, vous pouvez perdre le travail sans aucun avertissement. L’utilisateur ne voit jamais de message d’erreur et constate seulement la disparition de sa modification."}}]]},{"day":38,"title":{"en":"Fitting a Large Document into an LLM","fr":"Traiter un long document avec un LLM"},"pages":[156,158],"topic":"ai","correct":"A","scenario":[{"kind":"figure","page":156,"id":"156-02","width":800,"height":420,"alt":{"en":"Day 38 featured","fr":"Illustration de la question du jour 38"},"transcript":{"en":["m Des","Your LLM has 128K tokens.","Your document has 150K words. Something has to give. What do you do?","own |","‘Chunk &","Embed","Search","Context","uM","(128K tokens)","‘Long Document","(150K words)","Chunk the document into fixed-size pieces","Use a sliding window — process the document","and embed each one — retrieve the top-k","in overlapping chunks, stitch the outputs","together.","at query time.","‘Summarize each section progressively —","‘Truncate to the most recent tokens and","feed the running summary forward as context.","hope the answer is near the end.","[e"],"fr":["m Des","Votre LLM a 128K jetons.","Votre document a 150 000 mots. Quelque chose doit donner. Que faites-vous?","propre","«Chunk &","Intégrer","Rechercher","Contexte","uM","(128K jetons)","« Long document","(150K mots)","Découper le document en morceaux de taille fixe","Utiliser une fenêtre coulissante — traiter le document","et intégrer chacun d'eux — récupérer le top-k","en morceaux qui se chevauchent, assembler les sorties","ensemble.","à l'heure de la requête.","«Résumer chaque section progressivement","«Truncate aux derniers jetons et","transmettre le résumé en cours d'exécution en tant que contexte.","Espérons que la réponse est proche de la fin.","[e"]}},{"kind":"p","page":156,"text":{"en":"Your LLM has 128K tokens.","fr":"Votre LLM dispose d’une fenêtre de contexte de 128 000 tokens."}},{"kind":"p","page":156,"text":{"en":"Your document has 150K words.","fr":"Votre document contient 150 000 mots."}},{"kind":"p","page":156,"text":{"en":"Something has to give. What do you do?","fr":"Tout ne tiendra pas dans le contexte. Que faites-vous ?"}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":156,"text":{"en":"Chunk the document into fixed-size pieces and embed each one — retrieve the top-k at query time.","fr":"Découper le document en blocs de taille fixe et calculer un embedding pour chacun. Au moment de la requête, récupérer les k blocs les plus pertinents."}}]},{"letter":"B","blocks":[{"kind":"p","page":156,"text":{"en":"Use a sliding window — process the document in overlapping chunks, stitch the outputs together.","fr":"Utiliser une fenêtre glissante : traiter des blocs qui se chevauchent, puis combiner les résultats."}}]},{"letter":"C","blocks":[{"kind":"p","page":156,"text":{"en":"Summarize each section progressively — feed the running summary forward as context.","fr":"Résumer les sections au fur et à mesure et transmettre le résumé cumulatif comme contexte à la section suivante."}}]},{"letter":"D","blocks":[{"kind":"p","page":156,"text":{"en":"Truncate to the most recent tokens and hope the answer is near the end.","fr":"Ne garder que les tokens les plus récents en espérant que la réponse se trouve vers la fin."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"figure","page":157,"id":"157-03","width":800,"height":445,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["HY A WINS: RAG WITH","IUNKED EMBEDDINGS","2. Embed","4. Retrieve","3. Vector DB","[en","Loss, 027,","(Pinecone /","[enna","(on, 074","od","chek 2","Long Document","Embeding Mode","(150K words)","~500 tokens,","10-20% overiap","‘Store embedingt","SCALES TO ANY SIZE","4g prooucrion Fx","HYBRID RETRIEVAL","+ LLM ont soe retrieved","‘Chun boundaries bres","+ Chunkat sentence or","Combine Keyword (825)","chunks at inference","hot character counts.","paragraph boundaries,","‘semantic ea","Reta is fst ANN","lookup — nota sequential","fe claus starts on page 12","Covers edge eases semante","and resolves on page","ether chun rteves wel","+ Preserves meaning and","improves retrieval ty","search alone mises","Keeps latency low and","ths.","stays within cones"],"fr":["HY A WINS: RAG AVEC","MISES EN MATI — RE IUNKED","2. Intégrer","4. Récupère","3. Vector DB","[en]","Perte, 027,","(Pinécone /","[enna","(sur, 074","od","chek 2","long document","Mode d'intégration","(150K mots)","500 jetons,","10-20% overiap","«Store embedingt","ÉCHELLES À TOUTES TAILLES","4g prooucrion Fx","RETRAIT HYBRIDE","+ LLM ont été récupérés","«Chun frontières bres","+ Chunkat phrase ou","Combiner Mot-clé (825)","Chunks à l'inférence","Caractère chaud compte.","les limites du paragraphe,","«sémantique ea","Reta est FST ANN","lookup — nota séquentielle","fe claus commence à la page 12","Couvre le bord facilite semante","et se résout sur la page","éther chun rteves wel","+ Préserve le sens et","améliore la récupération ty","Recherche seule Mises","Maintient la latence faible et","ths.","Reste dans les cônes"]}},{"kind":"p","page":157,"text":{"en":"Why A wins (RAG with chunked embeddings):","fr":"Pourquoi retenir A — RAG avec des embeddings par bloc ?"}},{"kind":"p","page":157,"text":{"en":"You split the document into overlapping chunks (~500 tokens, ~10–20% overlap), embed each one, store in a vector DB (Pinecone, pgvector, Qdrant), and retrieve top-k at query time.","fr":"Découpez le document en blocs d’environ 500 tokens avec un chevauchement de 10 à 20 %. Calculez un embedding pour chacun, stockez les embeddings dans une base vectorielle (Pinecone, pgvector ou Qdrant), puis récupérez les k blocs les plus pertinents pour chaque requête."}},{"kind":"p","page":157,"text":{"en":"This scales to any document size. Your LLM context at inference only sees the retrieved chunks — staying well inside the context window. Latency stays low because retrieval is a fast ANN lookup, not a sequential scan.","fr":"L’approche s’applique quelle que soit la taille du document. À l’inférence, seuls les blocs récupérés sont fournis au LLM et restent largement dans la limite de sa fenêtre de contexte. La latence reste faible grâce à une recherche rapide de voisins approchés (ANN), sans parcours séquentiel de tout le document."}},{"kind":"p","page":157,"text":{"en":"The catch: chunking boundaries destroy semantic coherence. If a clause starts on page 12 and resolves on page 13, a hard chunk boundary between them means neither chunk retrieves well for that question. This is why overlap and chunk size tuning matter so much. Most teams underestimate this.","fr":"Le découpage peut rompre la continuité du sens. Si une clause commence à la page 12 et se termine à la page 13, couper net entre les deux peut réduire la pertinence des deux blocs pour une question sur la clause. Le chevauchement et le réglage de la taille des blocs sont donc essentiels, et souvent sous-estimés."}},{"kind":"p","page":157,"text":{"en":"Production fix: chunk at sentence or paragraph boundaries, not character counts. Hybrid retrieval (keyword + semantic) handles the edge cases.","fr":"En production, coupez aux limites des phrases ou des paragraphes plutôt qu’après un nombre fixe de caractères. Une recherche hybride, par mots-clés et par similarité sémantique, couvre les cas limites."}}],[{"kind":"p","page":158,"text":{"en":"Why B is the trap answer (sliding window):","fr":"Le piège de B — fenêtre glissante"}},{"kind":"p","page":158,"text":{"en":"Sliding window looks elegant — process the document in overlapping passes, accumulate the answer. But it doesn't actually fix the context window problem. You still have to process every chunk sequentially, and the answer to a question spanning chunk 1 and chunk 47 gets lost. You're doing O(n) LLM calls per query. At 150K words and a 3s/call LLM, that's minutes per query. Nobody ships this in production for QA on large documents.","fr":"La fenêtre glissante semble élégante : traitez le document en plusieurs passes qui se chevauchent et consolidez la réponse. Le problème de la fenêtre de contexte demeure. Vous devez encore traiter chaque bloc dans l’ordre et risquez de perdre les éléments de réponse répartis entre le premier et le 47ᵉ bloc. Chaque requête demande O(n) appels au LLM. Avec 150 000 mots et trois secondes par appel, il faut plusieurs minutes par requête. Ce n’est pas viable en production pour des questions-réponses sur de gros documents."}},{"kind":"p","page":158,"text":{"en":"It works fine for summarization tasks where the output from chunk N feeds into chunk N+1. For retrieval? Wrong tool.","fr":"Cette technique fonctionne pour un résumé, où le résultat du bloc N alimente le bloc N+1. Elle se prête mal à la recherche d’informations précises."}}],[{"kind":"p","page":158,"text":{"en":"Why C sometimes works (progressive summarization):","fr":"Quand C peut fonctionner — résumé progressif"}},{"kind":"p","page":158,"text":{"en":"For summarizing a 200-page doc? Solid. You map-reduce the document — summarize sections, then summarize the summaries. GPT-4o does this well.","fr":"Pour résumer un document de 200 pages, l’approche est solide. Appliquez un map-reduce : résumez les sections, puis synthétisez les résumés. GPT-4o le fait bien."}},{"kind":"p","page":158,"text":{"en":"For answering a specific question about clause 38(b) on page 97? It doesn't. The intermediate summary will have compressed away the specific detail you needed. Lossy compression applied to information retrieval is a category error.","fr":"Pour répondre à une question précise sur la clause 38(b) de la page 97, l’approche échoue. Le résumé intermédiaire aura probablement supprimé le détail nécessaire. Une compression avec perte convient mal à une tâche de recherche d’information."}},{"kind":"p","page":158,"text":{"en":"Use progressive summarization when you want a high-level understanding. Don't use it when specific facts need to survive to the end of the pipeline.","fr":"Le résumé progressif convient pour obtenir une vue d’ensemble. Lorsque des faits précis doivent être conservés jusqu’à la fin du traitement, il risque de les faire disparaître."}}],[{"kind":"p","page":158,"text":{"en":"Why D is obviously wrong (and also surprisingly common):","fr":"Pourquoi D est une mauvaise option pourtant fréquente"}},{"kind":"p","page":158,"text":{"en":"Truncating to the last N tokens is the default behavior of most LLM API wrappers when you exceed the context limit and don't handle it explicitly. Many teams ship this by accident.","fr":"La plupart des bibliothèques qui encapsulent les API de LLM ne gardent par défaut que les N derniers tokens si vous dépassez la limite de contexte et ne gérez pas ce cas. Beaucoup d’équipes déploient ce comportement involontairement."}},{"kind":"p","page":158,"text":{"en":"The problem beyond the obvious data loss: LLMs have a \"lost in the middle\" failure mode (Liu et al., 2023). Performance on retrieval tasks is highest when the answer is at the start or end of the context window — and degrades significantly when it's buried in the middle. So even if you fit everything in context, position matters.","fr":"Au-delà de la perte d’information, les LLM présentent l’effet « lost in the middle » (Liu et al., 2023). Pour une tâche de recherche, ils répondent mieux quand l’information se trouve au début ou à la fin de la fenêtre de contexte. Les performances chutent si elle est enfouie au milieu. La position compte donc même quand tout tient dans la fenêtre."}},{"kind":"p","page":158,"text":{"en":"Truncation compounds this — you're not just losing data, you're losing data unpredictably.","fr":"La troncature aggrave le problème en supprimant une partie des informations sans que l’on sache si c’était celle dont on avait besoin."}}]]},{"day":39,"title":{"en":"Preventing Concurrent Balance Overspend","fr":"Empêcher deux opérations concurrentes de dépasser un solde"},"pages":[159,161],"topic":"data","correct":"B","scenario":[{"kind":"figure","page":159,"id":"159-02","width":800,"height":421,"alt":{"en":"Day 39 featured","fr":"Illustration de la question du jour 39"},"transcript":{"en":["Two users read $200 from the same wallet at the same time.","Both spend $150. Wallet ends up at -$100. How do you stop this?","{Initial Balance: $200","Spend $150","ead / Write","Balance —>","Wallet","Aer both writes:","Database","User 2","Transaction","Record","Log","Pessimistic locking — SELECT FOR UPDATE","Optimistic locking — read the row with a","‘on the wallet row. One transaction blocks","Until the other commits,","version number, only write if version hasn't","I)","changed since you read it. Retry on conflict","‘snapshot, rely on the database to detect,","MVCC — let both reads see a consistent","isolation level to SERIALIZABLE and let the","Serializable isolation — set the transaction","write conflicts at commit time.","database handle it."],"fr":["Deux utilisateurs lisent 200 $ du même portefeuille en même temps.","Les deux dépensent 150$. Le portefeuille finit à -100$. Comment arrêter ça ?","Solde initial: 200 $","Dépenser 150 $","ead / Écrire","Solde — >","Portefeuille","Aer écrit tous les deux :","Base de données","Utilisateur 2","Transaction","Enregistrer","Journal","Verrouillage pessimiste — SELECT FOR UPDATE","Verrouillage optimiste - lisez la ligne avec un","«sur la rangée de portefeuille. Un bloc de transaction","Jusqu'à ce que l'autre s'engage,","numéro de version, n'écrivez que si la version n'a pas","I)","changé depuis que vous l'avez lu.","«Snapshot, comptez sur la base de données pour détecter,","MVCC — permet aux deux lectures de voir une constante","niveau d'isolement à SERIALIZABLE et laissez le","Isolation sérialisable — définit la transaction","écrire des conflits au moment de l'engagement.","base de données le gère."]}},{"kind":"p","page":159,"text":{"en":"You have a payment system. Two users try to spend from the same wallet balance at the same time.","fr":"Votre système de paiement permet à deux utilisateurs de dépenser de l’argent en même temps depuis le même portefeuille."}},{"kind":"p","page":159,"text":{"en":"Both read $200. Both want to spend $150. Both see enough balance. Both write the deduction.","fr":"Chacun lit un solde de 200 $ et veut dépenser 150 $. Les deux constatent que le solde suffit et enregistrent leur débit."}},{"kind":"p","page":159,"text":{"en":"The wallet is now at -$100. How do you stop this?","fr":"Le solde du portefeuille est désormais de −100 $. Comment empêcher cela ?"}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":159,"text":{"en":"Pessimistic locking — SELECT FOR UPDATE on the wallet row. One transaction blocks until the other commits.","fr":"Verrouillage pessimiste — exécuter SELECT FOR UPDATE sur la ligne du portefeuille. L’une des transactions attend que l’autre soit validée."}}]},{"letter":"B","blocks":[{"kind":"p","page":159,"text":{"en":"Optimistic locking — read the row with a version number, only write if version hasn't changed since you read it. Retry on conflict.","fr":"Verrouillage optimiste — lire la ligne et son numéro de version, puis écrire uniquement si la version n’a pas changé depuis la lecture. Réessayer en cas de conflit."}}]},{"letter":"C","blocks":[{"kind":"p","page":159,"text":{"en":"MVCC — let both reads see a consistent snapshot, rely on the database to detect write conflicts at commit time.","fr":"MVCC — donner aux deux lectures une vue cohérente des données, puis laisser la base détecter les conflits d’écriture au moment de la validation."}}]},{"letter":"D","blocks":[{"kind":"p","page":159,"text":{"en":"Serializable isolation — set the transaction isolation level to SERIALIZABLE and let the database handle it.","fr":"Isolation sérialisable — définir le niveau d’isolation des transactions sur SERIALIZABLE et laisser la base gérer la concurrence."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"figure","page":160,"id":"160-03","width":800,"height":533,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["System","Design","©) Why B wins (optimistic locking):","Labs","You read the wallet row, grab the version number. When you write, you include a","WHERE version =","read_version condition. If another transaction already updated the row,","your WHERE matches zero rows — conflict detected, retry.","Optimistic Locking Flow","Update Query","© Read wallet row","UPDATE wallets","lance: $200,","SET balance","balance - 150, version = version + 1","Client /","version: 17","WHERE id","wallet_id AND version","ad_version;","Service","balance: $200,","version: 17","If rows_affected = 0 > conflict — retry.","© Atempt update wih","version condition","(version = 17)","No locks held during the read. At 10K TPS with low","if version = 17","conflict rates, this is significantly faster than","~ version becomes 18","-- © Ack success","pessimistic locking — you're only paying for retry","cost on actual conflicts, not lock acqui","ion on","every read.","The catch:","Redis INCRBY","Queue in front","under HIGH contention (same hot wallet","with atomic","of the wallet","hit repeatedly), retry storms eat you alive.","decrement","update"],"fr":["Système","Design",") Pourquoi retenir B (verrouillage optimal) :","Labs","Vous lisez la ligne du portefeuille, saisissez le numéro de version. Lorsque vous écrivez, vous incluez un","O — version","Si une autre transaction a déjà mis à jour la ligne,","votre WHERE correspond à zéro ligne — conflit détecté, réessayez.","Débit de verrouillage optimiste","Mettre à jour la requête","Lire la ligne de portefeuille","Portefeuilles UPDATE","lance: 200 $,","SET balance","balance - 150, version — version + 1","Client /","version: 17","O — id","wallet_id ET version","ad_version;","Service","Solde : 200 $,","version: 17","Si rows_affected — 0 > conflict — réessayer.","Mise à jour Atempt avec","condition de version","(version — 17)","Pas de serrures pendant la lecture. À 10K TPS avec faible","si version — 17","taux de conflit, c'est nettement plus rapide que","version devient 18","-- — Ack succès","verrouillage pessimiste - vous ne payez que pour réessayer","coût sur les conflits réels, pas verrouiller acqui","ion sur","chaque lecture.","Le catch :","Redis INCRBY","File d'attente devant","sous HIGH contention (même portefeuille chaud)","Avec Atomic","du portefeuille","frapper à plusieurs reprises), réessayer les tempêtes vous mangent vivant.","décrément","mise à jour"]}},{"kind":"p","page":160,"text":{"en":"Why B wins (optimistic locking):","fr":"Pourquoi retenir B — verrouillage optimiste ?"}},{"kind":"p","page":160,"text":{"en":"You read the wallet row, grab the version number. When you write, you include a WHERE version = :read_version condition. If another transaction already updated the row, your WHERE matches zero rows — conflict detected, retry.","fr":"Lisez la ligne du portefeuille et relevez son numéro de version. À l’écriture, ajoutez la condition WHERE version = :read_version. Si une autre transaction a déjà modifié cette ligne, la condition ne correspond à aucune ligne : le conflit est détecté et vous réessayez."}},{"kind":"code","page":160,"text":{"en":"UPDATE wallets","fr":"UPDATE wallets"}},{"kind":"code","page":160,"text":{"en":"SET balance = balance - 150, version = version + 1","fr":"SET balance = balance - 150, version = version + 1"}},{"kind":"code","page":160,"text":{"en":"WHERE id = :wallet_id AND version = :read_version;","fr":"WHERE id = :wallet_id AND version = :read_version;"}},{"kind":"p","page":160,"text":{"en":"If rows_affected = 0 → conflict → retry. No locks held during the read. At 10K TPS with low conflict rates, this is significantly faster than pessimistic locking — you're only paying for retry cost on actual conflicts, not lock acquisition on every read.","fr":"Si rows_affected = 0, il y a conflit et il faut réessayer. Aucun verrou n’est pris pendant la lecture. À 10 000 transactions par seconde, avec peu de conflits, cette méthode est nettement plus rapide que le verrouillage pessimiste. Vous payez le coût d’une nouvelle tentative lors d’un conflit réel et évitez de prendre un verrou à chaque lecture."}},{"kind":"p","page":160,"text":{"en":"The catch: under HIGH contention (same hot wallet hit repeatedly), retry storms eat you alive. Hot wallets need Redis INCRBY with atomic decrement, or a queue in front of the wallet update.","fr":"En cas de forte contention, quand le même portefeuille est modifié sans cesse, les nouvelles tentatives peuvent saturer le système. Pour les portefeuilles les plus sollicités, utilisez Redis INCRBY pour décrémenter le solde de façon atomique, ou placez une file d’attente devant les mises à jour."}}],[{"kind":"p","page":161,"text":{"en":"Why A is the trap answer (pessimistic locking):","fr":"Le piège de A — verrouillage pessimiste"}},{"kind":"p","page":161,"text":{"en":"SELECT FOR UPDATE works. It's correct. But it holds a row-level lock for the entire transaction — every concurrent write queues up.","fr":"SELECT FOR UPDATE fonctionne et garantit la correction. Le verrou de ligne est toutefois conservé jusqu’à la fin de la transaction, ce qui place toutes les écritures concurrentes en attente."}},{"kind":"p","page":161,"text":{"en":"At 10K TPS on a popular wallet, you've serialized all writes to a single queue. Throughput collapses. Lock wait timeouts cascade — failed transactions retry, adding more contention. You've built a self-reinforcing bottleneck.","fr":"À 10 000 transactions par seconde sur un portefeuille très sollicité, vous forcez toutes les écritures à passer dans une seule file. Le débit s’effondre. Les délais d’attente des verrous expirent en cascade. Les transactions échouées réessaient et aggravent la contention. Le goulet d’étranglement s’autoalimente."}},{"kind":"p","page":161,"text":{"en":"Use pessimistic locking for low-concurrency paths (admin ops, batch jobs) where conflict probability is near 100%. Not for high-throughput payment writes.","fr":"Le verrouillage pessimiste convient aux opérations peu concurrentes, par exemple à l’administration ou aux tâches batch, lorsque la probabilité de conflit est proche de 100 %. Évitez-le pour des écritures de paiement à fort débit."}}],[{"kind":"p","page":161,"text":{"en":"Why C is the silent failure (MVCC + default isolation):","fr":"Pourquoi C peut échouer sans signalement — MVCC avec l’isolation par défaut"}},{"kind":"p","page":161,"text":{"en":"This is the dangerous one. PostgreSQL defaults to READ COMMITTED. MVCC gives each transaction a consistent snapshot — but at READ COMMITTED, that snapshot refreshes per statement, not per transaction.","fr":"Le risque est important. PostgreSQL utilise READ COMMITTED par défaut. MVCC offre une vue cohérente des données. À ce niveau d’isolation, cette vue est renouvelée à chaque instruction au sein d’une même transaction."}},{"kind":"p","page":161,"text":{"en":"Two concurrent transactions both read $200, both pass the \"sufficient funds\" check, both commit. No conflict detected. Double spend in production.","fr":"Deux transactions concurrentes lisent chacune 200 $, valident toutes deux le contrôle de solde suffisant, puis sont toutes deux validées par la base. Aucun conflit n’est signalé et le portefeuille est débité deux fois en production."}},{"kind":"p","page":161,"text":{"en":"MVCC prevents dirty reads. It does NOT prevent lost updates at READ COMMITTED. Most engineers assume MVCC = safe from concurrent writes. It doesn't.","fr":"MVCC empêche les lectures sales. À l’isolation READ COMMITTED, des mises à jour peuvent toutefois être perdues. Beaucoup d’ingénieurs assimilent à tort MVCC à une protection complète contre les écritures concurrentes."}}],[{"kind":"p","page":161,"text":{"en":"Why D is almost always the wrong default (SERIALIZABLE):","fr":"Pourquoi D convient rarement par défaut — SERIALIZABLE"}},{"kind":"p","page":161,"text":{"en":"Theoretically correct — the database guarantees transactions behave as if they ran serially. No anomalies.","fr":"Ce niveau d’isolation est correct en théorie. La base garantit que les transactions se comportent comme si elles avaient été exécutées les unes après les autres, sans anomalie."}},{"kind":"p","page":161,"text":{"en":"The problem: PostgreSQL's SSI tracks read-write dependencies across transactions. Under high concurrency, serialization failures spike — transactions abort and retry even when there was no actual conflict. Real throughput penalty at scale.","fr":"PostgreSQL utilise SSI pour suivre les dépendances entre lectures et écritures de différentes transactions. En cas de forte concurrence, les échecs de sérialisation se multiplient. Des transactions sont annulées puis réessayées même sans conflit réel, ce qui pénalise sensiblement le débit à grande échelle."}},{"kind":"p","page":161,"text":{"en":"Right for complex financial workflows where correctness > throughput (end-of-day reconciliation). Wrong default for a high-throughput per-transaction API.","fr":"Cette approche convient aux traitements financiers complexes où l’exactitude prime sur le débit, comme le rapprochement de fin de journée. Elle convient mal par défaut à une API de transactions à fort débit."}}]]},{"day":40,"title":{"en":"Offloading Heavy Work Off the Main Thread","fr":"Déporter un traitement lourd hors du thread principal"},"pages":[162,165],"topic":"scale","correct":"B","scenario":[{"kind":"figure","page":162,"id":"162-02","width":800,"height":420,"alt":{"en":"Day 40 featured","fr":"Illustration de la question du jour 40"},"transcript":{"en":["Your React dashboard freezes for 4 seconds","G system Design Labs","every time a user uploads a CSV.","3.85 synchronous JS. |","Ulblocked","select fle","File","Vala","Data","Update","React","csv","Main Thread","App State","Dashboard","Dashboard","Parse + Validate + Map","(Memory)","UL","requestidleCallback +","1e-slicing — chunk the","Web Worker — move the entire parse +","parse into Sms slices, yield between rows, let","validation pipeline into worker.js, communicate","|o","the browser breathe.","|e","via postMessage, main thread stays free.","SharedArrayButfer + Atomics — share the file","Compile the parser to WebAssembly — drop the","buffer between main thread and 4 workers,","JS parser, run a Rust CSV parser through WASM","parallelize the parse across cores, zero-copy.","for near-native speed.","IC)"],"fr":["Votre tableau de bord React se fige pendant 4 secondes","G system Design Labs","chaque fois qu'un utilisateur télécharge un fichier CSV.","3.85 JS synchrone.","Ulblocked","sélectionner fle","Fichier","Vala","Données","Mise à jour","React","csv","Fil principal","App State","Tableau de bord","Tableau de bord","Analyse + Validation + Carte","(Mémoire)","UL","demandeidleCallback +","1e-tranchage — découper le","Web Worker — déplace l'ensemble de l'analyse +","analyser en tranches de Sms, céder entre les lignes, laisser","pipeline de validation dans worker.js, communiquer","o","Le navigateur respire.","e","via postMessage, le fil principal reste libre.","SharedArrayButfer + Atomics — partager le fichier","Compilez l'analyseur WebAssembly","tampon entre le fil principal et 4 travailleurs,","JS parser, exécutez un analyseur CSV Rust via WASM","paralléliser l'analyse à travers les cœurs, zéro-copie.","pour la vitesse quasi-native.","IC)"]}},{"kind":"p","page":162,"text":{"en":"Your React dashboard freezes for 4 seconds every time a user uploads a CSV.","fr":"Votre tableau de bord React se fige pendant quatre secondes chaque fois qu’un utilisateur importe un fichier CSV."}},{"kind":"p","page":162,"text":{"en":"Not a network freeze. A browser freeze. Tab unresponsive. Animations stuck. The \"Page Unresponsive\" dialog popping up on Chrome.","fr":"Le navigateur lui-même se bloque : l’onglet ne répond plus, les animations s’arrêtent et Chrome affiche « La page ne répond pas ». Le réseau n’est pas en cause."}},{"kind":"p","page":162,"text":{"en":"Here's what's happening in prod:","fr":"Voici ce qui se passe en production :"}},{"kind":"p","page":162,"text":{"en":"• User drops a 80MB CSV (200k rows, 40 columns) into the upload zone","fr":"• L’utilisateur dépose un CSV de 80 Mo, avec 200 000 lignes et 40 colonnes, dans la zone d’import."}},{"kind":"p","page":162,"text":{"en":"• Your code: Papa.parse(file, { complete: ... }) on the main thread","fr":"• Votre code appelle Papa.parse(file, { complete: ... }) sur le thread principal."}},{"kind":"p","page":162,"text":{"en":"• Parsing + validation + schema mapping = 3.8s of synchronous JS","fr":"• L’analyse du CSV, la validation et la mise en correspondance avec le schéma représentent 3,8 s de JavaScript synchrone."}},{"kind":"p","page":162,"text":{"en":"• During those 3.8s: scroll dies, the loading spinner stops spinning, input lag goes infinite","fr":"• Pendant ces 3,8 s, il est impossible de faire défiler la page ou de saisir du texte. L’indicateur de chargement ne tourne plus."}},{"kind":"p","page":162,"text":{"en":"• Your INP score on the perf dashboard is now red. Lighthouse is screaming.","fr":"• Sur le tableau de bord des performances, votre score INP est passé dans le rouge. Lighthouse signale le problème."}},{"kind":"p","page":162,"text":{"en":"Product wants this fixed before the enterprise demo on Friday. Four options on the table:","fr":"L’équipe produit veut une correction avant la démonstration pour les clients entreprise vendredi. Quatre approches sont envisagées :"}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":162,"text":{"en":"requestIdleCallback + time-slicing — chunk the parse into 5ms slices, yield between rows, let the browser breathe.","fr":"requestIdleCallback avec découpage temporel — découper l’analyse en tranches de 5 ms et rendre la main au navigateur entre les lignes."}}]},{"letter":"B","blocks":[{"kind":"p","page":163,"text":{"en":"Web Worker — move the entire parse + validation pipeline into worker.js, communicate via postMessage, main thread stays free.","fr":"Web Worker — déplacer tout le pipeline d’analyse et de validation dans worker.js, puis échanger les données via postMessage. Le thread principal reste disponible."}}]},{"letter":"C","blocks":[{"kind":"p","page":163,"text":{"en":"SharedArrayBuffer + Atomics — share the file buffer between main thread and 4 workers, parallelize the parse across cores, zero-copy.","fr":"SharedArrayBuffer et Atomics — partager le tampon du fichier entre le thread principal et quatre workers. Répartir l’analyse sur plusieurs cœurs sans copier les données."}}]},{"letter":"D","blocks":[{"kind":"p","page":163,"text":{"en":"Compile the parser to WebAssembly — drop the JS parser, run a Rust CSV parser through WASM for near-native speed.","fr":"Compiler l’analyseur en WebAssembly — remplacer la bibliothèque JavaScript par un analyseur CSV en Rust exécuté via WASM, pour obtenir des performances proches du natif."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"figure","page":164,"id":"164-03","width":800,"height":533,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["A, system Design Labs","Wh","ins: Web Worker","Move the heavy CSV parse + validation off the main thread.","ep the UI smooth. Alv","@ THE sovuTiON: weB WoRKER","Web Worker","Parse + Validate + Map","ter","[j- Parse + Validate","ULJANK","‘Separate 0S-lovel","React","Thread + Event Loop","Dashboard","Animation sick","Main throad stays fre and responsive:","RESULT:","Smooth UI","INP: ~B0ms","sero","cores @","KEY INSIGHT:","This isnt about faster code. It's about where the code runs.","Zoro-copy file transfer with Transferable.","Mair","No extra memory. Maximum performance.","IX. Worker thread = heavy compute.","Google Sheets","Excaidraw","VS Code Web","Boring,","oF","Everyone does","Rendering","Formula","Scene","Syntax","Pipeine","Recale","Processing","Highlighting","Ten years and","still the answer."],"fr":["A, système Design Labs","Wh","Ins: Web Worker","Déplacez l'analyse CSV lourde + validation hors du thread principal.","ep l'interface utilisateur lisse. Alv","LE sovuTiON: weB Worker","Web Worker","Analyse + Validation + Carte","ter","[j- Parse + Valider","ULJANK","«Séparés 0S-lovel","React","Thread + Boucle d'événement","Tableau de bord","Animation malade","Main throad reste fre et responsive:","RÉSULTAT:","Interface utilisateur fluide","INP: — B0ms","séro","cores","LA CLÉ D'INSTITUT:","Il ne s'agit pas de code plus rapide, mais de l'endroit où le code s'exécute.","Transfert de fichiers Zoro-copie avec Transferable.","Mair","Pas de mémoire supplémentaire. Performance maximale.","IX. Fil de travail — calcul intensif.","Google Sheets","Excaidraw","VS Code Web","Ennuyeux,","oF","Tout le monde fait","Rendu","Formule","Scène","Syntaxe","Pipeine","Recale","Traitement","Surlignement","Dix ans et","Toujours la réponse."]}},{"kind":"p","page":164,"text":{"en":"Why B wins:","fr":"Pourquoi retenir B ?"}},{"kind":"p","page":164,"text":{"en":"The actual problem isn't speed. It's where the work runs. The main thread is the same thread that handles scroll, input, layout, paint, and animation. Anything synchronous on it = jank. Period.","fr":"L’essentiel est de choisir où le traitement s’exécute. Le thread principal gère le défilement, les interactions, la mise en page, le rendu et l’animation. Une opération synchrone prolongée sur ce thread rend l’interface saccadée."}},{"kind":"p","page":164,"text":{"en":"A Web Worker is a separate OS-level thread with its own event loop. You ship the file (transferable via postMessage with a Transferable so it's zero-copy), parse it over there, send back the parsed rows. Main thread stays at 60fps the entire time. INP drops from 3800ms to ~80ms. Done.","fr":"Un Web Worker s’exécute sur un thread distinct doté de sa propre boucle d’événements. Envoyez le fichier via postMessage en utilisant un Transferable pour éviter une copie, analysez-le dans le worker et renvoyez les lignes obtenues. Le thread principal maintient 60 images par seconde pendant le traitement. L’INP passe de 3 800 ms à environ 80 ms."}},{"kind":"p","page":164,"text":{"en":"This is what Figma does for its rendering pipeline, what Google Sheets does for formula recalc, what Excalidraw does for its scene processing, what VS Code Web does for syntax highlighting. Every serious browser-based product runs heavy compute in a worker. It is the boring, correct, ten-year-old answer.","fr":"C’est l’approche employée par Figma pour son pipeline de rendu, Google Sheets pour le recalcul des formules, Excalidraw pour le traitement de sa scène et VS Code Web pour la coloration syntaxique. Les applications web exigeantes déportent couramment les calculs lourds vers un worker. Cette solution éprouvée existe depuis une dizaine d’années."}}],[{"kind":"p","page":165,"text":{"en":"Why A is wrong (the \"clever\" trap):","fr":"Le piège de A — découpage temporel"}},{"kind":"p","page":165,"text":{"en":"requestIdleCallback + time-slicing keeps the UI technically responsive but stretches the parse from 3.8s to ~6s of wall-clock time, because you're constantly yielding. Worse: idle callbacks are deprioritized — under load, they don't fire at all. React 18's concurrent rendering uses time-slicing for rendering, not for blocking IO-shaped work. Wrong tool.","fr":"Avec requestIdleCallback et le découpage temporel, l’interface reste réactive, mais l’analyse passe de 3,8 s à environ 6 s de temps réel parce que vous rendez sans cesse la main. Les callbacks de temps libre sont en outre moins prioritaires, au point de ne plus s’exécuter sous forte charge. Le rendu concurrent de React 18 découpe des tâches de rendu, ce qui ne répond pas à ce type de traitement bloquant."}}],[{"kind":"p","page":165,"text":{"en":"Why C is wrong (the SENIOR ENGINEER TRAP):","fr":"Le piège de C — SharedArrayBuffer et Atomics"}},{"kind":"p","page":165,"text":{"en":"SharedArrayBuffer + Atomics is the answer that sounds smart in a design review. \"We'll parallelize across cores! Zero-copy! Lock-free!\" Then you discover:","fr":"SharedArrayBuffer et Atomics paraissent séduisants en revue d’architecture : « On va distribuer le travail sur les cœurs, sans copie et sans verrou ! » Voici ce que cela implique :"}},{"kind":"p","page":165,"text":{"en":"• It requires COOP + COEP headers site-wide, which break Stripe Elements, YouTube embeds, Intercom, and half your analytics scripts.","fr":"• Les en-têtes COOP et COEP doivent être activés sur le site. Cela casse Stripe Elements, les vidéos YouTube intégrées, Intercom et la moitié des scripts d’analytics."}},{"kind":"p","page":165,"text":{"en":"• A single 80MB CSV parse is embarrassingly serializable — splitting rows across 4 cores saves you ~2s while costing you weeks of cross-origin isolation hell.","fr":"• L’analyse d’un seul CSV de 80 Mo se prête bien à un traitement séquentiel. Répartir les lignes sur quatre cœurs fait gagner environ deux secondes au prix de plusieurs semaines de travail liées à l’isolation cross-origin."}},{"kind":"p","page":165,"text":{"en":"• You now own a custom thread pool in JavaScript. In 2026.","fr":"• En 2026, votre équipe se retrouve à maintenir son propre pool de threads en JavaScript."}},{"kind":"p","page":165,"text":{"en":"SAB is the right answer for exactly two problems: real-time audio/video processing (where you need lock-free ring buffers between threads at 48kHz), and shared simulation state (think multiplayer game engines in the browser). A one-shot CSV upload is neither.","fr":"SharedArrayBuffer convient particulièrement à deux cas : le traitement audio ou vidéo en temps réel, qui demande des tampons circulaires sans verrou entre threads à 48 kHz, et le partage de l’état d’une simulation, par exemple dans un moteur de jeu multijoueur sur navigateur. L’import ponctuel d’un CSV présente d’autres contraintes."}}],[{"kind":"p","page":165,"text":{"en":"Why D is wrong:","fr":"Pourquoi écarter D ?"}},{"kind":"p","page":165,"text":{"en":"WASM makes the parser faster. It doesn't move it off the main thread. A WASM parser running synchronously on the main thread still freezes the UI — just for 1.2s instead of 3.8s. You'd still need to put it inside a worker. So D isn't an answer; it's a possible optimization inside B. And honestly, Papa Parse in a worker is fast enough that you don't need it.","fr":"WASM accélère l’analyse, mais ne la déplace pas. Sur le thread principal, un analyseur WASM synchrone fige encore l’interface, simplement pendant 1,2 s au lieu de 3,8 s. Vous devez malgré tout le placer dans un worker. D peut donc servir d’optimisation à l’intérieur de B. En pratique, Papa Parse dans un worker est déjà assez rapide."}}]]},{"day":41,"title":{"en":"Moving from Batch to Real-Time Streaming","fr":"Passer du traitement par lots au streaming en temps réel"},"pages":[166,168],"topic":"events","correct":"B","scenario":[{"kind":"figure","page":166,"id":"166-02","width":800,"height":420,"alt":{"en":"Day 41 featured","fr":"Illustration de la question du jour 41"},"transcript":{"en":["system","Design","abs","SLA: Surface fraud signals within 500ms","of a transaction. What do you pick?","consume","(fraud signals) ws road","Transaction","Katka","Streaming","DynamoDB","Fraud API","Source","Topic","Processor","(Table)","(Service)","(Python Model)","Kafka Streams — event-by-event processing,","Apache Flink — true streaming engine,","stateful operators, sub-10ms latency. Lives","‘exactly-once semantics, built for high-","inside your app JVM.","throughput stateful processing","under the hood, 100ms-5s windows, same","‘Spark Structured Streaming — micro-batch","Keep the batch job, drop the window to 1 minute —","ic)","‘near real-time” at zero migration cost.","‘API your team already knows."],"fr":["système","Design","abs","SLA: Signaux de fraude de surface dans les 500ms","d'une transaction. Que choisissez-vous?","consommer","(signaux de fraude) ws route","Transaction","Katka","Streaming","DynamoDB","API Fraude","Source","Thème","Processeur","(tableau)","(Service)","(modèle Python)","Kafka Streams — traitement événement par événement,","Apache Flink - moteur de streaming réel,","operators stateful, latence de sub-10ms. Vies","\"Sémantique exacte-une fois, construite pour les","dans votre application JVM.","traitement état de débit","sous le capot, 100ms-5s fenêtres, même","«Spark Structured Streaming — micro-lot","Gardez le travail de lot, baissez la fenêtre à 1 minute","ic)","« temps quasi réel » à coût de migration nul.","« Votre équipe le sait déjà."]}},{"kind":"p","page":166,"text":{"en":"Your data team just got a new SLA: surface fraud signals within 500ms of a transaction.","fr":"Votre équipe data a un nouvel engagement de niveau de service (SLA) : signaler les indices de fraude moins de 500 ms après une transaction."}},{"kind":"p","page":166,"text":{"en":"Right now you're running nightly Spark batch jobs. The business wants \"real-time.\" Your team knows Spark. Someone already opened a PR adding Spark Structured Streaming.","fr":"Aujourd’hui, vos tâches batch Spark tournent chaque nuit. Le métier demande du temps réel. Votre équipe connaît Spark, et quelqu’un a déjà ouvert une PR pour ajouter Spark Structured Streaming."}},{"kind":"p","page":166,"text":{"en":"The transaction volume: 8,000 events/sec peak. You're on AWS. The fraud model runs in Python. The output feeds a DynamoDB table the API reads from.","fr":"Le volume culmine à 8 000 événements par seconde. Votre infrastructure est sur AWS et le modèle de fraude s’exécute en Python. Les résultats alimentent une table DynamoDB que l’API consulte."}},{"kind":"p","page":166,"text":{"en":"You need to redesign the pipeline. What do you pick?","fr":"Vous devez repenser le pipeline. Quelle approche retenez-vous ?"}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":166,"text":{"en":"Kafka Streams — event-by-event processing, stateful operators, sub-10ms latency. Lives inside your app JVM.","fr":"Kafka Streams — traiter les événements un par un, avec des opérateurs à état et une latence inférieure à 10 ms. Le traitement tourne dans la JVM de votre application."}}]},{"letter":"B","blocks":[{"kind":"p","page":166,"text":{"en":"Apache Flink — true streaming engine, exactly-once semantics, built for high-throughput stateful processing.","fr":"Apache Flink — utiliser un moteur de streaming avec une sémantique exactly-once, conçu pour le traitement à état à haut débit."}}]},{"letter":"C","blocks":[{"kind":"p","page":166,"text":{"en":"Spark Structured Streaming — micro-batch under the hood, 100ms–5s windows, same API your team already knows.","fr":"Spark Structured Streaming — traiter des micro-lots en interne, avec des fenêtres de 100 ms à 5 s et une API que l’équipe connaît déjà."}}]},{"letter":"D","blocks":[{"kind":"p","page":166,"text":{"en":"Keep the batch job, drop the window to 1 minute — \"near real-time\" at zero migration cost.","fr":"Conserver le traitement batch et passer à une fenêtre d’une minute — obtenir du « quasi temps réel » sans coût de migration."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"figure","page":167,"id":"167-03","width":800,"height":533,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["ystem Design La","WHY B WINS","end-to-end","events/se","ro doubh","counting","handle out","of-order","handled","on failures","APACHE FLINK","ily","rly","write","(stream)","Apache","Flink","Transaction","Kafka","Fraud API","True Streaming Engine","DynamoDB","Source","Topic","(Event-by-Event)","(Table)","(Service)","‘TRUE STREAMING, NOT BATCH.","PYTHON FRAUD MODEL INTEGRATION","Flink sa true streaming engine — event-by-event","Integrate via PyFink (embedded Python operators)","Every transaction triggers processing the moment it arrives","ora sidecar Python microservce over @RPC.","LOW LATENCY","tency: sub-5Oms end-to-end with proper tuning","OPERATIONAL REALITY","Meets the 500ms SLA with headroom.","Operational overhead i eal. More components","More knobs. Requies skilled operators","HIGH THROUGHPUT","But the SLA demands it","[At 8K events/sec, Fink doesnt blink","But for high-throughput stateful workloads","EXACTLY-ONCE SEMANTICS","BUILT FOR THIS PROBLEM","State checkpoints + two-phase commits ensure your fraud","You're not reaching for Fink prematurely.","‘signals arent double-countod when anode falls.","‘The business asked for 500ms and gave you","HANDLES OUT-OF-ORDER EVENTS","8k events/eec. Thats exactly the problem","link was built for","Flink’s watermark model handles out-of-order events cleanly —","‘tial with elock sew from distributed payment processors"],"fr":["ystem Design","POURQUOI B WINS","de bout en bout","événements/se","ro doubh","comptage","hand out","d'ordre","manipulées","sur les échecs","APACHE FLINK","ily","rly","écrire","(flux)","Apache","Flink","Transaction","Kafka","API Fraude","Véritable moteur de streaming","DynamoDB","Source","Thème","(Événement par événement)","(tableau)","(Service)","«VRAI FLUX, PAS LOT.","INTÉGRATION DE MOD — LE DE FRAUDE AU PYTHON","Flink sa vrai moteur de streaming — événement par événement","Intégration via PyFink (opérateurs Python intégrés)","Chaque transaction déclenche le traitement dès son arrivée","ora sidecar Python microservce sur — RPC.","LATENCE FAIBLE","tency: sub-5Oms de bout en bout avec réglage approprié","RÉALITÉ OPÉRATIONNELLE","Répond à la 500ms SLA avec marge de manœuvre.","Frais généraux d'exploitation. Plus de composants","Plus de boutons. Requies opérateurs qualifiés","ÉLEVÉE","Mais le SLA l'exige","[À 8K événements/sec, Fink ne clignote pas","Mais pour les charges de travail à haut débit","SÉMANTIQUE EXACTEMENT UNIQUE","CONSTRUIRE POUR CE PROBL — ME","Les contrôles d'état + les commits en deux phases garantissent votre fraude","Tu ne cherches pas Fink prématurément.","Les signaux ne sont pas à double compte quand l'anode tombe.","L'entreprise a demandé 500ms et vous a donné","HANDLES ÉVÉNEMENTS HORS COMMANDE","8k events/eec. C'est exactement le problème","Le lien a été construit pour","Le modèle de filigrane de Flink gère proprement les événements hors-commande","«elock cousu à partir de processeurs de paiement distribués"]}},{"kind":"p","page":167,"text":{"en":"Why B wins (Apache Flink):","fr":"Pourquoi retenir B — Apache Flink ?"}},{"kind":"p","page":167,"text":{"en":"Flink is a true streaming engine — event-by-event, not batch. Every transaction triggers processing the moment it arrives. Latency: sub-50ms end-to-end with proper tuning. At 8K events/sec, Flink doesn't blink. Exactly-once semantics mean your fraud signals aren't double-counted when a node fails. The Python fraud model integrates via PyFlink or a sidecar microservice. Flink's watermark model handles out-of-order events cleanly — which matters when transactions arrive from distributed payment processors with clock skew.","fr":"Flink traite chaque événement dès son arrivée. Correctement réglé, il descend sous les 50 ms de bout en bout sans difficulté à 8 000 événements par seconde. La sémantique exactly-once évite de compter deux fois un signal de fraude si un nœud tombe. Le modèle Python s’intègre via PyFlink ou via un microservice sidecar. Les watermarks de Flink gèrent les événements arrivés dans le désordre, ce qui compte lorsque les transactions proviennent de prestataires de paiement distribués dont les horloges sont décalées."}},{"kind":"p","page":167,"text":{"en":"Operational overhead is real. But the SLA demands it. You're not reaching for Flink prematurely here — the business asked for 500ms and gave you 8K events/sec. That's exactly the problem Flink was built for.","fr":"Le surcoût d’exploitation est réel, mais le SLA le justifie. Le métier exige 500 ms à 8 000 événements par seconde. Flink est conçu pour ces contraintes."}}],[{"kind":"p","page":168,"text":{"en":"Why A is close but not the cleanest fit (Kafka Streams):","fr":"Pourquoi A est une solution proche, mais moins adaptée — Kafka Streams"}},{"kind":"p","page":168,"text":{"en":"Kafka Streams is event-by-event too — sub-10ms achievable. The constraint: it runs inside your application JVM. Your fraud model is Python. That means Kafka Streams handles the stream topology, but the model scoring lives in a separate Python service, adding a network hop. Flink handles that boundary more cleanly with PyFlink. Kafka Streams is the right call if the fraud logic is stateful JVM-native aggregation. Wrong default when the model is a Python service.","fr":"Kafka Streams traite lui aussi les événements un par un et peut passer sous les 10 ms. Sa contrainte est de tourner dans la JVM de l’application, tandis que votre modèle de fraude est en Python. Kafka Streams gère donc la topologie du flux, mais le calcul du score doit se faire dans un service Python distinct, via un appel réseau supplémentaire. Flink simplifie cette intégration avec PyFlink. Kafka Streams est un bon choix si la détection se résume à des agrégations à état dans la JVM. Il est moins adapté par défaut quand le modèle tourne dans un service Python."}}],[{"kind":"p","page":168,"text":{"en":"Why C is the senior engineer trap (Spark Structured Streaming):","fr":"Le piège de C — Spark Structured Streaming"}},{"kind":"p","page":168,"text":{"en":"The PR is already open. The API looks familiar. But Structured Streaming is micro-batch — it collects events for a trigger interval (practically 100ms–5s under production load), then processes them as a mini-batch. You'll tune it, it'll pass staging, and it'll breach SLA the first time peak traffic hits. Mistaking \"Streaming\" in the name for actual event-by-event processing is the trap.","fr":"La PR est déjà ouverte et l’API est familière. Pourtant, Structured Streaming traite des micro-lots : il accumule les événements pendant l’intervalle entre deux déclenchements, de 100 ms à 5 s en conditions de production, puis traite le lot. Avec un bon réglage, cela passera en préproduction, puis dépassera le SLA au premier pic de trafic. Le mot « Streaming » ne garantit pas un traitement événement par événement."}}],[{"kind":"p","page":168,"text":{"en":"Why D is eliminated immediately (batch, 1-minute windows):","fr":"Pourquoi éliminer D d’emblée — batch avec fenêtres d’une minute ?"}},{"kind":"p","page":168,"text":{"en":"Minimum latency = the window size. At 60 seconds you're 120x over SLA before the first line of fraud logic runs. \"Near real-time\" is not a SLA.","fr":"La latence minimale correspond à la taille de la fenêtre. À 60 secondes, vous dépassez déjà le SLA d’un facteur 120 avant même que la détection de fraude commence. « Quasi temps réel » ne constitue pas un engagement mesurable."}}]]},{"day":42,"title":{"en":"Designing Memory for an AI Agent","fr":"Concevoir la mémoire d’un agent IA"},"pages":[169,172],"topic":"ai","correct":"C","scenario":[{"kind":"figure","page":169,"id":"169-02","width":800,"height":420,"alt":{"en":"Day 42 featured","fr":"Illustration de la question du jour 42"},"transcript":{"en":["system","Your Al agent remembered the user’s name.","Design Labs","Then it","Read","Tools & APIs |","Call LLM","context","(with context)","Relevant","context","Updat","User","‘Agent","LLM","B we.","Orchestrator","Pricing","| Read/Write","Session State","Event","to","(Short-term)","In-context window only — full conversation","Vector memory store — embed","retrieve the top-k by semantic similarity","stays in the system prompt. Simple. Breaks","at query time. Works great until “NYC flight™","at ~15 turns or 8K tokens, whichever comes first.","pulls a memory about a past NYC trip","Instead of the current task.","Episodic memory with summarization —","‘compress old turns into structured event","Redis session state — structured key-value","summ:","ies, inject the relevant ones per","store, explicit agent reads/writes. Deterministic.","ic)","request. More complex to bulld. Much","Requires the agent to know what to store","harder to confuse.","and when."],"fr":["système","Votre agent Al se souvenait du nom de l'utilisateur.","Design Labs","Ensuite, il","Lire","Outils & APIs","Appelez LLM","contexte","(avec contexte)","Pertinent","contexte","Actualiser","Utilisateur","«Agent","LLM","B nous.","Orchestrator","Prix","Lire/écrire","État de la session","Événement","au","(à court terme)","Fenêtre dans le contexte seulement — conversation complète","Vector memory store — embed","récupérer le top-k par similarité sémantique","reste dans l'invite système. Simple. Pauses","à l'heure de la requête. Fonctionne très bien jusqu'à \"NYC flightTM","à — 15 tours ou 8K jetons, selon la première éventualité.","un souvenir d'un voyage passé à NYC","Au lieu de la tâche actuelle.","Mémoire épisodique avec résumé","« comprimer les vieux se transforme en événement structuré","État de la session Redis — valeur-clé structurée","summ:",", injecter les pertinentes par","store, explicit agent reads/writes. Déterministe.","ic)","demande. Plus complexe à bulld. Beaucoup","Nécessite que l'agent sache quoi stocker","plus difficile à confondre.","et quand."]}},{"kind":"p","page":169,"text":{"en":"Your AI agent remembered the user's name.","fr":"Votre agent IA s’est souvenu du nom de l’utilisateur."}},{"kind":"p","page":169,"text":{"en":"Then it forgot what it was doing.","fr":"Puis il a oublié la tâche qu’il était en train d’accomplir."}},{"kind":"p","page":169,"text":{"en":"Here's the setup:","fr":"Voici la configuration."}},{"kind":"p","page":169,"text":{"en":"User asks the agent: book the cheapest flight to NYC, search hotels under $150/night, then compare total trip cost.","fr":"L’utilisateur demande à l’agent de réserver le vol le moins cher pour New York, de chercher des hôtels à moins de 150 $ la nuit, puis de comparer le coût total du séjour."}},{"kind":"p","page":169,"text":{"en":"By step 3, the agent calls the LLM with 8,000 tokens of raw conversation history — and still answers as if it's turn 1.","fr":"À la troisième étape, l’agent envoie 8 000 tokens d’historique brut au LLM. Il répond malgré tout comme si la conversation venait de commencer."}},{"kind":"p","page":169,"text":{"en":"You need a memory architecture before this ships. Which one do you pick?","fr":"Vous devez concevoir la mémoire de l’agent avant la mise en production. Quelle architecture choisissez-vous ?"}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":169,"text":{"en":"In-context window only — full conversation stays in the system prompt. Simple. Breaks at ~15 turns or 8K tokens, whichever comes first.","fr":"Fenêtre de contexte uniquement — conserver toute la conversation dans le prompt système. C’est simple, mais l’approche atteint ses limites à environ 15 tours ou 8 000 tokens, au premier des deux seuils atteints."}}]},{"letter":"B","blocks":[{"kind":"p","page":169,"text":{"en":"Vector memory store — embed past turns, retrieve the top-k by semantic similarity at query time. Works great until \"NYC flight\" pulls a memory about a past NYC trip instead of the current task.","fr":"Mémoire vectorielle — calculer les embeddings des tours passés, puis récupérer les k tours les plus similaires à chaque requête. Cela fonctionne jusqu’à ce que « vol pour New York » fasse remonter un précédent voyage à New York à la place de la tâche en cours."}}]},{"letter":"C","blocks":[{"kind":"p","page":169,"text":{"en":"Episodic memory with summarization — compress old turns into structured event summaries, inject the relevant ones per request. More complex to build. Much harder to confuse.","fr":"Mémoire épisodique avec résumés — condenser les anciens tours sous forme de résumés structurés d’événements et injecter ceux qui sont pertinents pour chaque nouvelle requête. Cela demande plus de travail, mais limite les confusions."}}]},{"letter":"D","blocks":[{"kind":"p","page":170,"text":{"en":"Redis session state — structured key-value store, explicit agent reads/writes. Deterministic. Requires the agent to know what to store and when.","fr":"État de session dans Redis — utiliser un stockage clé-valeur structuré et laisser l’agent lire et écrire explicitement. Le comportement est déterministe. L’agent doit savoir quoi stocker et quand le faire."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"figure","page":171,"id":"171-03","width":800,"height":533,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["System Design Labs","C — Episodic memory with summarization","Right answer for task-oriented agents.","Keep the last N turns in context","> Compross older turns into","Inject only relevant summaries","(short-term)","structured event summaries (episodic)","per new request","Wire (new turns)","Short-Term Memory","ocont Tu","Inject Content","Message","APICals","External APIs","uM","(Flights, Hotels)","User","Al Agent","Summarize","(2024-05-10)","intent NYC in","Relevant","Retrieve","Summaries","+ Stable content window","+ Harder to confuse","+ Degraes gracefully","Veco < 80","* Used by Anthropic,LangChain","Memory v2, nd Open","In-contet window ony — fll","Vector memory store — embed","Episodic memory with","Redis session state — structured","‘conversion stay inthe system","past tums, retrieve the top-k by","summarization — compress","prompt. Simple Breaks at ~15","Semantic similarity at query time","cd turns int structured event","{ums or BK tokens, whichever","Wirks great until “NYC fight\"","summaries, jet the relevant","Requires the agent to know","pulls memory about a past NYC","cones per request. More complex","to build, Much harder to confuse","hat ostore and when,","trp instead ofthe curren tak."],"fr":["System Design Labs","C — Mémoire épisodique avec résumé","La bonne réponse pour les agents axés sur les tâches.","Garder les N derniers tours dans leur contexte","> Compros plus vieux se transforme en","Injecter uniquement des résumés pertinents","(à court terme)","Résumés d'événements structurés (épisodes)","par nouvelle demande","Fil (nouveaux virages)","Mémoire à court terme","ocont Tu","Injecter du contenu","Message","APICals","API externes","uM","(Vols, hôtels)","Utilisateur","Al Agent","Résumé","(2024-05-10)","Intention NYC dans","Pertinent","Récupère","Résumés","+ Fenêtre de contenu stable","+ Plus difficile à confondre","+ Degraes gracieusement","Veco — 80","* Utilisé par Anthropic,LangChain","Mémoire v2, nd Ouvert","Fenêtre sur la page de garde","Vector memory store — embed","Mémoire épisodique avec","État de la session Redis — structuré","«reste dans le système","passé tums, récupérer le top-k par","résumé — compress","Rapide. Pauses simples à — 15","Similitude sémantique au moment de la requête","cd devient un événement structuré","ums ou BK tokens, selon","Wirks grand jusqu'à \"NYC combat\"","résumés, jet le pertinent","Nécessite que l'agent sache","Mémoire d'un passé NYC","cônes sur demande. Plus complexe","à construire, beaucoup plus difficile à confondre","chapeau ostore et quand,","Trp au lieu du curren tak."]}},{"kind":"p","page":171,"text":{"en":"C — Episodic memory with summarization","fr":"C — Mémoire épisodique avec résumés"}},{"kind":"p","page":171,"text":{"en":"Right answer for task-oriented agents. The pattern:","fr":"C’est l’approche adaptée aux agents chargés d’accomplir des tâches :"}},{"kind":"p","page":171,"text":{"en":"→ Keep the last N turns in context (short-term)","fr":"→ Garder les N derniers tours dans le contexte, en mémoire à court terme."}},{"kind":"p","page":171,"text":{"en":"→ Compress older turns into structured event summaries (episodic)","fr":"→ Condenser les tours précédents en résumés structurés d’événements, dans la mémoire épisodique."}},{"kind":"p","page":171,"text":{"en":"→ Inject only relevant summaries per new request","fr":"→ Injecter uniquement les résumés pertinents pour la nouvelle requête."}},{"kind":"p","page":171,"text":{"en":"It's how production agents at Anthropic, LangChain Memory v2, and OpenAI Assistants API all converge. More engineering upfront — but the only pattern that degrades gracefully at scale.","fr":"Les agents en production chez Anthropic, LangChain Memory v2 et l’API OpenAI Assistants convergent vers cette approche. Elle demande plus d’ingénierie au départ, mais c’est la seule des quatre dont le comportement se dégrade progressivement à grande échelle."}}],[{"kind":"p","page":172,"text":{"en":"A — In-context window only","fr":"A — Fenêtre de contexte uniquement"}},{"kind":"p","page":172,"text":{"en":"Collapses fast. At ~15 turns or 8K tokens you're either truncating early context or hitting the model's limit. Works for demos. Fails in production agents with multi-step tasks. The \"just increase context length\" argument ignores cost and the lost-in-the-middle problem — LLMs reliably ignore content buried in the middle of long prompts.","fr":"L’approche atteint vite ses limites. À environ 15 tours ou 8 000 tokens, vous devez tronquer le début du contexte ou vous heurter à la limite du modèle. Cela suffit pour une démonstration, mais échoue en production pour des tâches en plusieurs étapes. Augmenter la fenêtre de contexte coûte plus cher et ne règle pas le problème « lost in the middle » : les LLM laissent souvent de côté ce qui est enfoui au milieu d’un long prompt."}}],[{"kind":"p","page":172,"text":{"en":"B — Vector memory store","fr":"B — Mémoire vectorielle"}},{"kind":"p","page":172,"text":{"en":"The retrieval problem is nastier than it looks. Semantic similarity isn't the same as task relevance. In a multi-step booking task, embedding \"find hotels under $150\" might retrieve a memory from a different user session — or a past conversation about a different city entirely. Great for knowledge retrieval. Unreliable for procedural task state.","fr":"La recherche est plus délicate qu’elle ne paraît. Une forte similarité sémantique ne suffit pas pour retrouver ce qui est pertinent à la tâche en cours. Lors d’une réservation en plusieurs étapes, calculer l’embedding de « trouver un hôtel à moins de 150 $ » peut faire remonter un souvenir d’une autre session, voire d’une conversation sur une autre ville. La mémoire vectorielle est utile pour retrouver des connaissances. Elle est peu fiable pour conserver l’état d’une tâche en cours."}}],[{"kind":"p","page":172,"text":{"en":"D — Redis session state","fr":"D — État de session dans Redis"}},{"kind":"p","page":172,"text":{"en":"Solid and deterministic. The catch: the agent has to explicitly decide what to write to state and when to read it. That's a non-trivial design problem — you're building a working memory protocol on top of your tool calls. Most teams underestimate the schema design this requires.","fr":"La solution est robuste et déterministe, à condition que l’agent détermine explicitement quoi écrire dans l’état et quand le lire. C’est un vrai travail de conception : vous ajoutez un protocole de mémoire de travail par-dessus les appels d’outils. La plupart des équipes sous-estiment la conception du schéma nécessaire."}}]]},{"day":43,"title":{"en":"Reliable CDN Cache Invalidation on Deploy","fr":"Invalider le cache du CDN à chaque déploiement"},"pages":[173,175],"topic":"scale","correct":"A","scenario":[{"kind":"figure","page":173,"id":"173-02","width":800,"height":420,"alt":{"en":"Day 43 featured","fr":"Illustration de la question du jour 43"},"transcript":{"en":["‘System Design Labs","You need a CDN configuration that handles","invalidation reliably under deploy pressure. Which one do you pick?","HTTPS","cache","Read","New","Request","Lookup","Assets","aS","DNS","lients","(Anycast)","CDN Edge","Origin","Object","(Anycast)","Server","Storage","(Purge)","oy)","Event","Anycast routing + stale-while-revalidate +","Unicast routing + aggressive TTLs +","event-driven purge via API on deploy","manual cache purge via dashboard","Anycast routing + long TTLs +","Anycast routing + short TTLs +","tag-based invalidation via API","no invalidation strategy (let caches expire naturally)"],"fr":["«System Design Labs","Vous avez besoin d'une configuration CDN qui gère","invalidation fiable sous pression de déploiement. Lequel choisissez-vous?","HTTPS","cache","Lire","Nouveau","Demande","Recherche","Actif","aS","DNS","lients","(Anycast)","CDN Edge","Origine","Objet","(Anycast)","Serveur","Stockage","(Purge)","oy)","Événement","Anycast routage + périmé-while-revalidate +","Routage Unicast + TTL agressifs +","purge par événement via API sur deploy","purge manuelle du cache via le tableau de bord","Routage Anycast + TTLs longs +","routage Anycast + TTL courts +","Invalidation basée sur les balises via API","pas de stratégie d'invalidation (laissez les caches expirer naturellement)"]}},{"kind":"p","page":173,"text":{"en":"Your CDN saved you from explaining a 400ms load time to your VP.","fr":"Votre CDN vous a évité d’avoir à expliquer à votre direction pourquoi le chargement prenait 400 ms."}},{"kind":"p","page":173,"text":{"en":"Then your deploy shipped. And nobody got the fix.","fr":"Puis vous avez déployé un correctif que personne n’a reçu."}},{"kind":"p","page":173,"text":{"en":"Here's what happened:","fr":"Voici ce qui s’est passé."}},{"kind":"p","page":173,"text":{"en":"Your edge nodes were still serving the old JS bundle — TTL hadn't expired. You triggered a cache purge manually. But you hit the wrong environment. Prod kept serving the stale version for 6 more hours.","fr":"Les nœuds périphériques continuaient de servir l’ancien bundle JavaScript, car son TTL n’avait pas expiré. Vous avez lancé une purge du cache à la main, dans le mauvais environnement. La production a servi l’ancienne version pendant six heures de plus."}},{"kind":"p","page":173,"text":{"en":"You need a CDN configuration that handles invalidation reliably under deploy pressure. Which one do you pick?","fr":"Il vous faut une configuration CDN qui invalide le cache de façon fiable même sous la pression d’un déploiement. Que choisissez-vous ?"}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":173,"text":{"en":"Anycast routing + stale-while-revalidate + event-driven purge via API on deploy","fr":"Routage anycast, stale-while-revalidate et purge via l’API déclenchée à chaque déploiement."}}]},{"letter":"B","blocks":[{"kind":"p","page":173,"text":{"en":"Unicast routing + aggressive TTLs + manual cache purge via dashboard","fr":"Routage unicast, TTL courts et purge manuelle du cache depuis le tableau de bord."}}]},{"letter":"C","blocks":[{"kind":"p","page":173,"text":{"en":"Anycast routing + long TTLs + tag-based invalidation via API","fr":"Routage anycast, TTL longs et invalidation par tags via l’API."}}]},{"letter":"D","blocks":[{"kind":"p","page":173,"text":{"en":"Anycast routing + short TTLs + no invalidation strategy (let caches expire naturally)","fr":"Routage anycast et TTL courts, sans stratégie d’invalidation. Chaque entrée expire naturellement."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"figure","page":174,"id":"174-03","width":800,"height":533,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["Anycast + stale-while-revalidate +","System Design Labs","event-driven purge via API on deploy","CDN Edge (Anycast PoPs)","Stale-while-revalidate","Users","(Aways fast)","Anycast","Serve from cache","Same fom multiple","(stant)","PoPs. BGP routes each","Tolge |","edge automaticaly.","User |","“Tokyo user hits Tokyo —","ag io","background","not Virgina","Stale-while-revaidate","aS","Serve the cached version","=o oe","{tesh copy inthe","background,","Users never wait on 8","Instant Purge oA","Event-driven purge","Purge Ite","CY/CO piptine fies an","targeting exactly the","‘APL call on every deploy","changed assets.","Cade","Build","Deploy","Notity","‘CON APL","No manual steps. No","commit","wrong-env clicks. No","2AM mistakes."],"fr":["Anycast + périmé-alors-revalider +","System Design Labs","purge par événement via API sur deploy","CDN Edge (PoPs)","Stale-while-revalidate","Utilisateurs","(Toujours rapide)","Anycast","Servir depuis le cache","Même fom multiple","(instantané)","PoPs. BGP routes chacun","Tolge","edge automatiquealy.","Utilisateur","« L’utilisateur de Tokyo frappe Tokyo","ag io","Contexte","pas Virgina","Stale-while-revaidate","aS","Servez la version en cache","o oe","tesh copier inthe","historique,","Les utilisateurs n'attendent jamais 8","Purge instantanée oA","Purge pilotée par événement","Purge Ite","CY/CO piptine","Cibler exactement le","« Appel APL à chaque déploiement","change d'actifs.","Cade","Construire","Déployer","Notity","«CON APL","Pas d'étapes manuelles. Non","commit","clics sur les mauvais env.","Erreurs 2AM."]}},{"kind":"p","page":174,"text":{"en":"A — Anycast + stale-while-revalidate + event-driven purge — the right answer","fr":"A — Anycast, stale-while-revalidate et purge déclenchée par le déploiement : le bon choix"}},{"kind":"p","page":174,"text":{"en":"Anycast advertises the same IP from multiple PoPs. BGP routes each user to the closest edge automatically. Tokyo user hits Tokyo — not Virginia.","fr":"En anycast, plusieurs points de présence (PoP) annoncent la même adresse IP. BGP dirige automatiquement les utilisateurs vers le nœud périphérique le plus proche. Un utilisateur à Tokyo est servi depuis Tokyo plutôt que depuis la Virginie."}},{"kind":"p","page":174,"text":{"en":"Stale-while-revalidate: serve the cached version immediately, fetch a fresh copy in the background. Users never wait on a cache miss to resolve.","fr":"stale-while-revalidate : servir immédiatement la version en cache, puis récupérer la version actualisée en arrière-plan. Les utilisateurs n’attendent pas que le cache ait fini de se reconstituer."}},{"kind":"p","page":174,"text":{"en":"Event-driven purge: your CI/CD pipeline fires a Cloudflare or CloudFront API call on every deploy, targeting exactly the changed assets. No manual steps. No wrong-env clicks. No 2 AM mistakes.","fr":"Purge déclenchée par le déploiement : votre pipeline CI/CD appelle l’API de Cloudflare ou de CloudFront à chaque déploiement, en ciblant précisément les ressources modifiées. Cela élimine les manipulations manuelles, les erreurs d’environnement et les oublis à deux heures du matin."}}],[{"kind":"p","page":175,"text":{"en":"C — Anycast + long TTLs + tag-based invalidation — solid, but has a trap","fr":"C — Anycast, TTL longs et invalidation par tags : une approche solide qui présente un risque"}},{"kind":"p","page":175,"text":{"en":"Tag-based invalidation (Cloudflare Cache-Tag, Fastly surrogate keys) lets you group objects and purge entire logical groups in one API call. New product images? Invalidate tag:product-images. Clean and surgical.","fr":"L’invalidation par tags, par exemple avec Cache-Tag chez Cloudflare ou les surrogate keys chez Fastly, permet de regrouper les objets et de purger tout un groupe logique en un appel d’API. Pour de nouvelles images de produits, invalidez tag:product-images. La purge reste précise et ciblée."}},{"kind":"p","page":175,"text":{"en":"The trap: long TTLs work perfectly when your deploy pipeline is robust. But if your invalidation API call fails silently during an incident — when you're moving the fastest — you're serving the wrong version for hours with no TTL fallback to save you.","fr":"Les TTL longs fonctionnent bien lorsque le pipeline de déploiement est robuste. Si l’appel d’invalidation échoue sans alerte pendant un incident, au moment où vous allez le plus vite, vous servez la mauvaise version pendant des heures. Le TTL est trop long pour limiter le problème."}},{"kind":"p","page":175,"text":{"en":"Option A's stale-while-revalidate degrades more gracefully when your pipeline gets messy.","fr":"Avec stale-while-revalidate dans l’option A, le service se dégrade plus progressivement lorsque le pipeline rencontre un problème."}}],[{"kind":"p","page":175,"text":{"en":"B — Unicast + aggressive TTLs + manual purge","fr":"B — Unicast, TTL courts et purge manuelle"}},{"kind":"p","page":175,"text":{"en":"Unicast means one edge region. Your Tokyo users are routing to Virginia. You've deployed a CDN and you're routing past it.","fr":"Dans cette configuration unicast, une seule région périphérique reçoit le trafic. Vos utilisateurs à Tokyo sont redirigés vers la Virginie. Vous avez déployé un CDN sans profiter de sa proximité."}},{"kind":"p","page":175,"text":{"en":"Manual dashboard purges during a deploy: someone will forget, click the wrong environment, or skip it entirely at 2 AM. Aggressive TTLs shrink the damage window — they don't make invalidation reliable.","fr":"Lors des déploiements, quelqu’un finira par oublier de purger le cache, choisir le mauvais environnement ou passer l’étape à deux heures du matin. Des TTL courts limitent la durée d’exposition sans rendre l’invalidation plus fiable."}}],[{"kind":"p","page":175,"text":{"en":"D — Short TTLs, no invalidation","fr":"D — TTL courts, sans invalidation"}},{"kind":"p","page":175,"text":{"en":"\"Short TTLs = always fresh\" is the most expensive misconception in CDN config.","fr":"Croire que des « TTL courts garantissent des données toujours à jour » est une erreur particulièrement coûteuse en configuration CDN."}},{"kind":"p","page":175,"text":{"en":"Every TTL expiry is a potential cache stampede. 200k RPS at peak, TTL expires on a hot endpoint, every PoP fires a simultaneous request to your origin. You go from 0 to 200k RPS in 2 seconds.","fr":"À chaque expiration du TTL, une ruée sur le cache est possible. À 200 000 requêtes par seconde en pointe, le TTL d’un endpoint très sollicité expire et tous les PoP interrogent le serveur d’origine en même temps. Vous passez de 0 à 200 000 requêtes par seconde en deux secondes."}},{"kind":"p","page":175,"text":{"en":"And you have zero control for hotfixes. You just wait for the TTLs to drain.","fr":"Vous n’avez par ailleurs aucun levier pour appliquer un correctif urgent. Vous devez attendre que les TTL expirent."}}]]},{"day":44,"title":{"en":"Syncing Offline Edits Without Data Loss","fr":"Synchroniser les modifications hors ligne sans perdre de données"},"pages":[176,179],"topic":"data","correct":"D","scenario":[{"kind":"figure","page":176,"id":"176-02","width":800,"height":420,"alt":{"en":"Day 44 featured","fr":"Illustration de la question du jour 44"},"transcript":{"en":["tem De","What's your architecture?","Syacon","Syne Service","eas wre","Local Store","(Backend)","Primary","Database","Field Tech","op","Process","Service","Move everything to localStorage + a manut","Keep IndexedDB, add a vector-clock field to every","ISON diff on syne. Simpler API, deterministic","record. On syne, compare clocks —if diverged,","‘schema versioning — no IndexedDB migration","surface a merge UI. Let the technician decid","headaches.","Never throw away a write.","Wrap IndexedDB in a versioned schema migration","Replace client-side storage with a CRDT-based","yer","ike Dexie,js). Add a per-record updated_at","ye (Automerge or Yjs). Operations are","+devi","composite","-wins, but","commutative and associat","— merge is always","last-write","now deter","jatic and au","ble,","vali",", conflicts are structurally impossible."],"fr":["tem De","Quelle est votre architecture ?","Syacon","Syne Service","eas wre","Magasin local","(Backend)","Primaire","Base de données","Field Tech","op","Processus","Service","Déplacer tout vers localStorage + une manut","Gardez IndexedDB, ajoutez un champ vector-clock à chaque","ISON diff sur syne. API plus simple, déterministe","En syne, comparer les horloges — si divergé,","«versionnement du schéma — pas de migration IndexedDB","surface une interface utilisateur de fusion. Laissez le technicien décider","Des maux de tête.","Ne jetez jamais une écriture.","Wrap IndexedDB dans une migration de schéma versionnée","Remplacer le stockage côté client par un stockage CRDT","yer","ike Dexie,js). Ajouter un enregistrement updated_at","ye (Automerge ou Yjs).","+devi","composite","- Gagne, mais","commutatif et associatif","la fusion est toujours","dernière-écriture","Détruisez maintenant","jatic et au","ble,","vali","Les conflits sont structurellement impossibles."]}},{"kind":"p","page":176,"text":{"en":"Your team just shipped \"offline mode\" for your field-service app.","fr":"Votre équipe vient de lancer le « mode hors ligne » de son application d’intervention sur le terrain."}},{"kind":"p","page":176,"text":{"en":"Technicians work in basements, tunnels, plant floors — connectivity is unreliable.","fr":"Les techniciens travaillent dans des sous-sols, des tunnels et des ateliers. La connexion y est instable."}},{"kind":"p","page":176,"text":{"en":"The demo looked great. Navigator.onLine said false, the app kept working, the sync button pulsed green. You shipped to 400 users.","fr":"La démonstration était convaincante : Navigator.onLine renvoyait false, l’application continuait de fonctionner et le bouton de synchronisation clignotait en vert. Vous avez déployé la fonctionnalité auprès de 400 utilisateurs."}},{"kind":"p","page":176,"text":{"en":"Then the incident reports started.","fr":"Puis les incidents ont commencé à remonter."}},{"kind":"p","page":176,"text":{"en":"Technician in Munich finishes a repair job offline, syncs when she gets signal. Her updates are gone — overwritten by a colleague who edited the same record online 12 minutes earlier. Last-write-wins. Her write lost.","fr":"À Munich, une technicienne termine une réparation sans réseau et synchronise dès qu’elle retrouve du signal. Ses mises à jour ont disparu. Les modifications d’un collègue, qui a changé le même enregistrement en ligne douze minutes plus tôt, les ont écrasées. Avec la règle Last-Write-Wins, son écriture a été perdue."}},{"kind":"p","page":176,"text":{"en":"Technician in São Paulo opens the app, goes offline, edits three assets. Comes back online. App throws an unhandled promise rejection and crashes. IndexedDB schema was on version 2. The update shipped version 3. The migration never ran because he'd never opened the app while online.","fr":"À São Paulo, un technicien ouvre l’application, passe hors ligne et modifie trois équipements. Quand il se reconnecte, une promesse est rejetée sans que l’erreur soit interceptée, et l’application plante. Son schéma IndexedDB était encore en version 2 alors que la mise à jour livrait la version 3. La migration ne s’était pas exécutée, car il n’avait jamais ouvert l’application en ligne."}},{"kind":"p","page":176,"text":{"en":"You're now asked to actually fix offline-first — not demo it.","fr":"On vous demande maintenant de rendre l’application réellement offline-first, au-delà de la démonstration."}},{"kind":"p","page":176,"text":{"en":"Here's the setup:","fr":"Voici la configuration."}},{"kind":"p","page":176,"text":{"en":"• 400 field technicians, avg offline window of 40 minutes","fr":"• 400 techniciens sur le terrain, avec des périodes hors ligne de 40 minutes en moyenne."}},{"kind":"p","page":177,"text":{"en":"• Write conflicts happen ~3x per day, always on the same 8 \"hot\" assets","fr":"• Environ trois conflits d’écriture par jour, toujours sur les huit mêmes équipements très sollicités."}},{"kind":"p","page":177,"text":{"en":"• Sync currently runs on reconnect via a single bulk POST","fr":"• La synchronisation se lance à la reconnexion via une seule requête POST groupée."}},{"kind":"p","page":177,"text":{"en":"• IndexedDB is being used but schema migrations are undocumented","fr":"• L’application utilise IndexedDB, sans documentation sur les migrations de schéma."}},{"kind":"p","page":177,"text":{"en":"• You need conflict resolution, migration safety, and sync reliability","fr":"• Il faut résoudre les conflits, sécuriser les migrations et fiabiliser la synchronisation."}},{"kind":"p","page":177,"text":{"en":"What's your architecture?","fr":"Quelle architecture adoptez-vous ?"}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":177,"text":{"en":"Move everything to localStorage + a manual JSON diff on sync. Simpler API, deterministic schema versioning — no IndexedDB migration headaches.","fr":"Tout migrer vers localStorage et calculer manuellement un diff JSON à la synchronisation. L’API est plus simple, le versionnement du schéma est déterministe et vous évitez les migrations IndexedDB."}}]},{"letter":"B","blocks":[{"kind":"p","page":177,"text":{"en":"Keep IndexedDB, add a vector-clock field to every record. On sync, compare clocks — if diverged, surface a merge UI. Let the technician decide. Never throw away a write.","fr":"Conserver IndexedDB et ajouter une horloge vectorielle à chaque enregistrement. À la synchronisation, comparer les horloges. Si elles ont divergé, afficher une interface de fusion et laisser le technicien décider. Aucune écriture n’est jetée automatiquement."}}]},{"letter":"C","blocks":[{"kind":"p","page":177,"text":{"en":"Wrap IndexedDB in a versioned schema migration layer (like Dexie.js). Add a per-record updated_at + device_id composite key. Last-write-wins, but last-write is now deterministic and auditable.","fr":"Encapsuler IndexedDB dans une couche de migration de schéma versionnée, comme Dexie.js. Ajouter une clé composite updated_at + device_id à chaque enregistrement. Garder Last-Write-Wins, avec une règle de départage désormais déterministe et auditable."}}]},{"letter":"D","blocks":[{"kind":"p","page":177,"text":{"en":"Replace client-side storage with a CRDT-based sync engine (Automerge or Yjs). Operations are commutative and associative — merge is always valid, conflicts are structurally impossible.","fr":"Remplacer le stockage côté client par un moteur de synchronisation basé sur des CRDT, comme Automerge ou Yjs. Les opérations sont commutatives et associatives, de sorte que la fusion reste valide et que les conflits sont exclus par la structure."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"figure","page":178,"id":"178-03","width":800,"height":533,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["Why D wins: CRDT Engine — Automerge / Yjs","TECHNICIAN A","TECHNICIAN","CCRDTs guarantee the same","(OFFLINE)","(OFFLINE)","FINAL STATE","result no matter the order.","yee)","© Commutative","age","© Associative","Edits Asset","Edits Asset","(hours ofine)","‘Syne Engine","‘Same result","done","+ Order","Merge is mathemati","ily","ops et tau","uaranteed. Always the","0p: ad ote \"placed pure","‘same final state,","‘0p! add note “Checked valves\"","+ Network","‘This is what the best tools run on.","‘No merge UI. No “who wins” logic.","It's not overengineering.","No data loss.","It's the endgame.","Linear + Automerge","bd","Figma — Custom CROT","‘Two people can edt the same record","‘Teams try LWW. Then timestamps.","Notion — CROT for block store","fie for hours, Avays safe,","‘Then merge Uls. Then they bud","(er adopt) CROTS.","Larger payloads","Engine matters","‘Server must understand ops","What you","Sa","(CROTS cary operation","You cant just overwrite rows,","trade off","story. More data over","sharing, updates AP.","Server needs to merge CROT","the wire and on ask","‘Automerge is simple,","‘operations, not valves.","heavier","Ifyou ns","cd offline + multi-writer + zero data los","CRD’","fe the only approach with a mathematical guarantee."],"fr":["Pourquoi retenir D: CRDT Engine — Automerge / Yjs","TECHNICIEN A","TECHNICIAN","Les CCRDT garantissent la même chose","(ARR — T)","(ARR — T)","ÉTAT FINAL","résultat, peu importe l'ordre.","oui)","Commutatif","age","Association","Édite la ressource","Édite la ressource","(heures de cours)","«Syne Engine","«Même résultat","terminé","+ Commande","La fusion est mathématique","ily","ops et tau","Toujours la même chose.","0p: ad ote \"placé pur","«même état final,","«0p! ajouter la note \"Valves contrôlées\"","+ Réseau","« C’est sur cela que fonctionnent les meilleurs outils.","Pas de logique « qui gagne ».","Ce n'est pas de la suringénierie.","Pas de perte de données.","C'est la finale.","Linéaire + Autofusion","bd","Figma — Custom CROT","\"Deux personnes peuvent battre le même record","« Les équipes essaient LWW. Puis les horodatages.","Notion — CROT pour magasin de blocs","fie pendant des heures,","« Puis fusionnent Uls. Puis ils bourgeonnent","(ou adopter) des CROTS.","Charges utiles plus importantes","Le moteur est important","« Le serveur doit comprendre les opérations","Ce que vous","Sa","(CROTS cary opération","Vous ne pouvez pas simplement écraser des lignes,","commercer","story. Plus de données","partage, mises à jour AP.","Le serveur doit fusionner CROT","le fil et sur demande","« L’automérisation est simple,","« Des opérations, pas des vannes.","plus lourd","Si vous ns","cd offline + multi-auteur + zéro données los","CRD»","C'est la seule approche avec une garantie mathématique."]}},{"kind":"p","page":178,"text":{"en":"Why D wins (CRDT engine — Automerge / Yjs):","fr":"Pourquoi retenir D — moteur CRDT avec Automerge ou Yjs ?"}},{"kind":"p","page":178,"text":{"en":"CRDTs (Conflict-free Replicated Data Types) are the only approach where merge is mathematically guaranteed to produce the same result regardless of the order operations arrive. They're commutative, associative, and idempotent.","fr":"Parmi ces approches, les CRDT, ou types de données répliquées sans conflit, sont les seuls à garantir mathématiquement que la fusion produit le même résultat quel que soit l’ordre d’arrivée des opérations. Celles-ci sont commutatives, associatives et idempotentes."}},{"kind":"p","page":178,"text":{"en":"Two technicians can edit the same asset record offline for 6 hours, sync in any order — and the final state is always deterministic. No merge UI. No \"who wins\" logic. No data loss.","fr":"Deux techniciens peuvent modifier la fiche du même équipement hors ligne pendant six heures, puis synchroniser dans n’importe quel ordre. L’état final est déterministe, sans interface de fusion, choix d’un gagnant ni perte de données."}},{"kind":"p","page":178,"text":{"en":"Linear uses Automerge. Figma uses a custom CRDT for multiplayer. Notion runs a similar model for their block store. This isn't overengineering — it's what teams reach after trying everything else.","fr":"Linear utilise Automerge. Figma emploie un CRDT maison pour l’édition multiutilisateur. Notion s’appuie sur un modèle similaire pour le stockage de ses blocs. C’est une solution que les équipes adoptent après avoir éprouvé les autres approches."}},{"kind":"p","page":178,"text":{"en":"Tradeoff: CRDT payloads are larger (they carry operation history). Yjs is lighter than Automerge for most cases. Server-side merge logic needs to understand CRDT ops, not just overwrite rows.","fr":"Le compromis : les charges utiles sont plus volumineuses parce qu’elles transportent l’historique des opérations. Yjs est plus léger qu’Automerge dans la plupart des cas. Côté serveur, la logique de fusion doit interpréter les opérations du CRDT au lieu d’écraser simplement des lignes."}}],[{"kind":"p","page":179,"text":{"en":"Why B is the correct second choice (Vector Clocks + Merge UI):","fr":"Pourquoi B est le deuxième choix — horloges vectorielles et interface de fusion"}},{"kind":"p","page":179,"text":{"en":"Vector clocks detect exactly when a conflict occurred — which device wrote what and in what order. When diverged, you surface a merge UI and let the technician decide.","fr":"Les horloges vectorielles permettent de repérer précisément un conflit et de savoir quelles écritures viennent de quels appareils et dans quel ordre. Si les versions divergent, affichez une interface de fusion et laissez le technicien décider."}},{"kind":"p","page":179,"text":{"en":"Right answer when humans must stay in the loop. A technician marking an asset \"inspected\" vs another marking it \"needs repair\" — that's not a conflict an algorithm should auto-resolve.","fr":"C’est le bon choix lorsqu’une personne doit garder la main. Si un technicien marque un équipement comme « inspecté » et un autre comme « à réparer », une résolution automatique n’est pas souhaitable."}},{"kind":"p","page":179,"text":{"en":"Tradeoff: every conflict requires user action. At 3/day it's manageable. At 300/day it's a support nightmare.","fr":"Chaque conflit demande en contrepartie l’intervention d’un utilisateur. À trois par jour, cela reste gérable. À 300, la charge de support devient ingérable."}}],[{"kind":"p","page":179,"text":{"en":"Why C is good but not enough (Versioned IndexedDB + LWW):","fr":"Pourquoi C répond à une partie du problème — IndexedDB versionné et LWW"}},{"kind":"p","page":179,"text":{"en":"Dexie.js makes IndexedDB migrations genuinely manageable. LWW with a deterministic composite key (updated_at + device_id) is production-grade.","fr":"Dexie.js rend les migrations IndexedDB réellement gérables. Last-Write-Wins avec une clé composite déterministe (updated_at + device_id) est une approche utilisable en production."}},{"kind":"p","page":179,"text":{"en":"But LWW throws away real writes. The Munich technician always loses to anyone who touched the same record online in the interim. In a field-service app where \"inspected\" vs \"not inspected\" has regulatory consequences — that's data loss you can't accept.","fr":"Des écritures sont toutefois perdues. La technicienne de Munich perd sa modification face à toute personne qui a modifié le même enregistrement en ligne entre-temps. Dans une application d’intervention, où la différence entre « inspecté » et « non inspecté » peut avoir des conséquences réglementaires, cette perte est inacceptable."}},{"kind":"p","page":179,"text":{"en":"LWW works when the cost of losing a write is low (a UI preference). It breaks when every write has operational meaning.","fr":"Last-Write-Wins fonctionne quand perdre une écriture ne coûte presque rien, par exemple pour une préférence d’interface. La règle atteint ses limites lorsque chaque écriture a une conséquence opérationnelle."}}],[{"kind":"p","page":179,"text":{"en":"Why A fails (localStorage + JSON diff):","fr":"Pourquoi A échoue — localStorage et diff JSON"}},{"kind":"p","page":179,"text":{"en":"localStorage is hard-capped at ~5MB. At 200 records with attachment metadata, you'll hit it — silently, with no useful error in older Chrome. No indexing. No range queries. In private/incognito mode, it's scoped per-tab and wiped on close.","fr":"localStorage est plafonné à environ 5 Mo. Avec 200 enregistrements et des métadonnées de pièces jointes, vous atteindrez cette limite, sans message exploitable dans les anciennes versions de Chrome. Il n’y a ni index ni requêtes sur des plages de valeurs. En navigation privée, le stockage est limité à l’onglet et effacé à sa fermeture."}},{"kind":"p","page":179,"text":{"en":"JSON diff breaks on nested arrays, partial field updates, deletions. You'd end up building a mini-CRDT by hand without the guarantees.","fr":"Le diff JSON atteint ses limites avec les tableaux imbriqués, les mises à jour partielles et les suppressions. Vous finiriez par recréer un petit CRDT à la main sans en obtenir les garanties."}},{"kind":"p","page":179,"text":{"en":"Works in a weekend prototype. Corrupts silently in production.","fr":"Vous pouvez en faire un prototype en un week-end. En production, les données risquent d’être corrompues sans signalement."}}]]},{"day":45,"title":{"en":"Scaling Full-Text Search","fr":"Mettre à l’échelle la recherche plein texte"},"pages":[180,183],"topic":"scale","correct":"A","scenario":[{"kind":"figure","page":180,"id":"180-02","width":800,"height":420,"alt":{"en":"Day 45 featured","fr":"Illustration de la question du jour 45"},"transcript":{"en":["‘System Design Labs","Product is escalating. What do you do?","100M documents","le, descr","tags)","Current p9!","2s","search","read","query","cute","documents","deliver","results","Search","yeSQL","Tetch","Object","Web / Mobil","results","API","Full-Text Search","content","Storage","Client","(42s p95)","earch — inverted index,","‘Add GIN indexes on your PostgreSQL","Migrate to Ela","tsvector columns — no new infra, meaningful","purpose-built for full-text, sub-100ms at scale.","performance gain.","Cache the top 1,000 most common queries","Move to Typesense or Meilisearch —","in Redis — free win for the majority of traffic.","simpler ops than Elasticsearch, built for search."],"fr":["«System Design Labs","Le produit s'intensifie. Que faites-vous ?","100M documents","le, descr","tags)","P9 actuel !","2s","recherche","lire","requête","mignon","documents","livre","résultats","Rechercher","yeSQL","Tetch","Objet","Web / Mobil","résultats","API","Recherche plein texte","contenu","Stockage","Client","(42s p95)","earch — indice inversé,","‘Ajouter des index GIN sur votre PostgreSQL","Migrer vers Ela","tsvector columns — pas de nouvel infra, significatif","spécialement conçu pour le texte intégral, sous-100ms à l'échelle.","gain de performance.","Cache le top 1000 requêtes les plus courantes","Passez à Typesense ou Meilisearch","en Redis — gain gratuit pour la majorité du trafic.","plus simple que Elasticsearch, construit pour la recherche."]}},{"kind":"p","page":180,"text":{"en":"Your search box returns results in 80ms.","fr":"Votre moteur de recherche renvoie des résultats en 80 ms."}},{"kind":"p","page":180,"text":{"en":"Then you add 50M more documents. Now it's 4 seconds.","fr":"Puis vous ajoutez 50 millions de documents. Il faut désormais quatre secondes."}},{"kind":"p","page":180,"text":{"en":"Your DBA says \"add an index.\" Your search engineer says \"that's not how this works.\"","fr":"Votre administrateur de base de données vous dit : « Ajoutez un index. » Votre spécialiste de la recherche répond : « Ce n’est pas comme ça que ça marche. »"}},{"kind":"p","page":180,"text":{"en":"They're both right — about different things.","fr":"Tous les deux ont raison, sur des aspects différents."}},{"kind":"p","page":180,"text":{"en":"Here's the setup:","fr":"Voici la configuration."}},{"kind":"p","page":180,"text":{"en":"Platform: SaaS product, 100M documents","fr":"Plateforme : produit SaaS de 100 millions de documents."}},{"kind":"p","page":180,"text":{"en":"Search fields: title, description, tags, partial phrases","fr":"Éléments recherchés : titres, descriptions, tags et fragments d’expressions."}},{"kind":"p","page":180,"text":{"en":"Current stack: PostgreSQL full-text search","fr":"Stack actuelle : recherche plein texte PostgreSQL."}},{"kind":"p","page":180,"text":{"en":"Current perf: p95 = 4.2s","fr":"Performances actuelles : p95 = 4,2 s."}},{"kind":"p","page":180,"text":{"en":"Target: sub-200ms at p99","fr":"Objectif : moins de 200 ms au p99."}},{"kind":"p","page":180,"text":{"en":"Product is escalating. What do you do?","fr":"L’équipe produit demande une solution rapidement. Que faites-vous ?"}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":180,"text":{"en":"Migrate to Elasticsearch — inverted index, purpose-built for full-text, sub-100ms at scale.","fr":"Migrer vers Elasticsearch — adopter un index inversé conçu pour la recherche plein texte, avec des réponses en moins de 100 ms à grande échelle."}}]},{"letter":"B","blocks":[{"kind":"p","page":181,"text":{"en":"Add GIN indexes on your PostgreSQL tsvector columns — no new infra, meaningful performance gain.","fr":"Ajouter des index GIN sur les colonnes tsvector de PostgreSQL — obtenir un gain sensible sans ajouter d’infrastructure."}}]},{"letter":"C","blocks":[{"kind":"p","page":181,"text":{"en":"Cache the top 1,000 most common queries in Redis — free win for the majority of traffic.","fr":"Mettre en cache dans Redis les 1 000 requêtes les plus courantes — accélérer la majorité du trafic à peu de frais."}}]},{"letter":"D","blocks":[{"kind":"p","page":181,"text":{"en":"Move to Typesense or Meilisearch — simpler ops than Elasticsearch, built for search.","fr":"Migrer vers Typesense ou Meilisearch — adopter un moteur spécialisé dont l’exploitation est plus simple qu’Elasticsearch."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"figure","page":182,"id":"182-03","width":800,"height":445,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["‘System Design Labs","¥) ANSWER: A - Elasticsearch with inverted indexes","Elasticsearch uses inverted indexes. Queries do fast posting-list intersections instead of table scans.","Scales to 100M+ docs with horizontal sharding and parallel query fan-out for sub-100ms at p99.","Target","iG","Elasticsearch Cluster","query","cm | { om","search query","(tant)","reste","Search","Shard2","|<} object","Web / Mobile","API","top hits","(Lucene)","(lucene)","fetch","Storage","Client","(scores)","content","Q 8g","‘Add GIN indexes on your PostgreSQL","Migrate to Elasticsearch — inverted index,","tevector columne — no new infra, meaningful","purpose-built for full-text, sub-100ms at scale.","performance gain","Cache the top 1,000 most common queries","Move to Typesense or Meilisearch —","in Redis — free win for the maj","of traffic,","simpler ops than Elasticsearch, built for search.","(0"],"fr":["«System Design Labs",") RÉPONSE : A - Elasticsearch avec index inversés","Elasticsearch utilise des index inversés. Les requêtes accélèrent les intersections de liste de publication au lieu d'analyses de table.","Échelle jusqu'à 100 M+ docs avec découpage horizontal et sortie de requête parallèle pour les sous-100ms à p99.","Objectif","iG","Elasticsearch Cluster","requête","cm","recherche requête","(tant)","reste","Rechercher","Shard2","objet","Web / Mobile","API","top hits","(Lucene)","(lucène)","récupérer","Stockage","Client","(notes)","contenu","Q 8g","‘Ajouter des index GIN sur votre PostgreSQL","Migrer vers Elasticsearch — index inversé,","tevector columne — pas de nouvel infra, significatif","spécialement conçu pour le texte intégral, sous-100ms à l'échelle.","gain de performance","Cache le top 1000 requêtes les plus courantes","Passez à Typesense ou Meilisearch","à Redis — victoire gratuite pour le maj","de trafic,","plus simple que Elasticsearch, construit pour la recherche.","(0"]}},{"kind":"p","page":182,"text":{"en":"Why A wins (Elasticsearch):","fr":"Pourquoi retenir A — Elasticsearch ?"}},{"kind":"p","page":182,"text":{"en":"Elasticsearch is built on an inverted index. When you index a document, Elasticsearch tokenizes the text and writes posting lists: \"database\" → [doc_1, doc_5, doc_23...], \"index\" → [doc_2, doc_5, doc_18...]. A query for \"database index\" does a fast posting-list intersection — not a table scan.","fr":"Elasticsearch repose sur un index inversé. À l’indexation d’un document, il segmente le texte en tokens et produit une liste de documents pour chaque terme : « database » → [doc_1, doc_5, doc_23...], « index » → [doc_2, doc_5, doc_18...]. Rechercher « database index » revient à calculer rapidement l’intersection des deux listes, sans parcourir la table entière."}},{"kind":"p","page":182,"text":{"en":"At 100M documents, that intersection still runs in milliseconds because posting lists are stored in delta-compressed sorted form, Lucene segments are immutable (no row locking, no MVCC overhead), horizontal sharding is native (queries fan out in parallel), and BM25 scoring runs during retrieval — not after it.","fr":"À 100 millions de documents, cette intersection prend encore quelques millisecondes. Les listes triées sont compressées par différences, les segments Lucene sont immuables, ce qui évite les verrous de ligne et le surcoût MVCC, le sharding horizontal est natif et répartit les requêtes en parallèle, et le score BM25 est calculé pendant la recherche."}},{"kind":"p","page":182,"text":{"en":"Result: sub-100ms at p99, even at 100M+ docs, with proper shard sizing. Netflix, Uber, and GitHub all run some form of this at their search layer.","fr":"Avec des shards bien dimensionnés, le p99 passe sous les 100 ms, même au-delà de 100 millions de documents. Netflix, Uber et GitHub utilisent chacun une approche de ce type dans leur couche de recherche."}},{"kind":"p","page":182,"text":{"en":"The tradeoffs you accept: new infrastructure to operate (index lifecycle, shard rebalancing), write amplification from segment merging, and eventual consistency — by default, newly indexed docs aren't searchable for ~1 second.","fr":"Les compromis : vous devez exploiter une nouvelle infrastructure, gérer le cycle de vie des index et rééquilibrer les shards. La fusion des segments amplifie les écritures, et la cohérence est à terme : par défaut, les documents fraîchement indexés ne sont consultables qu’après environ une seconde."}}],[{"kind":"p","page":183,"text":{"en":"Why B is the trap answer (GIN indexes on PostgreSQL):","fr":"Le piège de B — index GIN sur PostgreSQL"}},{"kind":"p","page":183,"text":{"en":"GIN indexes on tsvector are genuinely good. For 1M–5M documents, this is the right call — no new infra, no ops burden, real improvement.","fr":"Les index GIN sur tsvector sont efficaces. Pour 1 à 5 millions de documents, c’est le bon choix : le gain est réel sans nouvelle infrastructure ni charge d’exploitation supplémentaire."}},{"kind":"p","page":183,"text":{"en":"At 100M documents, you hit three walls: index size balloons (GIN is large — easily 40–80GB), PostgreSQL full-text has no native horizontal read scaling, and BM25 relevance scoring is bolted on, not native. You get from 4.2s down to maybe 500ms. You need 200ms. Close, but the wrong tool at this scale.","fr":"À 100 millions de documents, trois limites apparaissent. L’index GIN gonfle facilement entre 40 et 80 Go, la recherche plein texte de PostgreSQL n’offre pas de mise à l’échelle horizontale native des lectures et le classement BM25 nécessite une intégration supplémentaire. Vos 4,2 s descendront peut-être à 500 ms, alors que l’objectif est de 200 ms. Le gain est significatif, mais insuffisant à cette échelle."}},{"kind":"p","page":183,"text":{"en":"GIN is what you reach for before you need a dedicated search engine, not instead of one.","fr":"Adoptez GIN tant que votre charge ne nécessite pas de moteur de recherche dédié."}}],[{"kind":"p","page":183,"text":{"en":"Why C misses the point (Redis cache):","fr":"Pourquoi C passe à côté — cache Redis"}},{"kind":"p","page":183,"text":{"en":"Caching top queries is a real optimization — but it's not a search architecture. Your top 1,000 queries might cover 40% of traffic. The other 60% hits the slow path. Worse: every document update invalidates your cache logic. You've added complexity without touching the tail latency product is actually complaining about.","fr":"Mettre en cache les requêtes les plus fréquentes est une vraie optimisation. Les 1 000 premières couvrent peut-être 40 % du trafic, et les 60 % restants empruntent toujours le parcours lent. De plus, chaque mise à jour de document complique l’invalidation du cache. La latence des requêtes les plus lentes, qui motive la demande du produit, reste inchangée."}},{"kind":"p","page":183,"text":{"en":"C is a band-aid. The p99 problem is still there the moment any user types something that isn't in the cache.","fr":"C est un correctif ponctuel. Le problème de p99 réapparaît dès qu’un utilisateur saisit une requête absente du cache."}}],[{"kind":"p","page":183,"text":{"en":"Why D is tempting but limited (Typesense / Meilisearch):","fr":"Pourquoi D est séduisant, mais limité — Typesense ou Meilisearch"}},{"kind":"p","page":183,"text":{"en":"Typesense and Meilisearch are excellent — simpler ops than Elasticsearch, great developer experience, built-in typo tolerance. For 10M–30M documents, D is a legitimate answer that wins on simplicity.","fr":"Typesense et Meilisearch sont d’excellents moteurs : exploitation plus simple qu’Elasticsearch, bonne expérience de développement et tolérance intégrée aux fautes de frappe. Entre 10 et 30 millions de documents, la simplicité de D en fait une option valable."}},{"kind":"p","page":183,"text":{"en":"At 100M documents with strict p99 requirements and complex relevance tuning, you start hitting their limits: distributed indexing is less mature, fine-grained scoring customization is constrained, and operational tooling at scale is thinner than Elasticsearch's ecosystem. For a smaller product, D is the right call. At 100M with a p99 SLA, Elasticsearch is where you end up.","fr":"À 100 millions de documents, avec des exigences strictes sur le p99 et un réglage avancé de la pertinence, leurs limites apparaissent. L’indexation distribuée est moins mûre, la personnalisation fine du score est limitée et les outils d’exploitation à grande échelle sont moins étoffés que ceux de l’écosystème Elasticsearch. D convient aux produits plus petits. À 100 millions de documents avec un SLA sur le p99, Elasticsearch s’impose."}}]]},{"day":46,"title":{"en":"Enforcing Structured Output from an LLM","fr":"Imposer des sorties structurées à un LLM"},"pages":[184,188],"topic":"ai","correct":"B","scenario":[{"kind":"figure","page":184,"id":"184-02","width":800,"height":420,"alt":{"en":"Day 46 featured","fr":"Illustration de la question du jour 46"},"transcript":{"en":["System Design Labs","Your agent returns invalid, untyped JSON.","How do you guarantee valid, typed output — every time?","Confirmation","Email","Request","Order","LLM Prompt","JSON","Write","Processing","= Response —>","Service","Downstream","User","LLM Agent","Service","Prompt-engineer harder — add \"Always return","Use structured outputs / function calling","valid JSON with these exact fields\" to your","{OpenAl, Bedrock tool use, Gemini response","system prompt and document the schema inline.","schema) — constrain the model at the API level","to return a typed schema.","a validation layer — parse","‘Add a second LLM as a judge — pass the first","the output, run JSON Schema or Pydantic","model's output to a smaller, faster model that","validation, retry with corrective context","scores and flags invalid responses before they","if it fails (max 2 retries)","reach your service."],"fr":["System Design Labs","Votre agent renvoie JSON invalide et non tapé.","Comment garantissez-vous une sortie valide et tapée – à chaque fois?","Confirmation","Adresse électronique","Demande","Commande","LLM Prompt","JSON","Ecrire","Traitement","Réponse — >","Service","En aval","Utilisateur","LLM Agent","Service","Prompt-ingénieur plus difficile — ajouter \"Toujours revenir","Utiliser des sorties structurées / appel de fonction","valide JSON avec ces champs exacts\" à votre","OpenAl, utilisation de l'outil Bedrock, réponse Gemini","invite système et documente le schéma en ligne.","schema) — contraindre le modèle au niveau de l'API","pour retourner un schéma typé.","une couche de validation — parse","« Ajouter un deuxième LLM en tant que juge – passer le premier","la sortie, exécutez JSON Schema ou Pydantic","modèle vers un modèle plus petit et plus rapide qui","validation, réessayer avec le contexte correctif","scores et signale les réponses invalides avant qu'elles ne","si elle échoue (max 2 tentatives)","atteindre votre service."]}},{"kind":"p","page":184,"text":{"en":"Your production LLM agent just returned this JSON to your order processing service:","fr":"En production, votre agent LLM vient d’envoyer le JSON suivant au service de traitement des commandes."}},{"kind":"code","page":184,"text":{"en":"{\n  \"action\": \"refund\",\n  \"amount\": \"fifty dollars\",\n  \"order_id\": null,\n  \"confidence\": \"pretty high\"\n}","fr":"{\n  \"action\": \"refund\",\n  \"amount\": \"fifty dollars\",\n  \"order_id\": null,\n  \"confidence\": \"pretty high\"\n}"}},{"kind":"p","page":184,"text":{"en":"Your downstream service crashes. The retry hits the same model. Same broken output. The refund never fires — but the user got a confirmation email.","fr":"Le service aval plante. La nouvelle tentative interroge le même modèle et reçoit la même sortie invalide. Le remboursement n’est jamais déclenché, alors que l’utilisateur a reçu un e-mail de confirmation."}},{"kind":"p","page":184,"text":{"en":"You need your agent to return valid, typed, structured output — every time. What do you do?","fr":"Votre agent doit renvoyer une sortie valide, typée et structurée à chaque appel. Que faites-vous ?"}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":185,"text":{"en":"Prompt-engineer harder — add \"Always return valid JSON with these exact fields\" to your system prompt and document the schema inline.","fr":"Affiner le prompt. Ajoutez « Renvoyez toujours du JSON valide contenant exactement ces champs » au prompt système et décrivez le schéma dans le prompt."}}]},{"letter":"B","blocks":[{"kind":"p","page":185,"text":{"en":"Use structured outputs / function calling (OpenAI, Bedrock tool use, Gemini response schema) — constrain the model at the API level to return a typed schema.","fr":"Utiliser les sorties structurées ou l’appel de fonctions (OpenAI, outils Bedrock, schéma de réponse Gemini). Imposez au modèle un schéma typé au niveau de l’API."}}]},{"letter":"C","blocks":[{"kind":"p","page":185,"text":{"en":"Post-process with a validation layer — parse the output, run JSON Schema or Pydantic validation, retry with corrective context if it fails (max 2 retries).","fr":"Ajouter une couche de validation après la génération. Analysez la sortie, validez-la avec JSON Schema ou Pydantic et relancez avec des instructions de correction en cas d’échec, avec deux nouvelles tentatives au maximum."}}]},{"letter":"D","blocks":[{"kind":"p","page":185,"text":{"en":"Add a second LLM as a judge — pass the first model's output to a smaller, faster model that scores and flags invalid responses before they reach your service.","fr":"Utiliser un deuxième LLM comme juge. Transmettez la sortie du premier modèle à un modèle plus petit et plus rapide, qui la note et signale les réponses invalides avant qu’elles n’arrivent à votre service."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"figure","page":186,"id":"186-03","width":800,"height":533,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["Structured Outputs / API-Level Schema Enforcement","The only option that eliminates the problem at the source.","WITH STRUCTURED OUTPUTS (8 WINS)","pas","“ty as","Sere","on","mount 5.6,","Order","uM","uM","ord 25\",","Agent","“prety","Agent","‘Seve","(Constrained","Decoding)","loa untyped cut","‘Aways valid","Rais doit he","HOW IT WORKS (UNDER THE HOOD)","PRODUCTION USAGE","with Pantie","(roan acid","response_format","Python) oe","toe","aws","Pass schema","Sls owe","Teal Use Corrs APL","oa","Google Gemini","you typed","© onsite sta cvtmanc ony cal. Canc lt","© owner series verse ting wre they expec an"],"fr":["Structured Outputs / API-Level Schema","La seule option qui élimine le problème à la source.","AVEC STRUCTURE DE SORTIE (8 WINS)","pas","« Ti","Sere","le","Monture 5.6,","Commande","uM","uM","ord 25\",","Agent","«prety","Agent","«Seve","(Contrainte","Décodage)","loa coupe non typée","«Toujours valable","Rais fait he","COMMENT — A FONCTIONNÉ (APR — S LA MAISON)","UTILISATION DE LA PRODUCTION","avec Pantie","(acide roux)","format_réponse","Python)","orteil","aws","Schéma de passe","Sls doit","Correspond à l'utilisation des sarcelles","oa","Google Gemini","vous avez tapé","sur place sta cvtmanc ony cal. Canc lt","série propriétaire verset ting wre ils expec un"]}},{"kind":"p","page":186,"text":{"en":"Why B wins (Structured outputs / API-level schema enforcement):","fr":"Pourquoi B fonctionne, avec des sorties structurées imposées par l’API"}},{"kind":"p","page":186,"text":{"en":"This is the only option that eliminates the problem at the source. When you use OpenAI's response_format: { type: \"json_schema\" }, Bedrock's tool use / converse API, or Gemini's response_schema, the model's token sampling is constrained — it cannot produce output that violates the schema. Not \"it's less likely.\" Cannot.","fr":"Cette approche élimine le problème à la source. Avec response_format: { type: \"json_schema\" } chez OpenAI, les outils Bedrock ou son API Converse, ou response_schema chez Gemini, l’échantillonnage est contraint. Le modèle ne peut produire aucune sortie en dehors du schéma."}},{"kind":"p","page":186,"text":{"en":"Under the hood, these APIs use constrained decoding: the model's output probability distribution is masked so invalid tokens are zeroed out at each step. The result is guaranteed schema conformance on every call. No retries. No parsing. No \"it worked 98% of the time.\"","fr":"Ces API utilisent le décodage contraint. À chaque étape, le masque de probabilités attribue une probabilité nulle aux tokens qui rendraient la sortie invalide. La conformité au schéma est garantie à chaque appel, sans relance ni analyse corrective. Finis les résultats valides seulement 98 % du temps."}},{"kind":"p","page":186,"text":{"en":"In production: use Pydantic (Python) or Zod (TypeScript) to define your schema, pass it to the API, deserialize directly into your typed model. Your downstream service never sees a string where it expects an int.","fr":"En production, définissez le schéma avec Pydantic (Python) ou Zod (TypeScript), transmettez-le à l’API, puis désérialisez directement dans votre modèle typé. Le service aval reçoit toujours un entier lorsqu’il en attend un."}}],[{"kind":"p","page":187,"text":{"en":"Why A is wishful thinking (Prompt engineering):","fr":"Pourquoi le prompt seul (A) est insuffisant"}},{"kind":"p","page":187,"text":{"en":"\"Always return valid JSON\" is not a contract. It's a suggestion.","fr":"« Renvoyez toujours du JSON valide » reste une consigne indicative."}},{"kind":"p","page":187,"text":{"en":"LLMs are probabilistic text predictors. Under load, edge-case prompts, or slightly different phrasing, they drift. You'll get valid JSON 97% of the time and a markdown code block the other 3%. At 10k requests/day that's 300 failures. At 100k, it's 3,000.","fr":"Les LLM prédisent du texte par des méthodes probabilistes. Sous charge, face à des cas limites ou à une légère variation du prompt, la sortie peut dériver. Vous obtenez du JSON valide dans 97 % des cas et un bloc Markdown dans les 3 % restants. À 10 000 requêtes par jour, cela représente 300 échecs. À 100 000, 3 000 échecs."}},{"kind":"p","page":187,"text":{"en":"Prompt engineering is a first step when you're prototyping. It is not an output validation strategy for production. Teams that rely on this eventually write 50-line system prompts trying to enumerate every failure mode. The model still escapes.","fr":"Travailler le prompt est une première étape utile en prototypage. En production, il faut une validation effective des sorties. Les équipes qui s’en remettent au prompt finissent par écrire 50 lignes d’instructions système pour anticiper tous les cas d’échec. Le modèle trouve encore le moyen de sortir du cadre."}}],[{"kind":"p","page":187,"text":{"en":"Why C is correct but incomplete (Post-process + retry loop):","fr":"Pourquoi C est utile et reste incomplet, avec validation et relances"}},{"kind":"p","page":187,"text":{"en":"Validation layer + retry with corrective context is a legitimate, widely-used pattern — especially when you can't use structured outputs (e.g., open-source models like Llama, Mistral, or your own fine-tune via Ollama/vLLM).","fr":"Valider, puis relancer avec les corrections à apporter, est une pratique répandue, surtout lorsque les sorties structurées sont indisponibles, par exemple sur Llama ou Mistral en open source, ou un modèle affiné maison servi par Ollama ou vLLM."}},{"kind":"p","page":187,"text":{"en":"The implementation: parse → validate with Pydantic/JSON Schema → on failure, re-inject the original prompt + the bad output + a correction instruction (\"Your previous output had these errors: [list]. Try again.\") → retry, max 2 attempts → fail hard and surface to human review.","fr":"Analysez la sortie, puis validez-la avec Pydantic ou JSON Schema. En cas d’échec, renvoyez le prompt d’origine, la sortie erronée et la consigne « Votre réponse précédente contenait les erreurs suivantes : [liste]. Réessayez. ». Limitez-vous à deux tentatives et, si elles échouent, signalez explicitement l’échec pour examen humain."}},{"kind":"p","page":187,"text":{"en":"But: this is your fallback, not your primary. Every retry is latency + cost. Under high load, retry storms can spike your API spend 3–4x. Corrective context also doesn't help when the model fundamentally can't produce what you're asking — you'll just retry into the same failure.","fr":"Gardez cette méthode en secours. Chaque relance ajoute de la latence et des coûts. Sous forte charge, une avalanche de relances peut tripler ou quadrupler la facture API. Si le modèle est incapable de produire le résultat demandé, le contexte correctif conduira aux mêmes échecs."}},{"kind":"p","page":187,"text":{"en":"Use C when B isn't available. Use B when it is....","fr":"Utilisez B dès que possible et C en solution de secours."}}],[{"kind":"p","page":188,"text":{"en":"Why D is a trap (LLM-as-judge for validation):","fr":"Pourquoi D est un piège, avec un LLM comme juge pour la validation"}},{"kind":"p","page":188,"text":{"en":"LLM-as-judge is a real eval pattern — it's used to score quality, tone, safety, and correctness in offline evaluation pipelines and red-teaming.","fr":"Le LLM comme juge s’utilise réellement dans les évaluations hors ligne et le red teaming pour mesurer la qualité, le ton, la sûreté et l’exactitude."}},{"kind":"p","page":188,"text":{"en":"For structural output validation in a hot path? It's expensive, slow (~200–500ms extra per request), and unreliable for schema enforcement. A judge model can tell you \"this response seems wrong\" — it cannot guarantee a valid typed object. You've added latency and cost without actually solving the problem.","fr":"Vérifier la structure sur le chemin critique coûte cher et ajoute environ 200 à 500 ms par requête. Un modèle juge peut signaler qu’une réponse semble incorrecte. Seul un mécanisme de validation strict peut garantir un objet typé valide. Vous ajoutez de la latence et des coûts alors que le défaut initial subsiste."}},{"kind":"p","page":188,"text":{"en":"LLM-as-judge belongs in your eval harness (nightly runs, CI) — not in your request/response loop for data integrity.","fr":"Utilisez un LLM comme juge dans votre dispositif d’évaluation, par exemple dans les exécutions nocturnes et la CI. Confiez l’intégrité des données sur le chemin requête-réponse à une validation déterministe."}},{"kind":"p","page":188,"text":{"en":"The worse failure mode: teams add a judge in addition to bad structured prompting, feel safer, and ship it. Both models can hallucinate in sync. The judge agrees the broken output looks fine. Silent corruption ships to prod.","fr":"Le pire scénario survient quand une équipe ajoute un juge à un prompt de structuration défaillant et déploie, persuadée d’être mieux protégée. Les deux modèles peuvent halluciner de concert. Le juge valide la sortie erronée et les données corrompues arrivent silencieusement en production."}}]]},{"day":47,"title":{"en":"Incrementally Strangling a Monolith","fr":"Remplacer progressivement un monolithe avec le patron Strangler Fig"},"pages":[189,192],"topic":"architecture","correct":"A","scenario":[{"kind":"figure","page":189,"id":"189-02","width":800,"height":420,"alt":{"en":"Day 47 featured","fr":"Illustration de la question du jour 47"},"transcript":{"en":["System Design Labs","You need to extract Returns into a standalone","service without a big-bang rewrite.","What’s your migration strategy?","40 engineers","one codebase","Forward","OrderService","Returns","(Standalone)","Come","| meine Event)","‘Stra","Fig — route /returns traffic to a new","proxy/facade, keep the monolith","inside the me","Branch by Abst","ion = introdce","interface","mentation","intact until the new service is proven. Deprecate","it ip the switch when ready, then","‘monolith code after.","IC)","move","Big Bang Rewrite —","10 the monolith, rebuild","Database-First Migration — extract the returns","when done.","‘everything in micro:","8 in parallel, cut over","database tables into a separate schema first,","build the service around it, then reroute traffic","He)"],"fr":["System Design Labs","Vous devez extraire les Retours dans un système autonome","service sans une réécriture big-bang.","Quelle est votre stratégie de migration ?","40 ingénieurs","une base de code","En avant","OrderService","Retours","(Standalone)","Venez.","événement meine)","«Stra","Fig — route /retourne le trafic à un nouveau","proxy/facade, garder le monolithe","à l'intérieur de moi","Branche par Abst","ion — introdce","interface","ment","intact jusqu'à ce que le nouveau service soit prouvé.","il ip le commutateur quand prêt, alors","« code monolithe après.","IC)","déplacer","Big Bang réécrit","10 le monolithe, rebâtir","Database-First Migration — extraire les retours","Quand c'est fait.","«Tout en micro:","8 en parallèle, coupé","tables de base de données dans un schéma séparé,","construire le service autour, puis rediriger le trafic","Il)"]}},{"kind":"p","page":189,"text":{"en":"Your monolith is 6 years old.","fr":"Votre monolithe a six ans."}},{"kind":"p","page":189,"text":{"en":"500k lines of code. One deploy every 3 weeks. One bad migration takes down the whole thing.","fr":"500 000 lignes de code et un déploiement toutes les trois semaines. Une migration qui se passe mal suffit à faire tomber le système."}},{"kind":"p","page":189,"text":{"en":"Leadership says: \"rewrite it.\" You've seen what happens when teams do that. 18 months. Budget overruns. Half the features never make it back. The new system launches and nobody trusts it.","fr":"La direction demande de tout réécrire. Vous avez déjà vu le résultat : 18 mois de travail, le budget dépassé, la moitié des fonctionnalités jamais réintroduites. Au lancement, personne ne fait confiance au nouveau système."}},{"kind":"p","page":189,"text":{"en":"There's a better way. You don't rewrite — you strangle.","fr":"Une meilleure approche consiste à remplacer le monolithe progressivement grâce au modèle Strangler Fig."}},{"kind":"p","page":189,"text":{"en":"Here's your system:","fr":"Voici votre système."}},{"kind":"p","page":189,"text":{"en":"• OrderService (monolith) handles: order creation, fulfillment, invoicing, returns","fr":"• OrderService, le monolithe, gère la création et l’exécution des commandes, la facturation et les retours."}},{"kind":"p","page":189,"text":{"en":"• 40 engineers. 3 teams. All deploying to the same codebase.","fr":"• 40 ingénieurs, répartis en trois équipes, déploient à partir de la même base de code."}},{"kind":"p","page":189,"text":{"en":"• Returns processing is a bottleneck. The business wants it extracted first.","fr":"• Le traitement des retours est le goulet d’étranglement. L’entreprise veut l’extraire en premier."}},{"kind":"p","page":189,"text":{"en":"• You can't freeze feature work during migration.","fr":"• Le développement des fonctionnalités doit se poursuivre pendant la migration."}},{"kind":"p","page":189,"text":{"en":"You need to extract Returns into a standalone service without a big-bang rewrite.","fr":"Vous devez extraire la gestion des retours vers un service autonome sans tout réécrire d’un coup."}},{"kind":"p","page":189,"text":{"en":"What's your migration strategy?","fr":"Quelle stratégie de migration adoptez-vous ?"}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":190,"text":{"en":"Strangler Fig — route /returns traffic to a new service via a proxy/facade, keep the monolith intact until the new service is proven. Deprecate monolith code after.","fr":"Strangler Fig. Dirigez le trafic /returns vers un nouveau service via un proxy ou une façade. Gardez le monolithe intact jusqu’à ce que le nouveau service ait fait ses preuves, puis dépréciez le code concerné."}}]},{"letter":"B","blocks":[{"kind":"p","page":190,"text":{"en":"Branch by Abstraction — introduce an interface inside the monolith, build the new implementation behind it, flip the switch when ready, then move it out.","fr":"Branch by Abstraction. Introduisez une interface dans le monolithe, construisez derrière elle la nouvelle implémentation, activez-la lorsqu’elle est prête, puis externalisez-la."}}]},{"letter":"C","blocks":[{"kind":"p","page":190,"text":{"en":"Big Bang Rewrite — freeze the monolith, rebuild everything in microservices in parallel, cut over when done.","fr":"Réécriture intégrale en une fois. Gelez le monolithe, reconstruisez tout en microservices en parallèle, puis basculez lorsque tout est prêt."}}]},{"letter":"D","blocks":[{"kind":"p","page":190,"text":{"en":"Database-First Migration — extract the returns database tables into a separate schema first, build the service around it, then reroute traffic.","fr":"Migrer la base d’abord. Extrayez les tables des retours dans un schéma séparé, construisez un service qui les exploite, puis réacheminez le trafic."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"figure","page":191,"id":"191-03","width":800,"height":533,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["Why A wins","Strangler Fig — the right way to migrate","Route /returns to a new service via a proxy, keep the monolith intact,","Y Rollback te","tp","and deprecate old code only after the new service proves itself.","Live traffic. No freeze. Migrate one endpoint at a time.","CEP] Service","Routing Proxy /","Facade","Events / Syne (as needed)","xe","Routes by path","(Monolith)","Clients","invoicing,","urs (egacy)","— ae","© How it works","© Miorateincementaly","© Prove before you deprecate","© Why it's battle-tested","© ode a routing ony","atin","© Lathe new sree","row tal unr","NETFLIX amazon","there seven.","Netflix and Amazon have","run versions ofthis pattern","at massive scale.","we","este tive","[v] Outcomes","ll","Ne dts los Noam","Fp the roxtng ru back to the monoth"],"fr":["Pourquoi retenir A","Strangler Fig – la bonne façon de migrer","Router / retourner à un nouveau service via un proxy, garder le monolithe intact,","Y Rollback te","tp","et ne déprécier l'ancien code qu'après que le nouveau service ait fait ses preuves.","Trafic en direct. Pas de gel. Migrer un endpoint à la fois.","CEP] Service","Proxy de routage /","Façade","Événements / Syne (au besoin)","xe","Itinéraires par chemin","(Monolithe)","Clients","facturation,","urs (égérie)","ae","Comment ça marche","Miorateincementaly","Prouvez avant de déprécier","Pourquoi c'est testé au combat","ode un routage ony","atin","Nouveau sree tour","row tal unr","NETFLIX Amazon","Il y en a sept.","Netflix et Amazon ont","exécuter des versions de ce modèle","à grande échelle.","nous","este tive","[v] Résultats","ll","Ne dts los Noam","Fp le roxtng ru retour au monoth"]}},{"kind":"p","page":191,"text":{"en":"Why A wins:","fr":"Pourquoi A fonctionne"}},{"kind":"p","page":191,"text":{"en":"You introduce a routing proxy in front of the monolith. /returns traffic routes to the new service. The monolith handles everything else. You run both in parallel — no freeze, no big-bang. Migrate one endpoint at a time, each step independently rollback-able. Only deprecate monolith code after the new service has proven itself under real load. Netflix and Amazon have run versions of this at scale.","fr":"Placez un proxy de routage en amont du monolithe. Le trafic /returns atteint le nouveau service et le monolithe continue à traiter le reste. Les deux tournent en parallèle, ce qui permet de poursuivre le développement et d’éviter la bascule intégrale. Migrez un endpoint à la fois, avec un retour arrière possible à chaque étape. Dépréciez le code du monolithe lorsque le nouveau service a fait ses preuves sous charge réelle. Netflix et Amazon ont appliqué des variantes de cette méthode à grande échelle."}}],[{"kind":"p","page":191,"text":{"en":"Why B is close but different (Branch by Abstraction):","fr":"En quoi B, Branch by Abstraction, est proche"}},{"kind":"p","page":191,"text":{"en":"Real pattern — but it lives inside the codebase. You wrap the logic behind an interface, build the new implementation behind a flag, then flip it. It's a refactoring tool, not a deployment strategy. Often used inside a Strangler Fig migration to prepare internal structure. But on its own it doesn't get you to an independently deployed service.","fr":"Ce modèle s’applique au sein de la base de code. Isolez la logique derrière une interface, construisez la nouvelle implémentation derrière un feature flag, puis activez-la. Cette technique de refactorisation sert souvent à préparer la structure interne pour une migration Strangler Fig. Le déploiement d’un service indépendant demande des étapes supplémentaires."}}],[{"kind":"p","page":192,"text":{"en":"Why C is wrong (Big Bang Rewrite):","fr":"Pourquoi la réécriture intégrale (C) échoue"}},{"kind":"p","page":192,"text":{"en":"The monolith doesn't freeze while you rebuild. Business keeps shipping features. Your parallel rewrite immediately diverges from reality. \"Done\" keeps moving. The cutover is a single high-stakes event with no incremental validation. Joel Spolsky called this \"the single worst strategic mistake any software company can make\" — because every hack in the old codebase was a real bug fix you've now forgotten.","fr":"En pratique, les équipes continuent de livrer des fonctionnalités pendant la réécriture. Celle-ci diverge vite du système utilisé et la ligne d’arrivée recule sans cesse. La bascule concentre tout le risque, faute de validation progressive. Joel Spolsky a qualifié cette stratégie de « pire erreur stratégique qu’un éditeur de logiciels puisse commettre ». Chaque bricolage du code historique corrigeait un vrai bug dont vous avez perdu la mémoire."}}],[{"kind":"p","page":192,"text":{"en":"Why D is more dangerous than it looks (Database-First):","fr":"Pourquoi migrer la base en premier (D) est risqué"}},{"kind":"p","page":192,"text":{"en":"Extracting the DB tables first sounds logical but breaks the monolith's ORM immediately. You've created a distributed data problem before building the distributed system to handle it. Data migration is the last step — extract service logic first, keep data co-located temporarily, then migrate with dual-write. Doing it in reverse order compounds the risk at every step.","fr":"Extraire les tables en premier paraît logique et casse immédiatement l’ORM du monolithe. Vous voilà avec des données distribuées avant que le système puisse les gérer. Extrayez la logique du service, laissez provisoirement les données au même endroit, puis migrez-les par double écriture. C’est en déplaçant les données en dernier que vous réduisez le risque à chaque étape."}}]]},{"day":48,"title":{"en":"How an Agent Chooses Which Tools to Call","fr":"Comment un agent choisit les outils à appeler"},"pages":[193,196],"topic":"ai","correct":"A","scenario":[{"kind":"figure","page":193,"id":"193-02","width":800,"height":420,"alt":{"en":"Day 48 featured","fr":"Illustration de la question du jour 48"},"transcript":{"en":["‘System Design Li","Your Al agent just got a user message: “Book mea","flight to Dubai next Friday.” How does the agent decide","which tools to call, in what order, and when to stop?","Tooling Layer","select tot","rey","fa","Systeme","User","Al Agent","Tool","as","(eines ste,","‘one","(um","ReAct loop — model reasons step-by-step, emits a","Parallel tool calling — model emits ALL required tool","\"thought\" then picks one tool ata time, observes output,","call in a single response, executes them concurrently,","repeats until it self-decides i's done","feeds all results back in one context update","Forced function schema — you lock the model into a","Planner-executor split ~ a lightweight planner LLM","strict JSON schema per tur; it can't produce free text,","creates a tool call DAG upfront, a separate executor","only structured tool calls you defined","checkpoints","runs the graph, results flow back to planner only at"],"fr":["«Conception du système Li","Votre agent Al vient de recevoir un message de l’utilisateur : « Book mea","vol pour Dubaï vendredi prochain. » Comment l’agent décide-t-il","Quels outils appeler, dans quel ordre et quand s’arrêter ?","Couche d' outillage","Sélectionner tot","rey","fa","Systeme","Utilisateur","Al Agent","Outil","en","(eines ste,","«un","(um","ReAct loop — les raisons du modèle étape par étape, émet un","Le modèle d'appel d'outil parallèle émet TOUS les outils requis","\"pensée\" choisit alors un outil à la fois, observe la sortie,","appeler en une seule réponse, les exécuter simultanément,","répète jusqu'à ce qu'il auto-décide que je suis fait","renvoie tous les résultats dans une mise à jour de contexte","schéma de fonction forcée — vous verrouillez le modèle dans un","Planificateur-exécuteur split — un planificateur léger LLM","schéma JSON strict per tur; il ne peut pas produire de texte libre,","crée un appel d'outil DAG à l'avance, un exécuteur","seuls les appels d'outils structurés que vous avez définis","points de contrôle","exécute le graphique, les résultats retournent au planificateur uniquement à"]}},{"kind":"p","page":193,"text":{"en":"Your AI agent just got a user message: \"Book me a flight to Dubai next Friday.\"","fr":"Votre agent IA vient de recevoir le message « Réserve-moi un vol pour Dubaï vendredi prochain. »"}},{"kind":"p","page":193,"text":{"en":"The LLM has access to 12 tools: search_flights, get_user_preferences, check_calendar, book_flight, send_confirmation, get_weather…","fr":"Le LLM dispose de 12 outils, dont search_flights, get_user_preferences, check_calendar, book_flight, send_confirmation et get_weather."}},{"kind":"p","page":193,"text":{"en":"How does the agent decide which tools to call, in what order, and when to stop?","fr":"Comment l’agent choisit-il les outils à appeler, leur ordre d’exécution et le moment de s’arrêter ?"}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":193,"text":{"en":"ReAct loop — model reasons step-by-step, emits a \"thought\" then picks one tool at a time, observes output, repeats until it self-decides it's done","fr":"Boucle ReAct. Le modèle raisonne étape par étape, émet une « pensée », choisit un seul outil, observe le résultat et répète le cycle jusqu’à ce qu’il estime avoir terminé."}}]},{"letter":"B","blocks":[{"kind":"p","page":193,"text":{"en":"Parallel tool calling — model emits ALL required tool calls in a single response, executes them concurrently, feeds all results back in one context update","fr":"Appels d’outils en parallèle. Le modèle émet tous les appels requis dans une seule réponse. Ils s’exécutent simultanément et leurs résultats rejoignent le contexte en une seule mise à jour."}}]},{"letter":"C","blocks":[{"kind":"p","page":193,"text":{"en":"Forced function schema — you lock the model into a strict JSON schema per turn; it can't produce free text, only structured tool calls you defined","fr":"Schéma de fonctions imposé. À chaque tour, contraignez le modèle par un schéma JSON strict. Il ne peut renvoyer que des appels structurés aux outils que vous avez définis, sans texte libre."}}]},{"letter":"D","blocks":[{"kind":"p","page":193,"text":{"en":"Planner-executor split — a lightweight planner LLM creates a tool call DAG upfront, a separate executor runs the graph, results flow back to planner only at checkpoints","fr":"Séparer planificateur et exécuteur. Un LLM léger établit à l’avance un DAG d’appels d’outils, exécuté par un autre composant. Les résultats ne reviennent au planificateur qu’aux points de contrôle."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"figure","page":194,"id":"194-03","width":800,"height":533,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["ReAct loop [Vv] Correct for most cases","ReAct (Reason + Act) is the dominant production pattern for a reason.","ct","0p (Oni","fool at a Time)","‘The model emits.","\"Thought:\" explaining what it's doing,","User","then an \"Actior","Thought","with a single tool call, then observes","“Bock ne ght","the result before deciding what's next.","eo, ‘ation (Teo Cat)","Toole","Each step is observable and debuggable","‘The model can bailout, retry, or change direction","Os cman)","after each too","sult","Works even with tools that have side effects —","you can gate dangerous calls","‘Supported natively by OpenAl, Anthropic,","‘LangChain, Llamaindex out of the box","toUser","\"You Hight to Dubs","A Tre trap:","next Friday is booked","ese references AND check certo","‘ation","youre mang 3 ound ps whan you","ie"],"fr":["ReAct loop [Vv] Correct pour la plupart des cas","ReAct (Raison + Loi) est le modèle de production dominant pour une raison.","ct","0p (Oni)","imbécile à la fois)","« Le modèle émet.","\"Pensé\" : expliquer ce qu'il fait,","Utilisateur","Un « acteur »","Pensée","avec un seul appel d'outil, puis observe","«Bock ne ght","le résultat avant de décider ce qui va suivre.","eo, ‘ation (Teo Cat)","Toole","Chaque étape est observable et débuggable","« Le modèle peut renflouer, réessayer ou changer de direction.","Os cman)","Après chacun aussi","sult","Fonctionne même avec des outils qui ont des effets secondaires","vous pouvez passer des appels dangereux","« Soutenu nativement par OpenAl, Anthropic,","«LangChain, Llamaindex sorti de la boîte","toUser","\"Vous montez à Dubs","Un piège à Tre :","Vendredi prochain est réservé","ese références ET contrôle certo","«ation","youre mang 3 und ps whan vous","ie"]}},{"kind":"p","page":194,"text":{"en":"A — ReAct loop Correct for most cases","fr":"A — Boucle ReAct, adaptée à la plupart des cas"}},{"kind":"p","page":194,"text":{"en":"ReAct (Reason + Act) is the dominant production pattern for a reason.","fr":"ReAct (Reason + Act) est le modèle dominant en production pour une bonne raison."}},{"kind":"p","page":194,"text":{"en":"The model emits a \"Thought:\" explaining what it's doing, then an \"Action:\" with a single tool call, then observes the result before deciding what's next.","fr":"Le modèle émet un champ « Thought: » décrivant sa démarche, puis un champ « Action: » avec un seul appel d’outil. Il observe ensuite le résultat avant de décider de la suite."}},{"kind":"p","page":194,"text":{"en":"Why it works:","fr":"Cette approche fonctionne pour plusieurs raisons."}},{"kind":"p","page":194,"text":{"en":"• Each step is observable and debuggable","fr":"• Chaque étape peut être observée et déboguée."}},{"kind":"p","page":194,"text":{"en":"• The model can bail out, retry, or change direction after each tool result","fr":"• Après chaque résultat, le modèle peut abandonner, réessayer ou changer de direction."}},{"kind":"p","page":194,"text":{"en":"• Works even with tools that have side effects — you can gate dangerous calls","fr":"• Les outils qui produisent des effets de bord sont compatibles, avec un contrôle préalable pour les appels à risque."}},{"kind":"p","page":194,"text":{"en":"• Supported natively by OpenAI, Anthropic, LangChain, LlamaIndex out of the box","fr":"• OpenAI, Anthropic, LangChain et LlamaIndex la prennent en charge nativement."}},{"kind":"p","page":194,"text":{"en":"The trap: ReAct is sequential. If you need get_user_preferences AND check_calendar AND search_flights all before book_flight, you're making 3 round trips when you could make 1.","fr":"ReAct procède de façon séquentielle. Si get_user_preferences, check_calendar et search_flights doivent tous précéder book_flight, vous faites trois allers-retours là où un seul pourrait suffire."}}],[{"kind":"p","page":195,"text":{"en":"B — Parallel tool calling Right when dependencies allow it","fr":"B — Appels d’outils en parallèle, utiles quand les dépendances le permettent"}},{"kind":"p","page":195,"text":{"en":"Modern LLMs (GPT-4o, Claude 3.5+) can emit multiple tool calls in a single response.","fr":"Les LLM récents, comme GPT-4o ou Claude 3.5 et versions ultérieures, peuvent émettre plusieurs appels d’outils dans une seule réponse."}},{"kind":"p","page":195,"text":{"en":"If the tools are independent — run them in parallel. Massive latency win.","fr":"Exécuter les outils indépendants en parallèle réduit fortement la latence."}},{"kind":"p","page":195,"text":{"en":"Example: get_user_preferences + check_calendar have no dependency on each other. Call both at once. Then feed both results back before calling search_flights.","fr":"get_user_preferences et check_calendar sont indépendants. Lancez les deux en même temps, puis transmettez leurs résultats avant d’appeler search_flights."}},{"kind":"p","page":195,"text":{"en":"The trap: not all tools are independent. If Tool B needs the output of Tool A, parallel calling breaks your context. The model doesn't \"know\" B failed because A hadn't run yet — it just gets a bad result and may hallucinate a fix.","fr":"Certaines dépendances empêchent l’exécution en parallèle. Si l’outil B a besoin du résultat d’A, le lancer trop tôt produit un contexte incorrect. Le modèle reçoit un mauvais résultat sans savoir qu’A n’a pas encore tourné. Il peut alors inventer une solution."}},{"kind":"p","page":195,"text":{"en":"Production pattern: use parallel calling for the fan-out phase, ReAct for the sequential decision phase.","fr":"En production, utilisez les appels parallèles pendant la phase de dispersion, puis ReAct pour les décisions séquentielles."}}],[{"kind":"p","page":195,"text":{"en":"C — Forced function schema The senior engineer trap","fr":"C — Schéma de fonctions imposé, le piège des ingénieurs expérimentés"}},{"kind":"p","page":195,"text":{"en":"Looks like control. Actually limits you.","fr":"Ce contrôle apparent réduit en réalité vos possibilités."}},{"kind":"p","page":195,"text":{"en":"When you force strict JSON schema mode, you lose the model's ability to reason before calling.","fr":"En imposant un schéma JSON strict, vous empêchez le modèle de raisonner avant d’appeler un outil."}},{"kind":"p","page":195,"text":{"en":"This breaks down fast when:","fr":"Cette limite se fait vite sentir dans plusieurs cas."}},{"kind":"p","page":195,"text":{"en":"• The user's intent is ambiguous (should the agent call search_flights or clarify_intent?)","fr":"• L’intention est ambiguë. L’agent doit-il appeler search_flights ou clarify_intent ?"}},{"kind":"p","page":195,"text":{"en":"• A tool fails and the model needs to decide whether to retry or give up","fr":"• Un outil échoue et le modèle doit décider de réessayer ou d’abandonner."}},{"kind":"p","page":195,"text":{"en":"• You need conditional logic between steps","fr":"• Une condition détermine l’enchaînement des étapes."}},{"kind":"p","page":195,"text":{"en":"Use schema enforcement for output validation, not tool dispatch. Validate what comes back from the model — don't handcuff the model going in....","fr":"Appliquez le schéma à la validation des sorties. Laissez au modèle la latitude nécessaire pour décider des appels et vérifiez ce qu’il renvoie."}}],[{"kind":"p","page":196,"text":{"en":"D — Planner-executor split 🏗 Right at scale, overkill for most","fr":"D — Séparation du planificateur et de l’exécuteur 🏗 adaptée à grande échelle, excessive dans la plupart des cas"}},{"kind":"p","page":196,"text":{"en":"This is the architecture behind production agentic pipelines like Devin, AutoGPT-style systems, and enterprise agent frameworks.","fr":"Cette architecture sous-tend des workflows d’agents en production comme Devin, les systèmes de type AutoGPT et les frameworks d’entreprise."}},{"kind":"p","page":196,"text":{"en":"The planner builds a DAG of tool calls upfront. The executor runs it. The planner only re-engages at checkpoints or on failure.","fr":"Le planificateur construit d’abord un DAG d’appels. L’exécuteur le lance, puis sollicite le planificateur uniquement aux points de contrôle ou en cas d’échec."}},{"kind":"p","page":196,"text":{"en":"Benefits:","fr":"Cette architecture présente plusieurs avantages."}},{"kind":"p","page":196,"text":{"en":"• Parallelism by default (the DAG has clear dependency edges)","fr":"• Le parallélisme est prévu d’emblée par les arêtes de dépendance explicites du DAG."}},{"kind":"p","page":196,"text":{"en":"• Cost-efficient (the powerful planner model runs less)","fr":"• Le modèle de planification, plus puissant, est appelé moins souvent, ce qui réduit les coûts."}},{"kind":"p","page":196,"text":{"en":"• Auditable — you can inspect the plan before running it","fr":"• Le plan est vérifiable avant l’exécution."}},{"kind":"p","page":196,"text":{"en":"The trap: the planner has to get the full plan right before execution starts. If the world changes mid-run (API returns unexpected data, user updates their request), you need replanning. That's a whole second problem.","fr":"Le planificateur doit produire un plan complet et correct avant le premier appel. Si la situation change en cours de route, par exemple après une réponse inattendue d’une API ou une demande modifiée par l’utilisateur, il faut replanifier. Cela pose un deuxième problème de conception."}},{"kind":"p","page":196,"text":{"en":"Most teams reach for this too early. Start with ReAct. Add parallel tool calling when latency hurts. Only build planner-executor when you have complex multi-step workflows with 10+ tools and real parallelism requirements....","fr":"La plupart des équipes adoptent cette architecture trop tôt. Commencez par ReAct, puis parallélisez les appels si la latence pose problème. Séparez planification et exécution lorsque vos workflows complexes mobilisent au moins dix outils et exigent réellement du parallélisme."}}]]},{"day":49,"title":{"en":"Controlling Data-Warehouse Query Costs","fr":"Maîtriser le coût des requêtes dans un entrepôt de données"},"pages":[197,201],"topic":"scale","correct":"D","scenario":[{"kind":"figure","page":197,"id":"197-02","width":800,"height":421,"alt":{"en":"Day 49 featured","fr":"Illustration de la question du jour 49"},"transcript":{"en":["System Design Labs","You’re running a 3.2 TB events table on BigQuery.","Which partition + clustering strategy do you pick?","Run","Read Data","‘Stream","off","Queries","(Sean)","(@aiy)","Events","cS","Analytics","BigQuery","events Table","Ingestion","Event","Tools","Engine","(3278)","Pipeline","Sources","18 Months of Data","Partition by ingestion date — date range","Partition by customer","ranges — customer","queries only scan the relevant day-partit","ns.","queries only scan the relevant ID bucket.","Partition by ingestion date + cluster on","No pa","ning — use Redshift DISTKEY on","customer_i","+ SORTKEY on event_time.","‘customer_id — date pruning cuts the partition,","clustering prunes within it."],"fr":["System Design Labs","Vous exécutez une table d'événements de 3,2 To sur BigQuery.","Quelle stratégie de partition + clustering choisissez-vous ?","Exécuter","Lire les données","«Stream","off","Requêtes","(Sean)","( — aiy)","Événements","cS","Analyses","BigQuery","événements Tableau","Ingestion","Événement","Outils","Moteur","(3278)","Pipeline","Sources","18 mois de données","Partition par date d'ingestion — plage de dates","Partition par client","gammes — client","les requêtes ne scannent que le jour-partit pertinent","ns.","les requêtes analysent uniquement le compartiment d'identification correspondant.","Partition par date d'ingestion + cluster on","Non pa","Utiliser Redshift DISTKEY sur","customer_i","+ SORTKEY sur event_time.","‘customer_id — taille de date coupe la partition,","Les pruneaux à l'intérieur."]}},{"kind":"p","page":197,"text":{"en":"Your data team just opened a $4,200 BigQuery bill.","fr":"Votre équipe data vient de découvrir une facture BigQuery de 4 200 $."}},{"kind":"p","page":197,"text":{"en":"For a single month. One analyst. 12 queries.","fr":"Un seul mois, un seul analyste et douze requêtes."}},{"kind":"p","page":197,"text":{"en":"The queries weren't wrong. They weren't inefficient SQL. They were reasonable analytics queries — \"give me last 30 days of events for customer X.\" The problem was that every single one scanned the full 3.2 TB table. No partition pruning. No cost control. Just full scans, every time.","fr":"Le SQL était correct et les requêtes étaient raisonnables, comme « Donnez-moi les événements du client X sur les 30 derniers jours. » Chacune parcourait pourtant la table entière de 3,2 To. Sans élagage des partitions, le coût de chaque parcours complet était difficile à maîtriser."}},{"kind":"p","page":197,"text":{"en":"This is the most expensive silent bug in data engineering. You write a query. It looks fast. It returns results. And every run quietly eats through terabytes you're paying per-byte to scan.","fr":"C’est un défaut particulièrement coûteux et discret en ingénierie des données. La requête paraît rapide et livre les bons résultats. À chaque exécution, elle parcourt en silence des téraoctets facturés à l’octet."}},{"kind":"p","page":197,"text":{"en":"The fix is partition strategy — but picking the wrong one doesn't just fail to help, it actively makes things worse.","fr":"Le partitionnement peut résoudre le problème. Une mauvaise stratégie peut au contraire l’aggraver."}},{"kind":"p","page":197,"text":{"en":"Here's the setup:","fr":"Voici la configuration."}},{"kind":"p","page":197,"text":{"en":"You're running a 3.2 TB events table on BigQuery. 18 months of data. Ingested daily. Analyst queries almost always filter on two things: a date range (\"last 30 days\") and a customer_id (\"for customer X\").","fr":"Votre table d’événements BigQuery pèse 3,2 To. Elle contient 18 mois de données et reçoit des ajouts quotidiens. Les analystes filtrent presque toujours sur une plage de dates, par exemple les 30 derniers jours, et sur customer_id, par exemple pour le client X."}},{"kind":"p","page":197,"text":{"en":"Which partition + clustering strategy do you pick?","fr":"Quel partitionnement et quel clustering choisissez-vous ?"}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":197,"text":{"en":"Partition by ingestion date — date range queries only scan the relevant day-partitions.","fr":"Partitionner par date d’ingestion. Les requêtes filtrées par date ne parcourent que les partitions des jours concernés."}}]},{"letter":"B","blocks":[{"kind":"p","page":198,"text":{"en":"Partition by customer_id ranges — customer queries only scan the relevant ID bucket.","fr":"Partitionner par plages de customer_id. Les requêtes ciblant un client ne parcourent que la plage qui contient son identifiant."}}]},{"letter":"C","blocks":[{"kind":"p","page":198,"text":{"en":"No partitioning — use Redshift DISTKEY on customer_id + SORTKEY on event_time.","fr":"Se passer de partitionnement. Dans Redshift, affectez customer_id à DISTKEY et event_time à SORTKEY."}}]},{"letter":"D","blocks":[{"kind":"p","page":198,"text":{"en":"Partition by ingestion date + cluster on customer_id — date pruning cuts the partition, clustering prunes within it.","fr":"Partitionner par date d’ingestion et appliquer un clustering sur customer_id. La date écarte des partitions, puis le clustering réduit la lecture dans chacune des partitions restantes."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"figure","page":199,"id":"199-03","width":800,"height":533,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["Why D wins:","Partition by ingestion date","BigQuery","Partition + Cluster","+ cluster on customer.","id","WITHOUT PARTITIONING + CLUSTERING","WITH PARTITION BY DATE + CLUSTER BY CUSTOMER_ID","1. Partition by date","18 MONTHS OF DATA","18 MONTHS OF DATA","BigQuery skips every partition outside","2278","3278","the date range before scanning a","single row.","For “last 30 days” query on 18 months","of data, you immediately eliminate ~94%","Patton pruning (dt","ofthe table.","2. Cluster by customer_id","Within seanned partitions","‘Within each scanned partition, BigQuery","clustered by customer id","sorts the rows by customer_id into","last 30 days","Custer pring","storage blocks.","for customer X","ships 90-95%","Afiteron customer id now skips","90-95% of the remaining rows.","Combined impact","‘A “last 30 days for customer X\" query","~12GB","‘Same quer","‘goes from scanning 3.2 TB — ~12 GB.","Same data,","$70/month","Right strategy.","ops from $4,200","This pattern works across every major warehouse:","Snowflake","Redshift","BigQuery","Partition + Cluster","2S Mics","Partition Key +","ars","Cluster Keys.","it","‘SORTKEY Compound"],"fr":["Pourquoi retenir D :","Partition par date d'ingestion","BigQuery","Partition + cluster","+ cluster sur le client.","id","SANS PARTITIONNEMENT + CLUSTERING","AVEC PARTITION PAR DATE + CLUSTER PAR CUSTOMER_ID","1. Partition par date","18 mois de données","18 mois de données","BigQuery saute toutes les partitions à l'extérieur","2278","3278","la plage de dates avant de numériser une","une seule rangée.","Pour la requête « 30 derniers jours » sur 18 mois","de données, vous éliminez immédiatement — 94%","Taille Patton (dt","de la table.","2. Cluster par client_id","Dans les cloisons scellées","Dans chaque partition scannée, BigQuery","groupé par identifiant client","trie les lignes par client_id dans","30 derniers jours","Custer pring","blocs de stockage.","pour le client X","navires 90-95%","L'identifiant du client d'Afiteron saute maintenant","90-95% des rangs restants.","Impact combiné","Une requête « 30 derniers jours pour le client X »","12GB","«Même quer","«passe de 3,2 To à — 12 Go.","Mêmes données,","70$/mois","Bonne stratégie.","Ops à partir de $4,200","Ce modèle fonctionne dans tous les grands entrepôts:","Flocon neige","Redshift","BigQuery","Partition + cluster","2S Mics","Clé de partition +","ars","Clés de cluster.","il","«Composé SORTKEY"]}},{"kind":"p","page":199,"text":{"en":"Why D wins:","fr":"Pourquoi D fonctionne"}},{"kind":"p","page":199,"text":{"en":"Your analyst queries always filter on two columns: a date range and a customer_id. A single-key strategy protects one and ignores the other.","fr":"Vos analystes filtrent toujours sur deux dimensions, une plage de dates et customer_id. Une stratégie fondée sur une seule clé optimise un seul de ces filtres."}},{"kind":"p","page":199,"text":{"en":"Here's what D does in BigQuery:","fr":"Voici l’effet de D dans BigQuery."}},{"kind":"p","page":199,"text":{"en":"• Partition by date → BigQuery skips every partition outside the date range before scanning a single row. For a \"last 30 days\" query on 18 months of data, you immediately eliminate ~94% of the table.","fr":"• Partitionnement par date. BigQuery écarte les partitions hors de la plage avant même de lire une ligne. Une requête sur les 30 derniers jours dans 18 mois de données écarte directement environ 94 % de la table."}},{"kind":"p","page":199,"text":{"en":"• Cluster by customer_id → Within each scanned partition, BigQuery sorts the rows by customer_id into storage blocks. A filter on customer_id now skips 90–95% of the remaining rows.","fr":"• Clustering sur customer_id. Dans chaque partition parcourue, BigQuery ordonne les lignes par customer_id dans des blocs de stockage. Un filtre sur cet identifiant écarte alors 90 à 95 % des lignes restantes."}},{"kind":"p","page":199,"text":{"en":"Combined: a \"last 30 days for customer X\" query goes from scanning 3.2 TB → ~12 GB. Bill drops from $4,200 → ~$70/month. Same queries. Same data. Right strategy.","fr":"En combinant les deux, une requête sur les 30 derniers jours du client X passe de 3,2 To parcourus à environ 12 Go. La facture mensuelle descend de 4 200 $ à environ 70 $ avec les mêmes requêtes et les mêmes données."}},{"kind":"p","page":199,"text":{"en":"This pattern works across every major warehouse: BigQuery (partition + cluster), Snowflake (micro-partitioning + cluster keys), Redshift (partition key + SORTKEY compound).","fr":"Cette approche se décline sur les grands entrepôts de données : partitionnement et clustering dans BigQuery, micro-partitionnement et clés de clustering dans Snowflake, clé de partition et SORTKEY composée dans Redshift."}}],[{"kind":"p","page":200,"text":{"en":"Why A is incomplete (date partition only):","fr":"Pourquoi A, le partitionnement par date seul, est incomplet"}},{"kind":"p","page":200,"text":{"en":"Date partition alone is a real improvement — date range filters prune the irrelevant partitions immediately. Your bill probably drops 60–70%.","fr":"Partitionner par date apporte déjà un gain : les filtres temporels écartent immédiatement les partitions hors périmètre. La facture baisse probablement de 60 à 70 %."}},{"kind":"p","page":200,"text":{"en":"But your analyst queries also filter by customer_id. Inside each date partition, all customer rows are interleaved across storage blocks. BigQuery has to read the entire partition to find customer X's rows. You've cut the scan from 3.2 TB → ~500 GB (the last 30 days), but you're still scanning every customer inside that window.","fr":"Vos analystes filtrent aussi sur customer_id. Dans une partition de date, les lignes de tous les clients sont mélangées dans les blocs de stockage. BigQuery doit lire la partition entière pour trouver celles du client X. Vous êtes passé de 3,2 To à environ 500 Go pour les 30 derniers jours, mais vous lisez encore les lignes de tous les clients pendant cette période."}},{"kind":"p","page":200,"text":{"en":"A is the obvious first step. D is A taken all the way.","fr":"A constitue une première étape naturelle. D complète cette optimisation."}}],[{"kind":"p","page":200,"text":{"en":"Why B is the senior engineer trap (customer_id range partitioning):","fr":"Pourquoi B, le partitionnement par plages de customer_id, est un piège"}},{"kind":"p","page":200,"text":{"en":"This one gets smart people. Your analysts always filter by customer_id — why not partition on that?","fr":"Le piège est convaincant. Puisque les analystes filtrent systématiquement sur customer_id, pourquoi ne pas en faire la clé de partition ?"}},{"kind":"p","page":200,"text":{"en":"Because real customer_id distributions are never uniform. Your enterprise clients (IDs 1–10,000) generate 80% of all events. Every analytics query against active customers hits the same partition. No pruning benefit — the entire interesting data is in one bucket.","fr":"En pratique, les customer_id sont répartis de façon inégale. Vos clients grands comptes, identifiés de 1 à 10 000, génèrent 80 % des événements. Toutes les requêtes sur les clients actifs atteignent la même partition. L’élagage apporte peu, car les données qui vous intéressent sont regroupées dans cette partition."}},{"kind":"p","page":200,"text":{"en":"Worse: your queries also filter by date. BigQuery now has to scan the full customer partition to find rows from the last 30 days. You've traded a full table scan for a full-partition scan on your hottest partition. Same cost, different framing.","fr":"De plus, vos requêtes filtrent par date. BigQuery doit parcourir toute la partition client pour trouver les lignes des 30 derniers jours. Vous avez remplacé un parcours de table par un parcours complet de la partition la plus sollicitée, pour un coût comparable."}},{"kind":"p","page":200,"text":{"en":"Hot partitions on high-traffic ID ranges is the most common expensive mistake in data warehouse design. Looks right in theory. Never works in production.","fr":"Créer des partitions chaudes sur des plages d’identifiants très actives est une cause courante de surcoûts dans les entrepôts de données. Le partitionnement paraît pertinent sur le papier et s’effondre sous la charge réelle."}}],[{"kind":"p","page":201,"text":{"en":"Why C fails at this scale (DISTKEY + SORTKEY, no partitioning):","fr":"Pourquoi C échoue à cette échelle, avec DISTKEY et SORTKEY sans partitionnement"}},{"kind":"p","page":201,"text":{"en":"DISTKEY distributes rows across Redshift nodes by customer_id hash — optimizes joins. SORTKEY on event_time sorts rows on disk within each slice — helps date range scans read contiguous blocks.","fr":"DISTKEY répartit les lignes entre les nœuds Redshift en fonction du hachage de customer_id, ce qui optimise les jointures. SORTKEY sur event_time trie les lignes sur disque dans chaque segment, de sorte que les parcours par date lisent des blocs contigus."}},{"kind":"p","page":201,"text":{"en":"Both are real optimizations. Neither replaces partition pruning at 3.2 TB.","fr":"Ces deux optimisations sont utiles. À 3,2 To, l’élagage des partitions reste indispensable."}},{"kind":"p","page":201,"text":{"en":"Without partitioning, every query triggers a full table scan across all nodes. If your DISTKEY distribution is skewed — which it will be when enterprise customers dominate — one Redshift node holds 60–70% of your data. Every expensive query hammers that node.","fr":"Sans partitionnement, chaque requête déclenche un parcours de toute la table, sur tous les nœuds. Si la distribution de DISTKEY est déséquilibrée, comme lorsque les grands comptes dominent le trafic, un seul nœud peut contenir 60 à 70 % des données. Chaque requête coûteuse sollicite alors ce même nœud."}},{"kind":"p","page":201,"text":{"en":"You've turned a cost problem into a latency + cost problem.","fr":"Au problème de coût s’ajoute un problème de latence."}},{"kind":"p","page":201,"text":{"en":"DISTKEY + SORTKEY is solid for join optimization and smaller tables. It's not a substitute for partition pruning at terabyte scale.","fr":"DISTKEY et SORTKEY conviennent à l’optimisation des jointures et aux tables plus petites. À l’échelle du téraoctet, il faut pouvoir écarter des partitions entières."}}]]},{"day":50,"title":{"en":"Serving ML Models at High Throughput","fr":"Servir des modèles de ML à haut débit"},"pages":[202,205],"topic":"scale","correct":"A","scenario":[{"kind":"figure","page":202,"id":"202-02","width":800,"height":420,"alt":{"en":"Day 50 featured","fr":"Illustration de la question du jour 50"},"transcript":{"en":["the notebook.","Your ML model hits 94% accuracy","Deployed at 3,000 RPS, P99 latency","'s, GPU u","iS 23%,","PyTorch","| Service","Metrics &","Monitoring","Clients","model","eh","13 — buffer incoming","CE","IC)","Switeh to","ross multiple GPUs, debut the","(a"],"fr":["Le carnet.","Votre modèle ML atteint une précision de 94%","Déployé à 3000 RPS, latence P99","GPU u","iS 23%,","PyTorch","Service","Métriques &","Suivi","Clients","modèle","eh","13 — tampon entrant","CE","IC)","Switeh à","ROSS plusieurs GPU, début de la","(a)"]}},{"kind":"p","page":202,"text":{"en":"Your ML team trained a model that hits 94% accuracy in the notebook.","fr":"L’équipe ML a entraîné un modèle qui atteint 94 % d’exactitude dans son notebook."}},{"kind":"p","page":202,"text":{"en":"Then you deploy it.","fr":"Vous le déployez."}},{"kind":"p","page":202,"text":{"en":"Peak traffic: 3,000 inference requests/second.","fr":"Le pic de trafic atteint 3 000 requêtes d’inférence par seconde."}},{"kind":"p","page":202,"text":{"en":"P99 latency shoots to 4.2 seconds.","fr":"La latence p99 grimpe à 4,2 secondes."}},{"kind":"p","page":202,"text":{"en":"GPU utilization: 23%.","fr":"Le GPU tourne à 23 % d’utilisation."}},{"kind":"p","page":202,"text":{"en":"The model works. The serving layer is the bottleneck.","fr":"Le modèle fonctionne. Le goulet d’étranglement est dans la couche de service."}},{"kind":"p","page":202,"text":{"en":"Here's the setup:","fr":"Voici la configuration."}},{"kind":"p","page":202,"text":{"en":"• PyTorch model, ~6B params","fr":"• Modèle PyTorch d’environ 6 milliards de paramètres."}},{"kind":"p","page":202,"text":{"en":"• Single A100 GPU, 80GB VRAM","fr":"• Un seul GPU A100 avec 80 Go de VRAM."}},{"kind":"p","page":202,"text":{"en":"• FastAPI wrapper calling model.predict() one request at a time","fr":"• Une couche FastAPI appelle model.predict() pour une requête à la fois."}},{"kind":"p","page":202,"text":{"en":"• No batching, FP32 weights, no quantization","fr":"• Aucun traitement par lots et aucune quantification, avec des poids au format FP32."}},{"kind":"p","page":202,"text":{"en":"Users are hitting timeouts. GPUs are sitting mostly idle. Your infra bill is climbing.","fr":"Les requêtes des utilisateurs dépassent le délai d’attente. Les GPU restent pour la plupart inactifs et vos coûts d’infrastructure augmentent."}},{"kind":"p","page":202,"text":{"en":"What do you fix first?","fr":"Que corrigez-vous en premier ?"}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":203,"text":{"en":"Enable dynamic batching — buffer incoming requests, group into batches, process in one forward pass.","fr":"Activer le regroupement dynamique. Mettez les requêtes entrantes en tampon, regroupez-les en lots et traitez chaque lot en un seul passage dans le modèle."}}]},{"letter":"B","blocks":[{"kind":"p","page":203,"text":{"en":"Quantize the model to INT8 — reduce weight precision from 32-bit to 8-bit, shrink memory footprint and speed up inference.","fr":"Quantifier le modèle en INT8. Réduisez la précision des poids de 32 à 8 bits pour diminuer l’empreinte mémoire et accélérer l’inférence."}}]},{"letter":"C","blocks":[{"kind":"p","page":203,"text":{"en":"Switch to tensor parallelism — split the model across multiple GPUs, distribute the compute.","fr":"Utiliser le parallélisme de tenseurs. Répartissez le modèle et le calcul sur plusieurs GPU."}}]},{"letter":"D","blocks":[{"kind":"p","page":203,"text":{"en":"Add a request queue + async workers — decouple HTTP receiving from model inference, process jobs in background.","fr":"Ajouter une file de requêtes et des workers asynchrones. Découplez la réception HTTP de l’inférence et traitez les tâches en arrière-plan."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"figure","page":204,"id":"204-03","width":800,"height":533,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["‘System Design Labs","@ Answer: A— Dynamic Batching","jatch requests for a few milliseconds, run one forward pass,","and keep the GPU fed.","€ BEFORE: No Batching (One Request a Tine)","AFTER: Dynamic Batching (Many Requests per Forward Pass)","Incoming","Incoming","Requests","23%","Requests","85-90%","(3,000 RPs)","(@,000 RPs)","Dynamic","o—","FastaPl Service","os","Batcher","2-8","roo gPu | —>","(model predict)","a—","| ters","Metcs &","Monitoring","Monitoring","Process 1 request ~> GPU computes —» GPU idles ~> repeat","Collect many requests + Single forward pass —> High GPU utilization","Compute","ae","‘ae","Compute","Compute","Compute (Batch)","Comput (Bath)","Comput (Batch)","Time","Tne","2s, GPUU","23%","‘Symptoms: 3K RPS, PS!","Result: Higher throughput, lower P99 latency, happier users,","GPU is starving. High overhead, ow throughput.","and dramatically better GPU utilization.","Why A Wins","Why Others Don't Fix Ths First","rot the compute it’ the request pattem.","¥ yam bathing tuns many smal, e","nt","all","Jie maxed out.","latency without changing the mode","0:","uoves/asyne help resilience, not GPU utilization or latency","lever to pul fr low GPU ut +"],"fr":["«System Design Labs","Réponse: A — Battage dynamique","jatch demandes pour quelques millisecondes, exécuter une passe en avant,","et garder le GPU alimenté.","AVANT: Pas de batch (One Request a Tine)","APR — S : Battage dynamique (nombreuses demandes par passe aller)","Entrée","Entrée","Demandes","23%","Demandes","85-90%","(3 000 roupies)","( — ,000 RPs)","Dynamique","o","FastaPl Service","os","Batcher","2-8","roo gPu — — >","(prévision du modèle)","a","ters","Metcs &","Suivi","Suivi","Process 1 request — > GPU computes — » GPU idles — > repeat","Recueillir de nombreuses demandes + Single forward pass — > Haute utilisation du GPU","Calculer","ae","«ae","Calculer","Calculer","Calcul (lot)","Calcul (bain)","Calcul (lot)","Heure","Tne","2s, GPUU","23%","Symptômes : 3K RPS, PS !","Résultat: débit plus élevé, latence P99 plus faible, utilisateurs plus heureux,","Le GPU est affamé. Haute surcharge, ow débit.","et une meilleure utilisation du GPU.","Pourquoi gagner","Pourquoi les autres ne se fixent pas d'abord","pourrit le calcul it’ le pattem de requête.","bain d'igname tuns beaucoup smal, e","nt","toutes","Jie s'est évadé.","latence sans changer le mode","0:","uoves/asyne aide la résilience, pas l'utilisation du GPU ou la latence","levier vers pul fr bas GPU ut +"]}},{"kind":"p","page":204,"text":{"en":"Answer: A — Dynamic Batching ✅","fr":"Réponse A — Regroupement dynamique ✅"}},{"kind":"p","page":204,"text":{"en":"Here's the breakdown:","fr":"Voyons pourquoi."}},{"kind":"p","page":204,"text":{"en":"Why A wins (Dynamic Batching):","fr":"Pourquoi A fonctionne, avec le regroupement dynamique"}},{"kind":"p","page":204,"text":{"en":"The smoking gun is the combination: 3K RPS, P99 = 4.2s, GPU utilization = 23%.","fr":"L’indice est la combinaison des trois mesures : 3 000 RPS, 4,2 s de latence p99 et 23 % d’utilisation du GPU."}},{"kind":"p","page":204,"text":{"en":"GPU utilization at 23% tells you the GPU is starving. It's not overloaded — it's bored. Every request is arriving one at a time, paying the full GPU kernel launch overhead, then idling while the next request trickles in. GPUs are built for parallelism. They want 256 inputs to process simultaneously, not 1.","fr":"À 23 % d’utilisation, le GPU manque de travail. Chaque requête arrive seule et paie tout le coût de lancement d’un kernel GPU. Le GPU attend ensuite la requête suivante. Il est conçu pour traiter des centaines d’entrées en même temps, par exemple 256."}},{"kind":"p","page":204,"text":{"en":"Dynamic batching buffers requests for a few milliseconds (say, 50ms), collects 32–128 of them, and fires a single forward pass. That same GPU that was at 23% utilization can jump to 85–90%. Latency improves because batch throughput dramatically outpaces sequential per-request calls, even with the small buffer wait.","fr":"Le regroupement dynamique conserve les requêtes quelques millisecondes en tampon, par exemple 50 ms, en regroupe de 32 à 128 et les traite en un seul passage. L’utilisation du même GPU peut passer de 23 % à 85–90 %. Malgré le bref délai de mise en lot, la latence diminue parce que le débit du traitement par lots dépasse largement celui des appels séquentiels."}},{"kind":"p","page":204,"text":{"en":"This is exactly how NVIDIA Triton Inference Server, TorchServe, and vLLM (for LLMs) work by default. Batching is the first thing you reach for when GPU util is low and RPS is high.","fr":"C’est le fonctionnement par défaut de NVIDIA Triton Inference Server, de TorchServe et de vLLM pour les LLM. Lorsque le GPU est peu utilisé malgré un RPS élevé, le regroupement est la première piste."}}],[{"kind":"p","page":205,"text":{"en":"Why B is the trap answer (INT8 Quantization):","fr":"Pourquoi B, la quantification INT8, est un piège"}},{"kind":"p","page":205,"text":{"en":"Quantization is legitimate and valuable — but it solves a different problem. It reduces model size (~4x smaller) and speeds up individual forward passes. If you were memory-constrained or couldn't fit the model at all, quantization is critical. But this model fits comfortably in 80GB VRAM and the GPU isn't saturated.","fr":"Quantifier réduit la taille du modèle d’environ un facteur quatre et accélère chaque passage. C’est essentiel en cas de limite mémoire ou lorsqu’il est impossible de charger le modèle. Ici, les 80 Go de VRAM suffisent largement et le GPU est sous-utilisé."}},{"kind":"p","page":205,"text":{"en":"INT8 quantization also introduces precision loss you need to validate carefully, and the speedup on a modern A100 for a 6B param model in isolation is modest — maybe 1.5–2x. That doesn't fix 3K RPS with sequential inference. You'll still have sequential execution, just slightly faster per call.","fr":"La quantification INT8 entraîne une perte de précision à évaluer soigneusement. Pour un modèle de 6 milliards de paramètres sur une A100 récente, le gain d’un passage seul est modeste, de l’ordre de 1,5 à 2 fois. À 3 000 RPS, l’inférence reste séquentielle. Chaque appel est seulement un peu plus rapide."}},{"kind":"p","page":205,"text":{"en":"The right order: batch first, quantize second (for memory or cost, not latency emergencies).","fr":"Activez d’abord le traitement par lots. Envisagez ensuite la quantification pour la mémoire ou les coûts."}}],[{"kind":"p","page":205,"text":{"en":"Why C is wrong here (Tensor Parallelism):","fr":"Pourquoi C, le parallélisme de tenseurs, est inadapté ici"}},{"kind":"p","page":205,"text":{"en":"Tensor parallelism splits model layers across multiple GPUs using NVLink or interconnects. It reduces per-request latency for very large models that don't fit on one device, or when you need sub-100ms latency on a single huge model.","fr":"Le parallélisme de tenseurs répartit les couches d’un modèle sur plusieurs GPU reliés par NVLink ou d’autres interconnexions. Il réduit la latence par requête pour les très grands modèles qui dépassent la mémoire d’un seul appareil, ou quand un modèle de cette taille doit répondre en moins de 100 ms."}},{"kind":"p","page":205,"text":{"en":"But this is a 6B param model on an 80GB A100 — it fits. Tensor parallelism adds coordination overhead and complexity, and it doesn't help when the bottleneck is sequential request processing. You'd also need 2+ GPUs, which inflates cost before you've even tried the cheap fix.","fr":"Ici, le modèle de 6 milliards de paramètres tient dans une A100 de 80 Go. Répartir le calcul ajouterait du coût de coordination et de la complexité alors que le traitement séquentiel est le goulet d’étranglement. Il faudrait aussi au moins deux GPU, ce qui renchérirait l’infrastructure avant même d’avoir essayé la solution la moins chère."}}],[{"kind":"p","page":205,"text":{"en":"Why D is wrong (Async Queue + Workers):","fr":"Pourquoi D, la file et les workers asynchrones, est insuffisant"}},{"kind":"p","page":205,"text":{"en":"An async queue decouples HTTP from inference and prevents timeout failures — that's a reliability win. But it doesn't improve GPU utilization or actual throughput. You're still processing one request at a time, just asynchronously. Users now get job IDs instead of timeouts, but the wall-clock wait is the same or worse.","fr":"Une file asynchrone découple HTTP de l’inférence et évite les expirations côté requête. C’est un gain de fiabilité. L’utilisation du GPU et le débit restent identiques : les requêtes sont toujours traitées une par une, désormais en arrière-plan. L’utilisateur reçoit un identifiant de tâche et attend aussi longtemps, voire davantage."}},{"kind":"p","page":205,"text":{"en":"Queuing without batching is adding a lobby to a slow restaurant. It hides the congestion — it doesn't fix it.","fr":"Une file sans traitement par lots revient à aménager une salle d’attente dans un restaurant qui sert trop lentement. La congestion devient moins visible et subsiste."}}]]},{"day":51,"title":{"en":"Isolating Noisy Tenants in Multi-Tenant SaaS","fr":"Isoler les clients qui monopolisent les ressources d’un SaaS multitenant"},"pages":[206,209],"topic":"architecture","correct":"D","scenario":[{"kind":"figure","page":206,"id":"206-02","width":800,"height":420,"alt":{"en":"Day 51 featured","fr":"Illustration de la question du jour 51"},"transcript":{"en":["System Design Labs","B2B SaaS: One Free-","r Export Crashed a","Paying Customer’s Checkout. How Do You Isolate Tenants?","HTTPS","Requests","‘onevery table","Bs","Enterprise","Load","App","Customers","Balancer","Server","PostgreSQL","(One DB, One Schema}","Heavy Road","Timeouts /","Slowdowns","Checkout","(Paying Customer)","Keep one shared DB — add row-level","‘Schema-per-tenant — every customer","to enforce limits.","security + query budgets per tenant","{gets their own schema in the same","Postgres instance, migrations run per-schema,","r-tenant (silo model) — each","Middleware bridge — route requests to","‘customer gets a dedicated DB.","tenant-specific DB clusters based on a tenant","ier stays pooled.","registry, free tier stays on shared pool."],"fr":["System Design Labs","B2B SaaS: Une","r Exporter Crashed a","Payer le paiement du client. Comment isolez-vous les locataires?","HTTPS","Demandes","«sur chaque table","Bs","Entreprise","Charger","App","Clients","Balancer","Serveur","PostgreSQL","(Une base de données, un schéma)","Heavy Road","Délais d'attente /","Ralentissements","Checkout","(Payant client)","Conserver une base de données partagée — ajouter un niveau de ligne","«Schéma par locataire — chaque client","pour imposer des limites.","budgets de sécurité + requête par locataire","obtient leur propre schéma dans le même","instance Postgres, les migrations s'exécutent par schema,","r-tenant (modèle silo) — chaque","Middleware bridge — demande d'itinéraire à","« Le client obtient une base de données dédiée.","clusters de base de données spécifiques aux locataires basés sur un locataire","Les séjours sont partagés.","registre, des séjours de niveau gratuit sur la piscine partagée."]}},{"kind":"p","page":206,"text":{"en":"You're building a B2B SaaS product. 50 enterprise customers. Each one wants their data isolated. Some are on free plans. A few are paying $50k/year and demanding SLA guarantees.","fr":"Vous développez un SaaS B2B pour 50 entreprises qui souhaitent isoler leurs données. Certaines utilisent l’offre gratuite. Quelques-unes paient 50 000 $ par an et exigent des garanties de SLA."}},{"kind":"p","page":206,"text":{"en":"Your current setup:","fr":"Votre configuration actuelle tient en trois points."}},{"kind":"p","page":206,"text":{"en":"→ One database. One schema. A tenant_id column on every table.","fr":"→ Une base de données, un schéma et une colonne tenant_id dans chaque table."}},{"kind":"p","page":206,"text":{"en":"→ One app server handling all traffic.","fr":"→ Un serveur applicatif pour tout le trafic."}},{"kind":"p","page":206,"text":{"en":"→ A free-tier customer running a badly-written bulk export just hammered your DB for 40 seconds. A paying enterprise customer's checkout flow timed out.","fr":"→ Un client de l’offre gratuite a lancé un export en masse mal conçu. La base a subi 40 secondes de forte charge et le parcours de paiement d’un client entreprise a expiré."}},{"kind":"p","page":206,"text":{"en":"Your investors are not happy. Neither is that enterprise customer.","fr":"Vos investisseurs sont mécontents, tout comme ce client entreprise."}},{"kind":"p","page":206,"text":{"en":"The engineering question: how do you isolate tenants without rebuilding the whole product?","fr":"Comment isoler les clients sans reconstruire tout le produit ?"}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":206,"text":{"en":"Keep one shared DB — add row-level security + query budgets per tenant to enforce limits.","fr":"Garder une base partagée. Ajoutez la sécurité au niveau des lignes et limitez le budget de requêtes par client."}}]},{"letter":"B","blocks":[{"kind":"p","page":206,"text":{"en":"Schema-per-tenant — every customer gets their own schema in the same Postgres instance, migrations run per-schema.","fr":"Un schéma par client. Chaque client obtient son propre schéma dans la même instance PostgreSQL. Les migrations s’exécutent schéma par schéma."}}]},{"letter":"C","blocks":[{"kind":"p","page":206,"text":{"en":"Database-per-tenant (silo model) — each enterprise customer gets a dedicated DB. Free tier stays pooled.","fr":"Une base par client, selon un modèle en silos. Chaque client entreprise obtient une base dédiée et l’offre gratuite utilise une base partagée."}}]},{"letter":"D","blocks":[{"kind":"p","page":207,"text":{"en":"Middleware bridge — route requests to tenant-specific DB clusters based on a tenant registry, free tier stays on shared pool.","fr":"Un middleware de routage. À partir d’un registre des clients, acheminez les requêtes vers des clusters de bases spécifiques. L’offre gratuite conserve son environnement partagé."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"figure","page":208,"id":"208-03","width":800,"height":533,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["Why D win:","Middleware Bridge — Hybrid Model","ach tenant to th","ight","Isol","re it matter","ale where it’","che","REQUEST FLOW","© Free/ Small (Shared)","© Mi-tier(Schema-per-tenant)","forward","© Emerprise(08-per-tenant)","Client","Balancer","Lose","‘op Server","Tenant Registry","THE PAYOFF","Noisy neighbor is contained.","‘runaway fee-tie export can","only impact eter teeter","tenants","Enterprise customers can't","2) Mid-tier Tenants","3) Enterprise Tenants","touch each other. Period.","‘Shared Pot D8","1B per-tennt Silo)","Dedicated DBs provide strong","laolation and SLA guarantees.","Grow tenants up the isolation","= 86Ee-s","ladder without code changes.","Shared Postares Cuter","Postgres Custer","Dediate Postgres Custers","Move a tenant between ters","(Ore tera pe 08)","by up","the registry only.","aa ase","ala oar","a cascade","DPR deletion is drop, not","ee 002","‘One DB drop for enterprise","tenants, Clean, fst, verifiable,","How it works","‘Araquest time, the app server ats the Tenant Reistry wheres tenant vest gets back a connection config","(host port, db, schema) and connects. The application code stays the sme for every tenant.","Free Sat","marron"],"fr":["Pourquoi retenir D :","Modèle hybride Middleware Bridge","ach locataire à la","ight","Isol","re it important","Ale où il est »","che","DEMANDER LE FLUX","Gratuit/ Petit (partagé)","Mi-tier(Schema-per-tenant)","vers le haut","Emerprise(08-par-locataire)","Client","Balancer","Perdre","«op Serveur","Registre des locataires","LE PAYOFF","Le voisin bruyant est contenu.","«cannette d’exportation dérisoire","seulement impact eter teter","locataires","Les clients ne peuvent pas","2) Locataires de niveau intermédiaire","3) Locataires d'entreprise","Touchez-vous les uns les autres.","Pot D8","1B pour le silo)","Les DB dédiés offrent une forte","laolation et SLA garanties.","Augmenter l'isolement des locataires","86Ee-s","échelle sans changement de code.","Shared Postares Cuter","Postgres Custer","Dédiez Postgres Custers","Déplacer un locataire entre les ters","(Ore tera pe 08)","par up","le registre uniquement.","aa ase","ala oar","une cascade","La suppression de DPR est drop, pas","ee 002","«Une baisse de DB pour l’entreprise","locataires, Propre, fst, vérifiable,","Comment ça marche","‘Araquest time, le serveur de l’application ats le Tenant Reistry où le locataire vest récupère une configuration de connexion","(port hôte, db, schéma) et se connecte. Le code de l'application reste le sme pour chaque locataire.","Gratuit sam","Marron"]}},{"kind":"p","page":208,"text":{"en":"Why D wins (Middleware bridge — hybrid model):","fr":"Pourquoi D fonctionne, avec un middleware de routage et un modèle hybride"}},{"kind":"p","page":208,"text":{"en":"This is the pattern Salesforce, HubSpot, and every mature B2B SaaS converges on eventually.","fr":"Salesforce, HubSpot et les SaaS B2B matures convergent vers ce modèle."}},{"kind":"p","page":208,"text":{"en":"The architecture:","fr":"L’architecture distingue trois niveaux."}},{"kind":"p","page":208,"text":{"en":"→ Free/small tenants → shared pool DB (cost-efficient, acceptable risk)","fr":"→ Petits clients et offre gratuite : base partagée, à un coût et un risque acceptables."}},{"kind":"p","page":208,"text":{"en":"→ Mid-tier tenants → schema-per-tenant in a shared Postgres cluster","fr":"→ Offres intermédiaires : un schéma par client dans un cluster PostgreSQL partagé."}},{"kind":"p","page":208,"text":{"en":"→ Enterprise tenants → dedicated DB cluster (full isolation, SLA-able)","fr":"→ Grands comptes : un cluster de base dédié, avec isolation complète et SLA possible."}},{"kind":"p","page":208,"text":{"en":"A tenant registry (Redis or a lightweight service) maps tenant_id → connection config at request time. Your app server doesn't care which model a tenant uses — it asks the registry and gets a connection string back.","fr":"À chaque requête, un registre des clients, par exemple Redis ou un service léger, associe tenant_id à la configuration de connexion. Le serveur applicatif interroge le registre et reçoit une chaîne de connexion. Le modèle d’isolation reste transparent pour lui."}},{"kind":"p","page":208,"text":{"en":"The payoff:","fr":"Cette configuration apporte plusieurs avantages."}},{"kind":"p","page":208,"text":{"en":"→ Noisy neighbor is contained. A runaway free-tier export can only hurt other free-tier tenants.","fr":"→ Un client bruyant reste isolé à son niveau. Un export démesuré dans l’offre gratuite ne peut affecter que les autres clients de cette offre."}},{"kind":"p","page":208,"text":{"en":"→ Enterprise customers can't touch each other. Period.","fr":"→ Les grands comptes sont isolés les uns des autres."}},{"kind":"p","page":209,"text":{"en":"→ You can migrate a tenant up the isolation ladder as they grow — without touching app code.","fr":"→ Un client qui grandit peut passer à un niveau d’isolation supérieur sans modifier le code applicatif."}},{"kind":"p","page":209,"text":{"en":"→ GDPR deletion is one DB drop for enterprise tenants, not a cascade delete across shared tables.","fr":"→ Pour le droit à l’effacement prévu par le RGPD, il suffit de supprimer la base d’un grand compte. Aucune suppression en cascade dans des tables partagées."}}],[{"kind":"p","page":209,"text":{"en":"Why A fails (Row-level security + query budgets):","fr":"Pourquoi A échoue, avec la sécurité au niveau des lignes et des budgets de requêtes"}},{"kind":"p","page":209,"text":{"en":"RLS works. Query budgets can work. But they share the same DB process. A tenant that opens 500 connections, triggers a table lock, or fills the WAL — that bleeds into every other tenant on the instance. You can throttle CPU, but you can't throttle I/O blast radius once it's in the buffer pool.","fr":"La RLS fonctionne et les budgets de requêtes peuvent fonctionner. Pourtant, tous les clients partagent le processus de base de données. Si l’un ouvre 500 connexions, verrouille une table ou remplit le WAL, les autres clients de l’instance subissent l’effet. Vous pouvez limiter la consommation CPU. Une fois le cache de tampons touché, les effets d’E/S se propagent."}},{"kind":"p","page":209,"text":{"en":"This is the band-aid answer. Fine at 5 tenants. Falls apart at 50.","fr":"C’est une solution provisoire, acceptable avec cinq clients et fragile à cinquante."}}],[{"kind":"p","page":209,"text":{"en":"Why B is dangerous (Schema-per-tenant):","fr":"Pourquoi B, un schéma par client, devient risqué"}},{"kind":"p","page":209,"text":{"en":"Schema-per-tenant sounds clean. It is, until:","fr":"Un schéma par client semble simple jusqu’aux premières limites."}},{"kind":"p","page":209,"text":{"en":"→ 300 tenants need a migration. That's 300 sequential DDL operations on one Postgres instance. Migration windows become a multi-hour risk event.","fr":"→ Une migration sur 300 clients entraîne 300 opérations DDL séquentielles sur une seule instance PostgreSQL. La fenêtre de migration dure des heures, avec un risque tout du long."}},{"kind":"p","page":209,"text":{"en":"→ At 500 tenants you're burning connection slots faster than you can PgBounce your way out.","fr":"→ À 500 clients, les connexions disponibles s’épuisent même avec PgBouncer."}},{"kind":"p","page":209,"text":{"en":"→ One long-running query in schema_tenant_247 still holds locks on shared system tables. Noisy neighbor hasn't gone away — you just can't see it as clearly.","fr":"→ Une longue requête dans schema_tenant_247 peut encore verrouiller des tables système partagées. Le problème du voisin bruyant demeure, avec des symptômes moins visibles."}},{"kind":"p","page":209,"text":{"en":"Schema-per-tenant is a local maximum. You hit Postgres scaling walls before you hit the point where it pays off.","fr":"Un schéma par client est un optimum local. Les limites de mise à l’échelle de PostgreSQL arrivent avant que cette approche devienne rentable."}}],[{"kind":"p","page":209,"text":{"en":"Why C is too expensive too early (Full silo):","fr":"Pourquoi C, l’isolation complète en silos, coûte trop cher à ce stade"}},{"kind":"p","page":209,"text":{"en":"The silo model is the correct isolation model for enterprise customers. But applying it to all tenants — including a free tier with 1,000 accounts — means 1,000 Postgres instances. That's $40k/month in RDS costs before you've made a dollar.","fr":"Les silos assurent l’isolation nécessaire aux grands comptes. Appliquer ce modèle à tous les clients, y compris aux 1 000 comptes de l’offre gratuite, reviendrait à gérer 1 000 instances PostgreSQL et à dépenser 40 000 $ par mois sur RDS avant le premier revenu."}},{"kind":"p","page":209,"text":{"en":"Full silo for everyone is the right endgame for the top 5% of your customer base. Applying it everywhere is overengineering.","fr":"À terme, réservez l’isolation totale aux 5 % de clients qui en ont besoin. La généraliser ajoute une complexité inutile."}}]]},{"day":52,"title":{"en":"Versioning an API Without Breaking Clients","fr":"Versionner une API sans casser les intégrations clientes"},"pages":[210,213],"topic":"architecture","correct":"D","scenario":[{"kind":"figure","page":210,"id":"210-02","width":800,"height":420,"alt":{"en":"Day 52 featured","fr":"Illustration de la question du jour 52"},"transcript":{"en":["Design","Which strategy does your team use —","and has it ever cost you an incident?","Rogues","Clients","API","me","Cache","Partner Integrations)","(Mobile, Web,","Gateway","(Redis)","Simple. Expt.","URL path versioning fier, Wafer)","quest","‘lean URLs Version nee","Header versioning (API-Version:2)","the transport ayer, nt the pat","logrand caches. ut now youre maintaining 2 ulate res","Harder to tstin a","join logs unless you nsrumont","‘Query param versioning (Jusers?version=2)","Fast implement. Zero cent SDK changes. Cache-untiendly —","“The REST-puritaporcach. Semnticaly corect — youre asking","Content negotiation (Accept: application/vnd.apiv2+}son)","every CON layer treats version=1 and 2version=2 as separate key","LD |","{ors representation nota route. One wrong Accept header and 406,"],"fr":["Design","Quelle stratégie votre équipe utilise-t-elle?","Cela vous a-t-il déjà coûté un incident ?","Rogues","Clients","API","me","Cache","Intégrations de partenaires)","(Mobile, Web,","Passerelle","(Redis)","Simple. Expt.","URL path versioning fier, Wafer)","quête","‘lean URLs Version nee","Version d'en-tête (API-Version:2)","le transport ayer, nt la tape","logrand caches. ut maintenant vous êtes en train de maintenir 2 ulate res","Plus difficile à tstin a","Joindre des journaux à moins que vous nsrumont","«Query param versioning (Jusers?version — 2)","Implémentation rapide. Changements du SDK zéro cent.","« Le REST-puritaporcach. Semnticaly corect — vous demandez","(Accepter: Application/vnd.apiv2+son)","chaque couche CON traite les versions 1 et 2version 2 comme des clés séparées","LD","ors representation nota route. Une erreur Accepter l'en-tête et 406,"]}},{"kind":"p","page":210,"text":{"en":"Your API just shipped a breaking change.","fr":"Une modification de votre API vient de rompre la compatibilité."}},{"kind":"p","page":210,"text":{"en":"/users now returns fullName instead of first_name + last_name. 3 mobile clients broke. 1 partner integration went down. Your on-call is not happy.","fr":"Le chemin /users renvoie désormais fullName à la place de first_name + last_name. Trois clients mobiles cessent de fonctionner et une intégration partenaire tombe en panne. L’astreinte est mise à contribution."}},{"kind":"p","page":210,"text":{"en":"You had a versioning strategy. It just wasn't the right one.","fr":"Vous aviez prévu une stratégie de versionnement. Elle s’est révélée inadaptée."}},{"kind":"p","page":210,"text":{"en":"There are 4 ways to version an API. Here's what actually happens when you pick each one in production:","fr":"Il existe quatre façons de versionner une API. Voici leurs effets en production."}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":210,"text":{"en":"URL path versioning (/v1/users, /v2/users)","fr":"Version dans le chemin de l’URL (/v1/users, /v2/users)"}},{"kind":"p","page":210,"text":{"en":"Simple. Explicit. Every request makes the version visible in logs and caches. But now you're maintaining 2 full route trees. A bugfix in the business logic layer has to be patched in both. Teams quietly let v1 rot.","fr":"C’est simple et explicite. Chaque requête rend la version visible dans les journaux et les caches. En contrepartie, vous maintenez deux arborescences de routes complètes. Tout correctif de logique métier doit être reporté dans les deux versions. Les équipes finissent souvent par laisser la v1 se dégrader."}}]},{"letter":"B","blocks":[{"kind":"p","page":210,"text":{"en":"Header versioning (API-Version: 2)","fr":"Version dans un en-tête (API-Version: 2)"}},{"kind":"p","page":210,"text":{"en":"Clean URLs. Version negotiation in the transport layer, not the path. Harder to test in a browser, invisible in logs unless you instrument for it, and clients forget to send the header — defaulting to whatever your server decides \"latest\" means.","fr":"Les URL restent propres et la version se négocie au niveau du transport. Elle est plus difficile à tester dans un navigateur et n’apparaît dans les journaux que si vous l’instrumentez. Si un client oublie l’en-tête, le serveur choisit la version qu’il considère comme la plus récente."}}]},{"letter":"C","blocks":[{"kind":"p","page":210,"text":{"en":"Query param versioning (/users?version=2)","fr":"Version dans un paramètre de requête (/users?version=2)"}},{"kind":"p","page":211,"text":{"en":"Fast to implement. Zero client SDK changes. Cache-unfriendly — every CDN layer treats ?version=1 and ? version=2 as separate cache keys. Works until you have 40 endpoints and version drift becomes untrackable.","fr":"L’implémentation est rapide et les SDK clients restent inchangés. Chaque couche CDN traite ?version=1 et ?version=2 comme des clés de cache distinctes. Cela fonctionne jusqu’à ce qu’avec 40 endpoints, la dispersion des versions devienne impossible à suivre."}}]},{"letter":"D","blocks":[{"kind":"p","page":211,"text":{"en":"Content negotiation (Accept: application/vnd.api.v2+json)","fr":"Négociation de contenu (Accept: application/vnd.api.v2+json)"}},{"kind":"p","page":211,"text":{"en":"The REST-purist approach. Semantically correct — you're asking for a representation, not a route. Almost nobody implements it right. Client library support is inconsistent. One wrong Accept header and you get a 406.","fr":"C’est l’approche des puristes de REST. Sur le plan sémantique, vous demandez une représentation précise de la ressource. Peu d’implémentations le font correctement et la prise en charge varie d’une bibliothèque cliente à l’autre. Un en-tête Accept erroné déclenche une réponse 406."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"figure","page":212,"id":"212-03","width":800,"height":533,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["System Design Labs","(D] Content negotiation:","correct spec, wrong reality","HOW CONTENT NEGOTIATION SHOULD WORK","application/vnd.api.v2+json","GET fusers","is what the HTTP spec intended.","‘Accept","Client","Data","You're asking for a specific representation","Gateway","Store","of a resource, not a different route.","‘Semantically, it's the most correct.","2000K","(Representation v2)","‘THE REALITY IN PRODUCTION","Inconsistent client","Middleware strips","406 Not Acceptable","Hard to test and debug","Even GitHub moved on","library support","headers silently","with no context","Different HTTP clients","Browsers hide custom","Githlub tried content","Proxies, gateways, and","Misconfigured clients","headers in simple tests.","‘negotiation early in their","format or send the Accept","‘observabilty tots often","‘get 2 406 with no clear","‘APIs behave differently","‘AP and moved to","header dtferently — oF","remove unknown","hint that the Accept","‘across environments","URL versioning,","not at al","headers.","header isthe issue.","Bottom line:","‘The most correct on paper, but the least reliable in practice.","‘Accept: application/vnd.api.v2+json","—+ | 406 not Acceptable","Great in theory. Painful in production."],"fr":["System Design Labs","(D) Négociation de contenu :","correcte spec, mauvaise réalité","COMMENT LA NÉGOCIATION DE CONTENU DEVRAIT FAIRE","application/vnd.api.v2+json","GET fusibles","C'est ce que la spécification HTTP voulait.","«Accepter","Client","Données","Vous demandez une représentation spécifique","Passerelle","Stocker","d'une ressource, pas d'une autre route.","\"Sémantiquement, c'est le plus correct.","2000K","(Représentation v2)","«LA RÉALITÉ DE LA PRODUCTION","Client incohérent","Middleware bandes","406 Inacceptable","Difficile à tester et à déboguer","Même GitHub a déménagé","soutien de bibliothèque","En-têtes silencieusement","Sans contexte","Différents clients HTTP","Navigateurs cacher personnalisé","Githlub a essayé le contenu","Proxies, passerelles et","Clients mal configurés","des en-têtes dans des tests simples.","« La négociation au début de leur","formater ou envoyer le formulaire Accepter","‘observabilité souvent","« obtenir 2 406 avec aucun clair","« Les API se comportent différemment","« AP et déplacé à","header dtferently — oF","Supprimer Inconnu","Indication que le Accepter","«dans tous les environnements","Versioning URL,","Pas à Al","En-têtes.","L'en-tête est le problème.","Bottom line:","« Le plus correct sur le papier, mais le moins fiable en pratique.","«Accepter: application/vnd.api.v2+json","+ — 406 non acceptable","Douloureux en production."]}},{"kind":"p","page":212,"text":{"en":"D — Content negotiation: correct spec, wrong reality","fr":"D — Négociation de contenu, conforme à la spécification et délicate en pratique"}},{"kind":"p","page":212,"text":{"en":"Accept: application/vnd.api.v2+json is what the HTTP spec intended. You're asking for a specific representation of a resource, not a different route. Semantically, it's the most correct.","fr":"L’en-tête Accept: application/vnd.api.v2+json correspond à l’intention de la spécification HTTP. Vous sélectionnez une représentation précise d’une ressource en conservant la même route. C’est l’option la plus juste sur le plan sémantique."}},{"kind":"p","page":212,"text":{"en":"In practice: Accept header parsing is inconsistent across client libraries. Middleware strips headers silently. A misconfigured client gets a 406 Not Acceptable with no obvious error message pointing to the version field. GitHub tried content negotiation early in their API and moved to URL versioning. That tells you something.","fr":"En pratique, les bibliothèques clientes interprètent l’en-tête Accept différemment. Des middlewares peuvent retirer des en-têtes sans signalement. Un client mal configuré reçoit un 406 Not Acceptable, sans message qui indique clairement un problème de version. GitHub a d’abord expérimenté la négociation de contenu, avant de passer au versionnement dans l’URL."}}],[{"kind":"p","page":213,"text":{"en":"A — URL path versioning: the pragmatic default (not wrong, but has a cost)","fr":"A — Version dans le chemin de l’URL, un choix pragmatique qui a un coût"}},{"kind":"p","page":213,"text":{"en":"This is what Stripe, Twilio, and GitHub use. Not because it's theoretically pure — it isn't — but because it's operationally obvious.","fr":"Stripe, Twilio et GitHub utilisent cette approche parce qu’elle est facile à exploiter au quotidien."}},{"kind":"p","page":213,"text":{"en":"Every proxy, log aggregator, and CDN understands it without configuration. /v1/ vs /v2/ is visible everywhere without instrumentation.","fr":"Les proxies, les agrégateurs de journaux et les CDN la comprennent sans configuration. La distinction entre /v1/ et /v2/ est visible partout sans instrumentation."}},{"kind":"p","page":213,"text":{"en":"The cost is real: you're running parallel route trees, and v1 maintenance debt compounds fast. A bugfix in shared business logic has to be patched in both versions. Stripe's answer was to pin clients to a version at the API key level and deprecate slowly over years. Most teams don't have that discipline — so v1 quietly rots while v2 gets all the attention.","fr":"Vous gérez toutefois plusieurs arborescences de routes en parallèle et la dette de maintenance de la v1 augmente vite. Un correctif dans la logique métier commune doit être appliqué aux deux versions. Stripe a choisi d’associer une version à chaque clé API et d’étaler la dépréciation sur plusieurs années. Faute de cette discipline, les équipes se concentrent généralement sur la v2 et laissent la v1 vieillir."}}],[{"kind":"p","page":213,"text":{"en":"B — Header versioning: good theory, rough edges","fr":"B — Version dans un en-tête, élégante en théorie et délicate à exploiter"}},{"kind":"p","page":213,"text":{"en":"Clean architecture. The URL represents a resource, the header represents the negotiation. This is how internal microservices often version — when you control both client and server, it works well.","fr":"La répartition est claire : l’URL représente la ressource et l’en-tête sert à la négociation. Les microservices internes adoptent souvent ce modèle, qui fonctionne bien quand vous contrôlez à la fois le client et le serveur."}},{"kind":"p","page":213,"text":{"en":"The problem: invisible in browser tabs, impossible to share as a curl command without extra flags, and \"default to latest\" on a missing header is a footgun. In year two, a legacy client quietly drops the header. Your server defaults it to v2. The client breaks. Nobody knows why — it's not in the URL, it's not in the logs unless you specifically instrumented for it.","fr":"La version est invisible dans la barre d’adresse et les commandes curl demandent des options supplémentaires pour être partagées. Choisir la dernière version en l’absence d’en-tête est risqué. Deux ans plus tard, un client ancien omet silencieusement l’en-tête. Le serveur lui attribue la v2 et le client casse. La cause reste invisible dans l’URL et dans les journaux, sauf si vous avez prévu une instrumentation spécifique."}}],[{"kind":"p","page":213,"text":{"en":"C — Query params: the quick fix that stays forever","fr":"C — Paramètres de requête, la solution rapide qui s’installe dans la durée"}},{"kind":"p","page":213,"text":{"en":"Fast to implement. Zero client SDK changes. Works immediately.","fr":"Cette approche s’implémente rapidement, sans modification des SDK clients, et fonctionne immédiatement."}},{"kind":"p","page":213,"text":{"en":"Cache invalidation gets messy at scale — every CDN layer treats ?version=1 and ?version=2 as separate cache keys, so your cache hit rate tanks. The bigger problem is version drift: with no forcing function, clients scatter across v1/v2/v3 with no deprecation pressure. Good for internal tools where you control all the clients. Gets expensive for public APIs.","fr":"L’invalidation du cache se complique à grande échelle. Chaque couche CDN attribue des clés distinctes à ?version=1 et ?version=2, ce qui fait chuter le taux de succès du cache. Plus grave, sans mécanisme de dépréciation, les clients se dispersent entre v1, v2 et v3. Cela convient aux outils internes dont vous contrôlez tous les clients. Pour une API publique, cette stratégie devient coûteuse."}}]]},{"day":53,"title":{"en":"Zero-Downtime Schema Migrations","fr":"Migrer un schéma sans interruption de service"},"pages":[214,217],"topic":"data","correct":"B","scenario":[{"kind":"figure","page":214,"id":"214-02","width":800,"height":421,"alt":{"en":"Day 53 featured","fr":"Illustration de la question du jour 53"},"transcript":{"en":["tem Ds","ab","How do you split full_name into first_name + last_name","on a live users table with 40M rows and 8 active writers — without downtime?","User","Service","Writes","Metrics","aa","nw","Monitoring &","Clients / Apps","‘Alerts","users table","‘40M rows","Reads","Run ALTER TABLE to drop full_name and add","[Add first_name + last_name as nullable columns frst +","first_name + last_name ina single migration during","backfill > update all services to write to both ~ drop","‘the maintenance window.","full_name only after everything is migrated.","Create a new use","v2 table withthe target schema ->","‘Add a DB view that aliases full_name as","<dual-write to both tables - flip the read pointer ->","first_name |","Il last name ~ let each service","drain the old table.","migrate offit atts own pace."],"fr":["tem Ds","ab","Comment diviser nom_complet en prénom + nom_nom","sur une table d'utilisateurs en direct avec 40M lignes et 8 écrivains actifs - sans temps d'arrêt?","Utilisateur","Service","Écrit","Métrique","aa","nw","Surveillance &","Clients / Apps","«Alertes","table des utilisateurs","«40M lignes","Lectures","Exécutez ALTER TABLE pour supprimer full_name et ajouter","[Ajouter nom_de_la_première + nom_de_la_dernière comme colonnes nullables","prenom + nom de famille lors d'une migration unique","backfill > mettre à jour tous les services pour écrire à la fois — drop","« La fenêtre de maintenance.","full_name seulement après que tout soit migré.","Créer une nouvelle utilisation","table v2 avec le schéma cible ->","‘Ajouter une vue DB qui alias full_name comme","dual-write pour les deux tables - retourne le pointeur de lecture ->","prénom","Il nom — laisser chaque service","Videz l'ancienne table.","migrent d'ajustement à leur propre rythme."]}},{"kind":"p","page":214,"text":{"en":"Your migration ran fine in staging.","fr":"La migration s’est bien passée en préproduction."}},{"kind":"p","page":214,"text":{"en":"Then you ran it in production.","fr":"Vous l’avez ensuite lancée en production."}},{"kind":"p","page":214,"text":{"en":"The app went down.","fr":"L’application est tombée."}},{"kind":"p","page":214,"text":{"en":"Not because the SQL was wrong. Because you ran it on a live table with 40 million rows while 8 services were actively writing to it.","fr":"Le SQL était correct. La migration a ciblé une table en service de 40 millions de lignes alors que huit services y écrivaient."}},{"kind":"p","page":214,"text":{"en":"Your setup:","fr":"Voici votre configuration."}},{"kind":"p","page":214,"text":{"en":"→ PostgreSQL. users table. 40M rows. Active writes from 8 services.","fr":"→ Table users de 40 millions de lignes dans PostgreSQL, avec huit services qui écrivent en continu."}},{"kind":"p","page":214,"text":{"en":"→ Product request: split full_name into first_name + last_name.","fr":"→ L’équipe produit demande de scinder full_name en first_name et last_name."}},{"kind":"p","page":214,"text":{"en":"→ You have a 2-hour maintenance window tonight.","fr":"→ Vous disposez d’une fenêtre de maintenance de deux heures ce soir."}},{"kind":"p","page":214,"text":{"en":"The engineering question: how do you ship this without downtime?","fr":"Comment livrer cette modification sans interruption de service ?"}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":214,"text":{"en":"Run ALTER TABLE to drop full_name and add first_name + last_name in a single migration during the maintenance window.","fr":"Exécuter un ALTER TABLE qui supprime full_name et ajoute first_name et last_name dans une seule migration, pendant la fenêtre de maintenance."}}]},{"letter":"B","blocks":[{"kind":"p","page":214,"text":{"en":"Add first_name + last_name as nullable columns first → backfill → update all services to write to both → drop full_name only after everything is migrated.","fr":"Ajouter first_name et last_name comme colonnes acceptant NULL, reprendre les données existantes, faire écrire tous les services dans l’ancien et le nouveau format, puis supprimer full_name quand la migration est complète."}}]},{"letter":"C","blocks":[{"kind":"p","page":215,"text":{"en":"Create a new users_v2 table with the target schema → dual-write to both tables → flip the read pointer → drain the old table.","fr":"Créer une table users_v2 avec le schéma cible, écrire dans les deux tables, faire basculer les lectures vers la nouvelle, puis retirer progressivement l’ancienne."}}]},{"letter":"D","blocks":[{"kind":"p","page":215,"text":{"en":"Add a DB view that aliases full_name as first_name || ' ' || last_name → let each service migrate off it at its own pace.","fr":"Ajouter une vue de base de données qui définit full_name comme first_name || ' ' || last_name. Laissez chaque service abandonner la vue à son rythme."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"figure","page":216,"id":"216-03","width":800,"height":450,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["ys","De:","ab","Why |B is correct (expand/contract)","ExpaNO STATE","WRITE PATH (DURING PHASE 1)","© wavrasis sare","EXPAND","wre","were","ro","Adding arabe carn with no","as","‘earinstnt ook,","Beckfiin sal batches","‘Backfilin small batches hops","‘aes","rane","cry","wane","the system responsive.","we","(td coer reins source of","te","truth unt youre ready.","ed copy)","reversible","AFTER CONTRACT","CONTRACT","+ fullname is dropped ony when","© oe a services write tothe","00","sae","You conto the exact timing.","fay migrate","Minimal ak Masur control","© rep fall name.","Slower than A? Yes.","© ou cont the timing","‘3am pages? Zero."],"fr":["ys","Dé :","ab","Pourquoi — B est correct (extension/contrat)","L'ÉTAT EXPANO","PATH ÉCRITE (pendant la phase 1)","wavrasis sare","EXPAND","wre","étaient","ro","Ajouter un carn arabe avec non","en","«earinstnt ook,","Beckfiin sal batchs","«Backfilin small batchs houblon","«aes","rane","pleurer","déclin","Le système responsive.","nous","(à l'origine de","te","vérité unt vous êtes prêt.","ex. ed)","réversible","APR — S CONTRAT","CONTRACT","+ fullname est abandonné quand","oe un service écrire à","00","sae","Vous respectez le timing exact.","fay migre","Contrôle minimal ak Masur","nom de la rep.","Plus lent que A ?","ou continuer le timing","« 3 heures du matin ?"]}},{"kind":"p","page":216,"text":{"en":"Why B is correct","fr":"Pourquoi B est la bonne réponse"}},{"kind":"p","page":216,"text":{"en":"Two phases.","fr":"La migration se fait en deux phases."}},{"kind":"p","page":216,"text":{"en":"Phase 1 — Expand: add first_name and last_name as nullable columns. On PostgreSQL, adding a nullable column with no default is a metadata-only operation — near-instant, no lock. Backfill in small batches (rate-limited, no row lock escalation). Update services to write to both columns simultaneously.","fr":"Phase 1 — Extension. Ajoutez first_name et last_name comme colonnes acceptant NULL. Sur PostgreSQL, ajouter une colonne nullable sans valeur par défaut ne modifie que les métadonnées. L’opération est presque instantanée et ne maintient pas un verrou le temps de réécrire la table. Reprenez les données par petits lots, avec limitation du débit et sans escalade des verrous de ligne. Faites écrire les services dans les deux formats simultanément."}},{"kind":"p","page":216,"text":{"en":"Phase 2 — Contract: once every service is writing to the new columns and reads are fully migrated, drop full_name. You control the timing.","fr":"Phase 2 — Retrait. Lorsque tous les services écrivent dans les nouvelles colonnes et que toutes les lectures ont migré, supprimez full_name. Vous choisissez le moment."}},{"kind":"p","page":216,"text":{"en":"The key property: every step is independently reversible. If something breaks after Phase 1, you stop — the old column still exists, old services still work.","fr":"Chaque étape est réversible indépendamment. Si un problème survient après la première phase, vous pouvez vous arrêter. L’ancienne colonne existe toujours et les anciens services continuent de fonctionner."}},{"kind":"p","page":216,"text":{"en":"Slower than A? Yes. 3am pages? Zero.","fr":"La migration prend plus de temps que l’option A, mais vous évite les alertes à trois heures du matin."}}],[{"kind":"p","page":217,"text":{"en":"Why A will get you paged","fr":"Pourquoi A va déclencher des alertes"}},{"kind":"p","page":217,"text":{"en":"ALTER TABLE on a live table acquires an ACCESS EXCLUSIVE lock in PostgreSQL. It blocks every read and write for the duration. On a 40M row table with active traffic, that lock holds for minutes — not seconds. Your 8 services time out. The queue backs up. Alerts fire.","fr":"Sur PostgreSQL, ALTER TABLE prend un verrou ACCESS EXCLUSIVE sur la table en service. Toutes les lectures et écritures sont bloquées pendant l’opération. Sur 40 millions de lignes sous trafic, le verrou peut durer plusieurs minutes. Les huit services dépassent leurs délais d’attente, la file s’allonge et les alertes se déclenchent."}},{"kind":"p","page":217,"text":{"en":"CONCURRENTLY helps for index creation. It doesn't help for column drops or renames. The maintenance window doesn't save you — the lock is the problem, not the timing.","fr":"CONCURRENTLY aide à créer des index. Il ne s’applique pas à la suppression ni au renommage de colonnes. Même pendant une fenêtre de maintenance, le verrou reste problématique."}}],[{"kind":"p","page":217,"text":{"en":"Why C is overkill","fr":"Pourquoi C ajoute trop de travail"}},{"kind":"p","page":217,"text":{"en":"Shadow table + dual-write works. But it requires a dual-write layer in every service, an atomic read-pointer flip, and a drain/cleanup phase for the old table.","fr":"Une table miroir et une double écriture fonctionnent. Il faut cependant une couche de double écriture dans chaque service, une bascule atomique des lectures et une phase de retrait de l’ancienne table."}},{"kind":"p","page":217,"text":{"en":"Worth it for genuine structural rewrites — new primary key, re-partitioning, changing storage engines. For a column split on a single table? That's 3 weeks of engineering for a 3-day problem.","fr":"Cette stratégie se justifie pour une vraie refonte structurelle, comme changer la clé primaire, repartitionner ou migrer de moteur de stockage. Scinder une colonne dans une seule table revient ici à mobiliser trois semaines d’ingénierie pour un problème de trois jours."}}],[{"kind":"p","page":217,"text":{"en":"Why D defers the problem","fr":"Pourquoi D reporte le problème"}},{"kind":"p","page":217,"text":{"en":"A view aliasing full_name buys time. Useful as a transition layer inside Option B. But PostgreSQL write-through views only work on simple single-table views with no joins or aggregates. You still need to backfill the real columns eventually.","fr":"Une vue qui expose un alias full_name fait gagner du temps. Elle peut servir de couche de transition dans l’option B. PostgreSQL autorise l’écriture à travers une vue uniquement dans des cas simples, sur une seule table sans jointure ni agrégat. Il faut tout de même renseigner les nouvelles colonnes pour les lignes existantes."}},{"kind":"p","page":217,"text":{"en":"It defers the migration. It doesn't replace it.","fr":"Cette solution ne fait que différer la migration."}}]]},{"day":54,"title":{"en":"Handling Embedding Drift in RAG","fr":"Gérer la dérive des embeddings dans un système RAG"},"pages":[218,221],"topic":"ai","correct":"C","scenario":[{"kind":"figure","page":218,"id":"218-02","width":800,"height":420,"alt":{"en":"Day 54 featured","fr":"Illustration de la question du jour 54"},"transcript":{"en":["‘System Design Labs","You built a RAG pipeline. Works great in dev.","6 months later, your users complain: \"The search results are garbage.\"","Embed","Generate","Results","Query","Index","Service","Users","Fetch","Context","Index Built","Document","(Cached)","Store","‘Scheduled full rt","Incremental upserts + soft delete","Every Sunday, re-embed the entire corpus from serach,","‘On every document change, re-embed only the affected chunks","Replace the index atomically. Slow (ah at scale),","deleted chunks as tombstoned. Ki","expensive, but always fresh.","‘ach vector nd size grows overtime: compact quarterly","Embedding version registry + hot swap","Approximate staleness detection","“Track which embedding model version produced","ch vector","Runa nightly job that samples 1% of your corpus, embeds it,","When the model drifts (fine-tuned or upgraded), invalidate the","‘and measures cosine dstance against the stored vector,","‘mismatched veetors and rebuild only those. Two indexes run","If drift exceeds a threshold, trigger a full ebuild. Otherwise,","in parallel during migration. Route traffic by model version.","skip &. Cheap monitoring, reactive rebuilds"],"fr":["«System Design Labs","Vous avez construit un pipeline RAG. Fonctionne très bien en dev.","6 mois plus tard, vos utilisateurs se plaignent: \"Les résultats de recherche sont des ordures.\"","Intégrer","Générer","Résultats","Requête","Indice","Service","Utilisateurs","Récupère","Contexte","Index Construit","Document","(Encaissé)","Stocker","«Planifiée à temps plein","Upserts incrémentaux + suppression douce","Chaque dimanche, re-embeded l'ensemble du corpus de serach,","Sur chaque changement de document, ré-embed seulement les morceaux affectés","Remplacez l'indice atomique. Lent (ah à l'échelle),","morceaux supprimés comme tombstoned. Ki","C'est cher, mais toujours frais.","«chaque vecteur et taille augmente les heures supplémentaires: compact trimestriellement","Incorporation du registre de version + échange à chaud","Détection approximative de la vétusté","« Piste qui embedding modèle version produite","ch vecteur","Un travail nocturne qui échantillonne 1% de votre corpus, l'intègre,","Lorsque le modèle dérive (finement réglé ou mis à niveau), invalider le","«et mesures cosinus dstance contre le vecteur stocké,","«Vétérateurs mal assortis et ne reconstruisez que ceux-ci. Deux index fonctionnent","Si la dérive dépasse un seuil, déclenchez une construction complète. Sinon,","en parallèle pendant la migration. Router le trafic par version du modèle.","skip &. Surveillance bon marché, reconstruction réactive"]}},{"kind":"p","page":218,"text":{"en":"You built a RAG pipeline. Works great in dev.","fr":"Votre pipeline RAG fonctionne très bien en développement."}},{"kind":"p","page":218,"text":{"en":"6 months later, your users complain: \"The search results are garbage.\"","fr":"Six mois plus tard, les utilisateurs se plaignent de la mauvaise qualité des résultats de recherche."}},{"kind":"p","page":218,"text":{"en":"You haven't changed a line of code.","fr":"Vous n’avez modifié aucune ligne de code."}},{"kind":"p","page":218,"text":{"en":"Here's what happened:","fr":"Voici ce qui s’est passé."}},{"kind":"p","page":218,"text":{"en":"Your product evolved. New features, new docs, new support tickets. The data drifted — but your embedding index didn't.","fr":"Le produit a évolué, avec de nouvelles fonctionnalités, de nouveaux documents et de nouveaux tickets d’assistance. Les données ont dérivé tandis que l’index d’embeddings est resté inchangé."}},{"kind":"p","page":218,"text":{"en":"Now you're serving a 400GB FAISS index that was last rebuilt in January. Your chunks are stale. Your nearest-neighbor results point to deprecated docs. Your LLM is confidently hallucinating from outdated context.","fr":"Vous servez maintenant un index FAISS de 400 Go reconstruit pour la dernière fois en janvier. Vos fragments sont obsolètes et les plus proches voisins renvoient vers des documents dépréciés. Votre LLM hallucine avec assurance à partir d’un contexte périmé."}},{"kind":"p","page":218,"text":{"en":"You need to fix this. 4 engineers each propose a solution:","fr":"Quatre ingénieurs proposent chacun une solution."}}],"postScenario":[{"kind":"p","page":219,"text":{"en":"Real constraint: your corpus is 50M chunks. Full rebuild = 4 hours + ~$800 in embedding API cost. You deploy model updates every 6 weeks.","fr":"Votre corpus compte 50 millions de fragments. Une reconstruction complète prend quatre heures et coûte environ 800 $ d’appels à l’API d’embeddings. Vous déployez un nouveau modèle toutes les six semaines."}}],"choices":[{"letter":"A","blocks":[{"kind":"p","page":218,"text":{"en":"Scheduled full rebuild","fr":"Reconstruction complète planifiée"}},{"kind":"p","page":218,"text":{"en":"Every Sunday, re-embed the entire corpus from scratch. Replace the index atomically. Slow (4h+ at scale), expensive, but always fresh.","fr":"Recalculez tous les embeddings le dimanche et remplacez l’index d’un seul coup, de façon atomique. L’opération est coûteuse et dure au moins quatre heures à grande échelle, mais l’index reste à jour."}}]},{"letter":"B","blocks":[{"kind":"p","page":218,"text":{"en":"Incremental upserts + soft delete","fr":"Upserts incrémentaux et suppression logique"}},{"kind":"p","page":219,"text":{"en":"On every document change, re-embed only the affected chunks. Mark deleted chunks as tombstoned. Keep a version field on each vector. Index size grows over time; compact quarterly.","fr":"À chaque modification d’un document, recalculez seulement les embeddings des fragments concernés. Placez des marqueurs sur les fragments supprimés et conservez un champ de version pour chaque vecteur. L’index grossit avec le temps. Compactez-le tous les trimestres."}}]},{"letter":"C","blocks":[{"kind":"p","page":219,"text":{"en":"Embedding version registry + hot swap","fr":"Registre des versions du modèle d’embedding et bascule à chaud"}},{"kind":"p","page":219,"text":{"en":"Track which embedding model version produced each vector. When the model drifts (fine-tuned or upgraded), invalidate the mismatched vectors and rebuild only those. Two indexes run in parallel during migration. Route traffic by model version.","fr":"Identifiez la version du modèle qui a généré chaque vecteur. Après un changement de modèle, par exemple un affinage ou une mise à niveau, invalidez les vecteurs incompatibles et ne recalculez que ceux-là. Maintenez deux index en parallèle pendant la migration et acheminez le trafic selon la version du modèle."}}]},{"letter":"D","blocks":[{"kind":"p","page":219,"text":{"en":"Approximate staleness detection","fr":"Détection approximative de l’obsolescence"}},{"kind":"p","page":219,"text":{"en":"Run a nightly job that samples 1% of your corpus, re-embeds it, and measures cosine distance against the stored vector. If drift exceeds a threshold, trigger a full rebuild. Otherwise, skip it. Cheap monitoring, reactive rebuilds.","fr":"Chaque nuit, prenez un échantillon de 1 % du corpus, recalculez ses embeddings et mesurez la distance cosinus avec les vecteurs stockés. Reconstruisez intégralement l’index seulement si la dérive dépasse un seuil. La surveillance coûte peu et la reconstruction se déclenche au besoin."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"figure","page":220,"id":"220-03","width":800,"height":533,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["(es Cis the right answer — Embedding Version Registry + Hot Swap","system","This is the only solution that handles the real problem: your embedding model changed.","Design Labs","tracks which model produced which vector and routes queries to the correct index version during migration.","Two indexes in parallel during transition = zero downtime, zero mixed-space comparisons.","{B Embedding Version Registry","Moda Veron","sate","90%","@ owt by model vnon","onary","10%","@ Zero downtie migration","Rex","ry","‘Gradual Migration","Zero Downtine","Safe Validation","Correctness","‘he new index vate","Nobigbeng No hour","To nares rn perl","Compare rests, monitor","Coin ry adh","ul","WHY A,B, AND D FAIL","Scheduled Ful Rebuild","Index an up ith vectors rom","Approximate StalneesDstacton","‘The Real Problem","‘aystin the model changed","ies ig bong and uses","Scant compare em"],"fr":["(es Cis la bonne réponse — Intégration du Registre de version + Échange à chaud","système","C’est la seule solution qui gère le vrai problème : votre modèle d’intégration a changé.","Design Labs","trace quel modèle a produit quel vecteur et route les requêtes vers la version d'index correcte pendant la migration.","Deux indices en parallèle pendant la transition — zéro temps d'arrêt, zéro comparaisons d'espaces mixtes.","B Incorporation du Registre des Versions","Moda Veron","sate","90%","owt par modèle vnon","onary","10%","Zéro migration descendante","Rex","ry","«Migration graduelle","Zero Downtine","Validation sécurisée","Exactitude","«le nouvel index vate","Nobigbeng Aucune heure","Aux nares rn perl","Comparer les appuis, moniteur","Monnaies adh","ul","POURQUOI A, B ET D FAIL","Rénovation programmée Ful","Indexer un ième vecteur rom","Approximatif StalneesDstacton","« Le vrai problème","«aystin le modèle changé","ies ig bong et usages","Scant comparer em"]}},{"kind":"p","page":220,"text":{"en":"C is the right answer — Embedding Version Registry + Hot Swap","fr":"C est la bonne réponse — Registre des versions du modèle d’embedding et bascule à chaud"}},{"kind":"p","page":220,"text":{"en":"This is the only solution that handles the real problem: your embedding model changed. When you fine-tune or upgrade your model, Option A and B still serve a mixed index — some vectors from model v1, some from v2. Your cosine similarity math breaks because you're comparing vectors from different embedding spaces. They're not comparable. C is the only option that tracks which model produced which vector and routes queries to the correct index version during migration. Two indexes in parallel during transition = zero downtime, zero mixed-space comparisons.","fr":"Cette solution traite le changement de modèle d’embedding. Après un affinage ou une mise à niveau, les options A et B peuvent servir un index qui mêle des vecteurs du modèle v1 et du modèle v2. La similarité cosinus ne permet pas de comparer des vecteurs issus d’espaces différents. Seule l’option C garde la trace du modèle qui a produit chaque vecteur et route les requêtes vers la bonne version de l’index durant la migration. Deux index en parallèle permettent une transition sans interruption et sans comparaison entre espaces incompatibles."}},{"kind":"p","page":220,"text":{"en":"The production win: you can migrate 10% of traffic to the new index, validate retrieval quality, then cut over. No big bang. No 4-hour Sunday rebuild blocking your team.","fr":"En production, transférez 10 % du trafic vers le nouvel index, évaluez la qualité de la recherche, puis basculez le reste. Vous évitez une bascule brutale et une reconstruction de quatre heures le dimanche qui mobilise l’équipe."}}],[{"kind":"p","page":221,"text":{"en":"B is the senior engineer trap","fr":"B est le piège des ingénieurs expérimentés"}},{"kind":"p","page":221,"text":{"en":"Incremental upserts sound smart — you're only re-embedding what changed. But here's the silent killer: model drift. You update your embedding model every 6 weeks. Now your index has vectors from 4 different model versions. Chunk A was embedded with text-embedding-ada-002. Chunk B with your fine-tuned v2. Nearest neighbor search across a mixed-space index returns garbage — not because the data is stale, but because the geometry is inconsistent. B handles data drift. It doesn't handle model drift. At 6-week update cycles, model drift is your actual problem.","fr":"Les upserts incrémentaux paraissent efficaces : vous ne recalculez que les embeddings des fragments qui ont changé. Le problème discret vient de la dérive du modèle. Vous le mettez à jour toutes les six semaines et votre index finit par réunir les vecteurs de quatre versions différentes. Le fragment A a été encodé par text-embedding-ada-002, le fragment B par votre v2 affinée. La recherche des plus proches voisins devient peu fiable car elle compare des espaces vectoriels incompatibles. B gère la dérive des données. À un rythme de mise à jour de six semaines, c’est la dérive du modèle qui pose problème."}}],[{"kind":"p","page":221,"text":{"en":"A is brute-force ops debt","fr":"A crée une dette d’exploitation par reconstruction systématique"}},{"kind":"p","page":221,"text":{"en":"$800 every Sunday whether you need it or not. At 6-week model updates, most rebuilds are wasted spend on data that hasn't meaningfully changed. It works. It's just expensive and blunt. Fine for a startup at 1M chunks. Painful at 50M.","fr":"Vous dépensez 800 $ tous les dimanches, indépendamment du besoin. Avec un changement de modèle toutes les six semaines, la plupart des reconstructions portent sur des données qui ont peu évolué. Cette méthode fonctionne, au prix d’un traitement systématique et coûteux. Acceptable à un million de fragments, elle devient lourde à 50 millions."}}],[{"kind":"p","page":221,"text":{"en":"D is monitoring, not a fix","fr":"D détecte la dérive"}},{"kind":"p","page":221,"text":{"en":"Staleness detection is genuinely useful — but as a signal, not a strategy. The 1% sample tells you that you have drift, not which vectors are affected or why. You still need a rebuild strategy. D is a trigger, not an architecture. Combine it with C for a complete system.","fr":"La détection de l’obsolescence constitue un signal pertinent. L’échantillon de 1 % révèle une dérive sans montrer quels vecteurs sont concernés ni pourquoi. Il faut toujours définir une stratégie de reconstruction. Combinez ce déclencheur avec C pour couvrir la détection et la migration."}}]]},{"day":55,"title":{"en":"Parallel Agents with Shared State","fr":"Exécuter des agents en parallèle avec un état partagé"},"pages":[222,225],"topic":"ai","correct":"A","scenario":[{"kind":"figure","page":222,"id":"222-02","width":800,"height":421,"alt":{"en":"Day 55 featured","fr":"Illustration de la question du jour 55"},"transcript":{"en":["system Design Labs","Your pipeline breaks on the fir:","real workload.","_Dynaie Spawn","ak","respond","User",">! | [11] Analysis Agent |\" ,","‘Shared","Query","Orchestrator","Context","Synthesizer","‘Agent","Final","(Router)","we)","Centralized Orchestrator — one controller agent","Decentralized Peer Handoff — each agent","dispatches tasks, collects results, manages","decides who gets the task next. No central","shared state. Agents are dumb wor!","controller. Agents communicate directly.","‘Shared Message Queue + Blackboard — all","Hierarchical Nesting — orchestrator spawns","agents read/;","toa shared blackboard.","ssub-orchestrators. Each sub-tree is self-","Coordination happens through state, not calls.","coordinating. Recursive decomposition of the problem."],"fr":["système Design Labs","Votre pipeline se brise sur le sapin :","réelle charge de travail.","_Dynaie Spawn","ak","répondre","Utilisateur",">! — [11] Agent d'analyse — \" ,","«Partagé","Requête","Orchestrator","Contexte","Synthétiseur","«Agent","Finale","(Router)","nous)","Centralized Orchestrator — un agent contrôleur","Peer Handoff décentralisé – chaque agent","répartit les tâches, collecte les résultats, gère","décide qui aura la tâche suivante. No central","Les agents sont idiots.","Les agents communiquent directement.","« File d’attente de messages partagés + tableau noir — tous","Hiérarchique Nesting — orchestrateur frayers","agents lus/;","tableau noir partagé.","Chaque sous-arbre est auto-orchestral.","La coordination se fait par l’État, pas par les appels.","la décomposition récursive du problème."]}},{"kind":"p","page":222,"text":{"en":"You built an agent. It works.","fr":"Vous avez construit un agent qui fonctionne."}},{"kind":"p","page":222,"text":{"en":"Now you need 5 of them running in parallel, sharing state, and handing off work to each other.","fr":"Il vous en faut maintenant cinq. Ils doivent s’exécuter en parallèle, partager un état et se transmettre des tâches."}},{"kind":"p","page":222,"text":{"en":"Your pipeline breaks on the first real workload.","fr":"Votre pipeline s’effondre dès sa première charge réelle."}},{"kind":"p","page":222,"text":{"en":"Here's the setup:","fr":"Voici la configuration."}},{"kind":"p","page":222,"text":{"en":"You're building a research agent system. A user asks a complex question. You need to:","fr":"Vous concevez un système d’agents de recherche. Quand un utilisateur pose une question complexe, plusieurs étapes sont nécessaires."}},{"kind":"p","page":222,"text":{"en":"• Fan out to 3 specialized sub-agents simultaneously","fr":"• Répartir le travail entre trois sous-agents spécialisés qui s’exécutent simultanément."}},{"kind":"p","page":222,"text":{"en":"• One agent might spawn 2 more based on what it finds","fr":"• Permettre à un agent d’en lancer deux autres selon ses découvertes."}},{"kind":"p","page":222,"text":{"en":"• They all write back to shared context","fr":"• Faire remonter leurs résultats dans le contexte partagé."}},{"kind":"p","page":222,"text":{"en":"• A final agent synthesizes everything","fr":"• Confier la synthèse à un dernier agent."}},{"kind":"p","page":222,"text":{"en":"Classic multi-agent orchestration. You have 4 options for how agents coordinate.","fr":"C’est un cas classique d’orchestration multi-agent. Quatre modes de coordination sont possibles."}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":222,"text":{"en":"Centralized Orchestrator — one controller agent dispatches tasks, collects results, manages shared state. Agents are dumb workers.","fr":"Orchestrateur centralisé. Un agent de contrôle répartit les tâches, rassemble les résultats et gère l’état partagé. Les autres agents exécutent simplement leurs tâches."}}]},{"letter":"B","blocks":[{"kind":"p","page":223,"text":{"en":"Decentralized Peer Handoff — each agent decides who gets the task next. No central controller. Agents communicate directly.","fr":"Transmission décentralisée entre pairs. Chaque agent choisit le prochain destinataire de la tâche. Les agents communiquent directement, sans contrôleur central."}}]},{"letter":"C","blocks":[{"kind":"p","page":223,"text":{"en":"Shared Message Queue + Blackboard — all agents read/write to a shared blackboard. Coordination happens through state, not calls.","fr":"File de messages et tableau noir partagés. Tous les agents lisent et écrivent dans un espace commun. Ils se coordonnent à travers l’état partagé."}}]},{"letter":"D","blocks":[{"kind":"p","page":223,"text":{"en":"Hierarchical Nesting — orchestrator spawns sub-orchestrators. Each sub-tree is self-coordinating. Recursive decomposition of the problem.","fr":"Orchestration hiérarchique. L’orchestrateur lance des sous-orchestrateurs. Chaque sous-arbre se coordonne indépendamment. Le problème est décomposé de façon récursive."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"figure","page":224,"id":"224-03","width":800,"height":533,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["CENTRALIZED ORCHESTRATOR","Gy system Design Labs","One controller agent owns the plan, dispatches tasks,","collects results, manages state.","SPECIALIZED SUB-AGENTS","task","(Controle Agent)","poy","ak","Use","Manage State","eal","ey Timeout","task","Falck","SINGLE SOURCE.","EASY To DEBUG","PRODUCTION","‘oF RUTH","CG","BY DESIGN","PROVEN","hese cen","KEY TAKEAWAY","Clear ownership","Centralize control, distribute execution. Th orhestatr pan, dispatches, collects, and syntheses.","Sub-agents stay simple, stateless and reliable","Easier debugging","‘Scales with confidence"],"fr":["ORCHESTRATEUR CENTRALISÉ","Gy system Design Labs","Un agent de contrôle possède le plan, répartit les tâches,","collecte des résultats, gère l'état.","SOUS-AGENTS SPÉCIALISÉS","tâche","(agent de contrôle)","poy","ak","Utilisation","Gérer l'état","eal","ey Timeout","tâche","Falck","Une seule source.","FACILE À DÉBUGER","PRODUCTION","«oF RUTH","CG","PAR DESIGN","PROVEN","hese cen","PRINCIPAUX PRIX","Propriété claire","Centralisez le contrôle, distribuez l'exécution, répartissez, collectez et synthétisez.","Les sous-agents restent simples, apatrides et fiables","Débogage plus facile","« Scales avec confiance"]}},{"kind":"p","page":224,"text":{"en":"Answer: A — Centralized Orchestrator","fr":"Réponse A — Orchestrateur centralisé"}},{"kind":"p","page":224,"text":{"en":"Here's the full breakdown — and where each pattern actually belongs:","fr":"Comment chaque approche s’applique au problème."}},{"kind":"p","page":224,"text":{"en":"Why A wins (Centralized Orchestrator):","fr":"Pourquoi A fonctionne, avec un orchestrateur centralisé"}},{"kind":"p","page":224,"text":{"en":"One agent owns the plan. It dispatches, collects, retries, and synthesizes. Every sub-agent is stateless and dumb on purpose — they receive a task, return a result, done.","fr":"Un seul agent est responsable du plan. Il distribue les tâches, collecte les résultats, gère les relances et fait la synthèse. Les sous-agents sont volontairement simples et sans état : chacun reçoit une tâche et renvoie un résultat."}},{"kind":"p","page":224,"text":{"en":"This isn't a limitation. It's a feature.","fr":"Cette simplicité est voulue."}},{"kind":"p","page":224,"text":{"en":"When something fails, you know exactly where to look: the orchestrator. It holds the retry logic, the timeout budgets, the fallback paths. Sub-agents can die and restart without corrupting global state because the orchestrator is the only one maintaining it.","fr":"En cas d’échec, vous savez où chercher. L’orchestrateur concentre la logique de relance, les budgets de délai et les solutions de secours. Les sous-agents peuvent s’arrêter et redémarrer sans corrompre l’état global, que seul l’orchestrateur met à jour."}},{"kind":"p","page":224,"text":{"en":"LangGraph, CrewAI, and every production-grade agentic framework defaults to this model for a reason. It's debuggable, observable, and deterministic. You can replay an orchestrator run from its state log. Try doing that with peer-to-peer handoffs.","fr":"LangGraph, CrewAI et les frameworks d’agents destinés à la production privilégient ce modèle. Il est observable, débogable et déterministe. Le journal d’état permet de rejouer une exécution complète de l’orchestrateur, ce qui est beaucoup plus délicat avec les transmissions entre pairs."}}],[{"kind":"p","page":225,"text":{"en":"Why B is the trap (Decentralized Peer Handoff):","fr":"Pourquoi B, la transmission décentralisée entre pairs, est un piège"}},{"kind":"p","page":225,"text":{"en":"This sounds elegant in theory. Agents self-organize, no bottleneck at the top.","fr":"Sur le papier, l’auto-organisation est élégante et supprime le goulet d’étranglement central."}},{"kind":"p","page":225,"text":{"en":"The problem: who resolves conflicts? If Agent A hands off to Agent B, and Agent B decides the task actually belongs to Agent C, which also hands it back to Agent A — you have a cycle with no circuit breaker.","fr":"Qui résout les conflits ? Si l’agent A transmet sa tâche à B, que B la redirige vers C et que C la remet à A, vous avez un cycle sans coupe-circuit."}},{"kind":"p","page":225,"text":{"en":"Peer handoff works in closed, well-defined pipelines (like a Git commit hook chain). It breaks the moment you have conditional routing, error recovery, or parallel fan-out.","fr":"La transmission entre pairs fonctionne avec des pipelines fermés et bien définis, comme une chaîne de hooks Git exécutés au moment d’un commit. Elle devient fragile dès qu’il faut gérer un routage conditionnel, une reprise sur erreur ou des tâches lancées en parallèle."}}],[{"kind":"p","page":225,"text":{"en":"Why C is partial credit (Shared Blackboard):","fr":"Pourquoi C, le tableau noir partagé, n’apporte qu’une partie de la solution"}},{"kind":"p","page":225,"text":{"en":"A shared blackboard is real and useful — but as a data layer, not a coordination mechanism.","fr":"Un tableau noir partagé constitue une couche de données utile. Le pilotage de l’exécution relève d’un autre mécanisme."}},{"kind":"p","page":225,"text":{"en":"Agents writing to and reading from shared state works for passing context. What it can't do cleanly is orchestrate who runs next, when, and with what inputs. You end up building an implicit orchestrator via polling — same thing, no visibility into it.","fr":"Lire et écrire dans un état commun permet d’échanger le contexte. Il est plus difficile d’y définir quel agent exécuter ensuite, quand et avec quelles entrées. Vous finissez par reconstruire un orchestrateur implicite à coups d’interrogations périodiques, en perdant la visibilité."}},{"kind":"p","page":225,"text":{"en":"Use a blackboard for state sharing. Use an orchestrator for task routing. They're complementary, not alternatives.","fr":"Confiez le partage de l’état au tableau noir et le routage des tâches à l’orchestrateur. Les deux rôles se complètent."}}],[{"kind":"p","page":225,"text":{"en":"Why D fits a specific problem (Hierarchical Nesting):","fr":"Pourquoi D, l’orchestration hiérarchique, convient à un cas précis"}},{"kind":"p","page":225,"text":{"en":"Hierarchical orchestration is the right model when the problem itself is hierarchically decomposable — like a pipeline where \"summarize AI papers\" fans out to 10 sub-tasks, each of which fans out further.","fr":"Une hiérarchie convient aux problèmes qui se décomposent naturellement en sous-problèmes. Par exemple, un pipeline de synthèse d’articles de recherche en IA peut lancer dix tâches, elles-mêmes décomposées en tâches plus petites."}},{"kind":"p","page":225,"text":{"en":"The catch: recursion adds latency and debugging complexity at every layer. If your problem doesn't naturally decompose into clean sub-trees, you're adding indirection for no gain. Default to flat centralized orchestration first. Reach for hierarchical only when the problem demands it.","fr":"La récursion augmente la latence et complique le débogage à chaque niveau. Si le problème se prête mal à une décomposition en sous-arbres, cette indirection n’apporte aucun gain. Commencez par une orchestration centralisée à un seul niveau et ajoutez une hiérarchie quand le problème l’exige."}}]]},{"day":56,"title":{"en":"Tracking Long-Running Async Jobs","fr":"Suivre les tâches asynchrones de longue durée"},"pages":[226,229],"topic":"reliability","correct":"A","scenario":[{"kind":"figure","page":226,"id":"226-02","width":800,"height":420,"alt":{"en":"Day 56 featured","fr":"Illustration de la question du jour 56"},"transcript":{"en":["tom Design Lab:","You’re processing a video upload.","The job takes 2-8 minutes. Millions of users.","retry /requeue","upload","store","publish","consume","update","video","‘ie","7b","a]","‘Mobile","Upload","Object","Job","Job","Client","Service","Storage","Queue","Worker","Metadata","Polling endpoint — client hits","Webhook — job fires a POST","Jiobs/:id/status every 5s until done","to-client’s callback URL on completion","SSE / WebSocket — server pushes","‘Synchronous wait — keep the HTTP","progress updates in real time","connection open until the job finishes"],"fr":["tom Design Lab :","Vous traitez un téléchargement vidéo.","Le travail prend 2-8 minutes. Des millions d'utilisateurs.","retry /requeue","upload","magasin","publier","consommer","mise à jour","vidéo","«ie","7b","a]","«Mobile","Télécharger","Objet","Emploi","Emploi","Client","Service","Stockage","File d'attente","Travailleur","Métadonnées","Sondage endpoint — hits client","Webhook : une tâche déclenche un POST","Jiobs/:id/status tous les 5s jusqu'à ce que fait","URL de rappel du client à la fin","SSE / WebSocket — serveur pousse","‘Attente synchrone — garder le HTTP","progress updates en temps réel","connexion ouverte jusqu'à la fin du travail"]}},{"kind":"p","page":226,"text":{"en":"Your background job ran for 4 minutes and nobody knows if it finished.","fr":"Votre tâche d’arrière-plan a tourné pendant quatre minutes et personne ne sait si elle est terminée."}},{"kind":"p","page":226,"text":{"en":"That's not a job queue problem. That's a missing design problem.","fr":"Le problème vient de la conception du suivi de la tâche."}},{"kind":"p","page":226,"text":{"en":"Long-running jobs break every assumption you built for synchronous APIs. Your load balancer times out after 30s. Your mobile client doesn't know whether to retry. Your retry logic re-runs a job that already half-completed.","fr":"Une tâche longue met en défaut les hypothèses d’une API synchrone. Le répartiteur de charge coupe la connexion après 30 s. Le client mobile ignore s’il doit réessayer. En cas de relance, votre code peut redémarrer un traitement déjà exécuté à moitié."}},{"kind":"p","page":226,"text":{"en":"Here's the real scenario:","fr":"Voici le cas concret."}},{"kind":"p","page":226,"text":{"en":"You're processing a video upload. The job takes 2–8 minutes. Millions of users.","fr":"Vous traitez une vidéo téléversée. La tâche prend de deux à huit minutes et le service compte des millions d’utilisateurs."}},{"kind":"p","page":226,"text":{"en":"What do you expose to the client?","fr":"Quelle interface exposez-vous au client ?"}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":226,"text":{"en":"Polling endpoint — client hits /jobs/:id/status every 5s until done","fr":"Endpoint interrogé périodiquement. Le client appelle /jobs/:id/status toutes les 5 s jusqu’à la fin."}}]},{"letter":"B","blocks":[{"kind":"p","page":226,"text":{"en":"Webhook — job fires a POST to client's callback URL on completion","fr":"Webhook. À la fin de la tâche, le serveur envoie un POST à l’URL de rappel du client."}}]},{"letter":"C","blocks":[{"kind":"p","page":226,"text":{"en":"SSE / WebSocket — server pushes progress updates in real time","fr":"SSE ou WebSocket. Le serveur pousse les mises à jour de progression en temps réel."}}]},{"letter":"D","blocks":[{"kind":"p","page":226,"text":{"en":"Synchronous wait — keep the HTTP connection open until the job finishes","fr":"Attente synchrone. Gardez la connexion HTTP ouverte jusqu’à la fin de la tâche."}}]}],"afterChoices":[{"kind":"p","page":226,"text":{"en":"One scales to millions without coupling your infrastructure to client uptime.","fr":"Une option passe à l’échelle de millions d’utilisateurs sans faire dépendre votre infrastructure de la disponibilité du client."}},{"kind":"p","page":227,"text":{"en":"The others have hard production failure modes most teams don't discover until 3 AM.","fr":"Les autres peuvent connaître de graves défaillances en production, que les équipes découvrent souvent à trois heures du matin."}},{"kind":"p","page":227,"text":{"en":"The deeper problem isn't transport — it's these 4 things nobody gets right the first time:","fr":"Au-delà du transport, quatre points de conception passent souvent inaperçus à la première implémentation."}},{"kind":"p","page":227,"text":{"en":"→ Idempotency. Every job must be safe to re-run. If your retry logic can double-charge, double-send, or double-process — you don't have retries, you have bugs waiting.","fr":"→ Idempotence. Une tâche doit pouvoir être relancée sans risque. Une relance qui peut facturer, envoyer ou traiter deux fois une même opération introduit un bug."}},{"kind":"p","page":227,"text":{"en":"→ Progress granularity. \"0% → 100%\" is useless for a 6-minute job. You need intermediate states: queued, processing, transcoding, uploading, complete. Clients need something to show users.","fr":"→ Granularité de la progression. Passer directement de 0 % à 100 % n’informe pas les utilisateurs pendant une tâche de six minutes. Donnez au client des états intermédiaires à afficher, par exemple en file, en cours de traitement, en transcodage, en téléversement et terminé."}},{"kind":"p","page":227,"text":{"en":"→ Timeout vs failure. A job that stops responding isn't the same as a job that failed. Dead workers, OOM kills, spot instance evictions — your queue needs a heartbeat or a visibility timeout, not just a try/catch.","fr":"→ Expiration et échec. Une tâche silencieuse et une tâche en échec sont deux états distincts. Entre les workers arrêtés, les processus tués par manque de mémoire et les instances Spot interrompues, la file a besoin d’un signal de vie ou d’un délai d’invisibilité. Un bloc try/catch ne couvre pas ces cas."}},{"kind":"p","page":227,"text":{"en":"→ Deduplication. The client will retry. Your queue will redeliver. You need a dedup key scoped to the original request — not the job run.","fr":"→ Déduplication. Le client réessaiera et la file remettra certains messages. Associez votre clé de déduplication à la requête d’origine pour la réutiliser entre plusieurs exécutions."}}],"answerIntro":[{"kind":"p","page":226,"text":{"en":"One scales to millions without coupling your infrastructure to client uptime.","fr":"Une option passe à l’échelle de millions d’utilisateurs sans faire dépendre votre infrastructure de la disponibilité du client."}},{"kind":"p","page":227,"text":{"en":"The others have hard production failure modes most teams don't discover until 3 AM.","fr":"Les autres peuvent connaître de graves défaillances en production, que les équipes découvrent souvent à trois heures du matin."}},{"kind":"p","page":227,"text":{"en":"The deeper problem isn't transport — it's these 4 things nobody gets right the first time:","fr":"Au-delà du transport, quatre points de conception passent souvent inaperçus à la première implémentation."}},{"kind":"p","page":227,"text":{"en":"→ Idempotency. Every job must be safe to re-run. If your retry logic can double-charge, double-send, or double-process — you don't have retries, you have bugs waiting.","fr":"→ Idempotence. Une tâche doit pouvoir être relancée sans risque. Une relance qui peut facturer, envoyer ou traiter deux fois une même opération introduit un bug."}},{"kind":"p","page":227,"text":{"en":"→ Progress granularity. \"0% → 100%\" is useless for a 6-minute job. You need intermediate states: queued, processing, transcoding, uploading, complete. Clients need something to show users.","fr":"→ Granularité de la progression. Passer directement de 0 % à 100 % n’informe pas les utilisateurs pendant une tâche de six minutes. Donnez au client des états intermédiaires à afficher, par exemple en file, en cours de traitement, en transcodage, en téléversement et terminé."}},{"kind":"p","page":227,"text":{"en":"→ Timeout vs failure. A job that stops responding isn't the same as a job that failed. Dead workers, OOM kills, spot instance evictions — your queue needs a heartbeat or a visibility timeout, not just a try/catch.","fr":"→ Expiration et échec. Une tâche silencieuse et une tâche en échec sont deux états distincts. Entre les workers arrêtés, les processus tués par manque de mémoire et les instances Spot interrompues, la file a besoin d’un signal de vie ou d’un délai d’invisibilité. Un bloc try/catch ne couvre pas ces cas."}},{"kind":"p","page":227,"text":{"en":"→ Deduplication. The client will retry. Your queue will redeliver. You need a dedup key scoped to the original request — not the job run.","fr":"→ Déduplication. Le client réessaiera et la file remettra certains messages. Associez votre clé de déduplication à la requête d’origine pour la réutiliser entre plusieurs exécutions."}}],"explanations":[[{"kind":"figure","page":228,"id":"228-03","width":800,"height":533,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["‘System Design Labs","— CORRECT FOR MOST CASES","A)","Update","‘Status","@ why Potting wins","1.Upload","3 =@","Client-controlled, stateless, scales","Video","File","Job","independently. The server doesn't","care if the client disconnects,","Mobile","Upload","retries, or crashes — the job runs","Service","Object","Worker","Client","Storage","Fleet","and the status endpoint just","answers queries.","5. Poll Status","5s polling intervals on a job that","takes 2-8 minutes i trivially","Every ~55","cheap.","Status","Job","Linkedin, YouTube, and $3","Metadata","DB","‘multipant uploads all use poling","for rasyne job status.","THE KEY RULES.","Stable & Idempotent","Stateless","Job IDs","Status Endpoi","Make job IDs stable and","Set a TTL on job records so","Use exponential backoff","‘The status endpoint should be","Idempotent so retries return","you don't accumulate state","instead of ied intervals","fast, cacheable, and read-only","forever.","toreduce lad.","the same job."],"fr":["«System Design Labs","CORRECTE POUR LA PLUPART DES CAS","A)","Mise à jour","«État","Pourquoi le Potting gagne","1.Téléchargement","3 =@","Contrôlé par le client, sans état, balances","Vidéo","Fichier","Emploi","indépendant. Le serveur ne","Si le client se déconnecte,","Mobile","Télécharger","retrys, or crashs — le travail tourne","Service","Objet","Travailleur","Client","Stockage","Flotte","et le endpoint d'état juste","répond aux requêtes.","5. État du scrutin","Intervalles de sondage sur un travail qui","prend 2-8 minutes je trivially","Tous les — 55","bon marché.","Statut","Emploi","Linkedin, YouTube et 3 $","Métadonnées","DB","«multipant uploads tous utiliser poling","pour le statut d'emploi rasyne.","LES R — GLES CLÉS.","Stable & Idempotent","apatrides","Identifiants d'emploi","Statut Endpoi","Rendre les ID d'emploi stables et","Définir un TTL sur les enregistrements de travail de manière","Utiliser le backoff exponentiel","« L’état final doit être","Idempotent donc retrys retour","vous n'accumulez pas d'état","Au lieu d'intervalles","rapide, cacheable et en lecture seule","Pour toujours.","Toreduce, mon garçon.","le même travail."]}},{"kind":"p","page":228,"text":{"en":"A) Polling — Correct for most cases","fr":"A) Interrogation périodique — Adaptée à la plupart des cas"}},{"kind":"p","page":228,"text":{"en":"Client-controlled, stateless, scales independently. The server doesn't care if the client disconnects, retries, or crashes — the job runs and the status endpoint just answers queries. 5s polling intervals on a job that takes 2–8 minutes is trivially cheap. The key rules: make job IDs stable and idempotent, set a TTL on job records so you don't accumulate state forever, and use exponential backoff not fixed intervals. LinkedIn, YouTube, and S3 multipart uploads all use polling for async job status.","fr":"Le client pilote les appels. L’endpoint est sans état et peut monter en charge indépendamment. Le serveur continue à traiter la tâche si le client se déconnecte, réessaie ou plante. L’endpoint d’état se contente de répondre aux requêtes. Pour une tâche de deux à huit minutes, une interrogation toutes les cinq secondes coûte peu. Utilisez des identifiants de tâche stables et idempotents, un TTL sur les enregistrements pour éviter une accumulation indéfinie, et des délais de relance à croissance exponentielle. LinkedIn, YouTube et les téléversements multiparties S3 utilisent des interrogations périodiques pour suivre l’état des tâches asynchrones."}}],[{"kind":"p","page":228,"text":{"en":"B) Webhook — Right idea, wrong default","fr":"B) Webhook — Pertinent dans certains cas"}},{"kind":"p","page":228,"text":{"en":"Webhooks are great for server-to-server flows where the receiver has a stable HTTPS endpoint. They fall apart for mobile clients (no public URL), in environments with NAT/firewall, and when the receiver is down at delivery time. You'd need a retry queue, delivery guarantees, and signature verification just to make it reliable. Webhooks work well as a supplementary delivery mechanism for platform integrations — not as the primary client notification path for end users.","fr":"Les webhooks sont adaptés aux échanges de serveur à serveur quand le destinataire dispose d’un endpoint HTTPS stable. Ils deviennent fragiles pour des clients mobiles sans URL publique, derrière un NAT ou un pare-feu, ou quand le destinataire est indisponible au moment de l’envoi. Pour fiabiliser la livraison, il faut prévoir une file de relance, des garanties de livraison et la vérification des signatures. Gardez les webhooks comme mécanisme complémentaire pour les intégrations entre plateformes."}}],[{"kind":"p","page":229,"text":{"en":"C) SSE / WebSocket — Expensive for this use case","fr":"C) SSE ou WebSocket — Coûteux pour cet usage"}},{"kind":"p","page":229,"text":{"en":"Real-time push is fantastic for chat, live dashboards, and collaborative editing. For a job that takes 2–8 minutes and is triggered once? You're holding an open connection, burning a file descriptor, and adding connection-management complexity for maybe 3 meaningful state changes. SSE makes sense when you genuinely need sub-second updates or continuous streaming. For async job progress, polling is cheaper and simpler.","fr":"Le push en temps réel est excellent pour la messagerie, les tableaux de bord en direct et l’édition collaborative. Pour une tâche ponctuelle de deux à huit minutes, vous maintenez une connexion ouverte, utilisez un descripteur de fichier et compliquez la gestion des connexions pour peut-être trois changements d’état utiles. SSE est pertinent si vous avez réellement besoin de mises à jour à moins d’une seconde ou d’un flux continu. Pour suivre l’avancement d’une tâche asynchrone, l’interrogation périodique est plus simple et moins chère."}}],[{"kind":"p","page":229,"text":{"en":"D) Synchronous wait — Production antipattern","fr":"D) Attente synchrone — À éviter en production"}},{"kind":"p","page":229,"text":{"en":"Keeping the HTTP connection open for 2–8 minutes kills your load balancer (most timeout at 30– 60s), ties up a server thread or process, and gives the client no recovery path if the connection drops mid-job. This is how systems get \"stuck\" — jobs complete but the client never hears about it because the connection dropped at minute 3. Never block on long-running work. Always return immediately with a job ID.","fr":"Maintenir une connexion HTTP ouverte pendant deux à huit minutes met le répartiteur en difficulté, car la plupart expirent au bout de 30 à 60 s. Cela mobilise aussi un thread ou un processus sur le serveur. Si la connexion tombe au bout de trois minutes, le client reste bloqué sans moyen de savoir si la tâche s’est achevée. Pour les tâches longues, renvoyez immédiatement un identifiant de tâche et poursuivez le traitement en arrière-plan."}}]]},{"day":57,"title":{"en":"Consistency for Payment-Confirmation Reads","fr":"Garantir la cohérence à la lecture d’une confirmation de paiement"},"pages":[230,233],"topic":"data","correct":"C","scenario":[{"kind":"figure","page":230,"id":"230-02","width":800,"height":420,"alt":{"en":"Day 57 featured","fr":"Illustration de la question du jour 57"},"transcript":{"en":["‘System Design Labs","Replica returned stale data 200ms after a write.","How do you ensure reads-after-write consistency?","ead","Replication","Read","Switch to synchronous replication — primary","Use semi-syne replication — primary waits for","waits for at least one replica to confirm before","but not flush to disk.","exactly one replica to write to its relay log,","[a","ack'ing the writ.","IE","Route payment confirmation reads back","‘Add a short sleep (500ms) after every","to the primary, keep everything else","payment write before reading — wait","on replicas.","out the lag."],"fr":["«System Design Labs","Réplique retourné données périmées 200ms après une écriture.","Comment assurer la cohérence des lectures après écriture ?","ead","Réplication","Lire","Passer à la réplication synchrone — primaire","Utiliser la réplication semi-syne - attente primaire","attend au moins une réplique pour confirmer avant","mais pas sur le disque.","exactement une réplique à écrire dans son journal de relais,","[a","J'ai eu l'ordre.","IE","Confirmation du paiement de l'itinéraire","Ajoutez un court sommeil (500ms) après chaque","à la primaire, garder tout le reste","paiement écrire avant la lecture — attendre","sur les répliques.","Hors du lag."]}},{"kind":"p","page":230,"text":{"en":"Your write traffic just hit 50k writes/sec. Reads are 10x that.","fr":"Votre trafic vient d’atteindre 50 000 écritures par seconde. Le débit de lecture est dix fois plus élevé."}},{"kind":"p","page":230,"text":{"en":"You split your Postgres into one primary + two replicas. Reads go to replicas. Now you're shipping a payment confirmation flow — and a replica returned stale data 200ms after a write. The user saw \"payment pending\" when it already succeeded.","fr":"Votre cluster PostgreSQL comprend un primaire et deux répliques qui servent les lectures. Vous lancez un parcours de confirmation de paiement. Une réplique renvoie une donnée périmée 200 ms après une écriture et l’utilisateur voit « Paiement en attente » alors que le paiement a déjà abouti."}},{"kind":"p","page":230,"text":{"en":"Here's the setup:","fr":"Voici la configuration."}},{"kind":"p","page":230,"text":{"en":"→ Primary handles all writes","fr":"→ Le primaire traite toutes les écritures."}},{"kind":"p","page":230,"text":{"en":"→ Two read replicas, async replication","fr":"→ Deux répliques de lecture sont alimentées par réplication asynchrone."}},{"kind":"p","page":230,"text":{"en":"→ Payment confirmation reads from a replica","fr":"→ La confirmation du paiement lit sur une réplique."}},{"kind":"p","page":230,"text":{"en":"→ Replication lag: 80–300ms under load","fr":"→ Le retard de réplication varie de 80 à 300 ms sous charge."}},{"kind":"p","page":230,"text":{"en":"You need reads-after-write consistency on payment flows without tanking write throughput. What do you do?","fr":"Vous devez garantir la cohérence des lectures après écriture sur les parcours de paiement, tout en préservant le débit d’écriture. Que faites-vous ?"}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":230,"text":{"en":"Switch to synchronous replication — primary waits for at least one replica to confirm before ack'ing the write.","fr":"Passez à la réplication synchrone. Le primaire attend la confirmation d’au moins une réplique avant d’accuser réception de l’écriture."}}]},{"letter":"B","blocks":[{"kind":"p","page":231,"text":{"en":"Use semi-sync replication — primary waits for exactly one replica to write to its relay log, but not flush to disk.","fr":"Utilisez la réplication semi-synchrone. Le primaire attend qu’une seule réplique écrive dans son journal relais, sans attendre l’écriture forcée sur le disque."}}]},{"letter":"C","blocks":[{"kind":"p","page":231,"text":{"en":"Route payment confirmation reads back to the primary, keep everything else on replicas.","fr":"Redirigez les lectures de confirmation de paiement vers le primaire et gardez les autres lectures sur les répliques."}}]},{"letter":"D","blocks":[{"kind":"p","page":231,"text":{"en":"Add a short sleep (500ms) after every payment write before reading — wait out the lag.","fr":"Attendez 500 ms après chaque écriture de paiement avant de lire, pour laisser le temps à la réplication de rattraper son retard."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"figure","page":232,"id":"232-03","width":800,"height":533,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["‘System Design Labs","Why [€ wins (primary reads f","r critical paths):","Payment confirmations are a tiny slice of your read traffic.","You're not routing ALL reads to primary — just the reads where stale data causes visible user harm.","Read","Write","Read","Replication","Services","Payment","Service","Read","Service","Read (Consistency-sensiive)","‘Always read from primary","(Catial Path)","This pattern is called read-your-writes consistency. Stripe, Shopity, every serious fintech does this,","You add a flag or middleware: “if this is a consistency-sensitive flow, read from primary.”","Everything else keeps hitting replicas.","Minimal impact","‘Surgical precision","Maximum consistency","No new","lure modes","where it matters","Payment confiemations are","Only critical flows read","No topology change.","maybe 0.1% of your reads.","from primary.","No new components.","Users never ee “payment","Primary rad trafic","Everything else","pending” after successful","increases slightly","stays on replicas,","No added complesity","payment again.","and battle-tested.","Read from pr","ary for consi","rency-sensitive flows. Fast, safe"],"fr":["«System Design Labs","Pourquoi [ — gagne (le primaire lit f)","r chemins critiques) :","Les confirmations de paiement sont une petite tranche de votre trafic de lecture.","Vous n'achetez pas TOUTES les lectures en lecture primaire - seulement les lectures où les données périmées causent des dommages visibles aux utilisateurs.","Lire","Ecrire","Lire","Réplication","Services","Paiement","Service","Lire","Service","Lire (Sensibilité à la cohérence)","Toujours lire depuis le primaire","(chemin de croix)","Ce modèle s'appelle la cohérence de lecture-votre-écriture. Stripe, Shopity, chaque fintech sérieuse fait ceci,","Vous ajoutez un drapeau ou un middleware : « s’il s’agit d’un flux sensible à la cohérence, lisez depuis le primaire. »","Tout le reste ne cesse de frapper les répliques.","Impact minimal","«Précision chirurgicale","Consistance maximale","Pas de nouveauté","Modes de leurre","Là où ça compte","Les confiemations de paiement sont","Seuls les flux critiques sont lus","Pas de changement de topologie.","Peut-être 0,1% de vos lectures.","de primaire.","Pas de nouveaux composants.","Les utilisateurs ne voient jamais de « paiement »","Primaire rad trafic","Tout le reste","En attente » après avoir réussi","augmente légèrement","Reste sur les répliques,","Aucune complétude ajoutée","paiement à nouveau.","et testé au combat.","Lire sur pr","ary pour consi","écoulements sensibles à la fréquence. Rapide, sûr"]}},{"kind":"p","page":232,"text":{"en":"Why C wins (primary reads for critical paths):","fr":"Pourquoi C fonctionne, avec des lectures sur le primaire pour les parcours critiques"}},{"kind":"p","page":232,"text":{"en":"Payment confirmations are a tiny slice of your read traffic. You're not routing ALL reads to primary — just the reads where stale data causes visible user harm.","fr":"Les confirmations de paiement ne représentent qu’une faible part des lectures. Seules les lectures où une donnée périmée aurait un effet visible pour l’utilisateur sont dirigées vers le primaire."}},{"kind":"p","page":232,"text":{"en":"This pattern is called read-your-writes consistency. Stripe, Shopify, every serious fintech does this. You add a flag or middleware: \"if this is a consistency-sensitive flow, read from primary.\" Everything else keeps hitting replicas.","fr":"C’est la garantie de lecture de ses propres écritures, ou read-your-writes. Stripe, Shopify et les fintechs établies l’utilisent. Un indicateur ou un middleware envoie vers le primaire les lectures des parcours sensibles à la cohérence. Les autres continuent d’aller aux répliques."}},{"kind":"p","page":232,"text":{"en":"Primary read traffic increases slightly — but a \"just confirmed payment\" flow is maybe 0.1% of your reads. Negligible. No topology change, no new failure modes, surgical precision.","fr":"Le trafic de lecture sur le primaire augmente légèrement. Les paiements tout juste confirmés représentent peut-être 0,1 % des lectures, ce qui rend ce surcroît négligeable. Le changement est local et conserve la même topologie et les mêmes modes de défaillance."}}],[{"kind":"p","page":233,"text":{"en":"Why A is tempting but the wrong trade (synchronous replication):","fr":"Pourquoi A, la réplication synchrone, est un mauvais compromis ici"}},{"kind":"p","page":233,"text":{"en":"Postgres synchronous_commit = on — primary waits for a replica to confirm before ack'ing the write. Zero lag. Reads always consistent.","fr":"Avec synchronous_commit = on dans PostgreSQL, le primaire attend la confirmation d’une réplique avant d’accuser réception de l’écriture. Le retard disparaît et les lectures restent cohérentes."}},{"kind":"p","page":233,"text":{"en":"The cost: every write now takes primary_write_time + network roundtrip to replica. 1–5ms normally. Under load with a flaky replica? Your write latency is hostage to your slowest replica.","fr":"Chaque écriture prend désormais primary_write_time plus le temps d’un aller-retour réseau vers la réplique, généralement 1 à 5 ms. Sous charge, si une réplique est instable, sa latence se répercute sur celle des écritures."}},{"kind":"p","page":233,"text":{"en":"If that sync replica goes down → you either halt writes or fall back to async and break your guarantee. That choice gets made at 3am under pressure.","fr":"Si la réplique synchrone tombe, vous devez suspendre les écritures ou basculer en asynchrone et abandonner la garantie. La décision risque de tomber à trois heures du matin, sous pression."}},{"kind":"p","page":233,"text":{"en":"Sync replication is a serious architectural commitment for the whole DB. Routing payment reads to primary solves the same problem, surgically.","fr":"La réplication synchrone engage l’architecture de toute la base. Diriger les lectures de paiement vers le primaire règle le problème sur le seul parcours concerné."}}],[{"kind":"p","page":233,"text":{"en":"Why B is the sneaky wrong answer (semi-sync replication):","fr":"Pourquoi B, la réplication semi-synchrone, paraît convaincante"}},{"kind":"p","page":233,"text":{"en":"Semi-sync (rpl_semi_sync in MySQL) — primary waits for one replica to write to its relay log. Sounds like a middle ground. It's not.","fr":"En mode semi-synchrone, avec rpl_semi_sync dans MySQL, le primaire attend qu’une réplique écrive dans son journal relais. Cela paraît être un compromis."}},{"kind":"p","page":233,"text":{"en":"The replica acknowledged receipt of the bytes — not that the data is applied and readable. The relay log is the incoming queue, not the applied state. You can still read stale data immediately after a write.","fr":"La réplique confirme la réception des octets. Les données doivent encore être appliquées pour pouvoir être lues. Le journal relais est une file d’attente des changements entrants. Une lecture juste après l’écriture peut toujours renvoyer une valeur périmée."}},{"kind":"p","page":233,"text":{"en":"Semi-sync protects you from data loss on primary failure. It does NOT protect you from replication lag on reads. Different problem entirely.","fr":"Le mode semi-synchrone protège contre la perte de données en cas de panne du primaire. Les lectures restent exposées au retard de réplication."}},{"kind":"p","page":233,"text":{"en":"Senior engineers conflate \"replica has the data\" with \"replica has applied the data.\" They're not the same thing.","fr":"Même les ingénieurs expérimentés peuvent confondre la réception des données par la réplique et leur application."}}],[{"kind":"p","page":233,"text":{"en":"Why D will destroy you at scale (sleep-based lag compensation):","fr":"Pourquoi D, la compensation du retard par une attente fixe, se dégrade à grande échelle"}},{"kind":"p","page":233,"text":{"en":"Sounds pragmatic. Works for about 2 weeks.","fr":"Cela paraît pragmatique et peut fonctionner pendant environ deux semaines."}},{"kind":"p","page":233,"text":{"en":"Replication lag isn't a fixed constant. It's 50ms now, 300ms during a write spike, 2s during a vacuum. Hardcode a sleep and you've built a system that's either too slow (sleep > lag) or still broken (lag > sleep).","fr":"Le retard varie : 50 ms maintenant, 300 ms pendant un pic d’écritures et 2 s lors d’un vacuum. Une attente codée en dur est soit trop longue quand elle dépasse le retard, soit inefficace quand le retard la dépasse."}},{"kind":"p","page":233,"text":{"en":"Every payment confirmation path is now artificially 500ms slower. And when the sleep isn't enough during a spike — you're back to the original bug, with worse latency.","fr":"Toutes les confirmations de paiement sont artificiellement ralenties de 500 ms. Lors d’un pic où l’attente ne suffit plus, le bug initial revient avec une latence aggravée."}},{"kind":"p","page":233,"text":{"en":"Sleep-based consistency is always a smell.","fr":"Fonder la cohérence sur une attente fixe signale un défaut de conception."}}]]},{"day":58,"title":{"en":"Observability for LLM Agent Pipelines","fr":"Observer les workflows d’agents LLM"},"pages":[234,237],"topic":"ai","correct":"A","scenario":[{"kind":"figure","page":234,"id":"234-02","width":800,"height":420,"alt":{"en":"Day 58 featured","fr":"Illustration de la question du jour 58"},"transcript":{"en":["It’s 2am. Your LLM agent is on fire and every log says HTTP 200.","What do you instrument first?","Nests","nt","Wed / Mobile","‘lent","50\"","‘Pt","Search","(son","Pest","‘Structured trace IDs through every LLM + tool call","LLM-as-judge eval pipeine running on a sample","‘span-level token accounting, latency per hop —","(of prod traffic — assertion-based checks,","LangSmith, Helicone, or Ariz as the backbone.","ragas metrics, catch quality regressions before users do.","Custom middleware that logs every prompt in/out,","Cost dashboards per model/agent/user","with hard budget alerts — stop the token bleed fist,","‘model latency tokens to your own store —","everything else can wait.","‘own your data, no vendor lock-in, query ithowever you want.","He)"],"fr":["Il est 2h du matin. Votre agent LLM est en feu et chaque journal dit HTTP 200.","Qu’est-ce que vous instrumentez en premier ?","Nids","nt","Wed / Mobile","«Lent","50\"","«Pt","Rechercher","(Fils","Pest","‘Identifiants de trace structurés à travers chaque appel d’outil LLM +","LLM-as-juge pipeine eval fonctionnant sur un échantillon","‘span-level token comptabilisation, latence par saut","(de trafic prod — contrôles basés sur des affirmations,","LangSmith, Helicone ou Ariz comme colonne vertébrale.","mesures ragas, capturez les régressions de qualité avant les utilisateurs.","middleware personnalisé qui enregistre chaque invite in / out,","Tableau de bord des coûts par modèle/agent/utilisateur","avec des alertes de budget dur - arrêter le poing de saignement de jeton,","« modélisez des jetons de latence à votre propre magasin »","Tout le reste peut attendre.","«Posséder vos données, pas de verrouillage du fournisseur, interroger quand vous voulez.","Il)"]}},{"kind":"p","page":234,"text":{"en":"It's 2am. Your LLM agent is on fire and every log says HTTP 200.","fr":"Il est deux heures du matin. Votre agent LLM est en panne et tous les journaux affichent HTTP 200."}},{"kind":"p","page":234,"text":{"en":"You shipped an AI-powered support agent 6 weeks ago. It calls tools, chains 4-5 prompts per request, hits vector search, calls back into your API. Users are complaining. Answers are wrong. Token bills are 3x what they were last week.","fr":"Vous avez mis en ligne un agent d’assistance IA il y a six semaines. Il appelle des outils, enchaîne quatre à cinq prompts par requête, utilise la recherche vectorielle et rappelle votre API. Les utilisateurs se plaignent de réponses incorrectes et le coût des tokens a triplé depuis la semaine dernière."}},{"kind":"p","page":234,"text":{"en":"You open your logs. Everything is green. You open your traces. You see one span called POST /chat that took 14 seconds. That's it. That's your entire visibility.","fr":"Dans les journaux, tout est au vert. Les traces se résument à un seul span POST /chat de 14 secondes. Vous ne voyez rien d’autre."}},{"kind":"p","page":234,"text":{"en":"Here's the setup:","fr":"Voici la configuration."}},{"kind":"p","page":234,"text":{"en":"NestJS API → OpenAI (GPT-4o + GPT-4o-mini) + Anthropic (Claude Sonnet fallback)","fr":"API NestJS → OpenAI (GPT-4o + GPT-4o-mini) + Anthropic (Claude Sonnet en secours)."}},{"kind":"p","page":234,"text":{"en":"~8,000 agent runs/day, each chains 3-7 LLM calls + 2-4 tool calls","fr":"Environ 8 000 exécutions d’agent par jour, chacune enchaînant trois à sept appels LLM et deux à quatre appels d’outils."}},{"kind":"p","page":234,"text":{"en":"Token spend jumped from $180/day to $540/day this week, no idea which flow caused it","fr":"Le coût des tokens a bondi de 180 $ à 540 $ par jour cette semaine. Vous ignorez quel parcours est en cause."}},{"kind":"p","page":234,"text":{"en":"Eval suite passes 94% in CI, prod users are hitting hallucinations you can't reproduce","fr":"Votre suite d’évaluation atteint 94 % de réussite en CI, mais les utilisateurs rencontrent en production des hallucinations que vous ne savez pas reproduire."}},{"kind":"p","page":234,"text":{"en":"On-call engineer literally cannot answer \"why is this run slow / expensive / wrong?\"","fr":"La personne d’astreinte ne peut pas expliquer pourquoi une exécution est lente, coûteuse ou incorrecte."}},{"kind":"p","page":234,"text":{"en":"You have one sprint to fix the visibility problem before the next incident. What do you instrument first?","fr":"Vous avez un sprint pour améliorer la visibilité avant le prochain incident. Qu’instrumentez-vous en premier ?"}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":235,"text":{"en":"Structured trace IDs through every LLM + tool call, span-level token accounting, latency per hop — LangSmith, Helicone, or Arize as the backbone.","fr":"Propager des identifiants de trace structurés à chaque appel LLM ou d’outil, compter les tokens par span et mesurer la latence de chaque étape. Appuyez-vous sur LangSmith, Helicone ou Arize."}}]},{"letter":"B","blocks":[{"kind":"p","page":235,"text":{"en":"LLM-as-judge eval pipeline running on a sample of prod traffic — assertion-based checks, ragas metrics, catch quality regressions before users do.","fr":"Utiliser un LLM comme juge sur un échantillon du trafic de production. Évaluez les résultats à l’aide d’assertions et de métriques Ragas pour repérer les régressions de qualité avant les utilisateurs."}}]},{"letter":"C","blocks":[{"kind":"p","page":235,"text":{"en":"Cost dashboards per model/agent/user with hard budget alerts — stop the token bleed first, everything else can wait.","fr":"Suivre les coûts par modèle, agent et utilisateur, avec des alertes à des seuils budgétaires stricts. Réduisez d’abord la consommation de tokens. Le reste peut attendre."}}]},{"letter":"D","blocks":[{"kind":"p","page":235,"text":{"en":"Custom middleware that logs every prompt in/out, model, latency, tokens to your own store — own your data, no vendor lock-in, query it however you want.","fr":"Construire un middleware qui consigne chaque prompt, sa réponse, le modèle, la latence et les tokens dans votre propre stockage. Vous gardez la maîtrise des données et de vos requêtes, sans dépendance à un fournisseur."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"figure","page":236,"id":"236-03","width":800,"height":533,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["System Design Labs","fp Why A wins:","Slow?","Expensive?","Wrong?","(7)","Which of the 7 LLM calls","Which model on which step","Which retrieval returned garbage","was slow.","burned the tokens,","that poisoned the next prompt.","None of those questions have answers without a trace. LLM traces aren't HTTP traces — you need","span-level attributes: model name, prompt tokens, completion tokens, cost, tool name, retrieval doc IDs,","and the actual prompt/response payload. That's what LangSmith, Helicone, Arize, and Langfuse give you out of the box.","Before: One 14s span, Zero answers.","Att",": The 14-second span opens into 7 sub-spans.","eat | $0002","2. Anne ra (GP)","are","200","You have ne idea what happened","inside that 14 seconds","8 wite","wi","traces, you can finally answer:","Slow?","Expensive?","Wrong?","Step 5 (Claude fallback) took 9s","Retrieval returned 0 chunks,","'$540/day spike is one user","(ue to rate limiting,","recursively caling the agent","peisoring the downstream prompt"],"fr":["System Design Labs","fp Pourquoi retenir A :","Doucement ?","Cher ?","Faux ?","(7)","Lequel des 7 appels LLM","Quel modèle à quelle étape","Quelle récupération a retourné des déchets","était lent.","Brûler les jetons,","qui empoisonnait la prochaine prompte.","Aucune de ces questions n'a de réponses sans trace. Les traces LLM ne sont pas des traces HTTP — vous avez besoin","span-level attributs: nom du modèle, jetons d'invite, jetons de complétion, coût, nom de l'outil, ID de doc de récupération,","C'est ce que LangSmith, Helicone, Arize et Langfuse vous donnent à faire.","Avant : Une durée de 14 s, zéro réponse.","Att",": La plage de 14 secondes s'ouvre sur 7 sous-échelles.","manger — 002 $","2. Anne ra (GP)","sont","200","Vous avez une idée de ce qui s'est passé","Dans ces 14 secondes","8 wite","w","traces, vous pouvez enfin répondre :","Doucement ?","Cher ?","Faux ?","Étape 5 (Claude fallback) a pris 9s","Retrieval retourné 0 chunks,","'$540/day spike est un utilisateur","(en raison de la limitation du taux,","caler récursivement l'agent","la recherche de l'invite en aval"]}},{"kind":"p","page":236,"text":{"en":"Why A wins:","fr":"Pourquoi A fonctionne"}},{"kind":"p","page":236,"text":{"en":"Every problem in the scenario is the same root cause — you can't see the shape of a single agent run.","fr":"Tous les problèmes du scénario ont une cause commune. Vous ne pouvez pas reconstituer le déroulement d’une exécution de l’agent."}},{"kind":"p","page":236,"text":{"en":"Slow? → Which of the 7 LLM calls was slow.","fr":"Exécution lente ? Identifiez lequel des sept appels LLM a pris du temps."}},{"kind":"p","page":236,"text":{"en":"Expensive? → Which model on which step burned the tokens.","fr":"Exécution coûteuse ? Identifiez le modèle et l’étape qui ont consommé les tokens."}},{"kind":"p","page":236,"text":{"en":"Wrong? → Which retrieval returned garbage that poisoned the next prompt.","fr":"Réponse incorrecte ? Identifiez la recherche qui a renvoyé des résultats inadéquats et faussé le prompt suivant."}},{"kind":"p","page":236,"text":{"en":"None of those questions have answers without a trace. And LLM traces aren't HTTP traces — you need span-level attributes: model name, prompt tokens, completion tokens, cost, tool name, retrieval doc IDs, and the actual prompt/response payload. That's what LangSmith, Helicone, Arize, and Langfuse give you out of the box.","fr":"Une trace est nécessaire pour répondre. Le traçage LLM demande des attributs supplémentaires pour chaque span : nom du modèle, tokens d’entrée et de sortie, coût, nom de l’outil, identifiants des documents récupérés et contenu des prompts et des réponses. LangSmith, Helicone, Arize et Langfuse proposent ces fonctions d’emblée."}},{"kind":"p","page":236,"text":{"en":"Once you have it: the 14-second span opens into 7 sub-spans. You see the one that took 9s was a Claude fallback triggered by a rate limit. The $540/day spike is one user hammering an agent that recursively calls itself. The hallucinations correlate with retrievals that returned 0 chunks.","fr":"Le span de 14 secondes se décompose alors en sept sous-spans. Celui qui a pris neuf secondes correspond à un appel de secours à Claude après une limitation du débit. Le pic à 540 $ par jour vient d’un utilisateur qui sollicite massivement un agent qui s’appelle lui-même. Les hallucinations coïncident avec les recherches qui ne renvoient aucun fragment."}}],[{"kind":"p","page":237,"text":{"en":"Why B is the senior engineer trap:","fr":"Pourquoi B est le piège des ingénieurs expérimentés"}},{"kind":"p","page":237,"text":{"en":"Evals answer a different question: is quality trending up or down over time? They're not a debugging tool. When prod is on fire, \"78% correctness on last 200 samples\" tells you nothing about the request that broke. Worse — evals without tracing are unfalsifiable. When the score drops, you have no way to drill into failing samples to see why. Evals are step 2. They ride on top of traces.","fr":"Les évaluations mesurent l’évolution de la qualité. Pendant un incident, « 78 % de réponses correctes sur les 200 derniers exemples » ne permet pas d’expliquer la requête qui a échoué. Sans traces, une baisse du score ne peut pas être vérifiée jusqu’à sa cause : il manque le détail des échantillons en échec. Mettez en place les évaluations en deuxième étape, en vous appuyant sur les traces."}}],[{"kind":"p","page":237,"text":{"en":"Why C treats the symptom:","fr":"Pourquoi C traite le symptôme"}},{"kind":"p","page":237,"text":{"en":"\"Spend is up 3x\" is the same info you already had from the bill. Aggregate cost without span-level attribution just tells you the room is on fire without telling you which wall. You can't build per-agent, per-user cost attribution without instrumenting spans first. Budget alerts: yes, ship them. As your primary investment: you're solving the CFO's problem, not the on-call engineer's.","fr":"Un tableau de bord qui signale que la dépense a triplé répète ce que dit déjà la facture. Un coût agrégé indique une anomalie sans localiser sa cause. Pour attribuer les coûts par agent ou par utilisateur, commencez par instrumenter les spans. Les alertes budgétaires sont utiles à la direction financière. La personne d’astreinte a d’abord besoin de savoir quelle étape est en cause."}}],[{"kind":"p","page":237,"text":{"en":"Why D isn't actually pragmatic:","fr":"Pourquoi D est moins pratique qu’il n’y paraît"}},{"kind":"p","page":237,"text":{"en":"\"Own your data, no vendor lock-in\" is the sentence that has cost more teams more months than almost any other. You'd need: schema for nested agent runs, trace tree visualizer, correlation IDs across async tool calls, sampling logic, retention, PII redaction, cost rollups. You just rebuilt Langfuse badly, in your spare time, while the incident is still open. Every serious LLM observability tool emits OpenTelemetry-compatible spans — switch vendors in a week if needed. Ship the vendor now, revisit self-hosting when you've earned that problem.","fr":"Garder ses données et éviter la dépendance à un fournisseur a déjà coûté des mois à de nombreuses équipes. Il vous faut un schéma pour les exécutions imbriquées, une visualisation des arbres de traces, des identifiants de corrélation pour les appels asynchrones, l’échantillonnage, la rétention, le masquage des données personnelles et l’agrégation des coûts. Vous finissez par reproduire imparfaitement Langfuse sur votre temps libre pendant que l’incident reste ouvert. Les outils établis d’observabilité LLM émettent des spans compatibles avec OpenTelemetry, ce qui permet de changer de fournisseur en une semaine si nécessaire. Déployez d’abord l’outil et revenez à l’auto-hébergement quand le besoin est avéré."}}]]},{"day":59,"title":{"en":"Designing Idempotency Keys for Payments","fr":"Concevoir des clés d’idempotence pour les paiements"},"pages":[238,242],"topic":"data","correct":"A","scenario":[{"kind":"figure","page":238,"id":"238-02","width":800,"height":420,"alt":{"en":"Day 59 featured","fr":"Illustration de la question du jour 59"},"transcript":{"en":["Your payment service charged a customer twice.","‘System Design Labs","Which","mpotency strategy do you go with?","POST /payments","forward","Payment","Client","API Gateway","Service","publish","consume","Client-ger","ted keys","Server-generated keys","Cent sends 9","‘Your srvor stores key response in edie witha 24 TT","(Cient calls POST /payments/nt fist. Server returns one-time key","tent uses that Koy on the seta payment cal Sarvr own Koy","Duplicate request? Return cached eaponse. No reprocersing","Deterministic key from business fields","‘Outbox + idempotent consumer","No UUID. Hath the fla that define uniqueness","Forget the ey store. Write payment intent oan outbox table inthe","‘ame DB transaction ae your business write. A worker processes t","‘Sem business niet » same key. No cent coordination needed","‘consumers ddupiate on ovent","‘exactly once using the record ID a the dedup ten, Downstream"],"fr":["Votre service de paiement a facturé un client deux fois.","«System Design Labs","Qui","La stratégie de mpotency, vous y allez ?","POST /paiements","vers le haut","Paiement","Client","API Gateway","Service","publier","consommer","Client-ger","clés ted","Clés générées par le serveur","Cent envoie 9","‘Votre srvor stocke la réponse clé dans edie witha 24 TT","(Center appelle POST /payments/nt fist. Le serveur retourne une clé unique","tente utilise que Koy sur la seta paiement cal Sarvr propre Koy","Requête en double ? Retourne l'eaponse mise en cache.","Clé déterministe des domaines d'activité","«Outbox + idempotent consumer","No UUID. A le fla qui définit l'unicité","Oubliez le magasin ey. Écrivez l'intention de paiement oan table de boîte de réception inthe","‘ame DB transaction ae votre entreprise écrire. Un travailleur traite t","«Sem business niet» même clé. Pas de coordination cent nécessaire","«consommateurs ddupiate on ottent","'exactement une fois en utilisant l'ID de l'enregistrement a la dedup dix, en aval"]}},{"kind":"p","page":238,"text":{"en":"Your payment service charged a customer twice.","fr":"Votre service de paiement a prélevé deux fois le même client."}},{"kind":"p","page":238,"text":{"en":"Same request. Different response code. Client retried. You had no dedup logic.","fr":"Même requête, code de réponse différent. Le client a réessayé et vous n’aviez aucune logique de déduplication."}},{"kind":"p","page":238,"text":{"en":"That's not a race condition. That's a missing design decision.","fr":"Une décision de conception manquait."}},{"kind":"p","page":238,"text":{"en":"And the decision isn't whether to use idempotency keys. It's how you generate them.","fr":"Il reste à décider comment générer les clés d’idempotence."}},{"kind":"p","page":238,"text":{"en":"Here's the scenario:","fr":"Voici le scénario."}},{"kind":"p","page":238,"text":{"en":"Your API processes payments. Clients can and will retry on network failures. Your downstream calls (Stripe, Kafka, wallet credit) cannot be undone once triggered. A 500 or timeout on your side looks identical to a \"try again\" from the client's perspective.","fr":"Votre API traite des paiements. Lors d’une panne réseau, les clients relancent leurs requêtes. Une fois déclenchés, les appels aval à Stripe ou Kafka, ou le crédit d’un portefeuille, sont irréversibles. Pour le client, un code 500 ou une expiration côté serveur est un signal pour réessayer."}},{"kind":"p","page":238,"text":{"en":"Which idempotency strategy do you go with?","fr":"Quelle stratégie d’idempotence choisissez-vous ?"}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":238,"text":{"en":"Client-generated keys","fr":"Clés générées par le client"}},{"kind":"p","page":238,"text":{"en":"Client sends a UUID with every request (Idempotency-Key: ). Your server stores key → response in Redis with a 24h TTL. Duplicate request? Return cached response. No reprocessing.","fr":"Le client envoie un UUID à chaque requête dans l’en-tête Idempotency-Key. Le serveur conserve l’association entre clé et réponse dans Redis avec un TTL de 24 heures. Si la requête est un doublon, renvoyez la réponse en cache sans retraitement."}}]},{"letter":"B","blocks":[{"kind":"p","page":238,"text":{"en":"Server-generated keys","fr":"Clés générées par le serveur"}},{"kind":"p","page":239,"text":{"en":"Client calls POST /payments/init first. Server returns a one-time key. Client uses that key on the actual payment call. Server owns key lifecycle — rotation, expiry, scope.","fr":"Le client appelle d’abord POST /payments/init. Le serveur lui renvoie une clé à usage unique, que le client utilise pour le paiement. Le serveur maîtrise le cycle de vie de la clé, sa rotation, son expiration et sa portée."}}]},{"letter":"C","blocks":[{"kind":"p","page":239,"text":{"en":"Deterministic key from business fields","fr":"Clé déterministe dérivée des champs métier"}},{"kind":"p","page":239,"text":{"en":"No UUID. Hash the fields that define uniqueness: sha256(customer_id + order_id + amount + currency). Same business intent = same key. No client coordination needed.","fr":"Calculez sha256(customer_id + order_id + amount + currency) sur les champs qui définissent l’unicité. Une même intention métier donne la même clé, sans UUID ni coordination avec le client."}}]},{"letter":"D","blocks":[{"kind":"p","page":239,"text":{"en":"Outbox + idempotent consumer","fr":"Outbox et consommateur idempotent"}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"figure","page":240,"id":"240-03","width":800,"height":533,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["‘System Design Labs","A) Client-generated keys —","This is how Stripe does it. How Braintree does","the client owns the intent, so the cli","nt owns the key.","POST /payments","charge","(create payment)","HE, Gn)","@ were ne hoy win","Client","Payment","status pending before","Service","processing (Redis SET NX)","1. Write key","@© Process the payment","status: pending","2 Update key","status: completed","Update key to completed","he","with the fll response body","Return cached","en","response","Duplicate key?","Wie the hay fist Not ater.","response","payment succeeding andthe","fey wrto— youve charged","(dempotency Store)","the cord with no dec record","Nest retry charges again.","KEY SCOPING","‘Scope the idempotency key to (customerjd, key)","not globally","+ Aer expiry same UUID = new request","24h / 72h","7 a","© wien soon","Two diferent customers can use the sme UD.","They won't elide","Document your idempctncy contact inthe API docs","header name, ey Scope, TTL, ond expiry behave"],"fr":["«System Design Labs","A) Clés générées par le client","Voici comment Stripe le fait. Comment Braintree le fait","le client possède l'intention, donc le cli","nt possède la clé.","POST /paiements","charge","(créer le paiement)","HE, Gn)","étaient ne hoy gagner","Client","Paiement","statut en suspens avant","Service","traitement (Redis SET NX)","1. Clé d'écriture","Traiter le paiement","status: en attente","2 Mise à jour clé","Statut: Terminé","Mettre à jour la clé pour terminer","il","avec le corps de la réponse fll","Retour en cache","en","Réponse","Clé dupliquée ?","Pas d'ater.","Réponse","paiement réussi et le","fey wrto — vous avez chargé","(magasin de puissance)","le cordon sans enregistrement de dec","Nest réessaye à nouveau.","CALENDRIER CLÉ","‘Chargez la clé d’idempotence à (customerjd, clé)","pas globalement","+ Aer expire même UUID — nouvelle demande","24h / 72h","7 a","wien bientôt","Deux clients différents peuvent utiliser le sme UD.","Ils n'élideront pas","Documenter votre contact idempctncy dans les documents API","Nom d'en-tête, ey Scope, TTL, ond expiration se comportent"]}},{"kind":"p","page":240,"text":{"en":"A) Client-generated keys — ✅ GOLD STANDARD FOR EXTERNAL APIs","fr":"A) Clés générées par le client — ✅ Référence pour les API externes"}},{"kind":"p","page":240,"text":{"en":"This is how Stripe does it. How Braintree does it. Reason: the client owns the intent, so the client owns the key.","fr":"Stripe et Braintree utilisent cette approche. L’intention est définie par le client, qui peut donc produire la clé qui lui correspond."}},{"kind":"p","page":240,"text":{"en":"The flow that actually works in production:","fr":"Voici l’ordre des opérations qui fonctionne en production."}},{"kind":"list","page":240,"items":{"en":["1. Write the key with status pending before processing (Redis SET NX)","2. Process the payment","3. Update key to completed with the full response body"],"fr":["1. Écrivez la clé avec le statut pending avant le traitement, via Redis SET NX.","2. Traitez le paiement.","3. Passez la clé au statut completed en stockant tout le corps de la réponse."]}},{"kind":"p","page":240,"text":{"en":"Write the key first. Not after. If you crash between the payment succeeding and the key write — you've charged the card with no dedup record. Next retry charges again.","fr":"Écrivez la clé avant de traiter le paiement. Un plantage entre le paiement réussi et l’écriture de la clé laisse la carte débitée sans trace de déduplication. La tentative suivante débite le client une deuxième fois."}},{"kind":"p","page":240,"text":{"en":"Key scoping matters: scope to (customer_id, key) not globally. TTL: 24h standard, 72h for aggressive retry clients. After expiry, same UUID = new request — document this.","fr":"Limitez la portée de la clé au couple (customer_id, key). Le TTL standard est de 24 heures, ou de 72 heures pour les clients qui relancent beaucoup. Après expiration, le même UUID correspond à une nouvelle requête. Documentez ce comportement."}}],[{"kind":"p","page":241,"text":{"en":"B) Server-generated keys — ✅ RIGHT WHEN YOU DON'T TRUST CLIENTS","fr":"B) Clés générées par le serveur — ✅ Utile quand les clients ne sont pas fiables"}},{"kind":"p","page":241,"text":{"en":"Two-step feels like overhead. It's actually a feature.","fr":"Deux appels semblent ajouter du travail. Cette séparation apporte plusieurs garanties."}},{"kind":"p","page":241,"text":{"en":"The init call gives you: pre-validation before money moves, audit trail at key issuance, protection against clients sending garbage UUIDs (v1 timestamps, sequential IDs, non-unique values), and full key lifecycle control server-side.","fr":"L’appel d’initialisation permet de valider avant tout mouvement d’argent et de tracer la création de la clé. Il protège contre les UUID clients inadaptés, comme des horodatages v1, des identifiants séquentiels ou des valeurs non uniques. Le serveur contrôle tout le cycle de vie de la clé."}},{"kind":"p","page":241,"text":{"en":"Where it shines: internal service-to-service APIs, regulated environments, anywhere key collision is a compliance issue.","fr":"Cette option convient aux API internes de service à service, aux environnements réglementés et aux situations où une collision de clés poserait un problème de conformité."}},{"kind":"p","page":241,"text":{"en":"Where it hurts: mobile clients on flaky networks now have two calls that can fail independently. Retry complexity goes up, not down.","fr":"Sur un réseau mobile instable, le client doit désormais gérer deux appels qui peuvent échouer indépendamment. La logique de relance se complique."}}],[{"kind":"p","page":241,"text":{"en":"C) Deterministic key — ❌ THE SENIOR ENGINEER TRAP","fr":"C) Clé déterministe — ❌ Le piège des ingénieurs expérimentés"}},{"kind":"p","page":241,"text":{"en":"Looks clean. Falls apart on legitimate retries.","fr":"L’approche paraît simple et gère mal des requêtes légitimes."}},{"kind":"p","page":241,"text":{"en":"Same customer, same amount, same item — but a fresh order after a refund. Your hash matches the completed request. You return cached success for a brand new charge that should go through.","fr":"Après un remboursement, le même client commande à nouveau le même article au même prix. Votre hachage correspond à la requête déjà terminée. Vous renvoyez un succès en cache alors qu’un nouveau paiement devrait être traité."}},{"kind":"p","page":241,"text":{"en":"Second failure mode: field serialization drift across SDK versions. SDK v1 orders fields differently than v2. Different hash. Your dedup window disappears silently.","fr":"Autre risque : la sérialisation des champs change selon la version du SDK. La v1 et la v2 ordonnent les champs différemment. Le hachage change, et la fenêtre de déduplication disparaît sans signal."}},{"kind":"p","page":241,"text":{"en":"Use deterministic keys for internal job dedup — cron tasks, batch pipelines, where business intent is truly unique. Never for customer-facing payment flows.","fr":"Réservez les clés déterministes à la déduplication des tâches internes, comme les tâches cron et les traitements par lots, lorsque l’intention métier est véritablement unique. Évitez-les dans les parcours de paiement exposés aux clients."}}],[{"kind":"p","page":242,"text":{"en":"D) Outbox + idempotent consumer — ✅ STRONGEST FOR DISTRIBUTED SYSTEMS","fr":"D) Outbox et consommateur idempotent — ✅ Approche la plus robuste pour les systèmes distribués"}},{"kind":"p","page":242,"text":{"en":"The only option that makes the payment record and downstream event atomic.","fr":"Seule cette option rend atomiques l’enregistrement du paiement et celui de l’événement destiné à l’aval."}},{"kind":"p","page":242,"text":{"en":"The failure in A/B/C: Redis key write, DB write, and Stripe call are three separate operations. Crash between any two = inconsistent state.","fr":"Avec A, B ou C, l’écriture de la clé dans Redis, l’écriture en base et l’appel à Stripe sont trois opérations distinctes. Un plantage entre deux d’entre elles peut laisser un état incohérent."}},{"kind":"p","page":242,"text":{"en":"The outbox fixes it:","fr":"L’outbox règle ce problème en trois étapes."}},{"kind":"list","page":242,"items":{"en":["1. Write payment record + outbox event in one DB transaction","2. Worker processes downstream (Stripe, Kafka) using the row ID as dedup token","3. Downstream consumers deduplicate on event ID"],"fr":["1. Écrivez le paiement et l’événement d’outbox dans la même transaction en base.","2. Un worker appelle les systèmes aval, comme Stripe ou Kafka, en utilisant l’identifiant de la ligne pour dédupliquer.","3. Les consommateurs aval dédupliquent sur l’identifiant de l’événement."]}},{"kind":"p","page":242,"text":{"en":"No separate key store. No Redis dependency. Exactly-once enforced at the DB layer.","fr":"La base assure le traitement exactement une fois sans stockage séparé des clés ni dépendance à Redis."}},{"kind":"p","page":242,"text":{"en":"The cost: outbox table + reliable worker + idempotent consumers. Real infrastructure. Overkill at 100 payments/day. The only defensible architecture at 10K TPS with regulatory requirements.","fr":"Cette approche demande une table outbox, un worker fiable et des consommateurs idempotents. C’est une infrastructure trop lourde pour 100 paiements par jour. À 10 000 transactions par seconde et sous contraintes réglementaires, c’est l’architecture que l’auteur juge défendable."}}]]},{"day":60,"title":{"en":"Architecting a SaaS Platform from Scratch","fr":"Concevoir l’architecture d’une plateforme SaaS à partir de zéro"},"pages":[243,246],"topic":"architecture","correct":"B","scenario":[{"kind":"figure","page":243,"id":"243-02","width":800,"height":420,"alt":{"en":"Day 60 featured","fr":"Illustration de la question du jour 60"},"transcript":{"en":["You're designing the architecture for a new SaaS platform","system D","gn Labs","from scratch.","Ge","Servioes","ore","Load Balancer","cache","architecture — services for auth, billing,","Start with a distributed microservices","Start with a mod","deployable unit with clean internal module","yonolith — one","inference, and core domain from day one.","boundaries. Extract services only when a","‘Scale each independently.","specific boundary proves it needs it.","Start with serverless —","ymbda/Cloud","Start with an event-driven architecture —","Functions for every end","Kafla as the backbone, all services","for state, SQS for asyne.","fra to","‘communicate through events, no direct","manage, scales to zero between bursts","API calls between services from day one."],"fr":["Vous concevez l'architecture d'une nouvelle plateforme SaaS","système D","gn Labs","à partir de zéro.","Ge","Servioes","minerai","Balanceur de charge","cache","architecture — services pour auth, facturation,","Commencez avec un microservices distribué","Commencez par un mod","unité déployable avec module interne propre","yonolith — un","Inférence et domaine central dès le premier jour.","Extraire les services uniquement lorsqu'un","« Évoluez chacun indépendamment.","Une frontière spécifique prouve qu’il en a besoin.","Débuter avec serverless","ymbda/Cloud","Commencez avec une architecture événementielle","Fonctions pour chaque fin","Kafla comme colonne vertébrale, tous les services","pour l'état, SQS pour asyne.","fra to","« Communiquer à travers les événements, pas directement","gérer, échelles à zéro entre les rafales","Appels API entre les services dès le premier jour."]}},{"kind":"p","page":243,"text":{"en":"You're designing the architecture for a new SaaS platform from scratch.","fr":"Vous concevez l’architecture d’une nouvelle plateforme SaaS en partant de zéro."}},{"kind":"p","page":243,"text":{"en":"It needs to handle 50,000 requests per second at launch. Multi-tenant. Real-time data. Global users. AI inference built in.","fr":"Dès son lancement, elle devra traiter 50 000 requêtes par seconde. Elle sera multitenant, servira des utilisateurs partout dans le monde, fournira des données en temps réel et intégrera de l’inférence IA."}},{"kind":"p","page":243,"text":{"en":"Your CTO gives you 3 months and a blank slate.","fr":"Votre direction technique vous donne trois mois et toute latitude sur la conception."}},{"kind":"p","page":243,"text":{"en":"You've been thinking about this for a week. You finally sit down to draw the first box.","fr":"Vous y réfléchissez depuis une semaine et vous vous asseyez enfin pour poser la première brique de l’architecture."}},{"kind":"p","page":243,"text":{"en":"Here's what engineers actually debate in that room:","fr":"Voici les approches dont débattent les ingénieurs."}}],"postScenario":[],"choices":[{"letter":"A","blocks":[{"kind":"p","page":243,"text":{"en":"Start with a distributed microservices architecture — services for auth, billing, inference, and core domain from day one. Scale each independently.","fr":"Partir sur des microservices distribués. Séparez l’authentification, la facturation, l’inférence et le cœur métier dès le premier jour. Dimensionnez chaque service indépendamment."}}]},{"letter":"B","blocks":[{"kind":"p","page":243,"text":{"en":"Start with a modular monolith — one deployable unit with clean internal module boundaries. Extract services only when a specific boundary proves it needs it.","fr":"Partir sur un monolithe modulaire. Regroupez le système en une seule unité de déploiement, avec des frontières claires entre modules. Extrayez un service lorsqu’un module manifeste un besoin propre."}}]},{"letter":"C","blocks":[{"kind":"p","page":243,"text":{"en":"Start with serverless — Lambda/Cloud Functions for every endpoint, DynamoDB for state, SQS for async. Zero infra to manage, scales to zero between bursts.","fr":"Commencer en serverless. Utilisez Lambda ou Cloud Functions pour chaque endpoint, DynamoDB pour l’état et SQS pour l’asynchrone. Aucune infrastructure à gérer et la capacité retombe à zéro entre les pics."}}]},{"letter":"D","blocks":[{"kind":"p","page":243,"text":{"en":"Start with an event-driven architecture — Kafka as the backbone, all services communicate through events, no direct API calls between services from day one.","fr":"Commencer par une architecture événementielle. Appuyez-vous sur Kafka, faites communiquer tous les services par événements et évitez les appels API directs entre services dès le départ."}}]}],"afterChoices":[],"answerIntro":[],"explanations":[[{"kind":"figure","page":244,"id":"244-03","width":800,"height":533,"alt":{"en":"Answer 1 diagram","fr":"Schéma de l’explication 1"},"transcript":{"en":["[v) B) Modular Monolith — right","The constraint isn't scale. I's the 3-month runway plus uncertainty about domain boundaries.","4 Modular Monolith","‘A modular monolith gives you:","Fastitertion — no network serialization","‘overhead, no crose-service API contracts to","version","Real module boundaries enforced in code","‘Auth","ing","Inference","Core Domain","(auth, ling, inference, core domain —","Global","Module","Module","Module","‘Module","shared DB tables, no cross-module direct cal)","Users","ave","oes","teh","Single deploy single observability surface,","‘ingle transaction boundary","‘Shared Kernel","roe cting concn Logg, Mie MAN Con, rr","‘The option to extract services later —winen","you know exactly which boundary i ea","Extraction Path Example: Billing","Al inference piece: inference latency","is dominated by model /O","(60-500ms), not your application","al","Bing trate grows","{Bing mode","Extracting","Scale biting","‘code, That's resson to put it behind","ss separate","‘clean internal interface — not a","| terface boundary","re","series","reason to make ta separate service","‘on day one.","Modular now. Distributed later. Boundaries","st, extraction second. Retat","notre"],"fr":["[v) B) Monolithe modulaire — droite","La contrainte n'est pas l'échelle. Je suis la piste de 3 mois plus l'incertitude sur les limites de domaine.","4 Monolithe modulaire","« Un monolithe modulaire vous donne :","Fastitertion — pas de sérialisation réseau","«frais généraux, pas de contrats API de gros-service pour","version","Limites réelles des modules appliquées dans le code","«Auth","ing","Inférence","Domaine principal","(auth, ling, inférence, core domain","Mondial","Module","Module","Module","«Module","tables de base de données partagées, pas de calcul direct inter-modules)","Utilisateurs","ave","oes","teh","Surface unique d'observabilité à déploiement unique,","«frontière de transaction unique","« Noyau partagé","logg, Mie MAN Con, rr","«L’option d’extraire les services plus tard — winen","vous savez exactement quelle limite i ea","Exemple de chemin d'extraction : Facturation","Al inference piece : latence d'inférence","est dominé par le modèle /O","(60-500ms), pas votre application","al","Bing trate se développe","Mode — Bing","Extraction","Échelle mordant","« Code, c’est ça le problème de le mettre derrière","ss séparé","« Interface interne propre – pas une","terface boundary","re","série","raison de faire ta service séparé","« Le premier jour.","Modulaire maintenant. Distribué plus tard. Frontières","st, extraction seconde.","nore"]}},{"kind":"p","page":244,"text":{"en":"B) Modular Monolith — right","fr":"B) Monolithe modulaire — Bonne réponse"}},{"kind":"p","page":244,"text":{"en":"The constraint isn't scale. It's the 3-month runway plus uncertainty about domain boundaries.","fr":"Les contraintes déterminantes sont les trois mois disponibles et les frontières métier encore floues."}},{"kind":"p","page":244,"text":{"en":"A modular monolith gives you:","fr":"Un monolithe modulaire offre plusieurs avantages."}},{"kind":"p","page":244,"text":{"en":"• Fast iteration — no network serialization overhead, no cross-service API contracts to version","fr":"• Des itérations rapides, sans coût de sérialisation réseau ni contrats d’API interservices à versionner."}},{"kind":"p","page":244,"text":{"en":"• Real module boundaries enforced in code (auth, billing, inference, core domain — no shared DB tables, no cross-module direct calls)","fr":"• Des frontières explicites, imposées dans le code, entre l’authentification, la facturation, l’inférence et le cœur métier, sans tables partagées ni appels directs entre modules."}},{"kind":"p","page":244,"text":{"en":"• Single deploy, single observability surface, single transaction boundary","fr":"• Un seul déploiement, un périmètre d’observabilité commun et une frontière transactionnelle unique."}},{"kind":"p","page":244,"text":{"en":"• The option to extract services later — when you know exactly which boundary is real","fr":"• La possibilité d’isoler des services plus tard, une fois la frontière métier bien établie."}},{"kind":"p","page":244,"text":{"en":"When billing hits 10k RPS independently and needs separate scaling, you extract it. The boundary is already clean. The migration is a refactor, not a rewrite.","fr":"Quand la facturation atteint seule 10 000 RPS et nécessite une mise à l’échelle indépendante, extrayez-la. La séparation est déjà nette et la migration se fait par refactorisation."}},{"kind":"p","page":245,"text":{"en":"The AI inference piece specifically: inference latency is dominated by model I/O (50–500ms), not your application code. That's a reason to put it behind a clean internal interface — not a reason to make it a separate service on day one.","fr":"Pour l’inférence IA en particulier, le modèle et ses entrées-sorties dominent la latence, de 50 à 500 ms. Isolez ce composant derrière une interface interne claire. Vous pouvez décider plus tard s’il mérite un service indépendant."}}],[{"kind":"p","page":245,"text":{"en":"A) Microservices from day one — wrong","fr":"A) Microservices dès le premier jour — Inadaptés"}},{"kind":"p","page":245,"text":{"en":"50,000 RPS sounds like you need microservices. It doesn't.","fr":"Le chiffre de 50 000 RPS peut donner l’impression que vous avez besoin de microservices."}},{"kind":"p","page":245,"text":{"en":"That's a solved load balancing problem, not a distribution problem.","fr":"Ce débit relève d’un problème connu de répartition de charge, que vous pouvez gérer sans distribuer la logique métier."}},{"kind":"p","page":245,"text":{"en":"What microservices from day one actually gives you:","fr":"Partir sur des microservices impose plusieurs coûts dès le premier jour."}},{"kind":"p","page":245,"text":{"en":"• 6+ independently deployable services before you've found your real domain boundaries","fr":"• Au moins six services déployables indépendamment avant d’avoir identifié les frontières métier."}},{"kind":"p","page":245,"text":{"en":"• Distributed transactions across auth, billing, inference, and core domain","fr":"• Des transactions distribuées entre l’authentification, la facturation, l’inférence et le cœur métier."}},{"kind":"p","page":245,"text":{"en":"• Network hops on every request that used to be in-process calls","fr":"• Des allers-retours réseau pour des appels qui auraient pu se faire dans le même processus."}},{"kind":"p","page":245,"text":{"en":"• 3 months of infra work instead of product","fr":"• Trois mois mobilisés par l’infrastructure au détriment du produit."}},{"kind":"p","page":245,"text":{"en":"Amazon's \"two-pizza teams\" rule was for existing services with known boundaries. Not for new domains where you're still discovering what the boundaries are.","fr":"La règle des équipes « deux pizzas » d’Amazon concernait des services existants aux frontières bien connues. Ici, le domaine est nouveau et ses frontières restent à découvrir."}},{"kind":"p","page":245,"text":{"en":"The boundary is the hard part. You don't know it yet.","fr":"La difficulté est de trouver ces frontières."}}],[{"kind":"p","page":245,"text":{"en":"C) Serverless — wrong (senior engineer trap)","fr":"C) Serverless — Le piège des ingénieurs expérimentés"}},{"kind":"p","page":245,"text":{"en":"\"Scales to zero\" sounds great until you price out 50k RPS sustained on Lambda.","fr":"La possibilité de réduire la capacité à zéro paraît séduisante jusqu’au calcul du coût de 50 000 RPS soutenus sur Lambda."}},{"kind":"p","page":245,"text":{"en":"The math:","fr":"Voici le calcul et les contraintes."}},{"kind":"p","page":245,"text":{"en":"• 50,000 req/s × 100ms avg = 5,000 concurrent Lambda executions","fr":"• 50 000 requêtes par seconde à 100 ms de durée moyenne donnent 5 000 exécutions Lambda simultanées."}},{"kind":"p","page":245,"text":{"en":"• At that scale you're paying more than a reserved EC2 cluster","fr":"• À ce niveau, la facture dépasse celle d’un cluster EC2 à capacité réservée."}},{"kind":"p","page":245,"text":{"en":"• Cold starts are real and you promised \"real-time data\"","fr":"• Les démarrages à froid sont réels alors que vous avez promis des données en temps réel."}},{"kind":"p","page":245,"text":{"en":"• AI inference in Lambda = cold start + memory limit + 15-min hard timeout = pain","fr":"• Sur Lambda, l’inférence IA cumule démarrage à froid, mémoire limitée et un délai maximal de 15 minutes."}},{"kind":"p","page":245,"text":{"en":"Serverless wins for bursty, unpredictable event workloads. SaaS with consistent load and real-time requirements is not that workload.","fr":"Le serverless convient aux traitements événementiels imprévisibles et en rafales. Ce SaaS doit absorber une charge continue avec des exigences de temps réel."}}],[{"kind":"p","page":246,"text":{"en":"D) Event-driven from day one — wrong","fr":"D) Architecture événementielle dès le premier jour — Inadaptée"}},{"kind":"p","page":246,"text":{"en":"This one trips up engineers who've read about Kafka at Netflix and Uber.","fr":"Cette option séduit les ingénieurs qui ont lu comment Netflix et Uber utilisent Kafka."}},{"kind":"p","page":246,"text":{"en":"Event-driven is the right answer — for Netflix and Uber, after they've already mapped their domain.","fr":"L’approche événementielle leur convient après avoir défini leurs domaines métier."}},{"kind":"p","page":246,"text":{"en":"Starting with Kafka before you have a working system means:","fr":"Commencer avec Kafka avant d’avoir un système fonctionnel entraîne plusieurs coûts."}},{"kind":"p","page":246,"text":{"en":"• Every feature needs an event schema, a producer, and a consumer before it works","fr":"• Chaque fonctionnalité attend la définition d’un schéma d’événement, d’un producteur et d’un consommateur."}},{"kind":"p","page":246,"text":{"en":"• Debugging \"why didn't this event get processed\" during week 2 of development","fr":"• Dès la deuxième semaine, vous devez déboguer les événements qui ne sont pas traités."}},{"kind":"p","page":246,"text":{"en":"• Eventual consistency as the default when you don't yet know which operations need strong consistency","fr":"• La cohérence à terme devient la règle alors que vous ignorez encore quelles opérations exigent une cohérence forte."}},{"kind":"p","page":246,"text":{"en":"• Kafka operational overhead before you've validated the product","fr":"• Vous assumez le coût d’exploitation de Kafka avant même de valider le produit."}},{"kind":"p","page":246,"text":{"en":"Event-driven is an optimization for a known system. Not a foundation for an unknown one.","fr":"L’architecture événementielle optimise un système dont les frontières sont comprises. Décidez de l’adopter après les avoir identifiées."}}]]}],"topics":{"architecture":{"en":"Architecture & APIs","fr":"Architecture et API"},"data":{"en":"Data & Consistency","fr":"Données et cohérence"},"scale":{"en":"Performance & Scale","fr":"Performance et passage à l’échelle"},"reliability":{"en":"Reliability & Delivery","fr":"Fiabilité et déploiement"},"events":{"en":"Events & Real Time","fr":"Événements et temps réel"},"ai":{"en":"AI & Agents","fr":"IA et agents"}}};
